import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "<input[^>]*name\\s*=\\s*[\"']csrf[\"'][^>]*>", Pattern.CASE_INSENSITIVE);
    private static final Pattern VALUE_ATTR = Pattern.compile(
            "value\\s*=\\s*[\"']([^\"']*)[\"']", Pattern.CASE_INSENSITIVE);
    private static final Pattern NAME_ATTR = Pattern.compile(
            "name\\s*=\\s*[\"']([^\"']*)[\"']", Pattern.CASE_INSENSITIVE);

    private static String extractCsrf(String html) {
        if (html == null) return null;
        Matcher m = CSRF_INPUT.matcher(html);
        while (m.find()) {
            String tag = m.group();
            Matcher nm = NAME_ATTR.matcher(tag);
            if (!nm.find() || !"csrf".equals(nm.group(1))) continue;
            Matcher vm = VALUE_ATTR.matcher(tag);
            if (vm.find()) return vm.group(1);
        }
        return null;
    }

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE)
            .disableAutoReferer()
            .disableCaching()
            .disableFollowRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json");

    private static final String LOGIN_FORM = "login-form";
    private static final String LOGIN = "login";
    private static final String CATALOG = "catalog";
    private static final String CATALOG_PAGE = "catalog-page";
    private static final String CART_CREATE = "cart-create";
    private static final String CART_GET = "cart-get";
    private static final String CART_PATCH = "cart-patch";
    private static final String ORDER = "order";
    private static final String RENEW = "renew";
    private static final String RECOVER = "recover";
    private static final String CHALLENGE_FORM = "challenge-form";
    private static final String CHALLENGE_POST = "challenge-post";
    private static final String CHALLENGE_GET = "challenge-get";
    private static final String RESERVATION = "reservation";
    private static final String RESERVATION_STATUS = "reservation-status";
    private static final String WORK = "work";

    private static ChainBuilder loginFlow() {
        return exec(
                http(LOGIN_FORM)
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginHtml"))
        ).exec(session -> {
            String csrf = extractCsrf(session.getString("loginHtml"));
            if (csrf == null) {
                return session.markAsFailed().set("loginCsrf", "");
            }
            return session.set("loginCsrf", csrf);
        }).exec(
                http(LOGIN)
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String u = session.getString("username");
                            String c = session.getString("loginCsrf");
                            return "{\"username\":\"" + u + "\",\"password\":\"bench\",\"csrf\":\"" + c + "\"}";
                        }))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginBody"))
        ).exec(session -> {
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginRedirect", loc);
            }
            return session;
        }).doIf(session -> session.getString("loginRedirect") != null).then(
                exec(
                        http("login-redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("loginBody2"))
                ).exec(session -> {
                    String body = session.getString("loginBody2");
                    String csrf = extractCsrf(body);
                    if (csrf == null) {
                        // try JSON csrf field
                        csrf = jsonField(body, "csrf");
                    }
                    if (csrf == null) return session.markAsFailed();
                    return session.set("csrf", csrf);
                })
        ).exec(session -> {
            if (session.getString("csrf") != null) return session;
            String body = session.getString("loginBody");
            String csrf = jsonField(body, "csrf");
            if (csrf == null) return session.markAsFailed();
            return session.set("csrf", csrf);
        });
    }

    private static String jsonField(String body, String field) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(field) + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static ChainBuilder catalogFlow() {
        return exec(
                http(CATALOG)
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(bodyString().saveAs("catalogBody"))
        ).exec(session -> {
            String body = session.getString("catalogBody");
            String[] pick = pickProductVariant(body);
            if (pick == null) return session.markAsFailed();
            return session.set("productId", pick[0]).set("variantId", pick[1]);
        });
    }

    private static String[] pickProductVariant(String body) {
        if (body == null) return null;
        // naive parse: find products array entries with id and variants
        Pattern prod = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"[^}]*?\"variants\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher pm = prod.matcher(body);
        List<String[]> candidates = new ArrayList<>();
        while (pm.find()) {
            String pid = pm.group(1);
            String variants = pm.group(2);
            Pattern var = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"[^}]*?\"in_stock\"\\s*:\\s*(true|false)", Pattern.DOTALL);
            Matcher vm = var.matcher(variants);
            while (vm.find()) {
                if ("true".equals(vm.group(2))) {
                    candidates.add(new String[]{pid, vm.group(1)});
                }
            }
        }
        if (candidates.isEmpty()) return null;
        return candidates.get(ThreadLocalRandom.current().nextInt(candidates.size()));
    }

    private static ChainBuilder challengeFlow() {
        return exec(
                http(CHALLENGE_FORM)
                        .get("/v2/challenge-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("challengeHtml"))
        ).exec(session -> {
            String html = session.getString("challengeHtml");
            String action = null;
            String challenge = null;
            if (html != null) {
                Matcher am = Pattern.compile("action\\s*=\\s*[\"']([^\"']+)[\"']").matcher(html);
                if (am.find()) action = am.group(1);
                Matcher cm = Pattern.compile("<input[^>]*name\\s*=\\s*[\"']challenge[\"'][^>]*>").matcher(html);
                if (cm.find()) {
                    Matcher vm = VALUE_ATTR.matcher(cm.group());
                    if (vm.find()) challenge = vm.group(1);
                }
            }
            if (action == null || challenge == null) return session.markAsFailed();
            return session.set("challengeAction", action).set("challengeValue", challenge);
        }).exec(
                http(CHALLENGE_POST)
                        .post(session -> session.getString("challengeAction"))
                        .body(StringBody(session -> "{\"challenge\":\"" + session.getString("challengeValue") + "\"}"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("challengeLocation"))
        ).exec(session -> {
            String loc = session.getString("challengeLocation");
            if (loc == null || loc.isEmpty()) return session.markAsFailed();
            return session.set("challengeRedirect", loc);
        }).exec(
                http(CHALLENGE_GET)
                        .get(session -> session.getString("challengeRedirect"))
                        .check(status().is(200))
                        .check(bodyString().saveAs("challengeResult"))
        ).exec(session -> {
            String body = session.getString("challengeResult");
            String grant = jsonField(body, "grant_id");
            String csrf = jsonField(body, "csrf");
            if (grant == null) return session.markAsFailed();
            Session s = session.set("grantId", grant);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        });
    }

    private static ChainBuilder cartCreateFlow() {
        return exec(
                http(CART_CREATE)
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> {
                            String pid = session.getString("productId");
                            String vid = session.getString("variantId");
                            String grant = session.getString("grantId");
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"product_id\":\"").append(pid).append("\",\"variant_id\":\"").append(vid).append("\"");
                            if (grant != null && !grant.isEmpty()) {
                                sb.append(",\"grant_id\":\"").append(grant).append("\"");
                            }
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().is(201))
                        .check(header("ETag").optional().saveAs("cartEtag"))
                        .check(bodyString().saveAs("cartBody"))
        ).exec(session -> {
            String body = session.getString("cartBody");
            String id = jsonField(body, "id");
            String csrf = jsonField(body, "csrf");
            if (id == null) return session.markAsFailed();
            Session s = session.set("cartId", id);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        });
    }

    private static ChainBuilder cartPatchFlow() {
        return exec(
                http(CART_GET)
                        .get(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .check(status().is(200))
                        .check(header("ETag").optional().saveAs("cartEtag"))
        ).exec(
                http(CART_PATCH)
                        .patch(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> {
                            String e = session.getString("cartEtag");
                            return e == null ? "*" : e;
                        })
                        .body(StringBody("{\"quantity\":1}"))
                        .check(status().in(200, 204, 412))
                        .check(bodyString().optional().saveAs("patchBody"))
        ).exec(session -> {
            Integer st = session.getInt("patchStatus");
            return session;
        });
    }

    private static ChainBuilder orderFlow() {
        return exec(
                http(ORDER)
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                        .header("If-Match", session -> {
                            String e = session.getString("cartEtag");
                            return e == null ? "*" : e;
                        })
                        .body(StringBody(session -> {
                            String cart = session.getString("cartId");
                            String res = session.getString("reservationId");
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"cart_id\":\"").append(cart).append("\"");
                            if (res != null && !res.isEmpty()) {
                                sb.append(",\"reservation_id\":\"").append(res).append("\"");
                            }
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().is(201))
                        .check(bodyString().saveAs("orderBody"))
        ).exec(session -> {
            String body = session.getString("orderBody");
            if (body == null || !body.contains("\"accepted\":true")) {
                return session.markAsFailed();
            }
            String csrf = jsonField(body, "csrf");
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    private static ChainBuilder reservationFlow() {
        return exec(
                http(RESERVATION)
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                        .check(status().is(202))
                        .check(bodyString().saveAs("resBody"))
        ).exec(session -> {
            String body = session.getString("resBody");
            String statusUrl = jsonField(body, "status_url");
            String csrf = jsonField(body, "csrf");
            if (statusUrl == null) return session.markAsFailed();
            Session s = session.set("statusUrl", statusUrl).set("pollCount", 0);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        }).asLongAs(session -> {
            Integer pc = session.getInt("pollCount");
            String rid = session.getString("reservationId");
            return pc != null && pc < 5 && rid == null;
        }).on(
                pause(Duration.ofMillis(60)).exec(
                        http(RESERVATION_STATUS)
                                .get(session -> session.getString("statusUrl"))
                                .header("X-CSRF-Token", session -> session.getString("csrf"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("statusBody"))
                ).exec(session -> {
                    String body = session.getString("statusBody");
                    String status = jsonField(body, "status");
                    String csrf = jsonField(body, "csrf");
                    Session s = session.set("pollCount", session.getInt("pollCount") + 1);
                    if (csrf != null) s = s.set("csrf", csrf);
                    if ("ready".equals(status)) {
                        String rid = jsonField(body, "reservation_id");
                        if (rid != null) s = s.set("reservationId", rid);
                    } else if ("failed".equals(status)) {
                        s = s.markAsFailed();
                    }
                    return s;
                })
        );
    }

    private static ChainBuilder workFlow() {
        return exec(
                http(WORK)
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429))
                        .check(bodyString().optional().saveAs("workBody"))
        ).exec(session -> {
            Integer st = session.getInt("workStatus");
            return session;
        });
    }

    private static ChainBuilder journey() {
        return exec(session -> session.set("username", "bench-" + session.userId()))
                .exec(loginFlow())
                .exec(catalogFlow())
                .exec(challengeFlow())
                .exec(cartCreateFlow())
                .exec(cartPatchFlow())
                .exec(reservationFlow())
                .exec(orderFlow())
                .exec(workFlow());
    }

    private static ScenarioBuilder scenario() {
        return scenario("shop-flow")
                .exec(journey());
    }

    {
        setUp(
                scenario().injectOpen(
                        rampUsers(2).during(Duration.ofSeconds(1))
                )
        ).protocols(HTTP);
    }
}
