function parseCsrf(html) {
  // Find input[name=csrf] value, tolerant of attribute order and quoting.
  const inputRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRe.exec(html)) !== null) {
    const tag = m[0];
    const nameMatch = tag.match(/\bname\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameMatch) continue;
    const name = nameMatch[2] !== undefined ? nameMatch[2]
      : nameMatch[3] !== undefined ? nameMatch[3]
      : nameMatch[4];
    if (name !== 'csrf') continue;
    const valMatch = tag.match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!valMatch) continue;
    const val = valMatch[2] !== undefined ? valMatch[2]
      : valMatch[3] !== undefined ? valMatch[3]
      : valMatch[4];
    return val;
  }
  return null;
}

function parseChallengeForm(html) {
  const actionMatch = html.match(/<form\b[^>]*\baction\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
  if (!actionMatch) return null;
  const action = actionMatch[2] !== undefined ? actionMatch[2]
    : actionMatch[3] !== undefined ? actionMatch[3]
    : actionMatch[4];
  const inputRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRe.exec(html)) !== null) {
    const tag = m[0];
    const nameMatch = tag.match(/\bname\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameMatch) continue;
    const name = nameMatch[2] !== undefined ? nameMatch[2]
      : nameMatch[3] !== undefined ? nameMatch[3]
      : nameMatch[4];
    if (name !== 'challenge') continue;
    const valMatch = tag.match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!valMatch) continue;
    const val = valMatch[2] !== undefined ? valMatch[2]
      : valMatch[3] !== undefined ? valMatch[3]
      : valMatch[4];
    return { action, challenge: val };
  }
  return null;
}

function jsonBody(res) {
  try { return JSON.parse(res.body); } catch (e) { return null; }
}

function getCsrfFromBody(body, fallback) {
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) return body.csrf;
  return fallback;
}

function resolveUrl(loc) {
  if (!loc) return null;
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.startsWith('/')) return BASE + loc;
  return BASE + '/' + loc;
}

function doLogin(username) {
  const formRes = http.get(BASE + '/v2/login-form', { tags: { name: 'login-form' } });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body || '');
  check(csrf, { 'csrf extracted': (v) => typeof v === 'string' && v.length > 0 });
  if (!csrf) return null;

  const loginRes = http.post(BASE + '/v2/login', JSON.stringify({
    username, password: 'bench', csrf,
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });

  let body = jsonBody(loginRes);
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    const followRes = http.get(resolveUrl(loc), { tags: { name: 'login-follow' } });
    check(followRes, { 'login follow 200': (r) => r.status === 200 });
    body = jsonBody(followRes);
  } else {
    check(loginRes, { 'login 200': (r) => r.status === 200 });
  }
  check(body, { 'login body': (b) => b && typeof b.csrf === 'string' });
  if (!body || !body.csrf) return null;
  return { csrf: body.csrf, user: body.user };
}

function renewSession(csrf) {
  const res = http.post(BASE + '/v2/session/renew', JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'renew' },
  });
  const body = jsonBody(res);
  if (res.status === 200 && body && body.csrf) return body.csrf;
  return null;
}

function recoverCart(cartId, csrf) {
  const res = http.post(BASE + '/v2/carts/' + cartId + '/recover', JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'recover' },
  });
  const body = jsonBody(res);
  return getCsrfFromBody(body, csrf);
}

function authedRequest(method, url, payload, csrf, extraHeaders, tag) {
  const headers = Object.assign({
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
  }, extraHeaders || {});
  const params = { headers, tags: { name: tag || method } };
  let res;
  if (method === 'GET') res = http.get(url, params);
  else if (method === 'POST') res = http.post(url, payload ? JSON.stringify(payload) : null, params);
  else if (method === 'PATCH') res = http.patch(url, payload ? JSON.stringify(payload) : null, params);
  else res = http.request(method, url, payload ? JSON.stringify(payload) : null, params);
  return res;
}

function handleExpiry(res, csrf, cartId, retryFn) {
  const body = jsonBody(res);
  if (res.status === 401 && body && body.error === 'expired') {
    let newCsrf = renewSession(csrf);
    if (!newCsrf) {
      // session revoked: fresh login
      const login = doLogin('bench');
      if (!login) return { ok: false, csrf };
      newCsrf = login.csrf;
    }
    if (cartId) newCsrf = recoverCart(cartId, newCsrf);
    const retry = retryFn(newCsrf);
    return { ok: true, res: retry, csrf: newCsrf };
  }
  return { ok: false, res, csrf };
}

function fetchCatalog(csrf) {
  const products = [];
  let url = BASE + '/v2/catalog/page';
  let pages = 0;
  while (url && pages < 3) {
    const res = http.get(url, { tags: { name: 'catalog-page' } });
    check(res, { 'catalog page 200': (r) => r.status === 200 });
    const body = jsonBody(res);
    if (!body) break;
    if (body.product) products.push(body.product);
    else if (body.data && body.data.products) products.push(...body.data.products);
    url = body.next ? resolveUrl(body.next) : null;
    pages++;
  }
  if (products.length === 0) {
    const res = http.get(BASE + '/v2/catalog', { tags: { name: 'catalog' } });
    const body = jsonBody(res);
    if (body && body.data && body.data.products) products.push(...body.data.products);
  }
  return products;
}

function pickVariant(products) {
  for (const p of products) {
    if (!p.variants) continue;
    for (const v of p.variants) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function solveChallenge(csrf) {
  const formRes = http.get(BASE + '/v2/challenge-form', { tags: { name: 'challenge-form' } });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const parsed = parseChallengeForm(formRes.body || '');
  check(parsed, { 'challenge parsed': (p) => p !== null });
  if (!parsed) return null;
  const actionUrl = resolveUrl(parsed.action);
  const postRes = http.post(actionUrl, JSON.stringify({ challenge: parsed.challenge }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'challenge-post' },
  });
  check(postRes, { 'challenge post 302': (r) => r.status === 302 });
  const loc = postRes.headers['Location'] || postRes.headers['location'];
  if (!loc) return null;
  const followRes = http.get(resolveUrl(loc), { tags: { name: 'challenge-follow' } });
  check(followRes, { 'challenge follow 200': (r) => r.status === 200 });
  const body = jsonBody(followRes);
  if (!body || !body.grant_id) return null;
  return { grant_id: body.grant_id, csrf: getCsrfFromBody(body, csrf) };
}

function doWork(csrf) {
  let attempts = 0;
  while (attempts < 5) {
    const res = http.post(BASE + '/v2/work', JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      tags: { name: 'work' },
    });
    if (res.status === 429) {
      attempts++;
      sleep(1);
      continue;
    }
    check(res, { 'work 200': (r) => r.status === 200 });
    return res;
  }
  return null;
}

function pollReservation(statusUrl, csrf) {
  let currentCsrf = csrf;
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const res = http.get(resolveUrl(statusUrl), {
      headers: { 'X-CSRF-Token': currentCsrf },
      tags: { name: 'reservation-status' },
    });
    const body = jsonBody(res);
    if (!body) continue;
    currentCsrf = getCsrfFromBody(body, currentCsrf);
    if (body.status === 'ready' && body.reservation_id) {
      return { reservation_id: body.reservation_id, csrf: currentCsrf };
    }
    if (body.status === 'failed') return null;
  }
  return null;
}

export default function () {
  const vu = __VU;
  const username = 'bench-' + (((vu - 1) % 16) + 1);

  // Fresh login per journey
  const login = doLogin(username);
  if (!login) return;
  let csrf = login.csrf;

  // Fresh cart per journey
  const products = fetchCatalog(csrf);
  const pick = pickVariant(products);
  check(pick, { 'variant picked': (p) => p !== null });
  if (!pick) return;

  // Challenge for grant
  const challenge = solveChallenge(csrf);
  if (challenge) csrf = challenge.csrf;

  const cartPayload = { product_id: pick.product_id, variant_id: pick.variant_id };
  if (challenge && challenge.grant_id) cartPayload.grant_id = challenge.grant_id;

  let cartRes = authedRequest('POST', BASE + '/v2/carts', cartPayload, csrf, null, 'cart-create');
  let exp = handleExpiry(cartRes, csrf, null, (nc) => {
    return authedRequest('POST', BASE + '/v2/carts', cartPayload, nc, null, 'cart-create-retry');
  });
  if (exp.ok) { cartRes = exp.res; csrf = exp.csrf; }
  check(cartRes, { 'cart created 201': (r) => r.status === 201 });
  const cartBody = jsonBody(cartRes);
  if (!cartBody || !cartBody.id) return;
  const cartId = cartBody.id;
  csrf = getCsrfFromBody(cartBody, csrf);

  // Read cart for ETag
  let getRes = authedRequest('GET', BASE + '/v2/carts/' + cartId, null, csrf, null, 'cart-get');
  exp = handleExpiry(getRes, csrf, cartId, (nc) => {
    return authedRequest('GET', BASE + '/v2/carts/' + cartId, null, nc, null, 'cart-get-retry');
  });
  if (exp.ok) { getRes = exp.res; csrf = exp.csrf; }
  check(getRes, { 'cart get 200': (r) => r.status === 200 });
  let etag = getRes.headers['Etag'] || getRes.headers['ETag'] || getRes.headers['etag'];

  // PATCH quantity
  const patchPayload = { quantity: 1 };
  let patchRes = authedRequest('PATCH', BASE + '/v2/carts/' + cartId, patchPayload, csrf,
    etag ? { 'If-Match': etag } : null, 'cart-patch');
  if (patchRes.status === 412) {
    const reGet = authedRequest('GET', BASE + '/v2/carts/' + cartId, null, csrf, null, 'cart-reget');
    const reEtag = reGet.headers['Etag'] || reGet.headers['ETag'] || reGet.headers['etag'];
    patchRes = authedRequest('PATCH', BASE + '/v2/carts/' + cartId, patchPayload, csrf,
      reEtag ? { 'If-Match': reEtag } : null, 'cart-patch-retry');
  }
  exp = handleExpiry(patchRes, csrf, cartId, (nc) => {
    return authedRequest('PATCH', BASE + '/v2/carts/' + cartId, patchPayload, nc,
      etag ? { 'If-Match': etag } : null, 'cart-patch-expiry-retry');
  });
  if (exp.ok) { patchRes = exp.res; csrf = exp.csrf; }
  check(patchRes, { 'cart patch ok': (r) => r.status === 200 || r.status === 204 });
  const patchBody = jsonBody(patchRes);
  csrf = getCsrfFromBody(patchBody, csrf);

  // Reservation
  let resRes = authedRequest('POST', BASE + '/v2/reservations', { cart_id: cartId }, csrf, null, 'reservation');
  exp = handleExpiry(resRes, csrf, cartId, (nc) => {
    return authedRequest('POST', BASE + '/v2/reservations', { cart_id: cartId }, nc, null, 'reservation-retry');
  });
  if (exp.ok) { resRes = exp.res; csrf = exp.csrf; }
  check(resRes, { 'reservation 202': (r) => r.status === 202 });
  const resBody = jsonBody(resRes);
  if (!resBody || !resBody.status_url) return;
  csrf = getCsrfFromBody(resBody, csrf);

  const reservation = pollReservation(resBody.status_url, csrf);
  check(reservation, { 'reservation ready': (r) => r !== null });
  if (!reservation) return;
  csrf = reservation.csrf;

  // Work (business)
  doWork(csrf);

  // Order
  const orderPayload = { cart_id: cartId, reservation_id: reservation.reservation_id };
  const idemKey = 'idem-' + cartId + '-' + Date.now();
  const orderHeaders = { 'Idempotency-Key': idemKey };
  if (etag) orderHeaders['If-Match'] = etag;

  let orderRes = authedRequest('POST', BASE + '/v2/orders', orderPayload, csrf, orderHeaders, 'order');
  exp = handleExpiry(orderRes, csrf, cartId, (nc) => {
    return authedRequest('POST', BASE + '/v2/orders', orderPayload, nc, orderHeaders, 'order-retry');
  });
  if (exp.ok) { orderRes = exp.res; csrf = exp.csrf; }
  check(orderRes, { 'order 201': (r) => r.status === 201 });
  const orderBody = jsonBody(orderRes);
  check(orderBody, { 'order accepted': (b) => b && b.accepted === true });
  if (orderBody) csrf = getCsrfFromBody(orderBody, csrf);
}
