BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _extract_csrf(html):
    # Find input[name=csrf] value, tolerant of attribute order/quoting variants.
    # Look for <input ...> tags containing name=csrf and a value attribute.
    for m in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r"""name\s*=\s*["']?csrf["']?""", tag, re.IGNORECASE):
            vm = re.search(r"""value\s*=\s*["']([^"']*)["']""", tag, re.IGNORECASE)
            if vm:
                return vm.group(1)
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.1)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.iterations_done = 0
        self.max_iterations = 2
        self.username = None
        self.password = "bench"
        self.csrf = None

    def on_start(self):
        # Assign a distinct account per virtual user.
        idx = (self.environment.runner.user_count if self.environment.runner else 1)
        # Use a stable per-user name based on worker/user id.
        uid = getattr(self, "_user_index", None)
        if uid is None:
            uid = id(self) % 16
        self.username = "bench-%d" % ((uid % 16) + 1)

    def _login(self):
        # Fresh login form
        with self.client.get("/v2/login-form", name="GET /v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            token = _extract_csrf(r.text)
            if not token:
                r.failure("csrf not found in login form")
                return False
            self.csrf = token

        payload = {"username": self.username, "password": self.password, "csrf": self.csrf}
        with self.client.post("/v2/login", json=payload, name="POST /v2/login",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                url = urljoin(BASE_URL + "/", loc)
                with self.client.get(url, name="GET login redirect",
                                     catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code not in (200, 204):
                        r2.failure("redirect status %s" % r2.status_code)
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        data = {}
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                return True
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("login json parse")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            else:
                r.failure("login status %s" % r.status_code)
                return False

    def _headers(self, extra=None):
        h = {"X-CSRF-Token": self.csrf or ""}
        if extra:
            h.update(extra)
        return h

    def _renew(self):
        with self.client.post("/v2/session/renew", json={}, headers=self._headers(),
                              name="POST /v2/session/renew", catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    data = {}
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            r.failure("renew status %s" % r.status_code)
            return False

    def _recover_cart(self, cart_id):
        with self.client.post("/v2/carts/%s/recover" % cart_id, json={},
                              headers=self._headers(), name="POST /v2/carts/recover",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code in (200, 204):
                try:
                    data = r.json()
                except Exception:
                    data = {}
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            r.failure("recover status %s" % r.status_code)
            return False

    def _get_catalog_products(self):
        products = []
        # First page
        with self.client.get("/v2/catalog", name="GET /v2/catalog",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("catalog status %s" % r.status_code)
                return products
            try:
                data = r.json()
            except Exception:
                r.failure("catalog json")
                return products
            for p in (data.get("data", {}) or {}).get("products", []) or []:
                products.append(p)
            nxt = data.get("next")

        pages = 0
        while nxt and pages < 3:
            pages += 1
            url = urljoin(BASE_URL + "/", nxt)
            with self.client.get(url, name="GET /v2/catalog/page",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure("catalog page status %s" % r.status_code)
                    break
                try:
                    data = r.json()
                except Exception:
                    r.failure("catalog page json")
                    break
                # page returns one product plus next
                prod = data.get("product") or data.get("data")
                if isinstance(prod, dict) and prod.get("id") is not None:
                    products.append(prod)
                elif isinstance(data.get("data"), dict):
                    for p in (data["data"].get("products") or []):
                        products.append(p)
                nxt = data.get("next")
        return products

    def _pick_variant(self, products):
        for p in products:
            variants = p.get("variants") or []
            for v in variants:
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        return None, None

    def _maybe_challenge(self):
        # Attempt to obtain a grant_id via challenge flow.
        with self.client.get("/v2/challenge-form", name="GET /v2/challenge-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            html = r.text
            action_m = re.search(r"""action\s*=\s*["']([^"']+)["']""", html, re.IGNORECASE)
            if not action_m:
                r.failure("challenge action not found")
                return None
            action = action_m.group(1)
            cm = re.search(r"""<input\b[^>]*name\s*=\s*["']?challenge["']?[^>]*>""", html, re.IGNORECASE)
            challenge_val = None
            if cm:
                vm = re.search(r"""value\s*=\s*["']([^"']*)["']""", cm.group(0), re.IGNORECASE)
                if vm:
                    challenge_val = vm.group(1)
            if challenge_val is None:
                r.failure("challenge value not found")
                return None

        url = urljoin(BASE_URL + "/", action)
        with self.client.post(url, json={"challenge": challenge_val},
                              headers=self._headers(), name="POST /v2/challenges",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code != 302:
                r.failure("challenge post status %s" % r.status_code)
                return None
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge 302 no Location")
                return None
            loc_url = urljoin(BASE_URL + "/", loc)

        with self.client.get(loc_url, name="GET challenge Location",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge location status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("challenge location json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("grant_id")

    def _create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload, headers=self._headers(),
                              name="POST /v2/carts", catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 401:
                try:
                    err = r.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    if self._renew():
                        return self._create_cart(product_id, variant_id, grant_id)
                elif err == "session":
                    if self._login():
                        return self._create_cart(product_id, variant_id, grant_id)
                r.failure("cart 401 %s" % err)
                return None
            if r.status_code != 201:
                r.failure("cart status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("cart json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            etag = r.headers.get("ETag")
            return {"id": data.get("id"), "etag": etag}

    def _patch_quantity(self, cart_id, etag, qty):
        headers = self._headers({"If-Match": etag} if etag else None)
        with self.client.patch("/v2/carts/%s" % cart_id, json={"quantity": qty},
                               headers=headers, name="PATCH /v2/carts",
                               catch_response=True, allow_redirects=False) as r:
            if r.status_code == 412:
                # re-read and retry once
                with self.client.get("/v2/carts/%s" % cart_id, name="GET /v2/carts",
                                     catch_response=True, allow_redirects=False) as rg:
                    if rg.status_code != 200:
                        rg.failure("cart re-read status %s" % rg.status_code)
                        return False
                    new_etag = rg.headers.get("ETag")
                headers2 = self._headers({"If-Match": new_etag} if new_etag else None)
                with self.client.patch("/v2/carts/%s" % cart_id, json={"quantity": qty},
                                       headers=headers2, name="PATCH /v2/carts retry",
                                       catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code not in (200, 204):
                        r2.failure("patch retry status %s" % r2.status_code)
                        return False
                    try:
                        d = r2.json()
                        if d.get("csrf"):
                            self.csrf = d["csrf"]
                    except Exception:
                        pass
                    return True
            if r.status_code == 401:
                try:
                    err = r.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    if self._renew():
                        return self._patch_quantity(cart_id, etag, qty)
                elif err == "session":
                    if self._login():
                        self._recover_cart(cart_id)
                        return self._patch_quantity(cart_id, etag, qty)
                r.failure("patch 401 %s" % err)
                return False
            if r.status_code not in (200, 204):
                r.failure("patch status %s" % r.status_code)
                return False
            try:
                d = r.json()
                if d.get("csrf"):
                    self.csrf = d["csrf"]
            except Exception:
                pass
            return True

    def _reserve(self, cart_id):
        with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                              headers=self._headers(), name="POST /v2/reservations",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                try:
                    err = r.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    if self._renew():
                        return self._reserve(cart_id)
                elif err == "session":
                    if self._login():
                        self._recover_cart(cart_id)
                        return self._reserve(cart_id)
                r.failure("reservation 401 %s" % err)
                return None
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("reservation json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            status_url = data.get("status_url")
            if not status_url:
                r.failure("no status_url")
                return None

        url = urljoin(BASE_URL + "/", status_url)
        for attempt in range(5):
            time.sleep(0.06)
            with self.client.get(url, name="GET reservation status",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure("status poll %s" % r.status_code)
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("status json")
                    return None
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                st = data.get("status")
                if st == "ready":
                    return data.get("reservation_id")
                if st in ("pending",):
                    continue
                if st in ("failed",):
                    r.failure("reservation failed")
                    return None
        return None

    def _order(self, cart_id, reservation_id, etag):
        idem = "idem-%s-%s" % (cart_id, self.username)
        headers = self._headers({"Idempotency-Key": idem})
        if etag:
            headers["If-Match"] = etag
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        with self.client.post("/v2/orders", json=payload, headers=headers,
                              name="POST /v2/orders", catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 401:
                try:
                    err = r.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    if self._renew():
                        return self._order(cart_id, reservation_id, etag)
                elif err == "session":
                    if self._login():
                        self._recover_cart(cart_id)
                        return self._order(cart_id, reservation_id, etag)
                r.failure("order 401 %s" % err)
                return False
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    data = {}
                if data.get("accepted") is False:
                    r.failure("order business failure")
                    return False
            if r.status_code != 201:
                r.failure("order status %s" % r.status_code)
                return False
            try:
                data = r.json()
            except Exception:
                data = {}
            if not data.get("accepted"):
                r.failure("order not accepted")
                return False
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return True

    def _do_work(self):
        for _ in range(4):
            with self.client.post("/v2/work", json={}, headers=self._headers(),
                                  name="POST /v2/work", catch_response=True,
                                  allow_redirects=False) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    time.sleep(delay)
                    continue
                if r.status_code == 200:
                    return True
                if r.status_code == 401:
                    try:
                        err = r.json().get("error")
                    except Exception:
                        err = None
                    if err == "expired":
                        if self._renew():
                            continue
                    elif err == "session":
                        if self._login():
                            continue
                r.failure("work status %s" % r.status_code)
                return False
        return False

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self._login():
            raise StopUser()

        products = self._get_catalog_products()
        pid, vid = self._pick_variant(products)
        if pid is None:
            raise StopUser()

        grant_id = self._maybe_challenge()

        cart = self._create_cart(pid, vid, grant_id)
        if not cart or not cart.get("id"):
            raise StopUser()
        cart_id = cart["id"]
        etag = cart.get("etag")

        if not self._patch_quantity(cart_id, etag, 1):
            raise StopUser()

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            raise StopUser()

        if not self._order(cart_id, reservation_id, etag):
            raise StopUser()

        self._do_work()


class ShopShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        # 2 users, each does 2 iterations; stop after enough time.
        if run_time > 60:
            return None
        return (2, 2)
