import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    // ---- CSRF extraction: pick the real field, ignore decoys, no positional assumption ----
    // Real field: input[name=csrf] whose value is a token. Decoys may also be named csrf but
    // carry a decoy marker (e.g. value="decoy" / data-decoy). We select by name AND reject decoys.
    private static final Pattern INPUT_TAG = Pattern.compile("<input\\b[^>]*>", Pattern.CASE_INSENSITIVE);
    private static final Pattern ATTR = Pattern.compile("([a-zA-Z_:][-a-zA-Z0-9_:.]*)\\s*=\\s*\"([^\"]*)\"");
    private static final Pattern ATTR_SQ = Pattern.compile("([a-zA-Z_:][-a-zA-Z0-9_:.]*)\\s*=\\s*'([^']*)'");

    static String extractCsrf(String html) {
        if (html == null) return null;
        Matcher m = INPUT_TAG.matcher(html);
        while (m.find()) {
            String tag = m.group();
            Map<String, String> attrs = new HashMap<>();
            Matcher a = ATTR.matcher(tag);
            while (a.find()) attrs.put(a.group(1).toLowerCase(Locale.ROOT), a.group(2));
            Matcher b = ATTR_SQ.matcher(tag);
            while (b.find()) attrs.putIfAbsent(b.group(1).toLowerCase(Locale.ROOT), b.group(2));
            String name = attrs.get("name");
            if (name == null || !name.equals("csrf")) continue;
            String value = attrs.get("value");
            if (value == null || value.isEmpty()) continue;
            // reject decoys: explicit decoy markers
            if (attrs.containsKey("data-decoy")) continue;
            if ("decoy".equalsIgnoreCase(value)) continue;
            if (value.toLowerCase(Locale.ROOT).contains("decoy")) continue;
            return value;
        }
        return null;
    }

    // ---- JSON helpers (no extra libs) ----
    static String jsonStr(String body, String key) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\"");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1).replace("\\\"", "\"").replace("\\\\", "\\");
        return null;
    }

    static String jsonNum(String body, String key) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(-?\\d+)");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    static boolean jsonBool(String body, String key) {
        if (body == null) return false;
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(true|false)");
        Matcher m = p.matcher(body);
        return m.find() && "true".equals(m.group(1));
    }

    // ---- HTTP protocol ----
    HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json");

    // ---- Feeder: 2 users, 2 iterations each ----
    Iterator<Map<String, Object>> feeder = Stream.iterate(1, i -> i + 1)
            .limit(2)
            .map(i -> {
                Map<String, Object> m = new HashMap<>();
                m.put("username", "bench-" + i);
                m.put("password", "bench");
                return m;
            })
            .iterator();

    // ---- Scenario ----
    ScenarioBuilder scn = scenario("ModelSimulation")
            .feed(feeder)
            .exec(session -> session.set("csrf", "").set("sessionCsrf", "").set("cartId", "").set("etag", ""))
            // 1. GET login form
            .exec(http("GET /v2/login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(bodyString().saveAs("loginHtml")))
            .exec(session -> {
                String html = session.getString("loginHtml");
                String csrf = extractCsrf(html);
                if (csrf == null) {
                    throw new IllegalStateException("CSRF field not found in login form");
                }
                return session.set("csrf", csrf);
            })
            // 2. POST login
            .exec(http("POST /v2/login")
                    .post("/v2/login")
                    .body(StringBody(session -> {
                        String u = session.getString("username");
                        String p = session.getString("password");
                        String c = session.getString("csrf");
                        return "{\"username\":\"" + u + "\",\"password\":\"" + p + "\",\"csrf\":\"" + c + "\"}";
                    }))
                    .check(status().in(200, 302))
                    .check(bodyString().saveAs("loginBody")))
            .exec(session -> {
                String body = session.getString("loginBody");
                String csrf = jsonStr(body, "csrf");
                if (csrf != null) return session.set("sessionCsrf", csrf);
                return session;
            })
            // 3. GET catalog
            .exec(http("GET /v2/catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(bodyString().saveAs("catalogBody")))
            .exec(session -> {
                String body = session.getString("catalogBody");
                // parse first product id and first in_stock variant id
                String pid = null, vid = null;
                if (body != null) {
                    Pattern pp = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"[^}]*\"variants\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
                    Matcher pm = pp.matcher(body);
                    if (pm.find()) {
                        pid = pm.group(1);
                        String variants = pm.group(2);
                        Pattern vp = Pattern.compile("\\{[^}]*\"id\"\\s*:\\s*\"([^\"]+)\"[^}]*\"in_stock\"\\s*:\\s*(true|false)[^}]*\\}");
                        Matcher vm = vp.matcher(variants);
                        while (vm.find()) {
                            if ("true".equals(vm.group(2))) { vid = vm.group(1); break; }
                        }
                    }
                }
                if (pid == null || vid == null) {
                    throw new IllegalStateException("No in-stock product/variant found");
                }
                return session.set("productId", pid).set("variantId", vid);
            })
            // 4. POST cart
            .exec(http("POST /v2/carts")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", session -> session.getString("sessionCsrf"))
                    .body(StringBody(session -> {
                        String pid = session.getString("productId");
                        String vid = session.getString("variantId");
                        return "{\"product_id\":\"" + pid + "\",\"variant_id\":\"" + vid + "\"}";
                    }))
                    .check(status().is(201))
                    .check(header("ETag").saveAs("etag"))
                    .check(bodyString().saveAs("cartBody")))
            .exec(session -> {
                String body = session.getString("cartBody");
                String id = jsonStr(body, "id");
                String csrf = jsonStr(body, "csrf");
                if (id == null) throw new IllegalStateException("cart id missing");
                Session s = session.set("cartId", id);
                if (csrf != null) s = s.set("sessionCsrf", csrf);
                return s;
            })
            // 5. GET cart
            .exec(http("GET /v2/carts/{id}")
                    .get("/v2/carts/#{cartId}")
                    .check(status().is(200))
                    .check(header("ETag").saveAs("etag")))
            // 6. PATCH cart quantity
            .exec(http("PATCH /v2/carts/{id}")
                    .patch("/v2/carts/#{cartId}")
                    .header("X-CSRF-Token", session -> session.getString("sessionCsrf"))
                    .header("If-Match", session -> session.getString("etag"))
                    .body(StringBody("{\"quantity\":1}"))
                    .check(status().in(200, 412))
                    .check(bodyString().saveAs("patchBody")))
            .exec(session -> {
                String body = session.getString("patchBody");
                String csrf = jsonStr(body, "csrf");
                if (csrf != null) return session.set("sessionCsrf", csrf);
                return session;
            })
            // 7. POST order
            .exec(http("POST /v2/orders")
                    .post("/v2/orders")
                    .header("X-CSRF-Token", session -> session.getString("sessionCsrf"))
                    .header("Idempotency-Key", session -> "order-" + session.getString("cartId"))
                    .header("If-Match", session -> session.getString("etag"))
                    .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                    .check(status().is(201))
                    .check(bodyString().saveAs("orderBody")))
            .exec(session -> {
                String body = session.getString("orderBody");
                if (!jsonBool(body, "accepted")) {
                    throw new IllegalStateException("order not accepted");
                }
                String csrf = jsonStr(body, "csrf");
                if (csrf != null) return session.set("sessionCsrf", csrf);
                return session;
            });

    {
        setUp(
                scn.injectOpen(
                        rampUsers(2).during(Duration.ofSeconds(1))
                )
        ).protocols(httpProtocol);
    }
}
