import http from 'k6/http';
import { check, group } from 'k6';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

// Per-VU state
const state = {};

function jar() {
  if (!state.jar) state.jar = http.cookieJar();
  return state.jar;
}

function req(method, path, body, params) {
  params = params || {};
  params.jar = jar();
  params.redirects = 0;
  if (body !== null && body !== undefined && typeof body !== 'string') {
    params.headers = Object.assign({ 'Content-Type': 'application/json' }, params.headers || {});
    body = JSON.stringify(body);
  }
  return http.request(method, BASE + path, body, params);
}

// Extract CSRF from HTML: find input[name=csrf] regardless of attribute order,
// ignoring decoys (e.g. input[name=csrf_decoy], hidden decoys with other names).
function extractCsrf(html) {
  if (!html) return null;
  // Match any <input ...> tag
  const tagRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = tagRe.exec(html)) !== null) {
    const tag = m[0];
    const name = attrValue(tag, 'name');
    if (name !== 'csrf') continue;
    const val = attrValue(tag, 'value');
    if (val !== null && val !== undefined && val !== '') return val;
