function attrValue(tag, attr) {
  // attribute may appear in any order; support quoted and unquoted
  const re = new RegExp('\\b' + attr + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  const m = tag.match(re);
  if (!m) return null;
  return m[1] !== undefined ? m[1] : (m[2] !== undefined ? m[2] : m[3]);
}

function extractAction(html) {
  if (!html) return null;
  const formRe = /<form\b[^>]*>/gi;
  let m;
  while ((m = formRe.exec(html)) !== null) {
    const tag = m[0];
    const action = attrValue(tag, 'action');
    if (action) return action;
  }
  return null;
}

function extractChallenge(html) {
  if (!html) return null;
  const tagRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = tagRe.exec(html)) !== null) {
    const tag = m[0];
    const name = attrValue(tag, 'name');
    if (name !== 'challenge') continue;
    const val = attrValue(tag, 'value');
    if (val) return val;
  }
  return null;
