function parseJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function getCsrfFromBody(body) {
  if (!body) return null;
  if (typeof body === 'object' && body.csrf) return body.csrf;
  return null;
}

function login(username) {
  // Fresh login each journey
  const formRes = req('GET', '/v2/login-form');
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = extractCsrf(formRes.body);
  check(csrf, { 'login csrf extracted': (v) => !!v });
  if (!csrf) return null;

  const loginRes = req('POST', '/v2/login', { username: username, password: 'bench', csrf: csrf });
  let token = null;
  let user = null;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    check(loc, { 'login redirect location': (v) => !!v });
    if (loc) {
      const followRes = req('GET', loc.startsWith('http') ? loc.replace(BASE, '') : loc);
      const b = parseJson(followRes);
      token = getCsrfFromBody(b);
      user = b && b.user;
    }
