function handleExpiry(res, token, cartId) {
  const b = parseJson(res);
  if (res.status === 401 && b && b.error === 'expired') {
    let t = renewSession(token);
    if (cartId) t = recoverCart(cartId, t);
    return { expired: true, token: t };
  }
  if (res.status === 401 && b && b.error === 'session') {
