function collectProducts() {
  const products = [];
  // First page
  const r1 = req('GET', '/v2/catalog');
  const b1 = parseJson(r1);
  if (b1 && b1.data && b1.data.products) {
    for (const p of b1.data.products) products.push(p);
  }
  let next = b1 && b1.next;
  let pages = 1;
  while (next && pages < 3) {
    const path = next.startsWith('http') ? next.replace(BASE, '') : next;
    const r = req('GET', path);
    const b = parseJson(r);
    if (b && b.data && b.data.products) {
      for (const p of b.data.products) products.push(p);
    }
    next = b && b.next;
    pages++;
  }
  return products;
}

function pickVariant(product) {
  if (!product || !product.variants) return null;
  for (const v of product.variants) {
    if (v.in_stock) return v;
  }
  return product.variants[0] || null;
}

function doChallenge(token) {
  const formRes = req('GET', '/v2/challenge-form');
  const html = formRes.body;
  const action = extractAction(html);
  const challenge = extractChallenge(html);
  check(action, { 'challenge action': (v) => !!v });
  check(challenge, { 'challenge value': (v) => !!v });
