    const b = parseJson(followRes);
    grant = b && b.grant_id;
    t = getCsrfFromBody(b) || t;
  } else {
    const b = parseJson(postRes);
    grant = b && b.grant_id;
    t = getCsrfFromBody(b) || t;
  }
  return { grant_id: grant, token: t };
}

function createCart(product, variant, grantId, token) {
  const body = { product_id: product.id, variant_id: variant.id };
  if (grantId) body.grant_id = grantId;
  let res = req('POST', '/v2/carts', body, { headers: { 'X-CSRF-Token': token } });
  let h = handleExpiry(res, token, null);
  if (h.expired) {
    token = h.token;
    res = req('POST', '/v2/carts', body, { headers: { 'X-CSRF-Token': token } });
  }
  check(res, { 'cart created 201': (r) => r.status === 201 });
  const b = parseJson(res);
  const cartId = b && b.id;
  const fresh = getCsrfFromBody(b);
  return { cartId: cartId, token: fresh || token, etag: res.headers['Etag'] || res.headers['ETag'] };
