function patchQuantity(cartId, token, etag) {
  const payload = { quantity: 1 };
  let res = req('PATCH', '/v2/carts/' + cartId, payload, {
    headers: { 'X-CSRF-Token': token, 'If-Match': etag || '' },
  });
  if (res.status === 412) {
    const re = req('GET', '/v2/carts/' + cartId);
    const newEtag = re.headers['Etag'] || re.headers['ETag'];
    res = req('PATCH', '/v2/carts/' + cartId, payload, {
      headers: { 'X-CSRF-Token': token, 'If-Match': newEtag || '' },
    });
  }
  let h = handleExpiry(res, token, cartId);
  if (h.expired) {
    token = h.token;
    const re = req('GET', '/v2/carts/' + cartId);
    const newEtag = re.headers['Etag'] || re.headers['ETag'];
    res = req('PATCH', '/v2/carts/' + cartId, payload, {
      headers: { 'X-CSRF-Token': token, 'If-Match': newEtag || '' },
    });
  }
  check(res, { 'patch ok': (r) => r.status >= 200 && r.status < 300 });
  const b = parseJson(res);
  return { token: getCsrfFromBody(b) || token };
}

function reserve(cartId, token) {
  let res = req('POST', '/v2/reservations', { cart_id: cartId }, { headers: { 'X-CSRF-Token': token } });
  let h = handleExpiry(res, token, cartId);
  if (h.expired) {
    token = h.token;
    res = req('POST', '/v2/reservations', { cart_id: cartId }, { headers: { 'X-CSRF-Token': token } });
  }
  check(res, { 'reservation 202': (r) => r.status === 202 });
  const b = parseJson(res);
  const statusUrl = b && b.status_url;
  token = getCsrfFromBody(b) || token;
  if (!statusUrl) return { reservationId: null, token: token };

  let reservationId = null;
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      // poll at least 50ms apart
      const start = Date.now();
      while (Date.now() - start < 60) { /* busy wait */ }
    }
    const path = statusUrl.startsWith('http') ? statusUrl.replace(BASE, '') : statusUrl;
    const sr = req('GET', path);
    const sb = parseJson(sr);
    const status = sb && sb.status;
    if (status === 'ready') {
      reservationId = sb.reservation_id;
      token = getCsrfFromBody(sb) || token;
      break;
    }
    if (status === 'failed') break;
  }
  return { reservationId: reservationId, token: token };
}

function checkout(cartId, reservationId, token, etag) {
  const body = { cart_id: cartId };
  if (reservationId) body.reservation_id = reservationId;
  const idem = 'idem-' + cartId;
  const headers = { 'X-CSRF-Token': token, 'Idempotency-Key': idem };
  if (etag) headers['If-Match'] = etag;
  let res = req('POST', '/v2/orders', body, { headers: headers });
  let h = handleExpiry(res, token, cartId);
  if (h.expired) {
    token = h.token;
    headers['X-CSRF-Token'] = token;
    res = req('POST', '/v2/orders', body, { headers: headers });
  }
  check(res, {
    'order 201 accepted': (r) => {
      if (r.status !== 201) return false;
      const b = parseJson(r);
      return b && b.accepted === true;
    },
  });
  const b = parseJson(res);
  return { token: getCsrfFromBody(b) || token };
}

export default function () {
  const vu = __VU;
  state.username = 'bench-' + ((vu % 16) + 1);
  state.jar = http.cookieJar();

  group('journey', () => {
    const token0 = login(state.username);
    if (!token0) return;
    let token = token0;

    // Collect products
    const products = collectProducts();
    check(products, { 'products available': (p) => p.length > 0 });
    if (!products.length) return;
    const product = products[0];
    const variant = pickVariant(product);
    check(variant, { 'variant available': (v) => !!v });
    if (!variant) return;

    // Challenge for grant
    const ch = doChallenge(token);
    token = ch.token;

    // Create cart
    const cart = createCart(product, variant, ch.grant_id, token);
    token = cart.token;
    check(cart.cartId, { 'cart id': (v) => !!v });
    if (!cart.cartId) return;

    // Patch quantity
    const p = patchQuantity(cart.cartId, token, cart.etag);
    token = p.token;

    // Reserve
    const r = reserve(cart.cartId, token);
    token = r.token;

    // Checkout only if reservation ready (or no reservation required)
    if (r.reservationId) {
      checkout(cart.cartId, r.reservationId, token, cart.etag);
    } else {
      // No reservation_id: still attempt checkout per protocol (reservation optional)
      checkout(cart.cartId, null, token, cart.etag);
    }
  });
}
