                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    time.sleep(delay)
                    retries += 1
                    continue
                if resp.status_code == 401:
                    if self._handle_401(resp, lambda: True):
                        return True
                    return False
                resp.failure(f"work status {resp.status_code}")
                return False
        return False

    # ---------- journey ----------

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self.username:
            # pick a bench account deterministically per user
            idx = (id(self) % 16) + 1
            self.username = f"bench-{idx}"

        if not self._login():
            raise StopUser()

        products = self._get_catalog_products()
        self._traverse_pages(products)
        product_id, variant_id = self._pick_variant(products)
        if product_id is None:
            raise StopUser()

        grant_id = self._solve_challenge()

        cart = self._create_cart(product_id, variant_id, grant_id)
        if not cart:
            raise StopUser()
        cart_id, etag = cart

        if not self._patch_quantity(cart_id, etag, 1):
            raise StopUser()

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            raise StopUser()

        if not self._checkout(cart_id, etag, reservation_id):
            raise StopUser()

        self._do_work()


class ShopUser2(ShopUser):
    pass


class LoadTestShape:
    def tick(self):
        run_time = self.get_run_time()
        if run_time > 60:
            return None
        return (2, 2)
