import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile("name=\"csrf\"[^>]*value=\"([^\"]+)\"");
    private static final Pattern CSRF_INPUT_ALT = Pattern.compile("value=\"([^\"]+)\"[^>]*name=\"csrf\"");
    private static final Pattern CHALLENGE_ACTION = Pattern.compile("action=\"(/v2/challenges/[^\"]+)\"");
    private static final Pattern CHALLENGE_INPUT = Pattern.compile("name=\"challenge\"[^>]*value=\"([^\"]+)\"");
    private static final Pattern CHALLENGE_INPUT_ALT = Pattern.compile("value=\"([^\"]+)\"[^>]*name=\"challenge\"");

    private static String extractCsrf(String body) {
        if (body == null) return null;
        Matcher m = CSRF_INPUT.matcher(body);
        if (m.find()) return m.group(1);
        m = CSRF_INPUT_ALT.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractChallengeAction(String body) {
        if (body == null) return null;
        Matcher m = CHALLENGE_ACTION.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractChallenge(String body) {
        if (body == null) return null;
        Matcher m = CHALLENGE_INPUT.matcher(body);
        if (m.find()) return m.group(1);
        m = CHALLENGE_INPUT_ALT.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static final AtomicInteger IDEMPOTENCY_SEQ = new AtomicInteger(0);

    private HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    private static final String LOGIN_FORM = "GET /v2/login-form";
    private static final String LOGIN = "POST /v2/login";
    private static final String CATALOG = "GET /v2/catalog";
    private static final String CATALOG_PAGE = "GET /v2/catalog/page";
    private static final String CART_CREATE = "POST /v2/carts";
    private static final String CART_GET = "GET /v2/carts/{id}";
    private static final String CART_PATCH = "PATCH /v2/carts/{id}";
    private static final String ORDER = "POST /v2/orders";
    private static final String CHALLENGE_FORM = "GET /v2/challenge-form";
    private static final String CHALLENGE_POST = "POST /v2/challenges/{id}";
    private static final String RESERVATION = "POST /v2/reservations";
    private static final String RESERVATION_STATUS = "GET /v2/reservations/{id}";
    private static final String RENEW = "POST /v2/session/renew";
    private static final String RECOVER = "POST /v2/carts/{id}/recover";

    private ChainBuilder loginFlow() {
        return exec(
                http(LOGIN_FORM)
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginFormBody"))
        ).exec(session -> {
            String body = session.getString("loginFormBody");
            String csrf = extractCsrf(body);
            return session.set("csrf", csrf);
        }).exec(
                http(LOGIN)
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String user = session.getString("username");
                            String csrf = session.getString("csrf");
                            return "{\"username\":\"" + user + "\",\"password\":\"bench\",\"csrf\":\"" + csrf + "\"}";
                        }))
                        .check(status().in(200, 302))
                        .check(bodyString().saveAs("loginBody"))
        ).exec(session -> {
            String body = session.getString("loginBody");
            String csrf = extractCsrf(body);
            if (csrf != null) {
                return session.set("csrf", csrf);
            }
            return session;
        });
    }

    private ChainBuilder selectProduct() {
        return exec(
                http(CATALOG)
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(bodyString().saveAs("catalogBody"))
        ).exec(session -> {
            String body = session.getString("catalogBody");
            String productId = null;
            String variantId = null;
            if (body != null) {
                // find first product with an in_stock variant
                int pIdx = body.indexOf("\"products\"");
                if (pIdx >= 0) {
                    // simple scan: find "id":<num> then "variants" then in_stock true
                    Pattern prodPat = Pattern.compile("\"id\"\\s*:\\s*(\\d+)[^}]*?\"variants\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
                    Matcher pm = prodPat.matcher(body);
                    while (pm.find()) {
                        String pid = pm.group(1);
                        String variants = pm.group(2);
                        Pattern varPat = Pattern.compile("\"id\"\\s*:\\s*(\\d+)[^}]*?\"in_stock\"\\s*:\\s*(true|false)", Pattern.DOTALL);
                        Matcher vm = varPat.matcher(variants);
                        while (vm.find()) {
                            if ("true".equals(vm.group(2))) {
                                productId = pid;
                                variantId = vm.group(1);
                                break;
                            }
                        }
                        if (productId != null) break;
                    }
                }
            }
            return session.set("productId", productId).set("variantId", variantId);
        }).exec(session -> {
            if (session.getString("productId") == null) {
                throw new RuntimeException("No in-stock product found");
            }
            return session;
        });
    }

    private ChainBuilder challengeFlow() {
        return exec(
                http(CHALLENGE_FORM)
                        .get("/v2/challenge-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("challengeFormBody"))
        ).exec(session -> {
            String body = session.getString("challengeFormBody");
            String action = extractChallengeAction(body);
            String challenge = extractChallenge(body);
            return session.set("challengeAction", action).set("challengeValue", challenge);
        }).exec(
                http(CHALLENGE_POST)
                        .post(session -> session.getString("challengeAction"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> "{\"challenge\":\"" + session.getString("challengeValue") + "\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").saveAs("challengeLocation"))
        ).exec(
                http("GET challenge location")
                        .get(session -> session.getString("challengeLocation"))
                        .check(status().is(200))
                        .check(bodyString().saveAs("grantBody"))
        ).exec(session -> {
            String body = session.getString("grantBody");
            String grantId = null;
            if (body != null) {
                Matcher m = Pattern.compile("\"grant_id\"\\s*:\\s*\"?([^\"\\s,}]+)\"?").matcher(body);
                if (m.find()) grantId = m.group(1);
            }
            String csrf = extractCsrf(body);
            Session s = session.set("grantId", grantId);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        });
    }

    private ChainBuilder createCart() {
        return exec(
                http(CART_CREATE)
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> {
                            String pid = session.getString("productId");
                            String vid = session.getString("variantId");
                            String grant = session.getString("grantId");
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"product_id\":").append(pid).append(",\"variant_id\":").append(vid);
                            if (grant != null) sb.append(",\"grant_id\":\"").append(grant).append("\"");
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().is(201))
                        .check(bodyString().saveAs("cartBody"))
                        .check(header("ETag").saveAs("cartEtag"))
        ).exec(session -> {
            String body = session.getString("cartBody");
            String cartId = null;
            String csrf = null;
            if (body != null) {
                Matcher m = Pattern.compile("\"id\"\\s*:\\s*\"?([^\"\\s,}]+)\"?").matcher(body);
                if (m.find()) cartId = m.group(1);
                csrf = extractCsrf(body);
            }
            Session s = session.set("cartId", cartId);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        });
    }

    private ChainBuilder patchCart() {
        return exec(
                http(CART_GET)
                        .get(session -> "/v2/carts/" + session.getString("cartId"))
                        .check(status().is(200))
                        .check(header("ETag").saveAs("cartEtag"))
        ).exec(
                http(CART_PATCH)
                        .patch(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> session.getString("cartEtag"))
                        .body(StringBody("{\"quantity\":1}"))
                        .check(status().in(200, 412))
                        .check(bodyString().saveAs("patchBody"))
        ).exec(session -> {
            String body = session.getString("patchBody");
            String csrf = extractCsrf(body);
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    private ChainBuilder reservationFlow() {
        return exec(
                http(RESERVATION)
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                        .check(status().is(202))
                        .check(bodyString().saveAs("resBody"))
        ).exec(session -> {
            String body = session.getString("resBody");
            String statusUrl = null;
            String csrf = null;
            if (body != null) {
                Matcher m = Pattern.compile("\"status_url\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                if (m.find()) statusUrl = m.group(1);
                csrf = extractCsrf(body);
            }
            Session s = session.set("statusUrl", statusUrl);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        }).asLongAs(session -> {
            String status = session.getString("resStatus");
            return status == null || "pending".equals(status);
        }, counter("pollCount").isLessThan(5)).on(
                pause(Duration.ofMillis(60)).exec(
                        http(RESERVATION_STATUS)
                                .get(session -> session.getString("statusUrl"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("statusBody"))
                ).exec(session -> {
                    String body = session.getString("statusBody");
                    String status = null;
                    String resId = null;
                    String csrf = null;
                    if (body != null) {
                        Matcher m = Pattern.compile("\"status\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (m.find()) status = m.group(1);
                        Matcher m2 = Pattern.compile("\"reservation_id\"\\s*:\\s*\"?([^\"\\s,}]+)\"?").matcher(body);
                        if (m2.find()) resId = m2.group(1);
                        csrf = extractCsrf(body);
                    }
                    Session s = session.set("resStatus", status);
                    if (resId != null) s = s.set("reservationId", resId);
                    if (csrf != null) s = s.set("csrf", csrf);
                    return s;
                })
        ).exec(session -> {
            if (!"ready".equals(session.getString("resStatus"))) {
                throw new RuntimeException("Reservation not ready: " + session.getString("resStatus"));
            }
            return session;
        });
    }

    private ChainBuilder checkout() {
        return exec(
                http(ORDER)
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> "idem-" + session.getString("cartId") + "-" + IDEMPOTENCY_SEQ.incrementAndGet())
                        .header("If-Match", session -> session.getString("cartEtag"))
                        .body(StringBody(session -> {
                            String cartId = session.getString("cartId");
                            String resId = session.getString("reservationId");
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"cart_id\":\"").append(cartId).append("\"");
                            if (resId != null) sb.append(",\"reservation_id\":\"").append(resId).append("\"");
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().is(201))
                        .check(bodyString().saveAs("orderBody"))
        ).exec(session -> {
            String body = session.getString("orderBody");
            if (body == null || !body.contains("\"accepted\":true")) {
                throw new RuntimeException("Order not accepted: " + body);
            }
            return session;
        });
    }

    private ScenarioBuilder scenario(String name) {
        return scenario(name)
                .exec(session -> session.set("username", session.getString("username")))
                .exec(loginFlow())
                .exec(selectProduct())
                .exec(challengeFlow())
                .exec(createCart())
                .exec(patchCart())
                .exec(reservationFlow())
                .exec(checkout());
    }

    {
        List<ScenarioBuilder> scenarios = new ArrayList<>();
        for (int i = 1; i <= 2; i++) {
            final int idx = i;
            scenarios.add(scenario("user-" + idx)
                    .exec(session -> session.set("username", "bench-" + idx)));
        }

        setUp(
                scenarios.get(0).injectOpen(atOnceUsers(1)),
                scenarios.get(1).injectOpen(atOnceUsers(1))
        ).protocols(httpProtocol);
    }
}
