import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function parseCsrfFromForm(body) {
  // find input[name=csrf] value, tolerate attribute variants/order
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(body)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?csrf["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function getCookieJar() {
  return http.cookieJar();
}

function login(username) {
  const jar = getCookieJar();
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrfFromForm(formRes.body || '');
  check(csrf, { 'csrf parsed': (v) => !!v });

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );

  let token = csrf;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      if (follow.status === 200 && follow.body) {
        try {
          const j = JSON.parse(follow.body);
          if (j.csrf) token = j.csrf;
        } catch (e) {}
      }
    }
  } else if (loginRes.status === 200 && loginRes.body) {
    try {
      const j = JSON.parse(loginRes.body);
      if (j.csrf) token = j.csrf;
    } catch (e) {}
  }
  check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  return token;
}

function fetchCatalog() {
  const res = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  try {
    const j = JSON.parse(res.body);
    return (j.data && j.data.products) || [];
  } catch (e) {
    return [];
  }
}

function fetchCatalogPage(url) {
  const res = http.get(url.startsWith('http') ? url : `${BASE}${url}`, { redirects: 0 });
  check(res, { 'catalog page 200': (r) => r.status === 200 });
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function selectEligible(products) {
  for (const p of products) {
    if (!p || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (v && v.in_stock === true) {
        return { product_id: p.id, variant_id: v.id };
      }
    }
  }
  return null;
}

function findEligibleAcrossPages() {
  let products = fetchCatalog();
  let sel = selectEligible(products);
  if (sel) return sel;

  // traverse up to 3 pages
  let next = null;
  // first page from /v2/catalog/page
  let page = fetchCatalogPage(`${BASE}/v2/catalog/page`);
  let pages = 0;
  while (page && pages < 3) {
    pages++;
    const list = page.data && page.data.products ? page.data.products : (page.product ? [page.product] : []);
    sel = selectEligible(list);
    if (sel) return sel;
    next = page.next;
    if (!next) break;
    page = fetchCatalogPage(next);
  }
  return null;
}

function createCart(product_id, variant_id, csrf, grant_id) {
  const payload = { product_id, variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(res, { 'cart 201': (r) => r.status === 201 });
  let body = {};
  try { body = JSON.parse(res.body); } catch (e) {}
  return { id: body.id, csrf: body.csrf || csrf, etag: res.headers['Etag'] || res.headers['ETag'] };
}

function getCart(cartId) {
  const res = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
  check(res, { 'cart get 200': (r) => r.status === 200 });
  return { etag: res.headers['Etag'] || res.headers['ETag'], body: res.body };
}

function patchCart(cartId, quantity, csrf, etag) {
  const payload = JSON.stringify({ quantity });
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
  if (etag) headers['If-Match'] = etag;
  let res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, { headers, redirects: 0 });
  if (res.status === 412) {
    const fresh = getCart(cartId);
    headers['If-Match'] = fresh.etag;
    res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, { headers, redirects: 0 });
  }
  check(res, { 'cart patch ok': (r) => r.status === 200 || r.status === 204 });
  let body = {};
  try { body = JSON.parse(res.body); } catch (e) {}
  return { csrf: body.csrf || csrf, etag: res.headers['Etag'] || res.headers['ETag'] };
}

function createOrder(cartId, csrf, etag, idemKey) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify({ cart_id: cartId }), {
    headers,
    redirects: 0,
  });
  let body = {};
  try { body = JSON.parse(res.body); } catch (e) {}
  check(res, {
    'order 201 accepted': (r) => r.status === 201 && body.accepted === true,
  });
  return { status: res.status, body };
}

export default function () {
  const vu = __VU;
  const username = `bench-${((vu - 1) % 16) + 1}`;

  const csrf0 = login(username);

  const sel = findEligibleAcrossPages();
  check(sel, { 'eligible product selected': (v) => !!v });
  if (!sel) return;

  const cart = createCart(sel.product_id, sel.variant_id, csrf0, null);
  check(cart, { 'cart created': (c) => !!c.id });
  if (!cart.id) return;

  const patched = patchCart(cart.id, 1, cart.csrf, cart.etag);

  const idemKey = `order-${username}-${cart.id}-${Date.now()}`;
  const order = createOrder(cart.id, patched.csrf, patched.etag, idemKey);
  check(order, { 'order committed': (o) => o.status === 201 && o.body.accepted === true });

  sleep(0.05);
}
