import os
import re
import time
import json
import random
from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ["BASE_URL"]

CSRF_INPUT_RE = re.compile(
    r'<input[^>]*name\s*=\s*["\']?csrf["\']?[^>]*>', re.IGNORECASE
)
VALUE_RE = re.compile(r'value\s*=\s*["\']([^"\']*)["\']', re.IGNORECASE)


def extract_csrf(html):
    m = CSRF_INPUT_RE.search(html)
    if not m:
        return None
    v = VALUE_RE.search(m.group(0))
    return v.group(1) if v else None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.iterations_done = 0
        self.max_iterations = 2
        self.username = None
        self.csrf = None
        self.session_ok = False

    # ---------- helpers ----------
    def _login(self):
        # pick account
        if self.username is None:
            self.username = "bench-%d" % random.randint(1, 16)
        # GET login form
        with self.client.get("/v2/login-form", name="/v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = extract_csrf(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return False
            self.csrf = csrf
        # POST login
        with self.client.post("/v2/login",
                              json={"username": self.username,
                                    "password": "bench",
                                    "csrf": self.csrf},
                              name="/v2/login",
                              catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(loc, name="/v2/login-redirect",
                                     catch_response=True,
                                     allow_redirects=False) as r2:
                    if r2.status_code not in (200, 201):
                        r2.failure("redirect status %s" % r2.status_code)
                        return False
                    try:
                        body = r2.json()
                    except Exception:
                        r2.failure("redirect not json")
                        return False
                    if body.get("csrf"):
                        self.csrf = body["csrf"]
            elif r.status_code in (200, 201):
                try:
                    body = r.json()
                except Exception:
                    r.failure("login not json")
                    return False
                if body.get("csrf"):
                    self.csrf = body["csrf"]
            else:
                r.failure("login status %s" % r.status_code)
                return False
        self.session_ok = True
        return True

    def _headers(self, extra=None):
        h = {"X-CSRF-Token": self.csrf or ""}
        if extra:
            h.update(extra)
        return h

    def _renew(self):
        with self.client.post("/v2/session/renew", json={},
                              headers=self._headers(),
                              name="/v2/session/renew",
                              catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code in (200, 201):
                try:
                    body = r.json()
                except Exception:
                    r.failure("renew not json")
                    return False
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return True
            r.failure("renew status %s" % r.status_code)
            return False

    def _recover_cart(self, cart_id):
        with self.client.post("/v2/carts/%s/recover" % cart_id, json={},
                              headers=self._headers(),
                              name="/v2/carts/[id]/recover",
                              catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code in (200, 201):
                try:
                    body = r.json()
                except Exception:
                    pass
                else:
                    if body.get("csrf"):
                        self.csrf = body["csrf"]
                return True
            r.failure("recover status %s" % r.status_code)
            return False

    def _select_product(self):
        """Return (product_id, variant_id) from catalog, in-stock, parent-specific."""
        # Try paged catalog first (up to 3 pages)
        url = "/v2/catalog/page"
        pages = 0
        while url and pages < 3:
            pages += 1
            with self.client.get(url, name="/v2/catalog/page",
                                 catch_response=True,
                                 allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure("catalog page status %s" % r.status_code)
                    return None
                try:
                    body = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    return None
            prod = body.get("product") or body.get("data")
            if isinstance(prod, dict) and "products" in prod:
                prods = prod["products"]
            elif isinstance(prod, dict) and "id" in prod:
                prods = [prod]
            elif isinstance(prod, list):
                prods = prod
            else:
                prods = []
            for p in prods:
                sel = self._pick_variant(p)
                if sel:
                    return sel
            nxt = body.get("next")
            if not nxt:
                break
            url = nxt if nxt.startswith("/") else "/" + nxt.lstrip("/")
        # Fallback to full catalog
        with self.client.get("/v2/catalog", name="/v2/catalog",
                             catch_response=True,
                             allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("catalog status %s" % r.status_code)
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("catalog not json")
                return None
        data = body.get("data") or {}
        prods = data.get("products") or []
        for p in prods:
            sel = self._pick_variant(p)
            if sel:
                return sel
        return None

    def _pick_variant(self, product):
        if not isinstance(product, dict):
            return None
        pid = product.get("id")
        variants = product.get("variants") or []
        if pid is None:
            return None
        for v in variants:
            if isinstance(v, dict) and v.get("in_stock") and v.get("id") is not None:
                return (pid, v["id"])
        return None

    def _solve_challenge(self):
        with self.client.get("/v2/challenge-form", name="/v2/challenge-form",
                             catch_response=True,
                             allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            html = r.text
        m = re.search(r'action\s*=\s*["\']([^"\']*challenges[^"\']*)["\']', html, re.IGNORECASE)
        if not m:
            r.failure("no challenge action")
            return None
        action = m.group(1)
        if not action.startswith("/"):
            action = "/" + action.lstrip("/")
        cm = re.search(r'name\s*=\s*["\']?challenge["\']?[^>]*value\s*=\s*["\']([^"\']*)["\']', html, re.IGNORECASE)
        if not cm:
            cm = re.search(r'value\s*=\s*["\']([^"\']*)["\'][^>]*name\s*=\s*["\']?challenge["\']?', html, re.IGNORECASE)
        if not cm:
            r.failure("no challenge value")
            return None
        challenge = cm.group(1)
        with self.client.post(action, json={"challenge": challenge},
                              headers=self._headers(),
                              name="/v2/challenges/[id]",
                              catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code != 302:
                r.failure("challenge post status %s" % r.status_code)
                return None
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge 302 no Location")
                return None
        if not loc.startswith("/"):
            loc = "/" + loc.lstrip("/")
        with self.client.get(loc, name="/v2/challenge-claim",
                             catch_response=True,
                             allow_redirects=False) as r:
            if r.status_code not in (200, 201):
                r.failure("claim status %s" % r.status_code)
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("claim not json")
                return None
        if body.get("csrf"):
            self.csrf = body["csrf"]
        return body.get("grant_id")

    def _create_cart(self, pid, vid, grant_id):
        payload = {"product_id": pid, "variant_id": vid}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload,
                              headers=self._headers(),
                              name="/v2/carts",
                              catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 401:
                try:
                    err = r.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    r.success()
                    if self._renew():
                        return self._create_cart(pid, vid, grant_id)
                r.failure("cart create 401 %s" % err)
                return None
            if r.status_code != 201:
                r.failure("cart create status %s" % r.status_code)
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("cart create not json")
                return None
        if body.get("csrf"):
            self.csrf = body["csrf"]
        etag = r.headers.get("ETag")
        return (body.get("id"), etag)

    def _patch_quantity(self, cart_id, etag, qty):
        headers = self._headers({"If-Match": etag} if etag else None)
        with self.client.patch("/v2/carts/%s" % cart_id,
                               json={"quantity": qty},
                               headers=headers,
                               name="/v2/carts/[id]",
                               catch_response=True,
                               allow_redirects=False) as r:
            if r.status_code == 412:
                r.success()
                # re-read
                with self.client.get("/v2/carts/%s" % cart_id,
                                     name="/v2/carts/[id]",
                                     catch_response=True,
                                     allow_redirects=False) as rg:
                    if rg.status_code != 200:
                        rg.failure("cart re-read status %s" % rg.status_code)
                        return None
                    new_etag = rg.headers.get("ETag")
                headers2 = self._headers({"If-Match": new_etag} if new_etag else None)
                with self.client.patch("/v2/carts/%s" % cart_id,
                                       json={"quantity": qty},
                                       headers=headers2,
                                       name="/v2/carts/[id]",
                                       catch_response=True,
                                       allow_redirects=False) as r2:
                    if r2.status_code not in (200, 204):
                        r2.failure("cart patch retry status %s" % r2.status_code)
                        return None
                    try:
                        b = r2.json()
                        if b.get("csrf"):
                            self.csrf = b["csrf"]
                    except Exception:
                        pass
                    return r2.headers.get("ETag") or new_etag
            if r.status_code not in (200, 204):
                r.failure("cart patch status %s" % r.status_code)
                return None
            try:
                b = r.json()
                if b.get("csrf"):
                    self.csrf = b["csrf"]
            except Exception:
                pass
            return r.headers.get("ETag") or etag

    def _reserve(self, cart_id):
        with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                              headers=self._headers(),
                              name="/v2/reservations",
                              catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("reservation not json")
                return None
        if body.get("csrf"):
            self.csrf = body["csrf"]
        status_url = body.get("status_url")
        if not status_url:
            r.failure("no status_url")
            return None
        if not status_url.startswith("/"):
            status_url = "/" + status_url.lstrip("/")
        for _ in range(5):
            time.sleep(0.06)
            with self.client.get(status_url, name="/v2/reservations/status",
                                 catch_response=True,
                                 allow_redirects=False) as rs:
                if rs.status_code != 200:
                    rs.failure("res status %s" % rs.status_code)
                    return None
                try:
                    sb = rs.json()
                except Exception:
                    rs.failure("res status not json")
                    return None
            st = sb.get("status")
            if st == "ready":
                rid = sb.get("reservation_id")
                if not rid:
                    rs.failure("ready without reservation_id")
                    return None
                return rid
            if st in ("pending",):
                continue
            # failed
            rs.failure("reservation status %s" % st)
            return None
        return None

    def _checkout(self, cart_id, reservation_id, etag):
        headers = self._headers({"Idempotency-Key": "cart-%s" % cart_id})
        if etag:
            headers["If-Match"] = etag
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        with self.client.post("/v2/orders", json=payload,
                              headers=headers,
                              name="/v2/orders",
                              catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 401:
                try:
                    err = r.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    r.success()
                    if self._renew():
                        self._recover_cart(cart_id)
                        return self._checkout(cart_id, reservation_id, etag)
                r.failure("order 401 %s" % err)
                return False
            if r.status_code != 201:
                r.failure("order status %s" % r.status_code)
                return False
            try:
                body = r.json()
            except Exception:
                r.failure("order not json")
                return False
        if body.get("accepted") is not True:
            r.failure("order not accepted")
            return False
        if not body.get("id"):
            r.failure("order no id")
            return False
        if body.get("csrf"):
            self.csrf = body["csrf"]
        return True

    def _do_work(self):
        for attempt in range(5):
            with self.client.post("/v2/work", json={},
                                  headers=self._headers(),
                                  name="/v2/work",
                                  catch_response=True,
                                  allow_redirects=False) as r:
                if r.status_code == 429:
                    r.success()
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    time.sleep(delay)
                    continue
                if r.status_code == 200:
                    try:
                        b = r.json()
                    except Exception:
                        r.failure("work not json")
                        return
                    if b.get("ok") is True:
                        return
                    r.failure("work not ok")
                    return
                r.failure("work status %s" % r.status_code)
                return

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self._login():
            raise StopUser()

        sel = self._select_product()
        if not sel:
            raise StopUser()
        pid, vid = sel

        grant_id = self._solve_challenge()

        cart = self._create_cart(pid, vid, grant_id)
        if not cart:
            raise StopUser()
        cart_id, etag = cart

        qty = random.randint(1, 5)
        new_etag = self._patch_quantity(cart_id, etag, qty)
        if new_etag is None:
            raise StopUser()

        rid = self._reserve(cart_id)
        if not rid:
            raise StopUser()

        if not self._checkout(cart_id, rid, new_etag):
            raise StopUser()

        self._do_work()

        if self.iterations_done >= self.max_iterations:
            raise StopUser()


