import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "name=\"csrf\"[^>]*value=\"([^\"]+)\"|value=\"([^\"]+)\"[^>]*name=\"csrf\"");
    private static final Pattern ACTION = Pattern.compile("action=\"(/v2/challenges/[^\"]+)\"");

    private static String extractCsrf(String body) {
        if (body == null) return null;
        Matcher m = CSRF_INPUT.matcher(body);
        if (m.find()) return m.group(1) != null ? m.group(1) : m.group(2);
        return null;
    }

    private static String extractAction(String body) {
        if (body == null) return null;
        Matcher m = ACTION.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static final AtomicInteger SEED = new AtomicInteger(0);

    private static String nextUser() {
        int n = SEED.incrementAndGet();
        int idx = ((n - 1) % 16) + 1;
        return "bench-" + idx;
    }

    private final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    private static final String LOGIN_FORM = "login-form";
    private static final String LOGIN = "login";
    private static final String CATALOG = "catalog";
    private static final String CATALOG_PAGE = "catalog-page";
    private static final String CART_CREATE = "cart-create";
    private static final String CART_GET = "cart-get";
    private static final String CART_PATCH = "cart-patch";
    private static final String ORDER = "order";
    private static final String CHALLENGE_FORM = "challenge-form";
    private static final String CHALLENGE_POST = "challenge-post";
    private static final String CHALLENGE_GET = "challenge-get";
    private static final String RESERVATION = "reservation";
    private static final String RESERVATION_POLL = "reservation-poll";
    private static final String RENEW = "renew";
    private static final String RECOVER = "recover";
    private static final String WORK = "work";

    private static final int MAX_PAGES = 3;
    private static final int MAX_POLLS = 5;
    private static final int MAX_WORK_RETRIES = 4;

    private ChainBuilder loginFlow() {
        return exec(
                http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginFormBody"))
        ).exec(session -> {
            String csrf = extractCsrf(session.getString("loginFormBody"));
            return session.set("csrf", csrf);
        }).exec(
                http("login")
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String user = session.getString("username");
                            String csrf = session.getString("csrf");
                            return "{\"username\":\"" + user + "\",\"password\":\"bench\",\"csrf\":\"" + csrf + "\"}";
                        }))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginBody"))
        ).exec(session -> {
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginRedirect", loc);
            }
            return session;
        }).doIf(session -> session.getString("loginRedirect") != null).then(
                exec(
                        http("login-redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("loginBody2"))
                ).exec(session -> {
                    String csrf = extractCsrf(session.getString("loginBody2"));
                    if (csrf != null) return session.set("csrf", csrf);
                    return session;
                })
        ).exec(session -> {
            String body = session.getString("loginBody");
            if (body != null) {
                String csrf = extractCsrf(body);
                if (csrf != null) return session.set("csrf", csrf);
            }
            return session;
        });
    }

    private ChainBuilder catalogFlow() {
        return exec(
                http("catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[*]").findAll().optional().saveAs("products"))
                        .check(jsonPath("$.next").optional().saveAs("catalogNext"))
        ).exec(session -> {
            List<String> products = session.getList("products");
