                                .check(jsonPath("$.data.products[*]").findAll().optional().saveAs("pageProducts"))
                                .check(jsonPath("$.next").optional().saveAs("pageNext"))
                ).exec(session -> {
                    List<String> pageProducts = session.getList("pageProducts");
                    int pc = session.getInt("pageCount") + 1;
                    if (pageProducts != null && !pageProducts.isEmpty()) {
                        return session.set("products", pageProducts).set("catalogDone", true).set("pageCount", pc);
                    }
                    String next = session.getString("pageNext");
                    if (next == null || next.isEmpty() || "null".equals(next)) {
                        return session.set("catalogDone", true).set("pageCount", pc);
