    private ChainBuilder challengeFlow() {
        return exec(
                http("challenge-form")
                        .get("/v2/challenge-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("challengeFormBody"))
        ).exec(session -> {
            String action = extractAction(session.getString("challengeFormBody"));
            String csrf = extractCsrf(session.getString("challengeFormBody"));
            if (csrf != null) session = session.set("csrf", csrf);
