                                .check(status().in(200, 302))
                                .check(header("Location").optional().saveAs("challengeLocation"))
                ).doIf(session -> session.getString("challengeLocation") != null).then(
                        exec(
                                http("challenge-get")
                                        .get(session -> session.getString("challengeLocation"))
                                        .check(status().is(200))
                                        .check(jsonPath("$.grant_id").optional().saveAs("grantId"))
                                        .check(jsonPath("$.csrf").optional().saveAs("challengeCsrf"))
                        ).exec(session -> {
                            String csrf = session.getString("challengeCsrf");
                            if (csrf != null) return session.set("csrf", csrf);
                            return session;
                        })
                )
        );
    }

    private ChainBuilder cartFlow() {
        return exec(
                http("cart-create")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> {
