        }).exec(session -> session.set("pollCount", 0).set("reservationReady", false))
                .asLongAs(session -> !Boolean.TRUE.equals(session.get("reservationReady"))
                        && session.getInt("pollCount") < MAX_POLLS).on(
                        pause(Duration.ofMillis(60)).exec(
                                http("reservation-poll")
                                        .get(session -> session.getString("statusUrl"))
                                        .check(status().is(200))
                                        .check(jsonPath("$.status").optional().saveAs("resStatus"))
                                        .check(jsonPath("$.reservation_id").optional().saveAs("reservationId"))
                        ).exec(session -> {
                            int pc = session.getInt("pollCount") + 1;
                            String st = session.getString("resStatus");
                            if ("ready".equals(st)) {
                                return session.set("pollCount", pc).set("reservationReady", true);
                            }
                            if ("failed".equals(st)) {
                                return session.set("pollCount", pc).set("reservationReady", true).set("reservationFailed", true);
                            }
                            return session.set("pollCount", pc);
                        })
                );
    }

    private ChainBuilder orderFlow() {
        return exec(
                http("order")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                        .header("If-Match", session -> {
                            String et = session.getString("cartEtag");
                            return et != null ? et : "*";
                        })
                        .body(StringBody(session -> {
                            String rid = session.getString("reservationId");
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"cart_id\":\"").append(session.getString("cartId")).append("\"");
                            if (rid != null && !rid.isEmpty()) {
                                sb.append(",\"reservation_id\":\"").append(rid).append("\"");
                            }
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().is(201))
                        .check(jsonPath("$.accepted").is("true"))
                        .check(jsonPath("$.id").saveAs("orderId"))
                        .check(jsonPath("$.csrf").optional().saveAs("orderCsrf"))
        ).exec(session -> {
            String csrf = session.getString("orderCsrf");
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    private ChainBuilder workFlow() {
        return exec(session -> session.set("workRetries", 0))
                .asLongAs(session -> session.getInt("workRetries") <= MAX_WORK_RETRIES
                        && !Boolean.TRUE.equals(session.get("workDone"))).on(
                        exec(
                                http("work")
                                        .post("/v2/work")
                                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                                        .body(StringBody("{}"))
                                        .check(status().in(200, 429))
                                        .check(jsonPath("$.ok").optional().saveAs("workOk"))
                                        .check(header("Retry-After").optional().saveAs("retryAfter"))
                        ).exec(session -> {
                            Object st = session.get("work.status");
                            int retries = session.getInt("workRetries");
                            if (st != null && st.toString().equals("200")) {
                                return session.set("workDone", true);
                            }
                            if (st != null && st.toString().equals("429")) {
                                return session.set("workRetries", retries + 1);
                            }
                            return session.set("workRetries", retries + 1);
                        }).doIf(session -> {
                            Object st = session.get("work.status");
                            return st != null && st.toString().equals("429");
                        }).then(pause(Duration.ofSeconds(1)))
                );
    }

    private ScenarioBuilder scenario() {
        return scenario("ModelSimulation")
                .exec(session -> session
                        .set("username", nextUser())
                        .set("csrf", "")
                        .set("loginRedirect", null)
                        .set("grantId", null)
                        .set("reservationId", null)
                        .set("reservationFailed", false))
                .exec(loginFlow())
                .exec(catalogFlow())
                .exec(session -> {
                    List<String> products = session.getList("products");
                    if (products == null || products.isEmpty()) {
                        return session.markAsFailed();
                    }
                    String first = products.get(0);
                    String pid = null;
                    String vid = null;
                    try {
                        com.fasterxml.jackson.databind.JsonNode node = null;
                    } catch (Throwable t) {
                        // ignore
                    }
                    // products are JSON strings; parse minimal
                    pid = extractJsonField(first, "id");
                    String variants = extractJsonArray(first, "variants");
                    if (variants != null) {
                        vid = extractJsonField(variants, "id");
                    }
                    if (pid == null || vid == null) {
                        return session.markAsFailed();
                    }
                    return session.set("productId", pid).set("variantId", vid);
                })
                .exec(challengeFlow())
                .exec(cartFlow())
                .exec(patchFlow())
                .exec(reservationFlow())
                .doIf(session -> !Boolean.TRUE.equals(session.get("reservationFailed"))).then(
                        exec(orderFlow())
                )
                .exec(workFlow());
    }

    private static String extractJsonField(String json, String field) {
        if (json == null) return null;
        Pattern p = Pattern.compile("\"" + field + "\"\\s*:\\s*\"([^\"]+)\"");
        Matcher m = p.matcher(json);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractJsonArray(String json, String field) {
        if (json == null) return null;
        int idx = json.indexOf("\"" + field + "\"");
        if (idx < 0) return null;
        int start = json.indexOf('[', idx);
        if (start < 0) return null;
        int depth = 0;
        for (int i = start; i < json.length(); i++) {
            char c = json.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) return json.substring(start, i + 1);
            }
        }
        return null;
    }

    {
        setUp(
                scenario().injectOpen(
                        rampUsers(2).during(Duration.ofSeconds(1))
                )
        ).protocols(httpProtocol);
    }
}
