import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const USERS = new SharedArray('users', function () {
  return ['bench-1', 'bench-2'];
});

function parseCsrf(html) {
  // find input[name=csrf] value, tolerate attribute variants
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?csrf["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseChallengeForm(html) {
  const actionM = html.match(/<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i);
  const action = actionM ? actionM[1] : null;
  let challenge = null;
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?challenge["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) { challenge = vm[1]; break; }
  }
  return { action, challenge };
}

function absUrl(u) {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.startsWith('/')) return BASE + u;
  return BASE + '/' + u;
}

function jarFor(user) {
  return http.cookieJar();
}

function login(user) {
  const jar = http.cookieJar();
  // fresh login: clear cookies by using a new jar per journey is not directly supported;
  // we rely on server session semantics. We'll just perform login.
  const formRes = http.get(BASE + '/v2/login-form', { redirects: 0, tags: { name: 'login-form' } });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body || '');
  check(csrf, { 'csrf found': (v) => !!v });
  const loginRes = http.post(BASE + '/v2/login', JSON.stringify({ username: user, password: 'bench', csrf }), {
    redirects: 0,
    headers: { 'Content-Type': 'application/json' },
    tags: { name: 'login' },
  });
  let ok = check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  let sessionCsrf = null;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const follow = http.get(absUrl(loc), { redirects: 0, tags: { name: 'login-redirect' } });
      check(follow, { 'login redirect ok': (r) => r.status === 200 });
      try {
        const j = JSON.parse(follow.body);
        sessionCsrf = j.csrf;
      } catch (e) {}
    }
  } else {
    try {
      const j = JSON.parse(loginRes.body);
      sessionCsrf = j.csrf;
    } catch (e) {}
  }
  check(sessionCsrf, { 'session csrf': (v) => !!v });
  return { csrf: sessionCsrf };
}

function renewSession(state) {
  const r = http.post(BASE + '/v2/session/renew', JSON.stringify({}), {
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
    tags: { name: 'renew' },
  });
  if (r.status === 200) {
    try {
      const j = JSON.parse(r.body);
      if (j.csrf) state.csrf = j.csrf;
    } catch (e) {}
    return true;
  }
  return false;
}

function recoverCart(state, cartId) {
  const r = http.post(BASE + '/v2/carts/' + cartId + '/recover', JSON.stringify({}), {
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
    tags: { name: 'recover' },
  });
  if (r.status === 200) {
    try {
      const j = JSON.parse(r.body);
      if (j.csrf) state.csrf = j.csrf;
    } catch (e) {}
    return true;
  }
  return false;
}

function withAuth(state, fn) {
  // fn returns response; handle 401 expired once
  let res = fn();
  if (res.status === 401) {
    let err = null;
    try { err = JSON.parse(res.body).error; } catch (e) {}
    if (err === 'expired') {
      if (renewSession(state)) {
        res = fn();
      }
    } else if (err === 'session') {
      // revoked: renew may fail; fresh login
      if (!renewSession(state)) {
        const l = login(state.user);
        state.csrf = l.csrf;
      }
      if (state.cartId) recoverCart(state, state.cartId);
      res = fn();
    } else if (err === 'denied') {
      check(res, { 'denied not expiry': () => false });
    }
  }
  return res;
}

function traverseCatalog(state) {
  // First try /v2/catalog
  const catRes = http.get(BASE + '/v2/catalog', { redirects: 0, tags: { name: 'catalog' } });
  check(catRes, { 'catalog 200': (r) => r.status === 200 });
  let products = [];
  let next = null;
  try {
    const j = JSON.parse(catRes.body);
    products = (j.data && j.data.products) || [];
    next = j.next;
  } catch (e) {}
  // If catalog has products, use them; else paginate
  if (products.length > 0) {
    return products;
  }
  // pagination via /v2/catalog/page
  let pageUrl = BASE + '/v2/catalog/page';
  let pages = 0;
  const collected = [];
  while (pageUrl && pages < 3) {
    const r = http.get(pageUrl, { redirects: 0, tags: { name: 'catalog-page' } });
    check(r, { 'catalog page 200': (rr) => rr.status === 200 });
    if (r.status !== 200) break;
    let j = null;
    try { j = JSON.parse(r.body); } catch (e) {}
    if (!j) break;
    // one product plus next
    if (j.product) collected.push(j.product);
    else if (j.data && j.data.product) collected.push(j.data.product);
    else if (j.data && j.data.products) collected.push(...j.data.products);
    next = j.next;
    pageUrl = next ? absUrl(next) : null;
    pages++;
  }
  return collected;
}

function pickVariant(product) {
  if (!product || !product.variants) return null;
  for (const v of product.variants) {
    if (v.in_stock) return { product_id: product.id, variant_id: v.id };
  }
  return null;
}

function solveChallenge(state) {
  const formRes = http.get(BASE + '/v2/challenge-form', { redirects: 0, tags: { name: 'challenge-form' } });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const { action, challenge } = parseChallengeForm(formRes.body || '');
  check(action, { 'challenge action': (v) => !!v });
  check(challenge, { 'challenge value': (v) => !!v });
  if (!action || !challenge) return null;
  const postRes = http.post(absUrl(action), JSON.stringify({ challenge }), {
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
    tags: { name: 'challenge-post' },
  });
  check(postRes, { 'challenge post 302': (r) => r.status === 302 });
  const loc = postRes.headers['Location'] || postRes.headers['location'];
  if (!loc) return null;
  const follow = http.get(absUrl(loc), { redirects: 0, tags: { name: 'challenge-follow' } });
  check(follow, { 'challenge follow 200': (r) => r.status === 200 });
  try {
    const j = JSON.parse(follow.body);
    if (j.csrf) state.csrf = j.csrf;
    return j.grant_id || null;
  } catch (e) {}
  return null;
}

function createCart(state, product_id, variant_id, grant_id) {
  const body = { product_id, variant_id };
  if (grant_id) body.grant_id = grant_id;
  const res = withAuth(state, () => http.post(BASE + '/v2/carts', JSON.stringify(body), {
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
    tags: { name: 'cart-create' },
  }));
  check(res, { 'cart create 201': (r) => r.status === 201 });
  let cartId = null;
  try {
    const j = JSON.parse(res.body);
    cartId = j.id;
    if (j.csrf) state.csrf = j.csrf;
  } catch (e) {}
  check(cartId, { 'cart id': (v) => !!v });
  return cartId;
}

function patchQuantity(state, cartId, qty) {
  // read etag
  const getRes = withAuth(state, () => http.get(BASE + '/v2/carts/' + cartId, {
    redirects: 0,
    tags: { name: 'cart-get' },
  }));
  check(getRes, { 'cart get 200': (r) => r.status === 200 });
  let etag = getRes.headers['ETag'] || getRes.headers['etag'];
  const doPatch = (et) => withAuth(state, () => http.patch(BASE + '/v2/carts/' + cartId, JSON.stringify({ quantity: qty }), {
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf, 'If-Match': et || '' },
    tags: { name: 'cart-patch' },
  }));
  let res = doPatch(etag);
  if (res.status === 412) {
    const re = withAuth(state, () => http.get(BASE + '/v2/carts/' + cartId, { redirects: 0, tags: { name: 'cart-get-retry' } }));
    etag = re.headers['ETag'] || re.headers['etag'];
    res = doPatch(etag);
  }
  check(res, { 'cart patch ok': (r) => r.status === 200 || r.status === 204 });
  try {
    const j = JSON.parse(res.body);
    if (j && j.csrf) state.csrf = j.csrf;
  } catch (e) {}
  return res;
}

function createOrder(state, cartId) {
  const idem = 'idem-' + cartId + '-' + Date.now();
  const doPost = () => withAuth(state, () => http.post(BASE + '/v2/orders', JSON.stringify({ cart_id: cartId }), {
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Idempotency-Key': idem,
    },
    tags: { name: 'order-create' },
  }));
  let res = doPost();
  if (res.status === 412) {
    // re-read cart etag and retry once
    const re = withAuth(state, () => http.get(BASE + '/v2/carts/' + cartId, { redirects: 0, tags: { name: 'cart-get-order' } }));
    const etag = re.headers['ETag'] || re.headers['etag'];
    res = withAuth(state, () => http.post(BASE + '/v2/orders', JSON.stringify({ cart_id: cartId }), {
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
        'Idempotency-Key': idem,
        'If-Match': etag || '',
      },
      tags: { name: 'order-create-retry' },
    }));
  }
  check(res, { 'order 201': (r) => r.status === 201 });
  let orderId = null;
  try {
    const j = JSON.parse(res.body);
    if (j.accepted === true) orderId = j.id;
    if (j.csrf) state.csrf = j.csrf;
  } catch (e) {}
  check(orderId, { 'order accepted': (v) => !!v });
  return orderId;
}

function doWork(state) {
  let attempts = 0;
  while (attempts < 5) {
    const res = http.post(BASE + '/v2/work', JSON.stringify({}), {
      redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
      tags: { name: 'work' },
    });
    if (res.status === 429) {
      const ra = res.headers['Retry-After'] || res.headers['retry-after'] || '1';
      sleep(parseFloat(ra) || 1);
      attempts++;
      continue;
    }
    check(res, { 'work 200': (r) => r.status === 200 });
    return res;
  }
  return null;
}

export default function () {
  const user = USERS[(__VU - 1) % USERS.length];
  const state = { user, csrf: null, cartId: null };

  const l = login(user);
  state.csrf = l.csrf;

  // catalog traversal
  const products = traverseCatalog(state);
  check(products, { 'products found': (p) => p && p.length > 0 });

  let chosen = null;
  for (const p of products) {
    const v = pickVariant(p);
    if (v) { chosen = v; break; }
  }
  check(chosen, { 'variant chosen': (v) => !!v });
  if (!chosen) return;

  // challenge for grant
  const grantId = solveChallenge(state);

  // create cart
  const cartId = createCart(state, chosen.product_id, chosen.variant_id, grantId);
  if (!cartId) return;
  state.cartId = cartId;

  // patch quantity
  patchQuantity(state, cartId, 1);

  // reservation
  const resRes = withAuth(state, () => http.post(BASE + '/v2/reservations', JSON.stringify({ cart_id: cartId }), {
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
    tags: { name: 'reservation' },
  }));
  check(resRes, { 'reservation 202': (r) => r.status === 202 });
  let statusUrl = null;
  try {
    const j = JSON.parse(resRes.body);
    statusUrl = j.status_url;
    if (j.csrf) state.csrf = j.csrf;
  } catch (e) {}

  let reservationId = null;
  if (statusUrl) {
    let polls = 0;
    while (polls < 5) {
      sleep(0.06);
      const pr = http.get(absUrl(statusUrl), { redirects: 0, tags: { name: 'reservation-status' } });
      check(pr, { 'reservation status 200': (r) => r.status === 200 });
      let st = null;
      try {
        const j = JSON.parse(pr.body);
        st = j.status;
        if (j.csrf) state.csrf = j.csrf;
        if (st === 'ready') { reservationId = j.reservation_id; break; }
        if (st === 'failed') break;
      } catch (e) {}
      polls++;
    }
  }
  check(reservationId, { 'reservation ready': (v) => !!v });

  // order
  const orderId = createOrder(state, cartId);
  check(orderId, { 'order id': (v) => !!v });

  // work
  doWork(state);

  sleep(0.1);
}
