import os
import re
import time
from urllib.parse import urljoin

from locust import HttpUser, task, between
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL, url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf = None
        self.username = None
        self.password = "bench"
        self.iterations_done = 0
        self.max_iterations = 2

    # ---------- helpers ----------
    def _extract_csrf_from_form(self, text):
        # find input[name=csrf] value, tolerate attribute variants/order
        # look for input tags containing name=csrf
        for m in re.finditer(r"<input\b[^>]*>", text, re.IGNORECASE):
            tag = m.group(0)
            if re.search(r'name\s*=\s*["\']?csrf["\']?', tag, re.IGNORECASE):
                vm = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
                if vm:
                    return vm.group(1)
        return None

    def _extract_form_action(self, text):
        m = re.search(r'<form\b[^>]*action\s*=\s*["\']([^"\']+)["\']', text, re.IGNORECASE)
        if m:
            return m.group(1)
        return None

    def _extract_challenge_input(self, text):
        for m in re.finditer(r"<input\b[^>]*>", text, re.IGNORECASE):
            tag = m.group(0)
            if re.search(r'name\s*=\s*["\']?challenge["\']?', tag, re.IGNORECASE):
                vm = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
                if vm:
                    return vm.group(1)
        return None

    def _headers_csrf(self):
        h = {}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        return h

    def _login(self):
        # pick account
        idx = (self.environment.runner.user_count if self.environment.runner else 1)
        # deterministic per-user account based on id
        uid = getattr(self, "_user_index", None)
        if uid is None:
            uid = (id(self) % 16) + 1
            self._user_index = uid
        self.username = "bench-%d" % uid

        with self.client.get("/v2/login-form", name="/v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = self._extract_csrf_from_form(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return False
            self.csrf = csrf

        with self.client.post("/v2/login",
                              json={"username": self.username, "password": self.password, "csrf": self.csrf},
                              name="/v2/login", catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(_abs(loc), name="/v2/login-redirect",
                                     catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code not in (200, 201):
                        r2.failure("login redirect status %s" % r2.status_code)
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("login redirect not json")
                        return False
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    return True
            elif r.status_code in (200, 201):
                try:
                    data = r.json()
                except Exception:
                    r.failure("login not json")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            else:
                r.failure("login status %s" % r.status_code)
                return False

    def _renew_session(self):
        with self.client.post("/v2/session/renew", json={}, headers=self._headers_csrf(),
                              name="/v2/session/renew", catch_response=True, allow_redirects=False) as r:
            if r.status_code in (200, 201):
                try:
                    data = r.json()
                except Exception:
                    data = {}
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            return False

    def _recover_cart(self, cart_id):
        with self.client.post("/v2/carts/%s/recover" % cart_id, json={}, headers=self._headers_csrf(),
                              name="/v2/carts/[id]/recover", catch_response=True, allow_redirects=False) as r:
            if r.status_code in (200, 201):
                try:
                    data = r.json()
                except Exception:
                    data = {}
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            return False

    def _handle_401(self, resp, cart_id=None):
        try:
            data = resp.json()
        except Exception:
            return False
        err = data.get("error")
        if err == "expired":
            if self._renew_session():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        elif err == "session":
            if self._renew_session():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            # fresh login
            if self._login():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        elif err == "denied":
            return False
        return False

    def _get_catalog_page(self, url):
        with self.client.get(url, name="/v2/catalog/page",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("catalog page status %s" % r.status_code)
                return None
            try:
                return r.json()
            except Exception:
                r.failure("catalog page not json")
                return None

    def _find_eligible_product(self):
        # start from /v2/catalog
        with self.client.get("/v2/catalog", name="/v2/catalog",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("catalog status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("catalog not json")
                return None

        def scan(payload):
            d = payload.get("data") or {}
            products = d.get("products") or []
            for p in products:
                pid = p.get("id")
                for v in (p.get("variants") or []):
                    if v.get("in_stock"):
                        return (pid, v.get("id"))
            return None

        found = scan(data)
        if found:
            return found

        next_url = data.get("next")
        pages = 0
        while next_url and pages < 3:
            pages += 1
            page = self._get_catalog_page(_abs(next_url))
            if page is None:
                return None
            # page returns one product plus next
            d = page.get("data") or {}
            products = d.get("products") or []
            if not products and page.get("product"):
                products = [page["product"]]
            for p in products:
                pid = p.get("id")
                for v in (p.get("variants") or []):
                    if v.get("in_stock"):
                        return (pid, v.get("id"))
            next_url = page.get("next")
        return None

    def _solve_challenge(self):
        with self.client.get("/v2/challenge-form", name="/v2/challenge-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            action = self._extract_form_action(r.text)
            challenge = self._extract_challenge_input(r.text)
            if not action or not challenge:
                r.failure("challenge form missing action/input")
                return None
        with self.client.post(_abs(action), json={"challenge": challenge},
                              headers=self._headers_csrf(),
                              name="/v2/challenges/[id]", catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge 302 no Location")
                    return None
                with self.client.get(_abs(loc), name="/v2/challenge-redirect",
                                     catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code not in (200, 201):
                        r2.failure("challenge redirect status %s" % r2.status_code)
                        return None
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("challenge redirect not json")
                        return None
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    return data.get("grant_id")
            elif r.status_code in (200, 201):
                try:
                    data = r.json()
                except Exception:
                    r.failure("challenge not json")
                    return None
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return data.get("grant_id")
            else:
                r.failure("challenge status %s" % r.status_code)
                return None

    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload, headers=self._headers_csrf(),
                              name="/v2/carts", catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    # retry once
                    with self.client.post("/v2/carts", json=payload, headers=self._headers_csrf(),
                                          name="/v2/carts", catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code == 201:
                            try:
                                data = r2.json()
                            except Exception:
                                r2.failure("cart not json")
                                return None
                            if data.get("csrf"):
                                self.csrf = data["csrf"]
                            return data.get("id")
                        r2.failure("cart retry status %s" % r2.status_code)
                        return None
                r.failure("cart 401 unrecoverable")
                return None
            if r.status_code != 201:
                r.failure("cart status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("cart not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("id")

    def _patch_quantity(self, cart_id, qty):
        # read etag
        with self.client.get("/v2/carts/%s" % cart_id, name="/v2/carts/[id]",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    with self.client.get("/v2/carts/%s" % cart_id, name="/v2/carts/[id]",
                                         catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code != 200:
                            r2.failure("cart get retry status %s" % r2.status_code)
                            return False
                        etag = r2.headers.get("ETag")
                else:
                    r.failure("cart get 401 unrecoverable")
                    return False
            elif r.status_code != 200:
                r.failure("cart get status %s" % r.status_code)
                return False
            else:
                etag = r.headers.get("ETag")

        headers = self._headers_csrf()
        if etag:
            headers["If-Match"] = etag

        def do_patch():
            with self.client.patch("/v2/carts/%s" % cart_id, json={"quantity": qty},
                                   headers=headers, name="/v2/carts/[id]",
                                   catch_response=True, allow_redirects=False) as r:
                return r

        r = do_patch()
        if r.status_code == 412:
            # re-read and retry once
            with self.client.get("/v2/carts/%s" % cart_id, name="/v2/carts/[id]",
                                 catch_response=True, allow_redirects=False) as rg:
                if rg.status_code == 200:
                    etag2 = rg.headers.get("ETag")
                    if etag2:
                        headers["If-Match"] = etag2
            r = do_patch()
        if r.status_code == 401:
            if self._handle_401(r, cart_id):
                r = do_patch()
            else:
                r.failure("patch 401 unrecoverable")
                return False
        if r.status_code not in (200, 201, 204):
            r.failure("patch status %s" % r.status_code)
            return False
        try:
            data = r.json()
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]
        except Exception:
            pass
        return True

    def _reserve(self, cart_id):
        with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                              headers=self._headers_csrf(),
                              name="/v2/reservations", catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                                          headers=self._headers_csrf(),
                                          name="/v2/reservations", catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code != 202:
                            r2.failure("reservation retry status %s" % r2.status_code)
                            return None
                        try:
                            data = r2.json()
                        except Exception:
                            r2.failure("reservation not json")
                            return None
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        return data.get("status_url")
                r.failure("reservation 401 unrecoverable")
                return None
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("reservation not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("status_url")

    def _poll_reservation(self, status_url):
        for i in range(5):
            if i > 0:
                time.sleep(0.06)
            with self.client.get(_abs(status_url), name="/v2/reservations/status",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code == 401:
                    if self._handle_401(r):
                        continue
                    r.failure("poll 401 unrecoverable")
                    return None
                if r.status_code != 200:
                    r.failure("poll status %s" % r.status_code)
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("poll not json")
                    return None
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                status = data.get("status")
                if status == "ready":
                    return data.get("reservation_id")
                if status in ("pending",):
                    continue
                if status in ("failed",):
                    return None
        return None

    def _create_order(self, cart_id, reservation_id):
        headers = self._headers_csrf()
        headers["Idempotency-Key"] = "cart-%s" % cart_id
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id

        def do_post():
            with self.client.post("/v2/orders", json=payload, headers=headers,
                                  name="/v2/orders", catch_response=True, allow_redirects=False) as r:
                return r

        r = do_post()
        if r.status_code == 401:
            if self._handle_401(r, cart_id):
                r = do_post()
            else:
                r.failure("order 401 unrecoverable")
                return None
        if r.status_code == 201:
            try:
                data = r.json()
            except Exception:
                r.failure("order not json")
                return None
            if not data.get("accepted"):
                r.failure("order not accepted")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("id")
        if r.status_code == 200:
            try:
                data = r.json()
            except Exception:
                data = {}
            if data.get("accepted") is False:
                r.failure("order business failure accepted=false")
                return None
            r.failure("order unexpected 200")
            return None
        r.failure("order status %s" % r.status_code)
        return None

    def _do_work(self):
        for attempt in range(5):
            with self.client.post("/v2/work", json={}, headers=self._headers_csrf(),
                                  name="/v2/work", catch_response=True, allow_redirects=False) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    time.sleep(delay)
                    continue
                if r.status_code == 200:
                    try:
                        data = r.json()
                    except Exception:
                        r.failure("work not json")
                        return
                    if not data.get("ok"):
                        r.failure("work not ok")
                    return
                if r.status_code == 401:
                    if self._handle_401(r):
                        continue
                    r.failure("work 401 unrecoverable")
                    return
                r.failure("work status %s" % r.status_code)
                return

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self._login():
            raise StopUser()

        found = self._find_eligible_product()
        if not found:
            raise StopUser()
        product_id, variant_id = found

        grant_id = self._solve_challenge()

        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            raise StopUser()

        if not self._patch_quantity(cart_id, 1):
            raise StopUser()

        status_url = self._reserve(cart_id)
        if not status_url:
            raise StopUser()

        reservation_id = self._poll_reservation(status_url)
        if not reservation_id:
            raise StopUser()

        order_id = self._create_order(cart_id, reservation_id)
        if not order_id:
            raise StopUser()

        self._do_work()

        if self.iterations_done >= self.max_iterations:
            raise StopUser()


