    private static String extractCsrfFromHtml(String body) {
        if (body == null) return null;
        Matcher m = CSRF_INPUT.matcher(body);
        if (!m.find()) return null;
        String tag = m.group();
        Matcher v = VALUE_ATTR.matcher(tag);
        if (!v.find()) return null;
        return v.group(1);
    }

    private static String extractCsrfFromJson(String body) {
        if (body == null) return null;
        Matcher m = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]*)\"").matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractJsonString(String body, String field) {
        if (body == null) return null;
        Matcher m = Pattern.compile("\"" + Pattern.quote(field) + "\"\\s*:\\s*\"([^\"]*)\"").matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractJsonInt(String body, String field) {
        if (body == null) return null;
        Matcher m = Pattern.compile("\"" + Pattern.quote(field) + "\"\\s*:\\s*(-?\\d+)").matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractFirstProductId(String body) {
        if (body == null) return null;
        Matcher m = Pattern.compile("\"products\"\\s*:\\s*\\[\\s*\\{[^}]*?\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
        if (m.find()) return m.group(1);
        return null;
