                    // detect 412 by re-reading status via saved body? We need status.
                    // Use a saved status check instead.
                    return false;
                }).then(exec(session -> session))
                .exec(session -> session);
    }

    // We need status of patch. Use check to save status.
    private static ChainBuilder patchCartSavingStatus() {
        return exec(
                http(CART_PATCH)
                        .patch(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> session.getString("etag"))
                        .body(StringBody("{\"quantity\":" + QUANTITY + "}"))
                        .check(status().in(200, 412).saveAs("patchStatus"))
                        .check(bodyString().saveAs("patchBody"))
        ).exec(session -> {
            String csrf = extractCsrfFromJson(session.getString("patchBody"));
            if (csrf != null) session = session.set("csrf", csrf);
            return session;
        });
    }

    private static ChainBuilder patchWithRetry() {
        return exec(patchCartSavingStatus())
                .doIf(session -> {
                    Integer st = session.getInt("patchStatus");
                    return st != null && st == 412;
                }).then(
                        exec(readCart())
                                .exec(patchCartSavingStatus())
                );
    }

    private static ChainBuilder reservationFlow() {
        return exec(
                http(RESERVATION)
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                        .check(status().is(202))
                        .check(bodyString().saveAs("reservationBody"))
        ).exec(session -> {
            String csrf = extractCsrfFromJson(session.getString("reservationBody"));
            if (csrf != null) session = session.set("csrf", csrf);
            String url = extractStatusUrl(session.getString("reservationBody"));
            return session.set("statusUrl", url).set("pollCount", 0).set("reservationId", (String) null);
        }).asLongAs(session -> {
            Integer pc = session.getInt("pollCount");
            String rid = session.getString("reservationId");
            return (pc == null || pc < 5) && (rid == null || rid.isEmpty());
        }).on(
                pause(Duration.ofMillis(60))
                        .exec(
                                http(RESERVATION_POLL)
                                        .get(session -> session.getString("statusUrl"))
                                        .check(status().is(200))
                                        .check(bodyString().saveAs("pollBody"))
                        ).exec(session -> {
                            String status = extractStatus(session.getString("pollBody"));
                            Integer pc = session.getInt("pollCount");
                            int next = (pc == null ? 0 : pc) + 1;
                            session = session.set("pollCount", next);
                            if ("ready".equals(status)) {
                                String rid = extractReservationId(session.getString("pollBody"));
                                session = session.set("reservationId", rid);
                            } else if ("failed".equals(status)) {
                                session = session.set("reservationId", "");
                            }
                            return session;
                        })
        );
    }

    private static ChainBuilder orderFlow() {
        return exec(
                http(ORDER)
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                        .header("If-Match", session -> session.getString("etag"))
                        .body(StringBody(session -> {
                            String rid = session.getString("reservationId");
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"cart_id\":\"").append(session.getString("cartId")).append("\"");
                            if (rid != null && !rid.isEmpty()) sb.append(",\"reservation_id\":\"").append(rid).append("\"");
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().is(201))
                        .check(bodyString().saveAs("orderBody"))
        ).exec(session -> {
            String csrf = extractCsrfFromJson(session.getString("orderBody"));
            if (csrf != null) session = session.set("csrf", csrf);
            return session;
        }).exec(session -> {
            boolean ok = isAcceptedTrue(session.getString("orderBody"));
            return session.set("orderAccepted", ok);
        }).exec(
                http(WORK)
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429))
        );
    }

    private static ChainBuilder journey() {
        return exec(session -> session
                        .set("username", "bench-" + (1 + ThreadLocalRandom.current().nextInt(16)))
                        .set("csrf", "")
                        .set("etag", "")
                        .set("cartId", "")
                        .set("grantId", "")
                        .set("reservationId", "")
                        .set("pollCount", 0)
                        .set("orderAccepted", false))
                .exec(loginFlow())
                .exec(catalogFlow())
                .exec(challengeFlow())
                .exec(createCart())
                .exec(readCart())
                .exec(patchWithRetry())
                .exec(reservationFlow())
                .exec(orderFlow())
                .exec(session -> {
                    Boolean ok = session.getBoolean("orderAccepted");
                    if (ok == null || !ok) {
                        return session.markAsFailed();
                    }
                    return session;
                });
    }

    private static final ScenarioBuilder SCENARIO = scenario("ModelSimulation")
            .exec(journey());

    {
        setUp(
                SCENARIO.injectOpen(
                        rampUsers(USERS).during(Duration.ofSeconds(1))
                ).protocols(HTTP)
        ).maxDuration(Duration.ofMinutes(5));
    }
}
