```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const USERS = new SharedArray('users', function () {
  return ['bench-1', 'bench-2'];
});

function parseCsrf(html) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  // fallback: value before name
  const re2 = /<input\b[^>]*\bvalue\s*=\s*["']([^"']*)["'][^>]*\bname\s*=\s*["']?csrf["']?/gi;
  while ((m = re2.exec(html)) !== null) {
    return m[1];
  }
  return null;
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function extractEtag(res) {
  const e = getHeader(res, 'ETag');
  if (!e) return null;
  return e;
}

function login(user) {
  const jar = http.cookieJar();
  // fresh login: clear cookies for base
  jar.clear(BASE);

  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body);
  check(csrf, { 'login csrf extracted': (c) => !!c });

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf: csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );

  let body = null;
  try { body = loginRes.json(); } catch (e) { body = null; }

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loc, { 'login redirect location': (l) => !!l });
    const followRes = http.get(`${BASE}${loc}`, { redirects: 0 });
    check(followRes, { 'login redirect follow 200': (r) => r.status === 200 });
    try { body = followRes.json(); } catch (e) { body = null; }
  }

  check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  check(body, { 'login body': (b) => b && b.csrf && b.user });
  return body ? body.csrf : null;
}

function renewSession(csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.csrf) return body.csrf;
  return csrf;
}

function recoverCart(cartId, csrf) {
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.csrf) return body.csrf;
  return csrf;
}

function pickProduct() {
  const res = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (!body || !body.data || !body.data.products) return null;
  const products = body.data.products;
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p.variants) continue;
    for (let j = 0; j < p.variants.length; j++) {
      const v = p.variants[j];
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function solveChallenge(csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const actionMatch = formRes.body.match(/action\s*=\s*["']([^"']*\/v2\/challenges\/[^"']*)["']/i);
  const challengeMatch = formRes.body.match(/name\s*=\s*["']?challenge["']?[^>]*value\s*=\s*["']([^"']*)["']/i)
    || formRes.body.match(/value\s*=\s*["']([^"']*)["'][^>]*name\s*=\s*["']?challenge["']?/i);
  check(actionMatch, { 'challenge action': (a) => !!a });
  check(challengeMatch, { 'challenge value': (c) => !!c });
  if (!actionMatch || !challengeMatch) return { grant_id: null, csrf: csrf };

  const action = actionMatch[1];
  const challenge = challengeMatch[1];
  const postRes = http.post(`${BASE}${action}`, JSON.stringify({ challenge: challenge }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(postRes, { 'challenge post 302': (r) => r.status === 302 });
  const loc = getHeader(postRes, 'Location');
  check(loc, { 'challenge location': (l) => !!l });
  if (!loc) return { grant_id: null, csrf: csrf };
  const grantRes = http.get(`${BASE}${loc}`, { redirects: 0 });
  check(grantRes, { 'grant 200': (r) => r.status === 200 });
  let gbody = null;
  try { gbody = grantRes.json(); } catch (e) { gbody = null; }
  check(gbody, { 'grant body': (b) => b && b.grant_id });
  return {
    grant_id: gbody ? gbody.grant_id : null,
    csrf: gbody && gbody.csrf ? gbody.csrf : csrf,
  };
}

function createCart(product, csrf, grantId) {
  const payload = { product_id: product.product_id, variant_id: product.variant_id };
  if (grantId) payload.grant_id = grantId;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(res, { 'cart create 201': (r) => r.status === 201 });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  check(body, { 'cart body': (b) => b && b.id });
  return {
    id: body ? body.id : null,
    csrf: body && body.csrf ? body.csrf : csrf,
    etag: extractEtag(res),
  };
}

function readCart(cartId, csrf) {
  const res = http.get(`${BASE}/v2/carts/${cartId}`, {
    headers: { 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(res, { 'cart read 200': (r) => r.status === 200 });
  return { etag: extractEtag(res), status: res.status };
}

function patchCart(cartId, quantity, etag, csrf) {
  const res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: quantity }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag,
    },
    redirects: 0,
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return {
    status: res.status,
    csrf: body && body.csrf ? body.csrf : csrf,
    etag: extractEtag(res),
  };
}

function handleScheduled(res) {
  // scheduled 429 with Retry-After
  if (res.status === 429) {
    const ra = getHeader(res, 'Retry-After');
    const wait = ra ? parseFloat(ra) : 1;
    sleep(wait > 0 ? wait : 1);
    return true;
  }
  return false;
}

function doWork(csrf) {
  let attempts = 0;
  while (attempts < 4) {
    const res = http.post(`${BASE}/v2/work`, JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      redirects: 0,
    });
    if (handleScheduled(res)) { attempts++; continue; }
    check(res, { 'work 200': (r) => r.status === 200 });
    let body = null;
    try { body = res.json(); } catch (e) { body = null; }
    check(body, { 'work ok': (b) => b && b.ok === true });
    return body && body.csrf ? body.csrf : csrf;
  }
  return csrf;
}

function createOrder(cartId, csrf, etag) {
  const idemKey = `order-${cartId}-${Date.now()}`;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify({ cart_id: cartId }), {
    headers: headers,
    redirects: 0,
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  check(res, { 'order 201': (r) => r.status === 201 });
  check(body, { 'order accepted': (b) => b && b.accepted === true && b.id });
  return { status: res.status, body: body, csrf: body && body.csrf ? body.csrf : csrf };
}

export default function () {
  const user = USERS[(__VU - 1) % USERS.length];
  let csrf = login(user);
  if (!csrf) return;

  // pick product
  let product = pickProduct();
  check(product, { 'product found': (p) => !!p });
  if (!product) return;

  // solve challenge for grant
  const ch = solveChallenge(csrf);
  csrf = ch.csrf;

  // create cart
  const cart = createCart(product, csrf, ch.grant_id);
  csrf = cart.csrf;
  check(cart.id, { 'cart id': (c) => !!c });
  if (!cart.id) return;

  // initial revision extracted
  let etag = cart.etag;
  if (!etag) {
    const r = readCart(cart.id, csrf);
    etag = r.etag;
  }
  check(etag, { 'initial etag extracted': (e) => !!e });
  if (!etag) return;

  // stale update: use a deliberately stale etag to trigger 412 once
  const staleEtag = '"stale-' + Date.now() + '"';
  const quantity = 2;

  let patchRes = patchCart(cart.id, quantity, staleEtag, csrf);
  csrf = patchRes.csrf;

  // expect 412 on stale
  check(patchRes, { 'stale patch 412': (r) => r.status === 412 });

  // re-read and retry same payload once
  const reread = readCart(cart.id, csrf);
  check(reread, { 'reread 200': (r) => r.status === 200 });
  const freshEtag = reread.etag;
  check(freshEtag, { 'fresh etag': (e) => !!e });

  if (freshEtag) {
    const retryRes = patchCart(cart.id, quantity, freshEtag, csrf);
    csrf = retryRes.csrf;
    check(retryRes, { 'conditional retry 200': (r) => r.status === 200 || r.status === 204 });
  }

  // do some business work
  csrf = doWork(csrf);

  // create order
  const order = createOrder(cart.id, csrf, freshEtag);
  csrf = order.csrf;

  sleep(0.1);
}
