import os
import re
import time
import random
from urllib.parse import urljoin

from locust import HttpUser, task, between, events
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL, url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.iterations_done = 0
        self.target_iterations = 2
        self.username = None
        self.password = "bench"
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idem_key = None
        self._assigned = False

    # ---------- helpers ----------
    def _assign_account(self):
        if self._assigned:
            return
        self._assigned = True
        # pick a bench account deterministically-ish per user
        idx = random.randint(1, 16)
        self.username = "bench-%d" % idx

    def _extract_csrf_from_html(self, text):
        # input[name=csrf] with mixed attribute variants / decoys
        # find input tags, then check name=csrf and value
        for m in re.finditer(r"<input\b[^>]*>", text, re.IGNORECASE):
            tag = m.group(0)
            name_m = re.search(r'name\s*=\s*["\']?csrf["\']?', tag, re.IGNORECASE)
            if not name_m:
                continue
            val_m = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
            if val_m:
                return val_m.group(1)
        return None

    def _extract_challenge_form(self, text):
        # form action /v2/challenges/{id} and input[name=challenge]
        action = None
        for m in re.finditer(r"<form\b[^>]*>", text, re.IGNORECASE):
            tag = m.group(0)
            a = re.search(r'action\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
            if a and "/v2/challenges/" in a.group(1):
                action = a.group(1)
                break
        challenge_val = None
        for m in re.finditer(r"<input\b[^>]*>", text, re.IGNORECASE):
            tag = m.group(0)
            if re.search(r'name\s*=\s*["\']?challenge["\']?', tag, re.IGNORECASE):
                v = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
                if v:
                    challenge_val = v.group(1)
                    break
        return action, challenge_val

    def _login(self):
        self._assign_account()
        # GET login form
        with self.client.get("/v2/login-form", name="GET /v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = self._extract_csrf_from_html(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return False
        # POST login
        with self.client.post("/v2/login",
                              json={"username": self.username, "password": self.password, "csrf": csrf},
                              name="POST /v2/login", catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(_abs(loc), name="GET login redirect",
                                     catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code not in (200, 201):
                        r2.failure("login redirect status %s" % r2.status_code)
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("login redirect not json")
                        return False
                    self.csrf = data.get("csrf")
                    if not self.csrf:
                        r2.failure("no csrf after login")
                        return False
            elif r.status_code in (200, 201):
                try:
                    data = r.json()
                except Exception:
                    r.failure("login not json")
                    return False
                self.csrf = data.get("csrf")
                if not self.csrf:
                    r.failure("no csrf after login")
                    return False
            else:
                r.failure("login status %s" % r.status_code)
                return False
        return True

    def _renew_session(self):
        if not self.csrf:
            return False
        with self.client.post("/v2/session/renew", json={},
                              headers={"X-CSRF-Token": self.csrf},
                              name="POST /v2/session/renew",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code in (200, 201):
                try:
                    data = r.json()
                except Exception:
                    r.failure("renew not json")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            r.failure("renew status %s" % r.status_code)
            return False

    def _recover_cart(self):
        if not self.cart_id:
            return True
        with self.client.post("/v2/carts/%s/recover" % self.cart_id, json={},
                              headers={"X-CSRF-Token": self.csrf},
                              name="POST /v2/carts/recover",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code in (200, 201):
                try:
                    data = r.json()
                except Exception:
                    pass
                else:
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                return True
            r.failure("recover status %s" % r.status_code)
            return False

    def _handle_401(self, r):
        """Return True if recovered (caller should retry once)."""
        try:
            data = r.json()
        except Exception:
            return False
        err = data.get("error")
        if err == "expired":
            if self._renew_session():
                if self.cart_id:
                    self._recover_cart()
                return True
            return False
        if err == "session":
            # revoked: fresh login, recover cart
            if self._login():
                if self.cart_id:
                    self._recover_cart()
                return True
            return False
        # denied -> not expiry
        return False

    def _get_catalog_product(self):
        # traverse at most 3 pages
        url = "/v2/catalog/page"
        for _ in range(3):
            with self.client.get(url, name="GET /v2/catalog/page",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure("catalog page status %s" % r.status_code)
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    return None
            products = data.get("products") or []
            if not products and isinstance(data.get("data"), dict):
                products = data["data"].get("products") or []
            for p in products:
                variants = p.get("variants") or []
                for v in variants:
                    if v.get("in_stock"):
                        return (p.get("id"), v.get("id"))
            nxt = data.get("next")
            if not nxt:
                break
            url = _abs(nxt)
        return None

    def _solve_challenge(self):
        with self.client.get("/v2/challenge-form", name="GET /v2/challenge-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge-form status %s" % r.status_code)
                return False
            action, challenge = self._extract_challenge_form(r.text)
            if not action or not challenge:
                r.failure("challenge form parse failed")
                return False
        with self.client.post(_abs(action), json={"challenge": challenge},
                              headers={"X-CSRF-Token": self.csrf},
                              name="POST /v2/challenges",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge 302 no Location")
                    return False
                with self.client.get(_abs(loc), name="GET challenge redirect",
                                     catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code not in (200, 201):
                        r2.failure("challenge redirect status %s" % r2.status_code)
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("challenge redirect not json")
                        return False
                    self.grant_id = data.get("grant_id")
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    return bool(self.grant_id)
            elif r.status_code in (200, 201):
                try:
                    data = r.json()
                except Exception:
                    r.failure("challenge not json")
                    return False
                self.grant_id = data.get("grant_id")
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return bool(self.grant_id)
            else:
                r.failure("challenge status %s" % r.status_code)
                return False

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post("/v2/carts", json=payload,
                              headers={"X-CSRF-Token": self.csrf},
                              name="POST /v2/carts",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    # retry once
                    with self.client.post("/v2/carts", json=payload,
                                          headers={"X-CSRF-Token": self.csrf},
                                          name="POST /v2/carts",
                                          catch_response=True, allow_redirects=False) as r2:
                        return self._parse_cart_create(r2)
                return False
            return self._parse_cart_create(r)

    def _parse_cart_create(self, r):
        if r.status_code != 201:
            r.failure("cart create status %s" % r.status_code)
            return False
        try:
            data = r.json()
        except Exception:
            r.failure("cart create not json")
            return False
        self.cart_id = data.get("id")
        if data.get("csrf"):
            self.csrf = data["csrf"]
        etag = r.headers.get("ETag")
        if not etag:
            r.failure("cart create missing ETag")
            return False
        self.cart_etag = etag
        self.idem_key = "idem-%s-%s" % (self.cart_id, random.randint(0, 10**9))
        return bool(self.cart_id)

    def _get_cart_etag(self):
        with self.client.get("/v2/carts/%s" % self.cart_id,
                             name="GET /v2/carts/{id}",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    with self.client.get("/v2/carts/%s" % self.cart_id,
                                         name="GET /v2/carts/{id}",
                                         catch_response=True, allow_redirects=False) as r2:
                        return self._parse_cart_get(r2)
                return None
            return self._parse_cart_get(r)

    def _parse_cart_get(self, r):
        if r.status_code != 200:
            r.failure("cart get status %s" % r.status_code)
            return None
        etag = r.headers.get("ETag")
        if not etag:
            r.failure("cart get missing ETag")
            return None
        self.cart_etag = etag
        return etag

    def _patch_cart(self, quantity):
        """PATCH with If-Match; on 412 re-read and retry same payload once."""
        payload = {"quantity": quantity}
        headers = {"X-CSRF-Token": self.csrf, "If-Match": self.cart_etag}
        with self.client.patch("/v2/carts/%s" % self.cart_id, json=payload,
                               headers=headers, name="PATCH /v2/carts/{id}",
                               catch_response=True, allow_redirects=False) as r:
            if r.status_code == 412:
                # re-read
                new_etag = self._get_cart_etag()
                if not new_etag:
                    r.failure("412 but re-read failed")
                    return False
                headers2 = {"X-CSRF-Token": self.csrf, "If-Match": new_etag}
                with self.client.patch("/v2/carts/%s" % self.cart_id, json=payload,
                                       headers=headers2, name="PATCH /v2/carts/{id}",
                                       catch_response=True, allow_redirects=False) as r2:
                    return self._parse_patch(r2)
            if r.status_code == 401:
                if self._handle_401(r):
                    headers2 = {"X-CSRF-Token": self.csrf, "If-Match": self.cart_etag}
                    with self.client.patch("/v2/carts/%s" % self.cart_id, json=payload,
                                           headers=headers2, name="PATCH /v2/carts/{id}",
                                           catch_response=True, allow_redirects=False) as r2:
                        return self._parse_patch(r2)
                return False
            return self._parse_patch(r)

    def _parse_patch(self, r):
        if r.status_code not in (200, 201, 204):
            r.failure("patch status %s" % r.status_code)
            return False
        etag = r.headers.get("ETag")
        if etag:
            self.cart_etag = etag
        try:
            data = r.json()
        except Exception:
            data = None
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]
        return True

    def _reserve(self):
        with self.client.post("/v2/reservations", json={"cart_id": self.cart_id},
                              headers={"X-CSRF-Token": self.csrf},
                              name="POST /v2/reservations",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    with self.client.post("/v2/reservations", json={"cart_id": self.cart_id},
                                          headers={"X-CSRF-Token": self.csrf},
                                          name="POST /v2/reservations",
                                          catch_response=True, allow_redirects=False) as r2:
                        return self._parse_reservation(r2)
                return False
            return self._parse_reservation(r)

    def _parse_reservation(self, r):
        if r.status_code != 202:
            r.failure("reservation status %s" % r.status_code)
            return False
        try:
            data = r.json()
        except Exception:
            r.failure("reservation not json")
            return False
        if data.get("csrf"):
            self.csrf = data["csrf"]
        status_url = data.get("status_url")
        if not status_url:
            r.failure("reservation missing status_url")
            return False
        # poll at least 50ms apart, at most 5 times
        for i in range(5):
            time.sleep(0.06)
            with self.client.get(_abs(status_url), name="GET reservation status",
                                 catch_response=True, allow_redirects=False) as r2:
                if r2.status_code != 200:
                    r2.failure("reservation status poll %s" % r2.status_code)
                    return False
                try:
                    sd = r2.json()
                except Exception:
                    r2.failure("reservation status not json")
                    return False
            status = sd.get("status")
            if status == "ready":
                rid = sd.get("reservation_id")
                if not rid:
                    r2.failure("ready without reservation_id")
                    return False
                self.reservation_id = rid
                return True
            if status in ("pending",):
                continue
            if status in ("failed",):
                r2.failure("reservation failed")
                return False
            # unknown status
            r2.failure("reservation unknown status %s" % status)
            return False
        r2.failure("reservation not ready after polls")
        return False

    def _checkout(self):
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = {"X-CSRF-Token": self.csrf, "Idempotency-Key": self.idem_key}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.post("/v2/orders", json=payload, headers=headers,
                              name="POST /v2/orders",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    headers2 = {"X-CSRF-Token": self.csrf, "Idempotency-Key": self.idem_key}
                    if self.cart_etag:
                        headers2["If-Match"] = self.cart_etag
                    with self.client.post("/v2/orders", json=payload, headers=headers2,
                                          name="POST /v2/orders",
                                          catch_response=True, allow_redirects=False) as r2:
                        return self._parse_order(r2)
                return False
            return self._parse_order(r)

    def _parse_order(self, r):
        if r.status_code == 200:
            try:
                data = r.json()
            except Exception:
                r.failure("order 200 not json")
                return False
            if data.get("accepted") is False:
                r.failure("order business failure accepted=false")
                return False
            if data.get("accepted") is True:
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            r.failure("order 200 unexpected body")
            return False
        if r.status_code == 201:
            try:
                data = r.json()
            except Exception:
                r.failure("order 201 not json")
                return False
            if data.get("accepted") is not True:
                r.failure("order 201 accepted not true")
                return False
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return True
        r.failure("order status %s" % r.status_code)
        return False

    def _do_work(self):
        # scheduled 429 needs Retry-After 1s, at most 4 retries
        for attempt in range(5):
            with self.client.post("/v2/work", json={},
                                  headers={"X-CSRF-Token": self.csrf} if self.csrf else {},
                                  name="POST /v2/work",
                                  catch_response=True, allow_redirects=False) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After")
                    if ra is None:
                        r.failure("429 without Retry-After")
                        return False
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    if attempt >= 4:
                        r.failure("429 exceeded retries")
                        return False
                    time.sleep(max(delay, 0.05))
                    continue
                if r.status_code == 200:
                    try:
                        data = r.json()
                    except Exception:
                        r.failure("work not json")
                        return False
                    if data.get("ok") is not True:
                        r.failure("work ok not true")
                        return False
                    return True
                if r.status_code == 401:
                    if self._handle_401(r):
                        continue
                    return False
                r.failure("work status %s" % r.status_code)
                return False
        return False

    # ---------- journey ----------
    def _journey(self):
        # fresh login/cart each journey
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idem_key = None
        self.csrf = None

        if not self._login():
            return

        # optional challenge for grant
        self._solve_challenge()

        prod = self._get_catalog_product()
        if not prod:
            return
        product_id, variant_id = prod

        if not self._create_cart(product_id, variant_id):
            return

        # ensure we have etag
        if not self.cart_etag:
            if not self._get_cart_etag():
                return

        # update cart quantity (etag mode)
        if not self._patch_cart(2):
            return

        # reserve
        if not self._reserve():
            return

        # checkout
        if not self._checkout():
            return

        # work sample
        self._do_work()

    @task
    def run_journey(self):
        if self.iterations_done >= self.target_iterations:
            raise StopUser()
        self._journey()
        self.iterations_done += 1
        if self.iterations_done >= self.target_iterations:
            raise StopUser()


