public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "name\\s*=\\s*[\"']csrf[\"'][^>]*value\\s*=\\s*[\"']([^\"']+)[\"']|value\\s*=\\s*[\"']([^\"']+)[\"'][^>]*name\\s*=\\s*[\"']csrf[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_INPUT = Pattern.compile(
            "name\\s*=\\s*[\"']challenge[\"'][^>]*value\\s*=\\s*[\"']([^\"']+)[\"']|value\\s*=\\s*[\"']([^\"']+)[\"'][^>]*name\\s*=\\s*[\"']challenge[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_ACTION = Pattern.compile(
            "action\\s*=\\s*[\"']([^\"']*?/v2/challenges/[^\"']+)[\"']", Pattern.CASE_INSENSITIVE);

    private static String firstGroup(Pattern p, String s) {
        if (s == null) return null;
        Matcher m = p.matcher(s);
        if (m.find()) {
            return m.group(1) != null ? m.group(1) : m.group(2);
        }
        return null;
    }

    private static String absUrl(String u) {
        if (u == null) return null;
        if (u.startsWith("http://") || u.startsWith("https://")) return u;
        if (u.startsWith("/")) return BASE_URL + u;
        return BASE_URL + "/" + u;
    }

    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableFollowRedirect()
            .disableCaching()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json");

    private static ChainBuilder refreshCsrfFromBody(String sessionKey) {
        return exec(session -> {
            String body = session.getString("lastBody");
            String fresh = firstGroup(CSRF_INPUT, body);
            if (fresh == null) {
                // try JSON "csrf":"..."
                Matcher m = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body == null ? "" : body);
                if (m.find()) fresh = m.group(1);
            }
            if (fresh != null && !fresh.isEmpty()) {
                return session.set(sessionKey, fresh);
            }
            return session;
        });
    }

    private static ChainBuilder captureBody(String key) {
        return exec(session -> session.set(key, session.getString("lastBody")));
    }

    private static ChainBuilder loginFlow() {
        return exec(
                http("GET login-form")
