        ).exec(session -> {
            String body = session.getString("lastBody");
            String csrf = firstGroup(CSRF_INPUT, body);
            if (csrf == null) {
                Matcher m = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body == null ? "" : body);
                if (m.find()) csrf = m.group(1);
            }
            return session.set("csrf", csrf == null ? "" : csrf);
        }).exec(
                http("POST login")
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String u = session.getString("username");
