                Matcher pm = Pattern.compile("\\{\"id\"\\s*:\\s*\"?([^,\"}]+)\"?\\s*,\\s*\"variants\"\\s*:\\s*\\[(.*?)\\]\\s*\\}").matcher(body);
                while (pm.find()) {
                    String pid = pm.group(1);
