    private static ChainBuilder pollReservation() {
        return asLongAs(session -> session.getString("statusUrl") != null
                        && session.getInt("pollCount") < 5
                        && !"ready".equals(session.getString("reservationStatus")))
                .on(
                        pause(Duration.ofMillis(60)),
                        exec(
                                http("GET reservation status")
                                        .get(session -> session.getString("statusUrl"))
                                        .check(status().in(200, 401))
                                        .check(bodyString().saveAs("lastBody"))
                        ).exec(refreshCsrfFromBody("csrf"))
                                .exec(session -> {
                                    String body = session.getString("lastBody");
                                    String status = null;
                                    String rid = null;
                                    if (body != null) {
                                        Matcher sm = Pattern.compile("\"status\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                                        if (sm.find()) status = sm.group(1);
                                        Matcher rm = Pattern.compile("\"reservation_id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                                        if (rm.find()) rid = rm.group(1);
                                    }
                                    return session.set("reservationStatus", status)
                                            .set("reservationId", rid)
                                            .set("pollCount", session.getInt("pollCount") + 1);
                                })
                );
    }

    private static ChainBuilder placeOrder() {
        return exec(
                http("POST order")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                        .header("If-Match", session -> {
                            String e = session.getString("cartEtag");
                            return e == null ? "*" : e;
                        })
                        .body(StringBody(session -> {
                            String rid = session.getString("reservationId");
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"cart_id\":\"").append(session.getString("cartId")).append("\"");
                            if (rid != null && !rid.isEmpty()) {
                                sb.append(",\"reservation_id\":\"").append(rid).append("\"");
                            }
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().in(201, 200, 401))
                        .check(bodyString().saveAs("lastBody"))
        ).exec(refreshCsrfFromBody("csrf"))
                .exec(session -> {
                    String body = session.getString("lastBody");
                    boolean accepted = body != null && body.contains("\"accepted\":true");
                    if (!accepted) {
                        return session.markAsFailed();
                    }
                    return session;
                });
    }

    private static ChainBuilder workCall() {
        return exec(
                http("POST work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429))
                        .check(bodyString().saveAs("lastBody"))
        ).exec(refreshCsrfFromBody("csrf"));
    }

    private static ChainBuilder workWithRetry() {
        return exec(session -> session.set("workRetries", 0))
                .asLongAs(session -> session.getInt("workRetries") < 4
                        && session.getInt("lastStatus") == 429)
                .on(
                        pause(Duration.ofSeconds(1)),
                        workCall(),
                        exec(session -> session.set("workRetries", session.getInt("workRetries") + 1))
                );
    }

    private static ChainBuilder journey() {
        return exec(session -> session
                        .set("pollCount", 0)
                        .set("reservationStatus", "")
                        .set("reservationId", "")
                        .set("cartId", "")
                        .set("grantId", "")
                        .set("lastStatus", 0)
                        .set("workRetries", 0))
                .exec(loginFlow())
                .exec(fetchCatalog())
                .exec(fetchChallenge())
                .exec(createCart())
                .exec(patchCart())
                .doIf(session -> session.getInt("lastStatus") == 412).then(
                        reReadCart(),
                        patchCart()
                )
                .exec(reserveCart())
                .exec(pollReservation())
                .doIf(session -> "ready".equals(session.getString("reservationStatus"))).then(
                        placeOrder()
                )
                .exec(workWithRetry());
    }

    private static final ScenarioBuilder scn = scenario("ModelSimulation")
            .exec(session -> session.set("username", "bench-" + session.userId()))
            .exec(journey());

    {
        setUp(
                scn.injectOpen(
                        atOnceUsers(2)
                ).protocols(httpProtocol)
        ).maxDuration(Duration.ofMinutes(5));
    }
}
