import http from 'k6/http';
import { check } from 'k6';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

function jar() {
  return http.cookieJar();
}

function parseCsrfFromHtml(body) {
  if (!body) return null;
  // input[name=csrf] with various attribute orders / quoting
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(body)) !== null) {
    const tag = m[0];
    const vm = /\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(tag);
    if (vm) {
      const v = vm[2] !== undefined ? vm[2] : vm[3] !== undefined ? vm[3] : vm[4];
      if (v) return v;
    }
  }
  return null;
}

function parseChallengeForm(body) {
  if (!body) return null;
  const actionM = /<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i.exec(body);
  if (!actionM) return null;
  const action = actionM[1];
  const re = /<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(body)) !== null) {
    const tag = m[0];
    const vm = /\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(tag);
    if (vm) {
      const v = vm[2] !== undefined ? vm[2] : vm[3] !== undefined ? vm[3] : vm[4];
      if (v) return { action, value: v };
    }
  }
  return null;
}

function absUrl(u) {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.startsWith('/')) return BASE + u;
  return BASE + '/' + u;
}

function sleepMs(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) { /* busy wait */ }
}

function newSession() {
  return {
    csrf: null,
    user: null,
    cartId: null,
    etag: null,
    idemKey: null,
    reservationId: null,
    grantId: null,
  };
}

function getLoginForm(j) {
  const res = http.get(BASE + '/v2/login-form', { jar: j, redirects: 0 });
  check(res, { 'login-form 200': (r) => r.status === 200 });
  return parseCsrfFromHtml(res.body);
}

function doLogin(j, username) {
  const formCsrf = getLoginForm(j);
  check(formCsrf, { 'login form csrf extracted': (v) => !!v });
  if (!formCsrf) return null;
  const res = http.post(BASE + '/v2/login', JSON.stringify({
    username,
    password: 'bench',
    csrf: formCsrf,
  }), {
    jar: j,
    redirects: 0,
    headers: { 'Content-Type': 'application/json' },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (res.status === 302) {
    const loc = res.headers['Location'] || res.headers['location'];
    if (loc) {
      const r2 = http.get(absUrl(loc), { jar: j, redirects: 0 });
      try { body = r2.json(); } catch (e) { body = null; }
    }
  }
  check(body && body.csrf, { 'login returned csrf': (v) => !!v });
  if (!body || !body.csrf) return null;
  return { csrf: body.csrf, user: body.user };
}

function renew(j, s) {
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    jar: j,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': s.csrf,
    },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.csrf) s.csrf = body.csrf;
  return res;
}

function recoverCart(j, s) {
  if (!s.cartId) return;
  const res = http.post(BASE + '/v2/carts/' + s.cartId + '/recover', '{}', {
    jar: j,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': s.csrf,
    },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.csrf) s.csrf = body.csrf;
}

function handle401(j, s, res) {
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  const err = body && body.error;
  if (err === 'expired') {
    renew(j, s);
    if (s.cartId) recoverCart(j, s);
    return 'expired';
  }
  if (err === 'session') {
    renew(j, s);
    if (s.cartId) recoverCart(j, s);
    return 'session';
  }
  return 'denied';
}

function authHeaders(s, extra) {
  const h = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': s.csrf,
  };
  if (extra) Object.assign(h, extra);
  return h;
}

function captureCsrf(s, body) {
  if (body && body.csrf) s.csrf = body.csrf;
}

function fetchCatalog(j) {
  const res = http.get(BASE + '/v2/catalog', { jar: j, redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return body;
}

function fetchCatalogPage(j, url) {
  const res = http.get(absUrl(url), { jar: j, redirects: 0 });
  check(res, { 'catalog page 200': (r) => r.status === 200 });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return body;
}

function pickProduct(catalog) {
  if (!catalog || !catalog.data || !catalog.data.products) return null;
  for (const p of catalog.data.products) {
    if (!p.variants) continue;
    for (const v of p.variants) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function pickProductFromPage(page) {
  if (!page) return null;
  const p = page.product || (page.data && page.data.product);
  if (!p || !p.variants) return null;
  for (const v of p.variants) {
    if (v.in_stock) return { product_id: p.id, variant_id: v.id };
  }
  return null;
}

function findProduct(j) {
  const cat = fetchCatalog(j);
  let pick = pickProduct(cat);
  if (pick) return pick;
  // traverse pages
  let next = cat && cat.next;
  let pages = 0;
  while (next && pages < 3) {
    const page = fetchCatalogPage(j, next);
    pick = pickProductFromPage(page);
    if (pick) return pick;
    next = page && page.next;
    pages++;
  }
  return null;
}

function solveChallenge(j, s) {
  const res = http.get(BASE + '/v2/challenge-form', { jar: j, redirects: 0 });
  check(res, { 'challenge-form 200': (r) => r.status === 200 });
  const form = parseChallengeForm(res.body);
  check(form, { 'challenge form parsed': (v) => !!v });
  if (!form) return null;
  const post = http.post(absUrl(form.action), JSON.stringify({ challenge: form.value }), {
    jar: j,
    redirects: 0,
    headers: authHeaders(s),
  });
  let loc = post.headers['Location'] || post.headers['location'];
  if (post.status === 302 && loc) {
    const r2 = http.get(absUrl(loc), { jar: j, redirects: 0 });
    let body = null;
    try { body = r2.json(); } catch (e) { body = null; }
    if (body && body.csrf) s.csrf = body.csrf;
    if (body && body.grant_id) return body.grant_id;
  }
  return null;
}

function createCart(j, s, pick, grantId) {
  const payload = { product_id: pick.product_id, variant_id: pick.variant_id };
  if (grantId) payload.grant_id = grantId;
  let res = http.post(BASE + '/v2/carts', JSON.stringify(payload), {
    jar: j,
    redirects: 0,
    headers: authHeaders(s),
  });
  if (res.status === 401) {
    const kind = handle401(j, s, res);
    if (kind === 'denied') return null;
    res = http.post(BASE + '/v2/carts', JSON.stringify(payload), {
      jar: j,
      redirects: 0,
      headers: authHeaders(s),
    });
  }
  check(res, { 'cart created 201': (r) => r.status === 201 });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (!body || !body.id) return null;
  s.cartId = body.id;
  s.etag = res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'];
  s.idemKey = 'idem-' + s.cartId + '-' + Math.random().toString(36).slice(2);
  captureCsrf(s, body);
  return body.id;
}

function patchCart(j, s, quantity) {
  const payload = JSON.stringify({ quantity });
  const doPatch = () => http.patch(BASE + '/v2/carts/' + s.cartId, payload, {
    jar: j,
    redirects: 0,
    headers: authHeaders(s, s.etag ? { 'If-Match': s.etag } : {}),
  });
  let res = doPatch();
  if (res.status === 412) {
    const g = http.get(BASE + '/v2/carts/' + s.cartId, { jar: j, redirects: 0 });
    s.etag = g.headers['Etag'] || g.headers['ETag'] || g.headers['etag'];
    res = doPatch();
  }
  if (res.status === 401) {
    const kind = handle401(j, s, res);
    if (kind === 'denied') return false;
    res = doPatch();
  }
  check(res, { 'cart patched': (r) => r.status === 200 || r.status === 204 });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  captureCsrf(s, body);
  const newEtag = res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'];
  if (newEtag) s.etag = newEtag;
  return res.status === 200 || res.status === 204;
}

function createReservation(j, s) {
  let res = http.post(BASE + '/v2/reservations', JSON.stringify({ cart_id: s.cartId }), {
    jar: j,
    redirects: 0,
    headers: authHeaders(s),
  });
  if (res.status === 401) {
    const kind = handle401(j, s, res);
    if (kind === 'denied') return null;
    res = http.post(BASE + '/v2/reservations', JSON.stringify({ cart_id: s.cartId }), {
      jar: j,
      redirects: 0,
      headers: authHeaders(s),
    });
  }
  check(res, { 'reservation 202': (r) => r.status === 202 });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (!body || !body.status_url) return null;
  captureCsrf(s, body);
  const statusUrl = body.status_url;
  for (let i = 0; i < 5; i++) {
    sleepMs(60);
    const poll = http.get(absUrl(statusUrl), { jar: j, redirects: 0 });
    let pb = null;
    try { pb = poll.json(); } catch (e) { pb = null; }
    if (pb && pb.csrf) s.csrf = pb.csrf;
    if (pb && pb.status === 'ready' && pb.reservation_id) {
      return pb.reservation_id;
    }
    if (pb && (pb.status === 'failed')) return null;
  }
  return null;
}

function placeOrder(j, s) {
  const payload = { cart_id: s.cartId };
  if (s.reservationId) payload.reservation_id = s.reservationId;
  const headers = authHeaders(s, { 'Idempotency-Key': s.idemKey });
  if (s.etag) headers['If-Match'] = s.etag;
  const doPost = () => http.post(BASE + '/v2/orders', JSON.stringify(payload), {
    jar: j,
    redirects: 0,
    headers,
  });
  let res = doPost();
  if (res.status === 401) {
    const kind = handle401(j, s, res);
    if (kind === 'denied') return false;
    res = doPost();
  }
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  captureCsrf(s, body);
  const ok = res.status === 201 && body && body.accepted === true;
  check(res, { 'order accepted': () => ok });
  return ok;
}

function doWork(j, s) {
  let attempts = 0;
  while (attempts < 5) {
    const res = http.post(BASE + '/v2/work', '{}', {
      jar: j,
      redirects: 0,
      headers: authHeaders(s),
    });
    if (res.status === 429) {
      attempts++;
      sleepMs(1000);
      continue;
    }
    if (res.status === 401) {
      const kind = handle401(j, s, res);
      if (kind === 'denied') return false;
      continue;
    }
    let body = null;
    try { body = res.json(); } catch (e) { body = null; }
    captureCsrf(s, body);
    check(res, { 'work ok': (r) => r.status === 200 && body && body.ok === true });
    return res.status === 200;
  }
  return false;
}

export default function () {
  const j = jar();
  const s = newSession();
  const username = 'bench-' + ((__VU - 1) % 16 + 1);

  const login = doLogin(j, username);
  if (!login) return;
  s.csrf = login.csrf;
  s.user = login.user;

  const pick = findProduct(j);
  check(pick, { 'product picked': (v) => !!v });
  if (!pick) return;

  let grantId = null;
  // Try cart creation; if it needs a challenge, solve and retry once
  let cartId = createCart(j, s, pick, null);
  if (!cartId) {
    grantId = solveChallenge(j, s);
    if (grantId) {
      cartId = createCart(j, s, pick, grantId);
    }
  }
  check(cartId, { 'cart exists': (v) => !!v });
  if (!cartId) return;

  if (!patchCart(j, s, 1)) return;

  s.reservationId = createReservation(j, s);
  check(s.reservationId, { 'reservation ready': (v) => !!v });
  if (!s.reservationId) return;

  if (!placeOrder(j, s)) return;

  doWork(j, s);
}
