import os
import re
import time
from urllib.parse import urljoin

from locust import HttpUser, task, between
from locust.exception import StopUser, RescheduleTask
from locust import LoadTestShape

BASE_URL = os.environ["BASE_URL"]
PASSWORD = "bench"


def _extract_csrf(html):
    # find input[name=csrf] value, tolerant of attribute order/quoting
    for m in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r'name\s*=\s*["\']?csrf["\']?', tag, re.IGNORECASE):
            vm = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
            if vm:
                return vm.group(1)
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.1)

    def on_start(self):
        self.iterations_done = 0
        self.max_iterations = 2
        self.csrf = None
        self.session_ok = False

    def _login(self):
        # fresh login each journey
        self.client.cookies.clear()
        with self.client.get("/v2/login-form", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            tok = _extract_csrf(r.text)
            if not tok:
                r.failure("no csrf in login form")
                return False
            self.csrf = tok
        payload = {"username": self.username, "password": PASSWORD, "csrf": self.csrf}
        with self.client.post("/v2/login", json=payload, catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code != 200:
                        r2.failure("login redirect status %s" % r2.status_code)
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("login redirect not json")
                        return False
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    if not data.get("user"):
                        r2.failure("no user in login response")
                        return False
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("login not json")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                if not data.get("user"):
                    r.failure("no user in login response")
                    return False
            else:
                r.failure("login status %s" % r.status_code)
                return False
        self.session_ok = True
        return True

    def _update_csrf(self, resp):
        try:
            data = resp.json()
        except Exception:
            return
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def _renew(self):
        with self.client.post("/v2/session/renew", json={},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 200:
                self._update_csrf(r)
                return True
            r.failure("renew status %s" % r.status_code)
            return False

    def _recover_cart(self, cart_id):
        with self.client.post("/v2/carts/%s/recover" % cart_id, json={},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code in (200, 201):
                self._update_csrf(r)
                return True
            r.failure("recover status %s" % r.status_code)
            return False

    def _handle_401(self, resp, cart_id=None):
        try:
            data = resp.json()
        except Exception:
            return False
        err = data.get("error")
        if err == "expired":
            if self._renew():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        if err == "session":
            if self._renew():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            # fall back to fresh login
            if self._login():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        # denied or other: not expiry
        return False

    def _get_catalog_products(self):
        products = []
        with self.client.get("/v2/catalog", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("catalog status %s" % r.status_code)
                return products
            try:
                data = r.json()
            except Exception:
                r.failure("catalog not json")
                return products
            for p in data.get("data", {}).get("products", []):
                products.append(p)
        # traverse pages up to 3
        next_url = data.get("next") if isinstance(data, dict) else None
        pages = 0
        while next_url and pages < 3:
            pages += 1
            url = next_url if next_url.startswith("http") else urljoin(BASE_URL, next_url)
            with self.client.get(url, catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure("catalog page status %s" % r.status_code)
                    break
                try:
                    data = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    break
                if isinstance(data, dict) and data.get("product"):
                    products.append(data["product"])
                next_url = data.get("next") if isinstance(data, dict) else None
        return products

    def _pick_variant(self, products):
        for p in products:
            for v in p.get("variants", []):
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        return None, None

    def _get_challenge_grant(self):
        with self.client.get("/v2/challenge-form", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            html = r.text
            am = re.search(r'action\s*=\s*["\']([^"\']*challenges[^"\']*)["\']', html, re.IGNORECASE)
            if not am:
                r.failure("no challenge action")
                return None
            action = am.group(1)
            cm = re.search(r'name\s*=\s*["\']?challenge["\']?[^>]*value\s*=\s*["\']([^"\']*)["\']', html, re.IGNORECASE)
            if not cm:
                cm = re.search(r'value\s*=\s*["\']([^"\']*)["\'][^>]*name\s*=\s*["\']?challenge["\']?', html, re.IGNORECASE)
            if not cm:
                r.failure("no challenge value")
                return None
            challenge = cm.group(1)
        url = action if action.startswith("http") else urljoin(BASE_URL, action)
        with self.client.post(url, json={"challenge": challenge},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    return None
                r.failure("challenge post 401")
                return None
            if r.status_code != 302:
                r.failure("challenge post status %s" % r.status_code)
                return None
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge 302 no Location")
                return None
        loc_url = loc if loc.startswith("http") else urljoin(BASE_URL, loc)
        with self.client.get(loc_url, catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge location status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("challenge location not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("grant_id")

    def _create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload,
                              headers={"X-CSRF-Token": self.csrf or ""},
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    return None
                r.failure("cart create 401")
                return None
            if r.status_code != 201:
                r.failure("cart create status %s" % r.status_code)
                return None
            self._update_csrf(r)
            try:
                data = r.json()
            except Exception:
                r.failure("cart create not json")
                return None
            return data.get("id")

    def _patch_quantity(self, cart_id, qty):
        # read etag
        with self.client.get("/v2/carts/%s" % cart_id, catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    return self._patch_quantity(cart_id, qty)
                r.failure("cart get 401")
                return False
            if r.status_code != 200:
                r.failure("cart get status %s" % r.status_code)
                return False
            etag = r.headers.get("ETag")
        headers = {"X-CSRF-Token": self.csrf or "", "Content-Type": "application/json"}
        if etag:
            headers["If-Match"] = etag
        with self.client.patch("/v2/carts/%s" % cart_id, json={"quantity": qty},
                               headers=headers, catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    return self._patch_quantity(cart_id, qty)
                r.failure("cart patch 401")
                return False
            if r.status_code == 412:
                # re-read and retry once
                with self.client.get("/v2/carts/%s" % cart_id, catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code != 200:
                        r2.failure("cart re-read status %s" % r2.status_code)
                        return False
                    etag2 = r2.headers.get("ETag")
                headers2 = {"X-CSRF-Token": self.csrf or "", "Content-Type": "application/json"}
                if etag2:
                    headers2["If-Match"] = etag2
                with self.client.patch("/v2/carts/%s" % cart_id, json={"quantity": qty},
                                       headers=headers2, catch_response=True, allow_redirects=False) as r3:
                    if r3.status_code == 401:
                        if self._handle_401(r3, cart_id):
                            return self._patch_quantity(cart_id, qty)
                        r3.failure("cart patch retry 401")
                        return False
                    if r3.status_code not in (200, 204):
                        r3.failure("cart patch retry status %s" % r3.status_code)
                        return False
                    self._update_csrf(r3)
                    return True
            if r.status_code not in (200, 204):
                r.failure("cart patch status %s" % r.status_code)
                return False
            self._update_csrf(r)
            return True

    def _reserve(self, cart_id):
        with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    return self._reserve(cart_id)
                r.failure("reservation 401")
                return None
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None
            self._update_csrf(r)
            try:
                data = r.json()
            except Exception:
                r.failure("reservation not json")
                return None
            status_url = data.get("status_url")
        if not status_url:
            return None
        url = status_url if status_url.startswith("http") else urljoin(BASE_URL, status_url)
        for i in range(5):
            if i > 0:
                time.sleep(0.06)
            with self.client.get(url, catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure("reservation status %s" % r.status_code)
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("reservation status not json")
                    return None
                st = data.get("status")
                if st == "ready":
                    return data.get("reservation_id")
                if st in ("pending",):
                    continue
                if st in ("failed",):
                    return None
        return None

    def _checkout(self, cart_id, reservation_id):
        headers = {"X-CSRF-Token": self.csrf or "", "Idempotency-Key": "idem-%s" % cart_id}
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        # read etag if required
        with self.client.get("/v2/carts/%s" % cart_id, catch_response=True, allow_redirects=False) as r:
            if r.status_code == 200:
                etag = r.headers.get("ETag")
                if etag:
                    headers["If-Match"] = etag
        with self.client.post("/v2/orders", json=payload, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    return self._checkout(cart_id, reservation_id)
                r.failure("order 401")
                return False
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order not json")
                    return False
                if data.get("accepted") is False:
                    r.failure("order business failure")
                    return False
                self._update_csrf(r)
                return True
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order not json")
                    return False
                if data.get("accepted") is not True:
                    r.failure("order not accepted")
                    return False
                self._update_csrf(r)
                return True
            r.failure("order status %s" % r.status_code)
            return False

    def _do_work(self):
        for attempt in range(5):
            with self.client.post("/v2/work", json={},
                                  headers={"X-CSRF-Token": self.csrf or ""},
                                  catch_response=True, allow_redirects=False) as r:
                if r.status_code == 200:
                    try:
                        data = r.json()
                    except Exception:
                        r.failure("work not json")
                        return
                    if not data.get("ok"):
                        r.failure("work not ok")
                    return
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    time.sleep(delay)
                    continue
                if r.status_code == 401:
                    if self._handle_401(r):
                        continue
                    r.failure("work 401")
                    return
                r.failure("work status %s" % r.status_code)
                return

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self._login():
            raise StopUser()

        products = self._get_catalog_products()
        product_id, variant_id = self._pick_variant(products)
