    static String csrfFromHtml(String body) {
        if (body == null) return null;
        // find input[name=csrf] value=... (attribute order may vary)
        int idx = 0;
        while (true) {
            int i = body.indexOf("name=\"csrf\"", idx);
            if (i < 0) {
                i = body.indexOf("name='csrf'", idx);
                if (i < 0) return null;
            }
            // find enclosing <input ...>
            int start = body.lastIndexOf("<input", i);
            int end = body.indexOf(">", i);
            if (start < 0 || end < 0) return null;
            String tag = body.substring(start, end);
            String v = attr(tag, "value");
            if (v != null) return v;
            idx = end + 1;
        }
    }

    static String attr(String tag, String name) {
        String[] pats = {" " + name + "=\"", " " + name + "='", "\t" + name + "=\"", "\n" + name + "=\""};
        for (String p : pats) {
            int i = tag.indexOf(p);
            if (i >= 0) {
                char q = p.charAt(p.length() - 1);
                int s = i + p.length();
                int e = tag.indexOf(q, s);
                if (e > s) return tag.substring(s, e);
            }
        }
        return null;
    }

    static String jsonStr(String body, String key) {
        if (body == null) return null;
        String needle = "\"" + key + "\"";
        int i = body.indexOf(needle);
        if (i < 0) return null;
        int c = body.indexOf(':', i + needle.length());
        if (c < 0) return null;
        int p = c + 1;
        while (p < body.length() && Character.isWhitespace(body.charAt(p))) p++;
        if (p >= body.length()) return null;
        char ch = body.charAt(p);
        if (ch == '"') {
            int e = body.indexOf('"', p + 1);
            if (e < 0) return null;
            return body.substring(p + 1, e);
        }
        int e = p;
        while (e < body.length() && ",}] \n\r\t".indexOf(body.charAt(e)) < 0) e++;
        return body.substring(p, e);
    }

