```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const businessFailure = new Counter('business_failure');

function jar() {
  return http.cookieJar();
}

function parseCsrf(html) {
  if (!html) return null;
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  // fallback: value before name
  const re2 = /<input\b[^>]*\bvalue\s*=\s*["']([^"']*)["'][^>]*\bname\s*=\s*["']?csrf["']?/gi;
  while ((m = re2.exec(html)) !== null) {
    return m[1];
  }
  return null;
}

function getLoginForm(cj) {
  const res = http.get(`${BASE}/v2/login-form`, { jar: cj, redirects: 0 });
  check(res, { 'login-form 200': (r) => r.status === 200 });
  return parseCsrf(res.body);
}

function login(cj, username) {
  const csrf = getLoginForm(cj);
  check(csrf, { 'login csrf present': (c) => !!c });
  const res = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf }),
    { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (res.status === 302) {
    const loc = res.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: cj, redirects: 0 });
      try { body = follow.json(); } catch (e) { body = null; }
    }
  }
  check(res, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  check(body, { 'login body': (b) => b && b.csrf });
  return body ? body.csrf : null;
}

function getCatalog(cj) {
  const res = http.get(`${BASE}/v2/catalog`, { jar: cj, redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return body;
}

function pickProduct(catalog) {
  if (!catalog || !catalog.data || !catalog.data.products) return null;
  for (const p of catalog.data.products) {
    if (!p.variants) continue;
    for (const v of p.variants) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function getChallengeGrant(cj, csrf) {
  const res = http.get(`${BASE}/v2/challenge-form`, { jar: cj, redirects: 0 });
  check(res, { 'challenge-form 200': (r) => r.status === 200 });
  const actionM = res.body && res.body.match(/action\s*=\s*["']([^"']+)["']/i);
  const challengeM = res.body && res.body.match(/name\s*=\s*["']?challenge["']?[^>]*value\s*=\s*["']([^"']*)["']/i);
  if (!actionM || !challengeM) return null;
  const action = actionM[1].startsWith('http') ? actionM[1] : `${BASE}${actionM[1]}`;
  const post = http.post(
    action,
    JSON.stringify({ challenge: challengeM[1] }),
    { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf } }
  );
  check(post, { 'challenge post 302': (r) => r.status === 302 });
  const loc = post.headers['Location'];
  if (!loc) return null;
  const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: cj, redirects: 0 });
  let body = null;
  try { body = follow.json(); } catch (e) { body = null; }
  check(body, { 'grant body': (b) => b && b.grant_id });
  return body ? { grant_id: body.grant_id, csrf: body.csrf || csrf } : null;
}

function createCart(cj, csrf, product, grantId) {
  const payload = { product_id: product.product_id, variant_id: product.variant_id };
  if (grantId) payload.grant_id = grantId;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  check(res, { 'cart 201': (r) => r.status === 201 });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return { body, etag: res.headers['Etag'] || res.headers['ETag'] };
}

function renewSession(cj, csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return { status: res.status, body };
}

function recoverCart(cj, csrf, cartId) {
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return { status: res.status, body };
}

function isExpired(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'expired';
  } catch (e) {
    return false;
  }
}

function isSessionRevoked(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'session';
  } catch (e) {
    return false;
  }
}

function isDenied(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'denied';
  } catch (e) {
    return false;
  }
}

function patchQuantity(cj, csrf, cartId, etag, qty) {
  const res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: qty }), {
    jar: cj,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag || '',
    },
  });
  return res;
}

function getCart(cj, cartId) {
  const res = http.get(`${BASE}/v2/carts/${cartId}`, { jar: cj, redirects: 0 });
  return res;
}

function doReservation(cj, csrf, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return { status: res.status, body, csrf: (body && body.csrf) || csrf };
}

function pollReservation(cj, statusUrl) {
  const url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const res = http.get(url, { jar: cj, redirects: 0 });
    let body = null;
    try { body = res.json(); } catch (e) { body = null; }
    if (body && body.status === 'ready') return body;
    if (body && (body.status === 'failed')) return body;
  }
  return null;
}

function placeOrder(cj, csrf, cartId, etag, reservationId, idemKey) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    jar: cj,
    redirects: 0,
    headers,
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return { status: res.status, body, csrf: (body && body.csrf) || csrf };
}

function doWork(cj, csrf) {
  for (let i = 0; i < 5; i++) {
    const res = http.post(`${BASE}/v2/work`, JSON.stringify({}), {
      jar: cj,
      redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    });
    if (res.status === 429) {
      const ra = parseInt(res.headers['Retry-After'] || '1', 10);
      sleep(ra);
      continue;
    }
    if (res.status === 200) {
      let body = null;
      try { body = res.json(); } catch (e) { body = null; }
      check(body, { 'work ok': (b) => b && b.ok === true });
      return { status: 200, csrf };
    }
    if (res.status === 500) {
      businessFailure.add(1);
      return { status: 500, csrf };
    }
    if (isExpired(res)) {
      return { status: 401, expired: true, csrf };
    }
    return { status: res.status, csrf };
  }
  return { status: 429, csrf };
}

export default function () {
  const vu = __VU;
  const iter = __ITER;
  const username = `bench-${((vu - 1) * 2 + iter) % 16 + 1}`;
  const cj = jar();

  // Fresh login
  let csrf = login(cj, username);
  check(csrf, { 'csrf after login': (c) => !!c });
  if (!csrf) return;

  // Catalog
  const catalog = getCatalog(cj);
  const product = pickProduct(catalog);
  check(product, { 'product picked': (p) => !!p });
  if (!product) return;

  // Challenge grant
  const grant = getChallengeGrant(cj, csrf);
  if (grant && grant.csrf) csrf = grant.csrf;
  const grantId = grant ? grant.grant_id : null;

  // Create cart
  let cart = createCart(cj, csrf, product, grantId);
  check(cart.body, { 'cart created': (b) => b && b.id });
  if (!cart.body || !cart.body.id) return;
  const cartId = cart.body.id;
  if (cart.body.csrf) csrf = cart.body.csrf;
  let etag = cart.etag;

  // Simulate expiry: wait for expire_after (2s) then attempt PATCH
  sleep(2.2);

  // PATCH quantity with expiry recovery
  let patched = false;
  let patchRes = patchQuantity(cj, csrf, cartId, etag, 2);
  if (isExpired(patchRes)) {
    // renew
    const renew = renewSession(cj, csrf);
    check(renew, { 'renew attempted': (r) => r.status === 200 || r.status === 401 });
    if (renew.body && renew.body.csrf) csrf = renew.body.csrf;
    // recover cart
    const rec = recoverCart(cj, csrf, cartId);
    check(rec, { 'recover attempted': (r) => r.status === 200 || r.status === 201 || r.status === 401 });
    if (rec.body && rec.body.csrf) csrf = rec.body.csrf;
    // retry once
    patchRes = patchQuantity(cj, csrf, cartId, etag, 2);
  }
  if (patchRes.status === 412) {
    const reread = getCart(cj, cartId);
    etag = reread.headers['Etag'] || reread.headers['ETag'] || etag;
    patchRes = patchQuantity(cj, csrf, cartId, etag, 2);
  }
  if (patchRes.status === 200 || patchRes.status === 204) {
    patched = true;
    etag = patchRes.headers['Etag'] || patchRes.headers['ETag'] || etag;
    try {
      const pb = patchRes.json();
      if (pb && pb.csrf) csrf = pb.csrf;
    } catch (e) {}
  }
  check(patched, { 'patch succeeded': (p) => p === true });

  // Reservation
  let reservationId = null;
  let resv = doReservation(cj, csrf, cartId);
  if (isExpired({ status: resv.status, json: () => resv.body })) {
    const renew = renewSession(cj, csrf);
    if (renew.body && renew.body.csrf) csrf = renew.body.csrf;
    recoverCart(cj, csrf, cartId);
    resv = doReservation(cj, csrf, cartId);
  }
  if (resv.csrf) csrf = resv.csrf;
  if (resv.status === 202 && resv.body && resv.body.status_url) {
    const polled = pollReservation(cj, resv.body.status_url);
    if (polled && polled.status === 'ready' && polled.reservation_id) {
      reservationId = polled.reservation_id;
      if (polled.csrf) csrf = polled.csrf;
    }
  }

  // Order
  const idemKey = `idem-${username}-${cartId}-${Date.now()}`;
  let order = placeOrder(cj, csrf, cartId, etag, reservationId, idemKey);
  if (isExpired({ status: order.status, json: () => order.body })) {
    const renew = renewSession(cj, csrf);
    if (renew.body && renew.body.csrf) csrf = renew.body.csrf;
    recoverCart(cj, csrf, cartId);
    order = placeOrder(cj, csrf, cartId, etag, reservationId, idemKey);
  }
  if (order.csrf) csrf = order.csrf;

  check(order, {
    'order 201': (o) => o.status === 201,
    'order accepted': (o) => o.body && o.body.accepted === true,
  });

  // Work
  const work = doWork(cj, csrf);
  if (work.expired) {
    const renew = renewSession(cj, csrf);
    if (renew.body && renew.body.csrf) csrf = renew.body.csrf;
    doWork(cj, csrf);
  }
}
