import os
import re
import time
import uuid
from urllib.parse import urljoin

from locust import HttpUser, task, between
from locust.exception import StopUser, RescheduleTaskImmediately
from locust import LoadTestShape


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL + "/", url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.password = "bench"
        self.csrf = None
        self.session_ok = False
        self.iterations_done = 0
        self.max_iterations = 2
        self._assigned = False

    # ---------- helpers ----------
    def _extract_csrf(self, text):
        if not text:
            return None
        # input[name=csrf] with mixed attribute variants
        m = re.search(
            r'<input[^>]*name\s*=\s*["\']?csrf["\']?[^>]*>',
            text,
            re.IGNORECASE,
        )
        if not m:
            return None
        tag = m.group(0)
        v = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
        if v:
            return v.group(1)
        return None

    def _extract_form_action(self, text, pattern):
        if not text:
            return None
        m = re.search(
            r'<form[^>]*action\s*=\s*["\']([^"\']+)["\']',
            text,
            re.IGNORECASE,
        )
        if m and re.search(pattern, m.group(1)):
            return m.group(1)
        # fallback: any action matching pattern
        for mm in re.finditer(r'action\s*=\s*["\']([^"\']+)["\']', text, re.IGNORECASE):
            if re.search(pattern, mm.group(1)):
                return mm.group(1)
        return None

    def _extract_input_value(self, text, name):
        if not text:
            return None
        m = re.search(
            r'<input[^>]*name\s*=\s*["\']?' + re.escape(name) + r'["\']?[^>]*>',
            text,
            re.IGNORECASE,
        )
        if not m:
            return None
        v = re.search(r'value\s*=\s*["\']([^"\']*)["\']', m.group(0), re.IGNORECASE)
        return v.group(1) if v else None

    def _assign_user(self):
        if self._assigned:
            return
        self._assigned = True
        # assign bench-1..bench-16 based on a stable hash of the user id
        try:
            idx = (hash(self.environment.runner.user_classes) if False else 0)
        except Exception:
            idx = 0
        # Use a counter on the runner if available
        runner = getattr(self.environment, "runner", None)
        n = None
        if runner is not None:
            lock = getattr(runner, "_bench_lock", None)
            if lock is None:
                import threading
                lock = threading.Lock()
                try:
                    runner._bench_lock = lock
                except Exception:
                    lock = None
            if lock is not None:
                with lock:
                    c = getattr(runner, "_bench_counter", 0)
                    n = c
                    try:
                        runner._bench_counter = c + 1
                    except Exception:
                        pass
        if n is None:
            n = 0
        self.username = "bench-%d" % ((n % 16) + 1)

    def _login(self):
        self._assign_user()
        # GET login form
        with self.client.get(
            "/v2/login-form",
            name="GET /v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = self._extract_csrf(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return False
            self.csrf = csrf
        # POST login
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": self.csrf},
            name="POST /v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(
                    _abs(loc),
                    name="GET login redirect",
                    catch_response=True,
                    allow_redirects=False,
                ) as r2:
                    if r2.status_code not in (200, 204):
                        r2.failure("login redirect status %s" % r2.status_code)
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        data = None
                    if isinstance(data, dict) and data.get("csrf"):
                        self.csrf = data["csrf"]
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    data = None
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
            else:
                r.failure("login status %s" % r.status_code)
                return False
        self.session_ok = True
        return True

    def _renew_session(self):
        if not self.csrf:
            return False
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/session/renew",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    data = None
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            return False

    def _fresh_login(self):
        self.session_ok = False
        return self._login()

    def _recover_cart(self, cart_id):
        if not cart_id or not self.csrf:
            return False
        with self.client.post(
            "/v2/carts/%s/recover" % cart_id,
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/carts/[id]/recover",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code in (200, 201, 204):
                try:
                    data = r.json()
                except Exception:
                    data = None
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            return False

    def _handle_401(self, r, cart_id=None):
        """Return True if recovered (caller should retry once)."""
        try:
            data = r.json()
        except Exception:
            data = None
        err = None
        if isinstance(data, dict):
            err = data.get("error")
        if err == "expired":
            if self._renew_session():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        if err == "session":
            if self._fresh_login():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        if err == "denied":
            return False
        return False

    def _get_catalog_product(self):
        # Try paged catalog first (reverse_catalog variant), fall back to /v2/catalog
        product = None
        next_url = "/v2/catalog/page"
        pages = 0
        while next_url and pages < 3:
            pages += 1
            with self.client.get(
                _abs(next_url),
                name="GET /v2/catalog/page",
                catch_response=True,
                allow_redirects=False,
            ) as r:
                if r.status_code != 200:
                    r.failure("catalog page status %s" % r.status_code)
                    break
                try:
                    data = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    break
                prod = data.get("product") if isinstance(data, dict) else None
                if prod is None and isinstance(data, dict):
                    d = data.get("data")
                    if isinstance(d, dict):
                        prods = d.get("products") or []
                        if prods:
                            prod = prods[0]
                if prod:
                    product = prod
                    break
                nxt = data.get("next") if isinstance(data, dict) else None
                if not nxt:
                    break
                next_url = nxt
        if product is None:
            with self.client.get(
                "/v2/catalog",
                name="GET /v2/catalog",
                catch_response=True,
                allow_redirects=False,
            ) as r:
                if r.status_code != 200:
                    r.failure("catalog status %s" % r.status_code)
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("catalog not json")
                    return None
                prods = ((data or {}).get("data") or {}).get("products") or []
                if not prods:
                    r.failure("no products")
                    return None
                product = prods[0]
        # pick variant
        variants = product.get("variants") or []
        chosen = None
        for v in variants:
            if v.get("in_stock"):
                chosen = v
                break
        if chosen is None and variants:
            chosen = variants[0]
        if chosen is None:
            return None
        return {"product_id": product.get("id"), "variant_id": chosen.get("id")}

    def _maybe_challenge(self):
        """Return grant_id or None."""
        with self.client.get(
            "/v2/challenge-form",
            name="GET /v2/challenge-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            action = self._extract_form_action(r.text, r"/v2/challenges/")
            challenge_val = self._extract_input_value(r.text, "challenge")
            if not action or not challenge_val:
                r.failure("challenge form missing fields")
                return None
        with self.client.post(
            _abs(action),
            json={"challenge": challenge_val},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/challenges/[id]",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 302:
                r.failure("challenge post status %s" % r.status_code)
                return None
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge 302 no Location")
                return None
        with self.client.get(
            _abs(loc),
            name="GET challenge redirect",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure("challenge redirect status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("challenge redirect not json")
                return None
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]
            return (data or {}).get("grant_id")

    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/carts",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    # retry once
                    with self.client.post(
                        "/v2/carts",
                        json=payload,
                        headers={"X-CSRF-Token": self.csrf},
                        name="POST /v2/carts",
                        catch_response=True,
                        allow_redirects=False,
                    ) as r2:
                        if r2.status_code != 201:
                            r2.failure("cart retry status %s" % r2.status_code)
                            return None
                        return self._parse_cart(r2)
                r.failure("cart 401 unrecovered")
                return None
            if r.status_code != 201:
                r.failure("cart status %s" % r.status_code)
                return None
            return self._parse_cart(r)

    def _parse_cart(self, r):
        try:
            data = r.json()
        except Exception:
            r.failure("cart not json")
            return None
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]
        etag = r.headers.get("ETag")
        return {"id": (data or {}).get("id"), "etag": etag}

    def _patch_cart(self, cart_id, etag, quantity):
        payload = {"quantity": quantity}
        headers = {"X-CSRF-Token": self.csrf}
        if etag:
            headers["If-Match"] = etag
        with self.client.patch(
            "/v2/carts/%s" % cart_id,
            json=payload,
            headers=headers,
            name="PATCH /v2/carts/[id]",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 412:
                # re-read and retry once
                with self.client.get(
                    "/v2/carts/%s" % cart_id,
                    name="GET /v2/carts/[id]",
                    catch_response=True,
                    allow_redirects=False,
                ) as rg:
                    if rg.status_code != 200:
                        rg.failure("cart re-read status %s" % rg.status_code)
                        return None
                    new_etag = rg.headers.get("ETag")
                headers2 = {"X-CSRF-Token": self.csrf}
                if new_etag:
                    headers2["If-Match"] = new_etag
                with self.client.patch(
                    "/v2/carts/%s" % cart_id,
                    json=payload,
                    headers=headers2,
                    name="PATCH /v2/carts/[id]",
                    catch_response=True,
                    allow_redirects=False,
                ) as r2:
                    if r2.status_code not in (200, 204):
                        r2.failure("cart patch retry status %s" % r2.status_code)
                        return None
                    return r2.headers.get("ETag") or new_etag
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    headers3 = {"X-CSRF-Token": self.csrf}
                    if etag:
                        headers3["If-Match"] = etag
                    with self.client.patch(
                        "/v2/carts/%s" % cart_id,
                        json=payload,
                        headers=headers3,
                        name="PATCH /v2/carts/[id]",
                        catch_response=True,
                        allow_redirects=False,
                    ) as r3:
                        if r3.status_code not in (200, 204):
                            r3.failure("cart patch after recover status %s" % r3.status_code)
                            return None
                        return r3.headers.get("ETag") or etag
                r.failure("cart patch 401 unrecovered")
                return None
            if r.status_code not in (200, 204):
                r.failure("cart patch status %s" % r.status_code)
                return None
            return r.headers.get("ETag") or etag

    def _reserve(self, cart_id):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": cart_id},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/reservations",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    with self.client.post(
                        "/v2/reservations",
                        json={"cart_id": cart_id},
                        headers={"X-CSRF-Token": self.csrf},
                        name="POST /v2/reservations",
                        catch_response=True,
                        allow_redirects=False,
                    ) as r2:
                        if r2.status_code != 202:
                            r2.failure("reservation retry status %s" % r2.status_code)
                            return None
                        return self._poll_reservation(r2)
                r.failure("reservation 401 unrecovered")
                return None
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None
            return self._poll_reservation(r)

    def _poll_reservation(self, r):
        try:
            data = r.json()
        except Exception:
            r.failure("reservation not json")
            return None
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]
        status_url = (data or {}).get("status_url")
        if not status_url:
            r.failure("no status_url")
            return None
        for i in range(5):
            time.sleep(0.06)
            with self.client.get(
                _abs(status_url),
                name="GET reservation status",
                catch_response=True,
                allow_redirects=False,
            ) as rs:
                if rs.status_code != 200:
                    rs.failure("reservation status http %s" % rs.status_code)
                    return None
                try:
                    sd = rs.json()
                except Exception:
                    rs.failure("reservation status not json")
                    return None
                st = (sd or {}).get("status")
                if st == "ready":
                    rid = (sd or {}).get("reservation_id")
                    if not rid:
                        rs.failure("ready without reservation_id")
                        return None
                    return rid
                if st in ("pending",):
                    continue
                if st in ("failed",):
                    rs.failure("reservation failed")
                    return None
                rs.failure("unknown reservation status %s" % st)
                return None
        return None

    def _checkout(self, cart_id, reservation_id, idem_key):
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": idem_key,
        }
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            name="POST /v2/orders",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    headers2 = {
                        "X-CSRF-Token": self.csrf,
                        "Idempotency-Key": idem_key,
                    }
                    with self.client.post(
                        "/v2/orders",
                        json=payload,
                        headers=headers2,
                        name="POST /v2/orders",
                        catch_response=True,
                        allow_redirects=False,
                    ) as r2:
                        return self._check_order_response(r2)
                r.failure("order 401 unrecovered")
                return False
            return self._check_order_response(r)

    def _check_order_response(self, r):
        if r.status_code == 200:
            try:
                data = r.json()
            except Exception:
                data = None
            if isinstance(data, dict) and data.get("accepted") is False:
                r.failure("order accepted:false")
                return False
            r.failure("order 200 without accepted:true")
            return False
        if r.status_code != 201:
            r.failure("order status %s" % r.status_code)
            return False
        try:
            data = r.json()
        except Exception:
            r.failure("order not json")
            return False
        if not (isinstance(data, dict) and data.get("accepted") is True):
            r.failure("order not accepted:true")
            return False
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]
        return True

    def _do_work(self):
        for attempt in range(5):
            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf} if self.csrf else {},
                name="POST /v2/work",
                catch_response=True,
                allow_redirects=False,
            ) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    time.sleep(max(0.05, delay))
                    continue
                if r.status_code == 401:
                    if self._handle_401(r):
                        continue
                    r.failure("work 401 unrecovered")
                    return False
                if r.status_code == 500:
                    r.failure("work 500")
                    return False
                if r.status_code != 200:
                    r.failure("work status %s" % r.status_code)
                    return False
                try:
                    data = r.json()
                except Exception:
                    r.failure("work not json")
                    return False
                if not (isinstance(data, dict) and data.get("ok") is True):
                    r.failure("work not ok")
                    return False
                return True
        return False

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self._login():
            raise StopUser()

        # optional challenge
        grant_id = None
        try:
            grant_id = self._maybe_challenge()
        except Exception:
            grant_id = None

        prod = self._get_catalog_product()
        if not prod:
            raise StopUser()

        cart = self._create_cart(prod["product_id"], prod["variant_id"], grant_id)
        if not cart or not cart.get("id"):
            raise StopUser()
        cart_id = cart["id"]
        etag = cart.get("etag")

        new_etag = self._patch_cart(cart_id, etag, 1)
        if new_etag is None:
            raise StopUser()

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            raise StopUser()

        idem_key = "idem-%s-%s" % (cart_id, uuid.uuid4().hex)
        ok = self._checkout(cart_id, reservation_id, idem_key)
        if not ok:
            raise StopUser()

        self._do_work()

        if self.iterations_done >= self.max_iterations:
            raise StopUser()


