import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    reservation: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const PROFILES = [
  { job_polls: 2, poll_interval: 0.02 },
  { job_polls: 3, poll_interval: 0.02, html_layout: 1, reverse_catalog: true },
];

function parseCsrf(html) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?csrf["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseChallengeAction(html) {
  const re = /<form\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const am = tag.match(/\baction\s*=\s*["']([^"']*)["']/i);
    if (am && /\/v2\/challenges\//.test(am[1])) return am[1];
  }
  return null;
}

function parseChallengeInput(html) {
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?challenge["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function jar() {
  return http.cookieJar();
}

function get(url, params) {
  return http.get(url, params);
}

function post(url, body, params) {
  return http.post(url, body, params);
}

function patch(url, body, params) {
  return http.patch(url, body, params);
}

function jsonBody(obj) {
  return JSON.stringify(obj);
}

function login(user) {
  const formRes = get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body);
  check(csrf, { 'login csrf found': (v) => !!v });

  const loginRes = post(
    `${BASE}/v2/login`,
    jsonBody({ username: user, password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );
  check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });

  let token = csrf;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    check(loc, { 'login redirect location': (v) => !!v });
    const followRes = get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
    check(followRes, { 'login follow ok': (r) => r.status === 200 });
    try {
      const j = JSON.parse(followRes.body);
      if (j.csrf) token = j.csrf;
    } catch (e) {}
  } else {
    try {
      const j = JSON.parse(loginRes.body);
      if (j.csrf) token = j.csrf;
    } catch (e) {}
  }
  return token;
}

function renewSession(token) {
  const res = post(`${BASE}/v2/session/renew`, jsonBody({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
    redirects: 0,
  });
  let newToken = token;
  try {
    const j = JSON.parse(res.body);
    if (j.csrf) newToken = j.csrf;
  } catch (e) {}
  return { res, token: newToken };
}

function recoverCart(cartId, token) {
  const res = post(`${BASE}/v2/carts/${cartId}/recover`, jsonBody({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
    redirects: 0,
  });
  let newToken = token;
  try {
    const j = JSON.parse(res.body);
    if (j.csrf) newToken = j.csrf;
  } catch (e) {}
  return { res, token: newToken };
}

function fetchCatalog(profile) {
  const products = [];
  // page traversal
  let url = `${BASE}/v2/catalog/page`;
  let pages = 0;
  while (url && pages < 3) {
    const res = get(url, { redirects: 0 });
    check(res, { 'catalog page ok': (r) => r.status === 200 });
    let j;
    try { j = JSON.parse(res.body); } catch (e) { break; }
    if (j.product) products.push(j.product);
    else if (j.data && j.data.product) products.push(j.data.product);
    const next = j.next;
    if (!next) break;
    url = next.startsWith('http') ? next : `${BASE}${next}`;
    pages++;
  }
  if (products.length === 0) {
    const res = get(`${BASE}/v2/catalog`, { redirects: 0 });
    check(res, { 'catalog ok': (r) => r.status === 200 });
    try {
      const j = JSON.parse(res.body);
      const list = (j.data && j.data.products) || [];
      for (const p of list) products.push(p);
    } catch (e) {}
  }
  if (profile.reverse_catalog) products.reverse();
  return products;
}

function pickVariant(product) {
  const variants = product.variants || [];
  for (const v of variants) {
    if (v.in_stock) return v;
  }
  return variants[0];
}

function solveChallenge(token) {
  const formRes = get(`${BASE}/v2/challenge-form`, { redirects: 0 });
  check(formRes, { 'challenge-form ok': (r) => r.status === 200 });
  const action = parseChallengeAction(formRes.body);
  const challenge = parseChallengeInput(formRes.body);
  check(action, { 'challenge action found': (v) => !!v });
  check(challenge, { 'challenge input found': (v) => !!v });
  if (!action || !challenge) return { grant_id: null, token };

  const actionUrl = action.startsWith('http') ? action : `${BASE}${action}`;
  const postRes = post(actionUrl, jsonBody({ challenge }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
    redirects: 0,
  });
  check(postRes, { 'challenge post ok': (r) => r.status === 302 || r.status === 200 });
  let newToken = token;
  let grantId = null;
  if (postRes.status === 302) {
    const loc = postRes.headers['Location'];
    if (loc) {
      const followRes = get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      check(followRes, { 'challenge follow ok': (r) => r.status === 200 });
      try {
        const j = JSON.parse(followRes.body);
        if (j.grant_id) grantId = j.grant_id;
        if (j.csrf) newToken = j.csrf;
      } catch (e) {}
    }
  } else {
    try {
      const j = JSON.parse(postRes.body);
      if (j.grant_id) grantId = j.grant_id;
      if (j.csrf) newToken = j.csrf;
    } catch (e) {}
  }
  return { grant_id: grantId, token: newToken };
}

function createCart(product, variant, grantId, token) {
  const body = { product_id: product.id, variant_id: variant.id };
  if (grantId) body.grant_id = grantId;
  const res = post(`${BASE}/v2/carts`, jsonBody(body), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
    redirects: 0,
  });
  check(res, { 'cart create 201': (r) => r.status === 201 });
  let cartId = null;
  let newToken = token;
  let etag = res.headers['Etag'] || res.headers['ETag'];
  try {
    const j = JSON.parse(res.body);
    if (j.id) cartId = j.id;
    if (j.csrf) newToken = j.csrf;
  } catch (e) {}
  return { cartId, token: newToken, etag };
}

function getCart(cartId, token) {
  const res = get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
  check(res, { 'cart get ok': (r) => r.status === 200 });
  const etag = res.headers['Etag'] || res.headers['ETag'];
  return { res, etag };
}

function patchCart(cartId, etag, token) {
  const payload = jsonBody({ quantity: 1 });
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': token };
  if (etag) headers['If-Match'] = etag;
  let res = patch(`${BASE}/v2/carts/${cartId}`, payload, { headers, redirects: 0 });
  let newToken = token;
  if (res.status === 412) {
    const reread = getCart(cartId, token);
    const h2 = { 'Content-Type': 'application/json', 'X-CSRF-Token': token };
    if (reread.etag) h2['If-Match'] = reread.etag;
    res = patch(`${BASE}/v2/carts/${cartId}`, payload, { headers: h2, redirects: 0 });
  }
  check(res, { 'cart patch ok': (r) => r.status === 200 || r.status === 204 });
  try {
    const j = JSON.parse(res.body);
    if (j.csrf) newToken = j.csrf;
  } catch (e) {}
  return { res, token: newToken };
}

function createReservation(cartId, token) {
  const res = post(`${BASE}/v2/reservations`, jsonBody({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
    redirects: 0,
  });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  let statusUrl = null;
  let newToken = token;
  try {
    const j = JSON.parse(res.body);
    if (j.status_url) statusUrl = j.status_url;
    if (j.csrf) newToken = j.csrf;
  } catch (e) {}
  return { statusUrl, token: newToken };
}

function pollReservation(statusUrl, token, profile) {
  const maxPolls = Math.min(5, profile.job_polls);
  const interval = profile.poll_interval;
  let reservationId = null;
  let lastStatus = null;
  let polls = 0;
  let url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
  while (polls < maxPolls) {
    if (polls > 0) sleep(interval);
    const res = get(url, { redirects: 0 });
    polls++;
    check(res, { 'poll ok': (r) => r.status === 200 });
    let j;
    try { j = JSON.parse(res.body); } catch (e) { break; }
    lastStatus = j.status;
    if (j.status === 'ready') {
      reservationId = j.reservation_id;
      break;
    }
    if (j.status === 'failed') break;
    if (j.status_url) url = j.status_url.startsWith('http') ? j.status_url : `${BASE}${j.status_url}`;
  }
  check(polls, { 'poll count bounded': (n) => n <= 5 });
  return { reservationId, lastStatus, polls };
}

function checkout(cartId, reservationId, token) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': token,
    'Idempotency-Key': `idem-${cartId}`,
  };
  const body = { cart_id: cartId };
  if (reservationId) body.reservation_id = reservationId;
  const res = post(`${BASE}/v2/orders`, jsonBody(body), { headers, redirects: 0 });
  check(res, { 'order 201': (r) => r.status === 201 });
  let ok = false;
  try {
    const j = JSON.parse(res.body);
    ok = j.accepted === true;
  } catch (e) {}
  check(ok, { 'order accepted': (v) => v === true });
  return res;
}

export default function () {
  const vu = __VU;
  const iter = __ITER;
  const user = `bench-${((vu - 1) % 16) + 1}`;
  const profile = PROFILES[(vu + iter) % PROFILES.length];

  jar().clear(BASE);

  let token = login(user);

  const products = fetchCatalog(profile);
  check(products, { 'products available': (p) => p.length > 0 });
  if (!products.length) return;

  const product = products[0];
  const variant = pickVariant(product);
  check(variant, { 'variant available': (v) => !!v });
  if (!variant) return;

  const ch = solveChallenge(token);
  token = ch.token;

  const cart = createCart(product, variant, ch.grant_id, token);
  token = cart.token;
  check(cart.cartId, { 'cart id': (v) => !!v });
  if (!cart.cartId) return;

  const patched = patchCart(cart.cartId, cart.etag, token);
  token = patched.token;

  const resv = createReservation(cart.cartId, token);
  token = resv.token;
  check(resv.statusUrl, { 'status url': (v) => !!v });
  if (!resv.statusUrl) return;

  const poll = pollReservation(resv.statusUrl, token, profile);

  if (poll.lastStatus === 'ready' && poll.reservationId) {
    checkout(cart.cartId, poll.reservationId, token);
  } else {
    check(poll.lastStatus, { 'not ready -> no checkout': (s) => s !== 'ready' });
  }
}
