import os
import re
import time
import json
from urllib.parse import urljoin

from locust import HttpUser, task, between, events
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL, url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.01, 0.05)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf = None
        self.username = None
        self.password = "bench"
        self.iterations_done = 0
        self.max_iterations = 2
        self.profile = None

    # ---------- helpers ----------
    def _pick_profile(self):
        # Two profiles; alternate based on a stable per-user seed.
        seed = getattr(self, "user_seed", None)
        if seed is None:
            seed = int(time.time() * 1000) % 2
        if seed % 2 == 0:
            return {"job_polls": 2, "poll_interval": 0.02}
        else:
            return {"job_polls": 3, "poll_interval": 0.02,
                    "html_layout": 1, "reverse_catalog": True}

    def _pick_account(self):
        # bench-1..bench-16
        idx = (int(time.time() * 1000) % 16) + 1
        return "bench-%d" % idx

    def _extract_csrf_from_html(self, text):
        # input[name=csrf] mixed with decoys/attribute variants
        patterns = [
            r'<input[^>]*name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']',
            r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']',
        ]
        for p in patterns:
            m = re.search(p, text, re.IGNORECASE)
            if m:
                return m.group(1)
        return None

    def _login(self):
        self.username = self._pick_account()
        # GET login form
        with self.client.get("/v2/login-form", catch_response=True,
                             allow_redirects=False, name="/v2/login-form") as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = self._extract_csrf_from_html(r.text or "")
            if not csrf:
                r.failure("no csrf in login form")
                return False
        # POST login
        with self.client.post("/v2/login",
                              json={"username": self.username,
                                    "password": self.password,
                                    "csrf": csrf},
                              catch_response=True, allow_redirects=False,
                              name="/v2/login") as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if loc:
                    with self.client.get(_abs(loc), catch_response=True,
                                         allow_redirects=False,
                                         name="/v2/login-redirect") as r2:
                        if r2.status_code >= 400:
                            r2.failure("login redirect status %s" % r2.status_code)
                            return False
                        try:
                            body = r2.json()
                        except Exception:
                            body = {}
                        if body.get("csrf"):
                            self.csrf = body["csrf"]
                        else:
                            self.csrf = csrf
                else:
                    self.csrf = csrf
                return True
            elif r.status_code == 200:
                try:
                    body = r.json()
                except Exception:
                    body = {}
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                else:
                    self.csrf = csrf
                return True
            else:
                r.failure("login status %s" % r.status_code)
                return False

    def _headers(self, extra=None):
        h = {}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if extra:
            h.update(extra)
        return h

    def _update_csrf(self, resp):
        try:
            body = resp.json()
        except Exception:
            return
        if isinstance(body, dict) and body.get("csrf"):
            self.csrf = body["csrf"]

    def _renew_session(self):
        with self.client.post("/v2/session/renew", json={},
                              headers=self._headers(),
                              catch_response=True, name="/v2/session/renew") as r:
            if r.status_code == 200:
                self._update_csrf(r)
                return True
            return False

    def _recover_cart(self, cart_id):
        with self.client.post("/v2/carts/%s/recover" % cart_id, json={},
                              headers=self._headers(),
                              catch_response=True,
                              name="/v2/carts/recover") as r:
            if r.status_code in (200, 201):
                self._update_csrf(r)
                return True
            return False

    def _get_catalog_products(self):
        products = []
        # page 1
        with self.client.get("/v2/catalog", catch_response=True,
                             name="/v2/catalog") as r:
            if r.status_code != 200:
                r.failure("catalog status %s" % r.status_code)
                return products
            try:
                body = r.json()
            except Exception:
                r.failure("catalog not json")
                return products
            data = body.get("data") or {}
            for p in data.get("products") or []:
                products.append(p)
            nxt = body.get("next")
        pages = 0
        while nxt and pages < 2:
            pages += 1
            with self.client.get(_abs(nxt), catch_response=True,
                                 name="/v2/catalog/page") as r:
                if r.status_code != 200:
                    r.failure("catalog page status %s" % r.status_code)
                    break
                try:
                    body = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    break
                if body.get("product"):
                    products.append(body["product"])
                elif body.get("data") and body["data"].get("products"):
                    products.extend(body["data"]["products"])
                nxt = body.get("next")
        return products

    def _pick_product_variant(self, products):
        if not products:
            return None, None
        if self.profile and self.profile.get("reverse_catalog"):
            products = list(reversed(products))
        for p in products:
            variants = p.get("variants") or []
            for v in variants:
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        # fallback first
        p = products[0]
        variants = p.get("variants") or []
        if variants:
            return p.get("id"), variants[0].get("id")
        return p.get("id"), None

    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload,
                              headers=self._headers(),
                              catch_response=True, name="/v2/carts") as r:
            if r.status_code == 401:
                try:
                    err = r.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    if self._renew_session():
                        r.success()
                        # retry once
                        with self.client.post("/v2/carts", json=payload,
                                              headers=self._headers(),
                                              catch_response=True,
                                              name="/v2/carts") as r2:
                            if r2.status_code == 201:
                                self._update_csrf(r2)
                                return r2.json().get("id"), r2.headers.get("ETag")
                            r2.failure("cart retry status %s" % r2.status_code)
                            return None, None
                r.failure("cart status 401 %s" % err)
                return None, None
            if r.status_code != 201:
                r.failure("cart status %s" % r.status_code)
                return None, None
            self._update_csrf(r)
            try:
                body = r.json()
            except Exception:
                r.failure("cart not json")
                return None, None
            return body.get("id"), r.headers.get("ETag")

    def _patch_cart(self, cart_id, etag, quantity):
        payload = {"quantity": quantity}
        headers = self._headers({"If-Match": etag} if etag else None)
        with self.client.patch("/v2/carts/%s" % cart_id, json=payload,
                               headers=headers, catch_response=True,
                               name="/v2/carts/patch") as r:
            if r.status_code == 412:
                # re-read and retry once
                with self.client.get("/v2/carts/%s" % cart_id,
                                     catch_response=True,
                                     name="/v2/carts/get") as rg:
                    if rg.status_code != 200:
                        rg.failure("cart get status %s" % rg.status_code)
                        r.failure("412 and re-read failed")
                        return False
                    new_etag = rg.headers.get("ETag")
                headers = self._headers({"If-Match": new_etag} if new_etag else None)
                with self.client.patch("/v2/carts/%s" % cart_id, json=payload,
                                       headers=headers, catch_response=True,
                                       name="/v2/carts/patch") as r2:
                    if r2.status_code in (200, 204):
                        self._update_csrf(r2)
                        return True
                    r2.failure("cart patch retry status %s" % r2.status_code)
                    return False
            if r.status_code in (200, 204):
                self._update_csrf(r)
                return True
            r.failure("cart patch status %s" % r.status_code)
            return False

    def _create_reservation(self, cart_id):
        with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                              headers=self._headers(),
                              catch_response=True,
                              name="/v2/reservations") as r:
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None
            self._update_csrf(r)
            try:
                body = r.json()
            except Exception:
                r.failure("reservation not json")
                return None
            return body.get("status_url")

    def _poll_reservation(self, status_url):
        max_polls = 5
        profile_polls = self.profile.get("job_polls", 2) if self.profile else 2
        interval = self.profile.get("poll_interval", 0.02) if self.profile else 0.02
        polls = 0
        last = 0.0
        while polls < max_polls:
            # enforce separation
            now = time.time()
            if polls > 0:
                wait = interval - (now - last)
                if wait > 0:
                    time.sleep(wait)
            last = time.time()
            polls += 1
            with self.client.get(_abs(status_url), catch_response=True,
                                 name="/v2/reservations/status") as r:
                if r.status_code != 200:
                    r.failure("status poll status %s" % r.status_code)
                    return None
                try:
                    body = r.json()
                except Exception:
                    r.failure("status poll not json")
                    return None
                status = body.get("status")
                if status == "ready":
                    rid = body.get("reservation_id")
                    if not rid:
                        r.failure("ready without reservation_id")
                        return None
                    return rid
                elif status == "failed":
                    # negative control: must not checkout
                    return None
                elif status == "pending":
                    if polls >= profile_polls and polls >= max_polls:
                        break
                    continue
                else:
                    r.failure("unknown status %s" % status)
                    return None
        return None

    def _checkout(self, cart_id, reservation_id, etag):
        idem = "idem-%s-%s" % (cart_id, int(time.time() * 1000))
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = self._headers({"Idempotency-Key": idem})
        if etag:
            headers["If-Match"] = etag
        with self.client.post("/v2/orders", json=payload, headers=headers,
                              catch_response=True, name="/v2/orders") as r:
            if r.status_code == 401:
                try:
                    err = r.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    if self._renew_session():
                        if self._recover_cart(cart_id):
                            r.success()
                            with self.client.post("/v2/orders", json=payload,
                                                  headers=headers,
                                                  catch_response=True,
                                                  name="/v2/orders") as r2:
                                return self._check_order_response(r2)
                r.failure("order 401 %s" % err)
                return False
            return self._check_order_response(r)

    def _check_order_response(self, r):
        if r.status_code == 201:
            try:
                body = r.json()
            except Exception:
                r.failure("order not json")
                return False
            if body.get("accepted") is True and body.get("id"):
                self._update_csrf(r)
                return True
            r.failure("order 201 not accepted")
            return False
        if r.status_code == 200:
            try:
                body = r.json()
            except Exception:
                body = {}
            if body.get("accepted") is False:
                r.failure("order business failure accepted:false")
                return False
            r.failure("order 200 unexpected")
            return False
        r.failure("order status %s" % r.status_code)
        return False

    def _do_work(self):
        with self.client.post("/v2/work", json={}, headers=self._headers(),
                              catch_response=True, name="/v2/work") as r:
            if r.status_code == 429:
                retry_after = r.headers.get("Retry-After", "1")
                try:
                    wait = float(retry_after)
                except Exception:
                    wait = 1.0
                r.success()
                retries = 0
                while retries < 4:
                    retries += 1
                    time.sleep(wait)
                    with self.client.post("/v2/work", json={},
                                          headers=self._headers(),
                                          catch_response=True,
                                          name="/v2/work") as r2:
                        if r2.status_code == 200:
                            self._update_csrf(r2)
                            return True
                        if r2.status_code == 429:
                            r2.success()
                            continue
                        r2.failure("work status %s" % r2.status_code)
                        return False
                return False
            if r.status_code == 200:
                self._update_csrf(r)
                return True
            r.failure("work status %s" % r.status_code)
            return False

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1
        self.profile = self._pick_profile()

        if not self._login():
            raise StopUser()

        products = self._get_catalog_products()
        product_id, variant_id = self._pick_product_variant(products)
        if not product_id:
            raise StopUser()

        cart_id, etag = self._create_cart(product_id, variant_id)
        if not cart_id:
            raise StopUser()

        if not self._patch_cart(cart_id, etag, 1):
            raise StopUser()

        status_url = self._create_reservation(cart_id)
        if not status_url:
            raise StopUser()

        reservation_id = self._poll_reservation(status_url)
        if not reservation_id:
            # pending/failed: never checkout
            raise StopUser()

        # refresh etag
        with self.client.get("/v2/carts/%s" % cart_id, catch_response=True,
                             name="/v2/carts/get") as rg:
            if rg.status_code == 200:
                etag = rg.headers.get("ETag")

        self._checkout(cart_id, reservation_id, etag)
        self._do_work()

        if self.iterations_done >= self.max_iterations:
            raise StopUser()


