Looking at this task, I need to build a Gatling simulation that:
1. Logs in fresh per journey
2. Extracts a one-use challenge from `/v2/challenge-form` (with decoys/attribute variants)
3. Redeems it to get a `grant_id`
4. Creates a cart passing `grant_id` once
5. Reserves, polls, and checks out exactly one order
6. Handles 401 expiry/renewal, 412 retries, 429 retries
7. Supports two profiles (with/without `html_layout`/`reverse_catalog`)

Key constraints: no threads/files/sockets/reflection/System.exit, Java DSL only, default package, `ModelSimulation extends Simulation`, target `BASE_URL` default `http://127.0.0.1:8000`.

```java
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    String baseUrl = System.getenv("BASE_URL") != null
            ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

    HttpProtocolBuilder httpProtocol = http
            .baseUrl(baseUrl)
            .disableAutoRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json")
            .shareConnections();

    // ---------- helpers ----------

    // Extract csrf from login form HTML: input[name=csrf] with decoys/attribute variants.
    // We accept value before or after name, single or double quotes.
    private static final String CSRF_FROM_FORM =
            "input[^>]*name=['\"]?csrf['\"]?[^>]*value=['\"]([^'\"]+)['\"]";

    // Extract challenge input from challenge-form HTML.
    private static final String CHALLENGE_FROM_FORM =
            "input[^>]*name=['\"]?challenge['\"]?[^>]*value=['\"]([^'\"]+)['\"]";

    // Extract form action /v2/challenges/{id}
    private static final String CHALLENGE_ACTION =
            "action=['\"](/v2/challenges/[^'\"]+)['\"]";

    // ---------- reusable chains ----------

    // Fresh login: GET form -> POST login (handle 302) -> capture csrf + session
    ChainBuilder freshLogin =
            exec(http("login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(regex(CSRF_FROM_FORM).saveAs("loginCsrf")))
            .exec(http("login")
                    .post("/v2/login")
                    .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{loginCsrf}\"}"))
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("loginLocation"))
                    .check(bodyString().optional().saveAs("loginBody")))
            .exec(session -> {
                // If 302, follow Location exactly once to obtain csrf/user
                String loc = session.getString("loginLocation");
                if (loc != null && !loc.isEmpty()) {
                    return session.set("followLogin", true);
                }
                return session.set("followLogin", false);
            })
            .doIf(session -> session.getBoolean("followLogin")).then(
                    exec(http("login-follow")
                            .get("#{loginLocation}")
                            .check(status().is(200))
                            .check(jsonPath("$.csrf").saveAs("csrf"))
                            .check(jsonPath("$.user").saveAs("user")))
            )
            .doIf(session -> !session.getBoolean("followLogin")).then(
                    exec(session -> {
                        // parse csrf from body
                        String body = session.getString("loginBody");
                        String csrf = extractJson(body, "csrf");
                        return session.set("csrf", csrf);
                    })
            );

    // Renew session on 401 expired
    ChainBuilder renewSession =
            exec(http("session-renew")
                    .post("/v2/session/renew")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().in(200, 401))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf")))
            .exec(session -> {
                String nc = session.getString("newCsrf");
                if (nc != null && !nc.isEmpty()) {
                    return session.set("csrf", nc);
                }
                return session;
            });

    // Recover cart after session revoked
    ChainBuilder recoverCart =
            exec(http("cart-recover")
                    .post("/v2/carts/#{cartId}/recover")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().in(200, 401, 404))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf2")))
            .exec(session -> {
                String nc = session.getString("newCsrf2");
                if (nc != null && !nc.isEmpty()) {
                    return session.set("csrf", nc);
                }
                return session;
            });

    // Challenge flow: GET challenge-form -> POST action -> GET Location -> grant_id
    ChainBuilder challengeFlow =
            exec(http("challenge-form")
                    .get("/v2/challenge-form")
                    .check(status().is(200))
                    .check(regex(CHALLENGE_ACTION).saveAs("challengeAction"))
                    .check(regex(CHALLENGE_FROM_FORM).saveAs("challengeValue")))
            .exec(http("challenge-submit")
                    .post("#{challengeAction}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"challenge\":\"#{challengeValue}\"}"))
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("challengeLocation")))
            .exec(http("challenge-claim")
                    .get("#{challengeLocation}")
                    .check(status().is(200))
                    .check(jsonPath("$.grant_id").saveAs("grantId"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf3")))
            .exec(session -> {
                String nc = session.getString("newCsrf3");
                if (nc != null && !nc.isEmpty()) {
                    return session.set("csrf", nc);
                }
                return session;
            });

    // Catalog traversal (up to 3 pages), pick first in-stock product/variant
    ChainBuilder catalogTraverse =
            exec(http("catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.data.products[0].id").optional().saveAs("p0"))
                    .check(jsonPath("$.data.products[0].variants[0].id").optional().saveAs("v0"))
                    .check(jsonPath("$.data.products[0].variants[0].in_stock").optional().saveAs("s0"))
                    .check(jsonPath("$.next").optional().saveAs("nextUrl")))
            .exec(session -> {
                // choose first in-stock from page 0 if available
                String p = session.getString("p0");
                String v = session.getString("v0");
                Boolean s = session.get("s0") != null ? session.getBoolean("s0") : null;
                if (p != null && v != null && Boolean.TRUE.equals(s)) {
                    return session.set("productId", p).set("variantId", v).set("found", true);
                }
