            .doIf(session -> !session.getBoolean("found") && session.getString("nextUrl") != null).then(
                    exec(http("catalog-page-1")
                            .get("#{nextUrl}")
                            .check(status().is(200))
                            .check(jsonPath("$.data.products[0].id").optional().saveAs("p1"))
                            .check(jsonPath("$.data.products[0].variants[0].id").optional().saveAs("v1"))
                            .check(jsonPath("$.data.products[0].variants[0].in_stock").optional().saveAs("s1"))
                            .check(jsonPath("$.next").optional().saveAs("nextUrl2")))
                    .exec(session -> {
                        String p = session.getString("p1");
                        String v = session.getString("v1");
                        Boolean s = session.get("s1") != null ? session.getBoolean("s1") : null;
                        if (p != null && v != null && Boolean.TRUE.equals(s)) {
                            return session.set("productId", p).set("variantId", v).set("found", true);
                        }
                        return session.set("found", false);
                    })
            )
            .doIf(session -> !session.getBoolean("found") && session.getString("nextUrl2") != null).then(
                    exec(http("catalog-page-2")
                            .get("#{nextUrl2}")
                            .check(status().is(200))
                            .check(jsonPath("$.data.products[0].id").optional().saveAs("p2"))
                            .check(jsonPath("$.data.products[0].variants[0].id").optional().saveAs("v2"))
                            .check(jsonPath("$.data.products[0].variants[0].in_stock").optional().saveAs("s2")))
                    .exec(session -> {
                        String p = session.getString("p2");
                        String v = session.getString("v2");
                        Boolean s = session.get("s2") != null ? session.getBoolean("s2") : null;
                        if (p != null && v != null && Boolean.TRUE.equals(s)) {
                            return session.set("productId", p).set("variantId", v).set("found", true);
                        }
                        return session.set("found", false);
                    })
            );

    // Create cart with grant_id passed once
    ChainBuilder createCart =
            exec(http("cart-create")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\",\"grant_id\":\"#{grantId}\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.id").saveAs("cartId"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf4"))
                    .check(header("ETag").optional().saveAs("cartEtag")))
            .exec(session -> {
                String nc = session.getString("newCsrf4");
                if (nc != null && !nc.isEmpty()) {
                    return session.set("csrf", nc);
                }
                return session;
            });

    // PATCH quantity with If-Match, retry once on 412
    ChainBuilder patchQuantity =
            exec(http("cart-patch")
                    .patch("/v2/carts/#{cartId}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("If-Match", "#{cartEtag}")
                    .body(StringBody("{\"quantity\":1}"))
                    .check(status().in(200, 412))
                    .check(header("ETag").optional().saveAs("cartEtag2"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf5")))
            .exec(session -> {
                String nc = session.getString("newCsrf5");
                if (nc != null && !nc.isEmpty()) {
                    return session.set("csrf", nc);
                }
                return session;
            })
            .doIf(session -> session.getInt("patchStatus") == 412).then(
                    exec(http("cart-reread")
                            .get("/v2/carts/#{cartId}")
                            .check(status().is(200))
                            .check(header("ETag").saveAs("cartEtag3")))
                    .exec(http("cart-patch-retry")
                            .patch("/v2/carts/#{cartId}")
                            .header("X-CSRF-Token", "#{csrf}")
                            .header("If-Match", "#{cartEtag3}")
                            .body(StringBody("{\"quantity\":1}"))
                            .check(status().is(200))
                            .check(header("ETag").optional().saveAs("cartEtag4")))
            );

    // Reservation: POST -> poll status_url up to 5 times, >=50ms apart
    ChainBuilder reservation =
            exec(http("reservation-create")
                    .post("/v2/reservations")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                    .check(status().is(202))
                    .check(jsonPath("$.status_url").saveAs("statusUrl"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf6")))
            .exec(session -> {
                String nc = session.getString("newCsrf6");
                if (nc != null && !nc.isEmpty()) {
                    return session.set("csrf", nc);
                }
                return session;
            })
            .asLongAs(session -> session.getInt("pollCount") < 5 && !session.getBoolean("reservationReady"))
            .on(
                    exec(session -> session.set("pollCount", session.getInt("pollCount") + 1))
                            .pause(Duration.ofMillis(60))
                            .exec(http("reservation-poll")
                                    .get("#{statusUrl}")
                                    .check(status().is(200))
                                    .check(jsonPath("$.status").saveAs("resStatus"))
                                    .check(jsonPath("$.reservation_id").optional().saveAs("reservationId")))
                            .exec(session -> {
                                String st = session.getString("resStatus");
                                if ("ready".equals(st)) {
                                    return session.set("reservationReady", true);
                                }
                                return session;
                            })
            );

