                    .check(jsonPath("$.accepted").is("true"))
                    .check(jsonPath("$.id").saveAs("orderId"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf7")))
            .exec(session -> {
                String nc = session.getString("newCsrf7");
                if (nc != null && !nc.isEmpty()) {
                    return session.set("csrf", nc);
                }
                return session;
            });

    // Work endpoint with 429 retry (Retry-After 1s, max 4 retries)
    ChainBuilder workWithRetry =
            exec(http("work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().in(200, 429))
                    .check(jsonPath("$.ok").optional().saveAs("workOk")))
            .asLongAs(session -> session.getInt("workRetries") < 4
                    && session.getInt("workStatus") == 429)
