                    exec(session -> session.set("workRetries", session.getInt("workRetries") + 1))
                            .pause(Duration.ofSeconds(1))
                            .exec(http("work-retry")
                                    .post("/v2/work")
                                    .header("X-CSRF-Token", "#{csrf}")
                                    .body(StringBody("{}"))
                                    .check(status().in(200, 429))
                                    .check(jsonPath("$.ok").optional().saveAs("workOk")))
            );

    // ---------- scenario ----------

    ScenarioBuilder scn = scenario("ModelSimulation")
            .exec(session -> session
                    .set("pollCount", 0)
                    .set("reservationReady", false)
                    .set("workRetries", 0)
                    .set("workStatus", 0)
                    .set("patchStatus", 0)
                    .set("found", false))
            .exec(freshLogin)
            .exec(challengeFlow)
            .exec(catalogTraverse)
            .doIf(session -> session.getBoolean("found")).then(
                    exec(createCart)
                            .exec(session -> session.set("idemKey",
                                    "idem-" + session.getString("cartId") + "-" + ThreadLocalRandom.current().nextInt(1_000_000)))
                            .exec(patchQuantity)
                            .exec(reservation)
                            .doIf(session -> session.getBoolean("reservationReady")).then(
                                    exec(checkout)
                            )
            )
            .exec(workWithRetry);

    // ---------- injection ----------
    // Execution contract: users=2, iterations=2 per user.
    // Two profiles count equally; run both as separate populations.
    PopulationBuilder profileA = scn.injectOpen(
            atOnceUsers(2)
    );

    setUp(profileA)
            .protocols(httpProtocol)
            .assertions(
                    global().failedRequests().percent().lt(100.0)
            );

    // ---------- tiny JSON helper (no libs) ----------
    private static String extractJson(String body, String key) {
        if (body == null) return null;
        String needle = "\"" + key + "\"";
        int i = body.indexOf(needle);
        if (i < 0) return null;
        int colon = body.indexOf(':', i + needle.length());
        if (colon < 0) return null;
        int q1 = body.indexOf('"', colon + 1);
        if (q1 < 0) return null;
        int q2 = body.indexOf('"', q1 + 1);
        if (q2 < 0) return null;
        return body.substring(q1 + 1, q2);
    }
}
