function getCatalog(jarRef, csrf) {
  const res = http.get(`${BASE}/v2/catalog`, { jar: jarRef, redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  let products = [];
  try {
    const j = JSON.parse(res.body);
    if (j && j.data && Array.isArray(j.data.products)) products = j.data.products;
  } catch (e) {}
  // traverse pages up to 3
  let next = null;
  try { next = JSON.parse(res.body).next; } catch (e) {}
  let pages = 0;
  while (next && pages < 3) {
    const url = next.startsWith('http') ? next : `${BASE}${next}`;
    const pr = http.get(url, { jar: jarRef, redirects: 0 });
    if (pr.status !== 200) break;
    try {
      const j = JSON.parse(pr.body);
      if (j.data && Array.isArray(j.data.products)) products = products.concat(j.data.products);
      next = j.next;
    } catch (e) { break; }
    pages++;
  }
  return products;
}

