  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const { action, challenge } = extractChallenge(formRes.body);
  if (!action || !challenge) fail('challenge not extracted');
  const postRes = http.post(action.startsWith('http') ? action : `${BASE}${action}`, JSON.stringify({ challenge }), {
