    const j = JSON.parse(res.body);
    if (j && j.csrf) newCsrf = j.csrf;
  } catch (e) {}
  return { csrf: newCsrf, etag: res.headers['Etag'] || res.headers['ETag'] };
}

function reserve(jarRef, csrf, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  let status_url = null, newCsrf = csrf;
  try {
    const j = JSON.parse(res.body);
    if (j.status_url) status_url = j.status_url;
    if (j.csrf) newCsrf = j.csrf;
  } catch (e) {}
  if (!status_url) return { reservation_id: null, csrf: newCsrf };
  let reservation_id = null;
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      // sleep at least 50ms
      const start = Date.now();
      while (Date.now() - start < 60) {}
    }
    const url = status_url.startsWith('http') ? status_url : `${BASE}${status_url}`;
    const pr = http.get(url, { jar: jarRef, redirects: 0 });
    if (pr.status !== 200) continue;
    try {
      const j = JSON.parse(pr.body);
      if (j.csrf) newCsrf = j.csrf;
      if (j.status === 'ready' && j.reservation_id) { reservation_id = j.reservation_id; break; }
      if (j.status === 'failed') break;
    } catch (e) {}
  }
  return { reservation_id, csrf: newCsrf };
}

function placeOrder(jarRef, csrf, cartId, reservation_id, etag) {
  const payload = { cart_id: cartId };
  if (reservation_id) payload.reservation_id = reservation_id;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': `idem-${cartId}-${__VU}-${__ITER}`,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    jar: jarRef,
    redirects: 0,
    headers,
  });
  businessResponses.add(1);
  let ok = false;
  let newCsrf = csrf;
  if (res.status === 201) {
    try {
      const j = JSON.parse(res.body);
      if (j.accepted === true && j.id) ok = true;
      if (j.csrf) newCsrf = j.csrf;
    } catch (e) {}
  } else if (res.status === 200) {
    try {
      const j = JSON.parse(res.body);
      if (j.accepted === false) ok = false;
      if (j.csrf) newCsrf = j.csrf;
    } catch (e) {}
  } else if (res.status === 401) {
    // expiry handling
    try {
      const j = JSON.parse(res.body);
      if (j.error === 'expired') {
        const renew = http.post(`${BASE}/v2/session/renew`, '{}', {
          jar: jarRef, redirects: 0,
          headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        });
        if (renew.status === 200) {
          try {
            const rj = JSON.parse(renew.body);
            if (rj.csrf) newCsrf = rj.csrf;
          } catch (e) {}
        }
        const rec = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
          jar: jarRef, redirects: 0,
          headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': newCsrf },
        });
        if (rec.status === 200) {
          try {
            const rj = JSON.parse(rec.body);
            if (rj.csrf) newCsrf = rj.csrf;
          } catch (e) {}
        }
        const retryHeaders = Object.assign({}, headers, { 'X-CSRF-Token': newCsrf });
        const retry = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
          jar: jarRef, redirects: 0, headers: retryHeaders,
        });
        businessResponses.add(1);
        if (retry.status === 201) {
          try {
            const j2 = JSON.parse(retry.body);
            if (j2.accepted === true && j2.id) ok = true;
            if (j2.csrf) newCsrf = j2.csrf;
          } catch (e) {}
        }
      } else if (j.error === 'denied') {
        ok = false;
      }
    } catch (e) {}
  } else if (res.status >= 500) {
    unexpectedFailures.add(1);
  }
  check(res, { 'order accepted': () => ok });
  return { ok, csrf: newCsrf };
}

export default function () {
  const username = `bench-${((__VU - 1) % 16) + 1}`;
  const jarRef = jar();
  group('journey', () => {
    const { csrf: loginCsrf } = login(jarRef, username);
    let csrf = loginCsrf;

    const products = getCatalog(jarRef, csrf);
    const pick = pickVariant(products);
    if (!pick) fail('no in-stock variant');

    const ch = solveChallenge(jarRef, csrf);
    csrf = ch.csrf;
    if (!ch.grant_id) fail('no grant_id');

    const cart = createCart(jarRef, csrf, pick.product_id, pick.variant_id, ch.grant_id);
    csrf = cart.csrf;
    if (!cart.id) fail('no cart id');

    const patched = patchCart(jarRef, csrf, cart.id, cart.etag, 1);
    csrf = patched.csrf;

    const resv = reserve(jarRef, csrf, cart.id);
    csrf = resv.csrf;
    if (!resv.reservation_id) fail('no reservation_id');

    const order = placeOrder(jarRef, csrf, cart.id, resv.reservation_id, patched.etag);
    csrf = order.csrf;
    check(order, { 'order ok': (o) => o.ok === true });
  });
}
