def _extract_csrf(html):
    # input[name=csrf] mixed with decoys/attribute variants
    if not html:
        return None
    # Try common attribute orderings
    patterns = [
        r'<input[^>]*name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']',
        r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']',
    ]
    for p in patterns:
        m = re.search(p, html, re.IGNORECASE)
        if m:
            return m.group(1)
    return None


def _extract_challenge(html):
