                if self._handle_401(r, cart_id):
                    r.success()
                    return self._patch_with_etag(cart_id, qty, etag)
                r.failure("cart patch 401 unrecoverable")
                return False
            if r.status_code in (200, 204):
                self._update_csrf(r)
                r.success()
                return True
            r.failure("cart patch status %s" % r.status_code)
            return False

    def _reserve(self, cart_id):
        with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                              headers=self._headers(),
                              name="/v2/reservations",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    r.success()
                    with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                                          headers=self._headers(),
                                          name="/v2/reservations",
                                          catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code != 202:
                            r2.failure("reservation retry %s" % r2.status_code)
                            return None
                        self._update_csrf(r2)
                        r2.success()
                        try:
                            return r2.json().get("status_url")
                        except Exception:
                            return None
                r.failure("reservation 401 unrecoverable")
                return None
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None
            self._update_csrf(r)
            r.success()
            try:
                return r.json().get("status_url")
            except Exception:
                return None

    def _poll_reservation(self, status_url):
        if not status_url:
            return None
        url = _abs(status_url)
        for i in range(5):
            if i > 0:
                time.sleep(0.05)
            with self.client.get(url, name="/v2/reservations/status",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure("reservation status %s" % r.status_code)
                    return None
                try:
                    body = r.json()
                except Exception:
                    r.failure("reservation status not json")
                    return None
                status = body.get("status")
                if status == "ready":
                    rid = body.get("reservation_id")
                    if not rid:
                        r.failure("ready without reservation_id")
                        return None
                    r.success()
                    return rid
                if status in ("pending",):
                    r.success()
                    continue
                if status in ("failed",):
                    r.failure("reservation failed")
                    return None
                r.failure("unknown reservation status %s" % status)
                return None
        return None

    def _checkout(self, cart_id, reservation_id):
        headers = self._headers({"Idempotency-Key": "cart-%s" % cart_id})
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id

        def _attempt(hdrs):
            with self.client.post("/v2/orders", json=payload,
                                  headers=hdrs,
                                  name="/v2/orders",
                                  catch_response=True, allow_redirects=False) as r:
                return r

        r = _attempt(headers)
        if r.status_code == 401:
            if self._handle_401(r, cart_id):
                r.success()
                r = _attempt(self._headers({"Idempotency-Key": "cart-%s" % cart_id}))
            else:
                r.failure("order 401 unrecoverable")
                return False
        if r.status_code == 201:
            try:
                body = r.json()
            except Exception:
                r.failure("order not json")
                return False
            if body.get("accepted") is True:
                self._update_csrf(r)
                r.success()
                return True
            r.failure("order 201 not accepted")
            return False
        if r.status_code == 200:
            try:
                body = r.json()
            except Exception:
                r.failure("order 200 not json")
                return False
            if body.get("accepted") is False:
                r.failure("order business failure accepted=false")
                return False
            r.failure("order 200 unexpected")
            return False
        r.failure("order status %s" % r.status_code)
        return False

    def _do_work(self):
        for attempt in range(5):
            with self.client.post("/v2/work", json={},
                                  headers=self._headers(),
                                  name="/v2/work",
                                  catch_response=True, allow_redirects=False) as r:
                if r.status_code == 200:
                    try:
                        body = r.json()
                    except Exception:
                        r.failure("work not json")
                        return
                    if body.get("ok") is True:
                        r.success()
                        return
                    r.failure("work ok!=true")
                    return
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    r.success()
                    if attempt >= 4:
                        return
                    time.sleep(delay)
                    continue
                if r.status_code == 401:
                    if self._handle_401(r):
                        r.success()
                        continue
                    r.failure("work 401 unrecoverable")
                    return
                r.failure("work status %s" % r.status_code)
                return

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self._login():
            raise StopUser()

        products = self._get_catalog_products()
        product_id, variant_id = self._pick_variant(products)
        if not product_id or not variant_id:
            raise StopUser()

        grant_id = self._do_challenge()
        if not grant_id:
            raise StopUser()

        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            raise StopUser()

        if not self._patch_quantity(cart_id, 1):
            raise StopUser()

        status_url = self._reserve(cart_id)
        reservation_id = self._poll_reservation(status_url)
        if not reservation_id:
            raise StopUser()

        if not self._checkout(cart_id, reservation_id):
            raise StopUser()

        self._do_work()


class ShopShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        # 2 users, 2 iterations each; stop after enough time
        if run_time > 120:
            return None
        return (2, 2)
