# Complete Gatling Simulation Solution

```java
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    // Shared account: both users deliberately share "bench"
    private static final String SHARED_USER = "bench";
    private static final String SHARED_PASS = "bench";

    // Per-user delay staggering (from fixture: user1 delay=0, user2 delay=500ms)
    private static final long[] USER_DELAYS = {0L, 500L};
    private static final int[] USER_QUANTITIES = {2, 3};

    // Track login generation per virtual user to detect revocation
    private static final AtomicInteger loginGen = new AtomicInteger(0);

    private final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    // ---------- Reusable chains ----------

    private ChainBuilder loginForm() {
        return exec(
                http("GET /v2/login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(css("input[name=csrf]", "value").saveAs("csrf"))
                        .check(cookie("login_nonce").saveAs("login_nonce"))
        );
    }

    private ChainBuilder doLogin() {
        return exec(
                http("POST /v2/login")
                        .post("/v2/login")
                        .body(StringBody(session ->
                                "{\"username\":\"" + SHARED_USER + "\",\"password\":\"" + SHARED_PASS +
                                        "\",\"csrf\":\"" + session.getString("csrf") + "\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginBody"))
        ).exec(session -> {
            // If 302, follow Location exactly once
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("followLoginLocation", loc);
            }
            return session;
        }).doIf(session -> session.contains("followLoginLocation")).then(
                exec(
                        http("GET login Location")
                                .get(session -> session.getString("followLoginLocation"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("loginBody"))
                )
        ).exec(session -> {
            // Parse csrf from login body
            String body = session.getString("loginBody");
            String csrf = extractJsonString(body, "csrf");
            if (csrf != null) {
                return session.set("csrf", csrf);
            }
            return session;
        });
    }

    private ChainBuilder renewSession() {
        return exec(
                http("POST /v2/session/renew")
                        .post("/v2/session/renew")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 401))
                        .check(bodyString().optional().saveAs("renewBody"))
        ).exec(session -> {
            String body = session.getString("renewBody");
            String csrf = extractJsonString(body, "csrf");
            if (csrf != null) {
                return session.set("csrf", csrf);
            }
            return session;
        });
    }

    private ChainBuilder freshLogin() {
        return exec(loginForm()).exec(doLogin());
    }

    private ChainBuilder recoverCart() {
        return doIf(session -> session.contains("cartId")).then(
                exec(
                        http("POST /v2/carts/{id}/recover")
                                .post("/v2/carts/#{cartId}/recover")
                                .header("X-CSRF-Token", session -> session.getString("csrf"))
                                .body(StringBody("{}"))
                                .check(status().in(200, 401))
                                .check(bodyString().optional().saveAs("recoverBody"))
                ).exec(session -> {
                    String body = session.getString("recoverBody");
                    String csrf = extractJsonString(body, "csrf");
                    if (csrf != null) {
                        return session.set("csrf", csrf);
                    }
                    return session;
                })
        );
    }

    private ChainBuilder browseCatalog() {
        return exec(
                http("GET /v2/catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[0].id").saveAs("productId"))
                        .check(jsonPath("$.data.products[0].variants[0].id").saveAs("variantId"))
                        .check(jsonPath("$.data.products[0].variants[0].in_stock").saveAs("inStock"))
        );
    }

    private ChainBuilder createCart() {
        return exec(
                http("POST /v2/carts")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session ->
                                "{\"product_id\":\"" + session.getString("productId") +
                                        "\",\"variant_id\":\"" + session.getString("variantId") + "\"}"))
                        .check(status().in(201, 401))
                        .check(header("ETag").optional().saveAs("cartEtag"))
                        .check(bodyString().optional().saveAs("cartBody"))
        ).exec(session -> {
            String body = session.getString("cartBody");
            String cartId = extractJsonString(body, "id");
            String csrf = extractJsonString(body, "csrf");
            if (cartId != null) {
                session = session.set("cartId", cartId);
            }
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            return session;
        });
    }

    private ChainBuilder patchCart(int quantity) {
        return exec(
                http("PATCH /v2/carts/{id}")
                        .patch("/v2/carts/#{cartId}")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> session.getString("cartEtag"))
                        .body(StringBody("{\"quantity\":" + quantity + "}"))
                        .check(status().in(200, 412, 401))
                        .check(header("ETag").optional().saveAs("cartEtag"))
                        .check(bodyString().optional().saveAs("patchBody"))
        ).exec(session -> {
            String body = session.getString("patchBody");
            String csrf = extractJsonString(body, "csrf");
            if (csrf != null) {
                return session.set("csrf", csrf);
            }
            return session;
        });
    }

    private ChainBuilder reReadCart() {
        return exec(
                http("GET /v2/carts/{id}")
                        .get("/v2/carts/#{cartId}")
                        .check(status().in(200, 401))
                        .check(header("ETag").optional().saveAs("cartEtag"))
        );
    }

    private ChainBuilder createOrder() {
        return exec(
                http("POST /v2/orders")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> "order-" + session.getString("cartId"))
                        .header("If-Match", session -> session.getString("cartEtag"))
                        .body(StringBody(session ->
                                "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                        .check(status().in(201, 200, 401))
                        .check(bodyString().optional().saveAs("orderBody"))
        ).exec(session -> {
            String body = session.getString("orderBody");
            String csrf = extractJsonString(body, "csrf");
            if (csrf != null) {
                return session.set("csrf", csrf);
            }
            return session;
        });
    }

    // ---------- Journey with revocation detection & recovery ----------

    private ChainBuilder journey(int userIndex) {
        long delay = USER_DELAYS[userIndex];
        int quantity = USER_QUANTITIES[userIndex];

        return exec(session -> {
            // Stagger subsequent work per virtual user
            if (delay > 0) {
                try {
                    Thread.sleep(delay);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            return session;
        })
        // Initial login
        .exec(loginForm())
        .exec(doLogin())
        // Synchronize: both users have logged in; now detect revocation
        .exec(session -> {
            // Small sync barrier: wait for the other user's login to potentially invalidate
            try {
                Thread.sleep(200);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            return session;
        })
        // Detect revocation: try a work call; if 401 session, recover
        .exec(
                http("POST /v2/work (detect)")
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 401, 429))
                        .check(bodyString().optional().saveAs("workBody"))
        )
        .exec(session -> {
            String body = session.getString("workBody");
            if (body != null && body.contains("\"session\"")) {
                return session.set("revoked", true);
            }
            return session.set("revoked", false);
        })
        // If revoked: renew may fail, get fresh login, recover cart
        .doIf(session -> session.getBoolean("revoked")).then(
                exec(renewSession())
                .exec(session -> {
                    String body = session.getString("renewBody");
                    if (body != null && body.contains("\"expired\"")) {
                        return session.set("needFreshLogin", true);
                    }
                    return session.set("needFreshLogin", false);
                })
                .doIf(session -> session.getBoolean("needFreshLogin")).then(
                        exec(freshLogin())
                )
                .exec(recoverCart())
        )
        // Browse catalog
        .exec(browseCatalog())
        // Create cart
        .exec(createCart())
        // Handle 401 on cart creation
        .doIf(session -> session.getString("cartBody") != null &&
                session.getString("cartBody").contains("\"expired\"")).then(
                exec(renewSession())
                .exec(createCart())
        )
        // Patch cart quantity
        .exec(patchCart(quantity))
        // Handle 412: re-read and retry once
        .doIf(session -> session.getString("patchBody") != null &&
                session.getString("patchBody").contains("412")).then(
                exec(reReadCart())
                .exec(patchCart(quantity))
        )
        // Handle 401 on patch
        .doIf(session -> session.getString("patchBody") != null &&
                session.getString("patchBody").contains("\"expired\"")).then(
                exec(renewSession())
                .exec(patchCart(quantity))
        )
        // Create order
        .exec(createOrder())
        // Handle 401 on order
        .doIf(session -> session.getString("orderBody") != null &&
                session.getString("orderBody").contains("\"expired\"")).then(
                exec(renewSession())
                .exec(recoverCart())
                .exec(createOrder())
        )
        // Assert order accepted
        .exec(session -> {
            String body = session.getString("orderBody");
            if (body == null || !body.contains("\"accepted\":true")) {
                throw new RuntimeException("Order not accepted: " + body);
            }
            return session;
        });
    }

    // ---------- Simulation setup ----------

    {
        ScenarioBuilder scenario = scenario("Concurrent Account Sessions")
                .exec(journey(0))
                .exec(journey(1));

        setUp(
                scenario.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol)
                .assertions(
                        global().failedRequests().count().is(0L)
                );
    }

    // ---------- Helpers ----------

    private static String extractJsonString(String json, String key) {
        if (json == null) return null;
        String pattern = "\"" + key + "\":\"";
        int idx = json.indexOf(pattern);
        if (idx < 0) return null;
        int start = idx + pattern.length();
        int end = json.indexOf('"', start);
        if (end < 0) return null;
        return json.substring(start, end);
    }
}
