## Key Design Decisions

**Ownership mode**: Both virtual users share the `bench` account. The later login invalidates the earlier session — this is the core scenario being tested.

**Revocation detection**: After initial logins, a synchronization barrier (200ms sleep) allows the second login to invalidate the first. A `/v2/work` probe detects `401 error=session` (revoked) vs `401 error=expired` (expiry).

**Recovery paths**:
- **Revoked** (`error=session`): `renew` may fail → fresh form/login → cart recovery
- **Expired** (`error=expired`): `renew` with current CSRF → capture fresh csrf → cart recovery → retry interrupted op once

**Token ownership**: CSRF tokens are captured from login form, login response, renew response, cart creation, and every mutation response (retaining previous if absent). `X-CSRF-Token` is sent on all authenticated non-GET calls.

**Safety bounds**:
- 412 → re-read + retry same payload once
- 401 → renew + recover + retry once (never restart checkout)
- Idempotency-Key stable per cart (`order-{cartId}`)
- No login ping-pong: recovery is bounded per operation

**Per-user staggering**: `USER_DELAYS = {0, 500}` matches fixture delays, applied before subsequent work.

**Assertions**: Order must contain `"accepted":true`; HTTP 200 with `accepted:false` fails. Failed requests count must be 0.

```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';
import exec from 'k6/execution';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// Load accounts fixture (read-only alias)
const accounts = new SharedArray('accounts', function () {
  const raw = open('/fixtures/c11-accounts.json');
  return JSON.parse(raw);
});

export const options = {
  scenarios: {
    ownership: {
      executor: 'per-vu-iterations',
      vus: accounts.length,
      iterations: 1,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

// Per-VU state
let state = null;

function initState() {
  const idx = exec.vu.idInTest - 1;
  const acct = accounts[idx % accounts.length];
  return {
    username: acct.username,
    password: acct.password,
    quantity: acct.quantity,
    delay: acct.delay,
    cookies: {},
    csrf: null,
    session: null,
    cartId: null,
    cartEtag: null,
    grantId: null,
    reservationId: null,
    orderId: null,
    loginCount: 0,
    renewCount: 0,
    recovered: false,
    revoked: false,
    committed: false,
  };
}

function cookieHeader(cookies) {
  return Object.keys(cookies).map(k => `${k}=${cookies[k]}`).join('; ');
}

function mergeCookies(res) {
  // k6 response cookies
  if (res.cookies) {
    for (const name of Object.keys(res.cookies)) {
      const arr = res.cookies[name];
      if (arr && arr.length) {
        state.cookies[name] = arr[arr.length - 1].value;
      }
    }
  }
}

function req(method, path, body, extraHeaders) {
  const headers = Object.assign({}, extraHeaders || {});
  const ch = cookieHeader(state.cookies);
  if (ch) headers['Cookie'] = ch;
  let payload = null;
  if (body !== undefined && body !== null) {
    if (typeof body === 'string') {
      payload = body;
    } else {
      payload = JSON.stringify(body);
      if (!headers['Content-Type']) headers['Content-Type'] = 'application/json';
    }
  }
  const res = http.request(method, BASE + path, payload, {
    headers,
    redirects: 0,
    tags: { name: path },
  });
  mergeCookies(res);
  return res;
}

function extractCsrfFromForm(html) {
  // input[name=csrf] mixed with decoys/attribute variants
  // Try several patterns
  const patterns = [
    /<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["']/i,
    /<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["']/i,
    /name=["']csrf["'][^>]*value=["']([^"']+)["']/i,
    /value=["']([^"']+)["'][^>]*name=["']csrf["']/i,
  ];
  for (const p of patterns) {
    const m = html.match(p);
    if (m) return m[1];
  }
  return null;
}

function extractChallengeForm(html) {
  // form action /v2/challenges/{id} and input[name=challenge]
  const actionMatch = html.match(/action=["']([^"']*\/v2\/challenges\/[^"']+)["']/i);
  const challengeMatch = html.match(/<input[^>]*name=["']challenge["'][^>]*value=["']([^"']*)["']/i) ||
    html.match(/<input[^>]*value=["']([^"']*)["'][^>]*name=["']challenge["']/i);
  if (actionMatch && challengeMatch) {
    return { action: actionMatch[1], challenge: challengeMatch[1] };
  }
  return null;
}

function doLogin() {
  state.loginCount++;
  // GET login form
  const formRes = req('GET', '/v2/login-form');
  check(formRes, { 'login-form 200': r => r.status === 200 });
  const csrf = extractCsrfFromForm(formRes.body || '');
  check(csrf, { 'login csrf found': v => !!v });
  if (!csrf) return false;

  // POST login
  const loginRes = req('POST', '/v2/login', {
    username: state.username,
    password: state.password,
    csrf: csrf,
  });
  // May return 302 Location
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const followRes = req('GET', loc.startsWith('http') ? loc.replace(BASE, '') : loc);
      check(followRes, { 'login follow ok': r => r.status === 200 || r.status === 302 });
    }
  }
  check(loginRes, { 'login status ok': r => r.status === 200 || r.status === 302 });
  let body = null;
  try { body = loginRes.json(); } catch (e) { body = null; }
  if (body && body.csrf) {
    state.csrf = body.csrf;
  }
  if (body && body.user) {
    state.session = body.user;
  }
  // session cookie should be set
  check(state.cookies, { 'session cookie set': c => !!c['session'] || Object.keys(c).length > 0 });
  return true;
}

function renewSession() {
  state.renewCount++;
  const res = req('POST', '/v2/session/renew', {}, { 'X-CSRF-Token': state.csrf || '' });
  if (res.status === 200) {
    let body = null;
    try { body = res.json(); } catch (e) { body = null; }
    if (body && body.csrf) state.csrf = body.csrf;
    return true;
  }
  return false;
}

function recoverCart() {
  if (!state.cartId) return true;
  const res = req('POST', `/v2/carts/${state.cartId}/recover`, {}, { 'X-CSRF-Token': state.csrf || '' });
  if (res.status === 200) {
    let body = null;
    try { body = res.json(); } catch (e) { body = null; }
    if (body && body.csrf) state.csrf = body.csrf;
    return true;
  }
  return false;
}

function handle401(res, retryFn) {
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  const err = body && body.error;
  if (err === 'expired') {
    // renew
    const ok = renewSession();
    if (ok) {
      if (state.cartId) recoverCart();
      return retryFn();
    }
