    for (let i = 0; i < 4; i++) {
      sleep(1);
      const r2 = req('POST', '/v2/work', {}, { 'X-CSRF-Token': state.csrf || '' });
      if (r2.status === 200) return true;
      if (r2.status !== 429) return false;
    }
    return false;
  }
  check(res, { 'work 200': r => r.status === 200 });
  return res.status === 200;
}

export default function () {
