  let workRes = req('POST', '/v2/work', {}, { 'X-CSRF-Token': state.csrf || '' });
  if (workRes.status === 401) {
    let body = null;
    try { body = workRes.json(); } catch (e) { body = null; }
    if (body && body.error === 'session') {
      state.revoked = true;
      // Recover deliberately: fresh login
      const ok = doLogin();
      check(ok, { 'recovery login': v => v === true });
    } else if (body && body.error === 'expired') {
