  check(cartOk, { 'cart created': v => v === true });
  if (!cartOk) return;

  const patchOk = patchCartQuantity();
  check(patchOk, { 'cart patched': v => v === true });
  if (!patchOk) return;

  const resOk = createReservation();
  check(resOk, { 'reservation ready': v => v === true });
  if (!resOk) return;

  const orderOk = placeOrder();
  check(orderOk, { 'order committed': v => v === true });
  if (orderOk) {
    state.committed = true;
  }

  // Final work call to confirm session still valid
  doWork();

