        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = self._auth_headers({"Idempotency-Key": self._idem_key or f"idem-{self._cart_id}"})
        if self._etag:
            headers["If-Match"] = self._etag
        r = self._post_json("/v2/orders", payload, headers=headers,
                            name="POST /v2/orders")
        if r.status_code == 401:
            if self._handle_401(r, lambda: self._order(reservation_id)):
                return True
            return False
        if r.status_code != 201:
            r.failure(f"order status {r.status_code}")
            return False
        try:
            data = r.json()
        except Exception:
            r.failure("order non-json")
            return False
        if not data.get("accepted"):
            r.failure("order not accepted")
            return False
        if data.get("csrf"):
            self._csrf = data["csrf"]
        self._committed = True
        return True

    # ---------- 401 handling ----------

    def _handle_401(self, resp, retry_fn):
        """Returns True if retry_fn should be called (caller retries)."""
        try:
            data = resp.json()
        except Exception:
            resp.failure("401 non-json")
            return False
        err = data.get("error")
        if err == "denied":
            resp.failure("401 denied")
            return False
        if err == "expired":
            # renew
            self._renew_count += 1
            rr = self._post_json("/v2/session/renew", {},
                                 headers=self._auth_headers(),
                                 name="POST /v2/session/renew")
            if rr.status_code == 200:
                self._update_csrf_from(rr)
                if self._cart_id:
                    self._recover_count += 1
                    self._post_json(f"/v2/carts/{self._cart_id}/recover", {},
                                    headers=self._auth_headers(),
                                    name="POST /v2/carts/{id}/recover")
                return True
            # renew failed -> fall through to revoked handling
            err = "session"
        if err == "session":
            # revoked: fresh login + recover cart
            self._revoked_detected = True
            if not self._login(mark_failure=False):
                resp.failure("re-login after revoke failed")
                return False
            if self._cart_id:
                self._recover_count += 1
                self._post_json(f"/v2/carts/{self._cart_id}/recover", {},
                                headers=self._auth_headers(),
                                name="POST /v2/carts/{id}/recover")
            self._recovered_after_revoke = True
            return True
        resp.failure(f"401 {err}")
        return False

    # ---------- work ----------

    def _do_work(self):
        for attempt in range(5):
            r = self._post_json("/v2/work", {}, headers=self._auth_headers(),
                                name="POST /v2/work")
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("work non-json")
                    return False
                if not data.get("ok"):
                    r.failure("work not ok")
                    return False
                return True
            if r.status_code == 429:
                ra = r.headers.get("Retry-After", "1")
                try:
                    wait = float(ra)
                except Exception:
                    wait = 1.0
                time.sleep(wait)
                continue
            if r.status_code == 401:
                if self._handle_401(r, self._do_work):
                    return True
                return False
            r.failure(f"work status {r.status_code}")
            return False
        return False

    # ---------- journey ----------

    @task
    def journey(self):
        if self._iterations_done >= 1:
            raise StopUser()
        self._account = self._pick_account()
        self._sleep_delay()

        # Initial login
        if not self._login():
            raise StopUser()
        self._initial_login_done = True

        # Synchronize after initial logins: brief pause so both users have logged in.
        if not self._sync_done:
            time.sleep(0.3)
            self._sync_done = True

        # Detect revocation: try a work call; if revoked, recover deliberately.
        self._do_work()

        # Fresh cart journey
        products = self._fetch_catalog()
        if not products:
            raise StopUser()
        product_id, variant_id = self._pick_product(products)

        if not self._do_challenge():
            raise StopUser()
        if not self._create_cart(product_id, variant_id):
            raise StopUser()
        if not self._read_cart():
            raise StopUser()
        qty = max(1, min(20, self._account.get("quantity", 1)))
        if not self._patch_cart(qty):
            raise StopUser()

        reservation_id = self._reserve()
        if not self._order(reservation_id):
            raise StopUser()

        self._iterations_done += 1
        raise StopUser()


class ShopUserA(ShopUser):
    pass


class ShopUserB(ShopUser):
    pass


class SingleRunShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time > 60:
            return None
        return (2, 2)
