import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableFollowRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    // ---- helpers ----

    private static ChainBuilder extractCsrf(String name) {
        return jsonPath("$.csrf").saveAs(name);
    }

    private static ChainBuilder extractCsrfKeep(String name) {
        // retain previous token if absent
        return jsonPath("$.csrf").optional().saveAs(name);
    }

    private static ChainBuilder extractEtag(String name) {
        return headerRegex("(?im)^ETag:\\s*([^\\r\\n]+)").saveAs(name);
    }

    private static ChainBuilder extractEtagKeep(String name) {
        return headerRegex("(?im)^ETag:\\s*([^\\r\\n]+)").optional().saveAs(name);
    }

    // ---- login flow ----

    private static ChainBuilder loginForm() {
        return exec(
                http("GET /v2/login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(regex("<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>")
                                .saveAs("form"))
        );
    }

    private static ChainBuilder loginPost() {
        return exec(session -> {
            String user = "bench-" + session.userId();
            return session.set("username", user);
        })
                .exec(
                        http("POST /v2/login")
                                .post("/v2/login")
                                .body(StringBody(session ->
                                        "{\"username\":\"" + session.getString("username") +
                                                "\",\"password\":\"bench\",\"csrf\":\"" +
                                                session.getString("form") + "\"}"))
                                .check(status().in(200, 302))
                                .check(extractCsrfKeep("csrf"))
                                .check(headerRegex("(?im)^Location:\\s*([^\\r\\n]+)").optional().saveAs("location"))
                )
                .exec(session -> {
                    String loc = session.getString("location");
                    if (loc != null && !loc.isEmpty()) {
                        return session.set("redirect", true);
                    }
                    return session.set("redirect", false);
                })
                .doIf(session -> Boolean.TRUE.equals(session.get("redirect"))).then(
                        exec(
                                http("GET login redirect")
                                        .get(session -> session.getString("location"))
                                        .check(status().is(200))
                                        .check(extractCsrfKeep("csrf"))
                                        .check(jsonPath("$.grant_id").optional().saveAs("grant"))
                        )
                );
    }

    // ---- catalog ----

    private static ChainBuilder catalog() {
        return exec(
                http("GET /v2/catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id").find().saveAs("product"))
                        .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").find().saveAs("variant"))
        );
    }

    // ---- cart ----

    private static ChainBuilder createCart() {
        return exec(
                http("POST /v2/carts")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> {
                            String grant = session.getString("grant");
                            if (grant != null && !grant.isEmpty() && !"MISSING".equals(grant)) {
                                return "{\"product_id\":\"" + session.getString("product") +
                                        "\",\"variant_id\":\"" + session.getString("variant") +
                                        "\",\"grant_id\":\"" + grant + "\"}";
                            }
                            return "{\"product_id\":\"" + session.getString("product") +
                                    "\",\"variant_id\":\"" + session.getString("variant") + "\"}";
                        }))
                        .check(status().is(201))
                        .check(extractCsrfKeep("csrf"))
                        .check(jsonPath("$.id").saveAs("cart"))
                        .check(extractEtagKeep("etag"))
        );
    }

    // ---- order ----

    private static ChainBuilder placeOrder() {
        return exec(
                http("POST /v2/orders")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> session.getString("cart"))
                        .header("If-Match", session -> {
                            String e = session.getString("etag");
                            return e == null ? "" : e;
                        })
                        .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                        .check(status().is(201))
                        .check(jsonPath("$.accepted").is("true"))
                        .check(extractCsrfKeep("csrf"))
        );
    }

    // ---- scenario ----

    private ScenarioBuilder scn = scenario("ModelSimulation")
            .exec(session -> session.set("csrf", "MISSING").set("etag", "MISSING").set("grant", "MISSING"))
            .exec(loginForm())
            .exec(loginPost())
            .exec(catalog())
            .exec(createCart())
            .exec(placeOrder());

    {
        setUp(
                scn.injectOpen(
                        rampUsers(2).during(Duration.ofSeconds(1))
                ).protocols(httpProtocol)
        ).maxDuration(Duration.ofSeconds(120));
    }
}
