```javascript
import http from 'k6/http';
import { check } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {},
};

function parseCsrfFromForm(body) {
  if (!body) return null;
  const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const m = re.exec(body);
  return m ? m[1] : null;
}

function getHeader(res, name) {
  const h = res.headers || {};
  const lower = name.toLowerCase();
  for (const k of Object.keys(h)) {
    if (k.toLowerCase() === lower) return h[k];
  }
  return null;
}

function safeJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function isExpiredOrSession(res) {
  const j = safeJson(res);
  if (j && (j.error === 'expired' || j.error === 'session')) return j.error;
  return null;
}

function renewSession(state) {
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    tags: { name: 'session-renew' },
  });
  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  return res;
}

function recoverCart(state) {
  if (!state.cart) return null;
  const res = http.post(`${BASE}/v2/carts/${state.cart}/recover`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    tags: { name: 'cart-recover' },
  });
  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  return res;
}

function freshLogin(state, username) {
  // GET login form
  const formRes = http.get(`${BASE}/v2/login-form`, {
    tags: { name: 'login-form' },
  });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const formCsrf = parseCsrfFromForm(formRes.body);
  check(formCsrf, { 'login-form csrf present': (v) => !!v });

  // POST login
  const loginBody = JSON.stringify({
    username: username,
    password: 'bench',
    csrf: formCsrf || '',
  });
  const loginRes = http.post(`${BASE}/v2/login`, loginBody, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });

  let loginJson = safeJson(loginRes);
  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loc, { 'login redirect location': (v) => !!v });
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
        redirects: 0,
        tags: { name: 'login-follow' },
      });
      loginJson = safeJson(followRes);
      check(followRes, { 'login-follow 200': (r) => r.status === 200 });
    }
  } else {
    check(loginRes, { 'login 200': (r) => r.status === 200 });
  }

  check(loginJson, { 'login csrf present': (j) => !!(j && j.csrf) });
  if (loginJson && loginJson.csrf) state.csrf = loginJson.csrf;
  return loginJson;
}

function fetchCatalog(state) {
  const res = http.get(`${BASE}/v2/catalog`, {
    headers: { 'X-CSRF-Token': state.csrf || '' },
    tags: { name: 'catalog' },
  });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  if (!j || !j.data || !Array.isArray(j.data.products)) return null;
  for (const p of j.data.products) {
    if (!p || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (v && v.in_stock === true) {
        return { product: p.id, variant: v.id };
      }
    }
  }
  return null;
}

function fetchChallenge(state) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, {
    headers: { 'X-CSRF-Token': state.csrf || '' },
    tags: { name: 'challenge-form' },
  });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const body = formRes.body || '';
  const actionMatch = /<form[^>]*\baction=["']([^"']+)["']/i.exec(body);
  const challengeMatch = /<input(?=[^>]*\bname=["']challenge["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i.exec(body);
  const action = actionMatch ? actionMatch[1] : null;
  const challenge = challengeMatch ? challengeMatch[1] : null;
  check(action, { 'challenge action present': (v) => !!v });
  check(challenge, { 'challenge value present': (v) => !!v });
  if (!action || !challenge) return null;

  const actionUrl = action.startsWith('http') ? action : `${BASE}${action}`;
  const postRes = http.post(actionUrl, JSON.stringify({ challenge: challenge }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    redirects: 0,
    tags: { name: 'challenge-submit' },
  });
  check(postRes, { 'challenge-submit 302': (r) => r.status === 302 });
  const loc = getHeader(postRes, 'Location');
  check(loc, { 'challenge location': (v) => !!v });
  if (!loc) return null;
  const locUrl = loc.startsWith('http') ? loc : `${BASE}${loc}`;
  const grantRes = http.get(locUrl, {
    redirects: 0,
    tags: { name: 'challenge-grant' },
  });
  check(grantRes, { 'challenge-grant 200': (r) => r.status === 200 });
  const gj = safeJson(grantRes);
  check(gj, { 'grant_id present': (j) => !!(j && j.grant_id) });
  if (gj && gj.csrf) state.csrf = gj.csrf;
  return gj ? gj.grant_id : null;
}

function createCart(state, product, variant, grant) {
  const payload = { product_id: product, variant_id: variant };
  if (grant) payload.grant_id = grant;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    tags: { name: 'cart-create' },
  });
  check(res, { 'cart-create 201': (r) => r.status === 201 });
  const j = safeJson(res);
  check(j, { 'cart id present': (v) => !!(v && v.id) });
  if (j && j.csrf) state.csrf = j.csrf;
  const etag = getHeader(res, 'ETag');
  if (etag) state.etag = etag;
  if (j && j.id) state.cart = j.id;
  return j;
}

function patchQuantity(state, qty) {
  if (!state.cart) return null;
  const doPatch = () => http.patch(`${BASE}/v2/carts/${state.cart}`, JSON.stringify({ quantity: qty }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
      'If-Match': state.etag || '',
    },
    tags: { name: 'cart-patch' },
  });
  let res = doPatch();
  if (res.status === 412) {
    const readRes = http.get(`${BASE}/v2/carts/${state.cart}`, {
      headers: { 'X-CSRF-Token': state.csrf || '' },
      tags: { name: 'cart-read' },
    });
    const etag = getHeader(readRes, 'ETag');
    if (etag) state.etag = etag;
    res = doPatch();
  }
  check(res, { 'cart-patch ok': (r) => r.status === 200 || r.status === 204 });
  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  const etag = getHeader(res, 'ETag');
  if (etag) state.etag = etag;
  return res;
}

function createReservation(state) {
  if (!state.cart) return null;
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: state.cart }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    tags: { name: 'reservation-create' },
  });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  if (!j || !j.status_url) return null;
  const statusUrl = j.status_url.startsWith('http') ? j.status_url : `${BASE}${j.status_url}`;
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      // sleep at least 50ms between polls
      const start = Date.now();
      while (Date.now() - start < 60) { /* busy wait */ }
    }
    const pollRes = http.get(statusUrl, {
      headers: { 'X-CSRF-Token': state.csrf || '' },
      tags: { name: 'reservation-poll' },
    });
    const pj = safeJson(pollRes);
    if (pj && pj.csrf) state.csrf = pj.csrf;
    if (pj && pj.status === 'ready' && pj.reservation_id) {
      return pj.reservation_id;
    }
    if (pj && (pj.status === 'failed')) {
      return null;
    }
  }
  return null;
}

function placeOrder(state, reservationId) {
  if (!state.cart) return null;
  const payload = { cart_id: state.cart };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf || '',
    'Idempotency-Key': state.cart,
  };
  if (state.etag) headers['If-Match'] = state.etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    headers: headers,
    tags: { name: 'order-create' },
  });
  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  check(res, { 'order 201': (r) => r.status === 201 });
  check(j, { 'order accepted true': (v) => !!(v && v.accepted === true) });
  return j;
}

export default function () {
  const vu = __VU;
  const username = `bench-${vu}`;
  const state = { csrf: null, cart: null, etag: null };

  // Fresh login
  freshLogin(state, username);

  // Catalog
  const pick = fetchCatalog(state);
  check(pick, { 'catalog pick found': (v) => !!v });
  if (!pick) return;

  // Challenge for grant
  const grant = fetchChallenge(state);

  // Create cart
  createCart(state, pick.product, pick.variant, grant);
  if (!state.cart) return;

  // Patch quantity
  patchQuantity(state, 2);

  // Reservation
  const reservationId = createReservation(state);

  // Order
  placeOrder(state, reservationId);
}
