import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL =
            System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableFollowRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .shareConnections();

    // ---- helpers ---------------------------------------------------------

    private static String csrfFromHtml(String body) {
        if (body == null) return null;
        // find input with name=csrf and capture its value (attribute order tolerant)
        java.util.regex.Pattern p = java.util.regex.Pattern.compile(
                "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>",
                java.util.regex.Pattern.CASE_INSENSITIVE);
        java.util.regex.Matcher m = p.matcher(body);
        return m.find() ? m.group(1) : null;
    }

    // ---- scenario --------------------------------------------------------

    private static final ScenarioBuilder SCENARIO = scenario("ModelSimulation")
            .exec(session -> session
                    .set("csrf", "")
                    .set("cart", "")
                    .set("etag", "")
                    .set("grant", "")
                    .set("product", "")
                    .set("variant", "")
                    .set("quantity", 2)
                    .set("hasCart", false)
                    .set("idemKey", "")
                    .set("reservationId", "")
                    .set("statusUrl", "")
                    .set("ready", false)
                    .set("pending", true))

            // 1. login form
            .exec(http("GET /v2/login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(bodyString().transform(ModelSimulation::csrfFromHtml)
                            .notNull()
                            .saveAs("formCsrf")))

            // 2. login (may 302 with Location)
            .exec(http("POST /v2/login")
                    .post("/v2/login")
                    .body(StringBody(session ->
                            "{\"username\":\"bench-" + session.userId() +
                                    "\",\"password\":\"bench\",\"csrf\":\"" +
                                    session.getString("formCsrf") + "\"}"))
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("loginLocation"))
                    .check(bodyString().optional().saveAs("loginBody")))

            // 3. follow dynamic Location exactly once if present
            .doIf(session -> session.contains("loginLocation") &&
                    session.getString("loginLocation") != null &&
                    !session.getString("loginLocation").isEmpty())
            .then(
                    exec(http("GET login redirect")
                            .get(session -> session.getString("loginLocation"))
                            .check(status().is(200))
                            .check(bodyString().saveAs("loginBody")))
            )

            // 4. extract csrf from login body
            .exec(session -> {
                String body = session.getString("loginBody");
                String csrf = null;
                if (body != null) {
                    java.util.regex.Matcher m = java.util.regex.Pattern
                            .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"")
                            .matcher(body);
                    if (m.find()) csrf = m.group(1);
                }
                return csrf != null ? session.set("csrf", csrf) : session;
            })

            // 5. catalog
            .exec(http("GET /v2/catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.data.products[*]").findAll().saveAs("productsRaw"))
                    .check(bodyString().saveAs("catalogBody")))

            // 6. pick first in-stock product/variant
            .exec(session -> {
                String body = session.getString("catalogBody");
                String product = null, variant = null;
                if (body != null) {
                    java.util.regex.Matcher pm = java.util.regex.Pattern
                            .compile("\"id\"\\s*:\\s*\"([^\"]+)\"\\s*,\\s*\"variants\"\\s*:\\s*\\[\\s*\\{[^}]*\"id\"\\s*:\\s*\"([^\"]+)\"[^}]*\"in_stock\"\\s*:\\s*true")
                            .matcher(body);
                    if (pm.find()) {
                        product = pm.group(1);
                        variant = pm.group(2);
                    }
                }
                return session.set("product", product).set("variant", variant);
            })

            // 7. challenge form (require_challenge profile)
            .exec(http("GET /v2/challenge-form")
                    .get("/v2/challenge-form")
                    .check(status().is(200))
                    .check(bodyString().saveAs("challengeBody")))

            .exec(session -> {
                String body = session.getString("challengeBody");
                String action = null, challenge = null;
                if (body != null) {
                    java.util.regex.Matcher am = java.util.regex.Pattern
                            .compile("action=[\"']([^\"']+)[\"']")
                            .matcher(body);
                    if (am.find()) action = am.group(1);
                    java.util.regex.Matcher cm = java.util.regex.Pattern
                            .compile("<input(?=[^>]*\\bname=[\"']challenge[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>")
                            .matcher(body);
                    if (cm.find()) challenge = cm.group(1);
                }
                return session.set("challengeAction", action).set("challenge", challenge);
            })

            // 8. POST challenge -> 302 Location
            .exec(http("POST challenge")
                    .post(session -> session.getString("challengeAction"))
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody(session ->
                            "{\"challenge\":\"" + session.getString("challenge") + "\"}"))
