            // 9. GET challenge Location -> grant_id
            .doIf(session -> session.contains("challengeLocation") &&
                    session.getString("challengeLocation") != null &&
                    !session.getString("challengeLocation").isEmpty())
            .then(
                    exec(http("GET challenge redirect")
                            .get(session -> session.getString("challengeLocation"))
                            .check(status().is(200))
                            .check(bodyString().saveAs("grantBody")))
            )

            .exec(session -> {
                String body = session.getString("grantBody");
                String grant = null, csrf = session.getString("csrf");
                if (body != null) {
                    java.util.regex.Matcher gm = java.util.regex.Pattern
                            .compile("\"grant_id\"\\s*:\\s*\"([^\"]+)\"")
                            .matcher(body);
                    if (gm.find()) grant = gm.group(1);
                    java.util.regex.Matcher cm = java.util.regex.Pattern
                            .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"")
                            .matcher(body);
                    if (cm.find()) csrf = cm.group(1);
                }
                return session.set("grant", grant).set("csrf", csrf);
            })

            // 10. create cart with grant_id once
            .exec(http("POST /v2/carts")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody(session ->
                            "{\"product_id\":\"" + session.getString("product") +
                                    "\",\"variant_id\":\"" + session.getString("variant") +
                                    "\",\"grant_id\":\"" + session.getString("grant") + "\"}"))
                    .check(status().is(201))
                    .check(header("ETag").optional().saveAs("etag"))
                    .check(bodyString().saveAs("cartBody")))

            .exec(session -> {
                String body = session.getString("cartBody");
                String cart = null, csrf = session.getString("csrf");
                if (body != null) {
                    java.util.regex.Matcher cm = java.util.regex.Pattern
                            .compile("\"id\"\\s*:\\s*\"([^\"]+)\"")
                            .matcher(body);
                    if (cm.find()) cart = cm.group(1);
                    java.util.regex.Matcher sm = java.util.regex.Pattern
                            .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"")
                            .matcher(body);
                    if (sm.find()) csrf = sm.group(1);
                }
                return session.set("cart", cart)
                        .set("csrf", csrf)
                        .set("hasCart", cart != null)
                        .set("idemKey", "idem-" + cart);
            })

            // 11. reservation
            .exec(http("POST /v2/reservations")
                    .post("/v2/reservations")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody(session ->
                            "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                    .check(status().is(202))
                    .check(bodyString().saveAs("resBody")))

            .exec(session -> {
                String body = session.getString("resBody");
                String statusUrl = null, csrf = session.getString("csrf");
                if (body != null) {
                    java.util.regex.Matcher um = java.util.regex.Pattern
                            .compile("\"status_url\"\\s*:\\s*\"([^\"]+)\"")
                            .matcher(body);
                    if (um.find()) statusUrl = um.group(1);
                    java.util.regex.Matcher sm = java.util.regex.Pattern
                            .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"")
                            .matcher(body);
                    if (sm.find()) csrf = sm.group(1);
                }
                return session.set("statusUrl", statusUrl).set("csrf", csrf);
            })

            // 12. poll reservation status (up to 5 times, >=50ms apart)
            .asLongAs(session -> !session.getBoolean("ready"))
            .on(
                    pause(Duration.ofMillis(60))
                            .exec(http("GET reservation status")
                                    .get(session -> session.getString("statusUrl"))
                                    .check(status().is(200))
                                    .check(bodyString().saveAs("statusBody")))
                            .exec(session -> {
                                String body = session.getString("statusBody");
                                String status = null, rid = null;
                                if (body != null) {
                                    java.util.regex.Matcher sm = java.util.regex.Pattern
                                            .compile("\"status\"\\s*:\\s*\"([^\"]+)\"")
                                            .matcher(body);
                                    if (sm.find()) status = sm.group(1);
                                    java.util.regex.Matcher rm = java.util.regex.Pattern
                                            .compile("\"reservation_id\"\\s*:\\s*\"([^\"]+)\"")
                                            .matcher(body);
                                    if (rm.find()) rid = rm.group(1);
                                }
                                boolean ready = "ready".equals(status);
                                return session.set("ready", ready)
                                        .set("reservationId", rid == null ? "" : rid);
                            })
            )
            .exitHereIfFailed()

            // 13. checkout
            .exec(http("POST /v2/orders")
                    .post("/v2/orders")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .header("Idempotency-Key", session -> session.getString("idemKey"))
                    .header("If-Match", session -> session.getString("etag"))
                    .body(StringBody(session ->
                            "{\"cart_id\":\"" + session.getString("cart") +
                                    "\",\"reservation_id\":\"" +
                                    session.getString("reservationId") + "\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.accepted").is("true"))
                    .check(bodyString().saveAs("orderBody")))

            .exec(session -> {
                String body = session.getString("orderBody");
                String csrf = session.getString("csrf");
                if (body != null) {
                    java.util.regex.Matcher sm = java.util.regex.Pattern
                            .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"")
                            .matcher(body);
                    if (sm.find()) csrf = sm.group(1);
                }
                return session.set("csrf", csrf);
            });

    {
        setUp(
                SCENARIO.injectOpen(
                        rampUsersPerSec(0).to(2).during(Duration.ofSeconds(1))
                                .andThen(constantUsersPerSec(2).during(Duration.ofSeconds(1)))
                ).protocols(HTTP)
        ).maxDuration(Duration.ofMinutes(2));
    }
}
