    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  }));

  let location = null;
  if (res.status === 302) {
    location = getHeader(res, 'Location');
    check(res, { 'login redirect has location': () => !!location });
    if (location) {
      // Follow dynamic Location exactly once
      const followRes = http.get(location.startsWith('http') ? location : `${BASE}${location}`, params());
      check(followRes, { 'login redirect follow 200': (r) => r.status === 200 });
      const j = safeJson(followRes);
      if (j && j.csrf) csrf = j.csrf;
      if (j && j.grant_id) { /* not expected here */ }
    }
  } else {
    check(res, { 'login 200': (r) => r.status === 200 });
    const j = safeJson(res);
