  const challengeMatch = (res.body || '').match(/<input(?=[^>]*\bname=["']challenge["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  if (!actionMatch || !challengeMatch) fail('challenge form missing action/challenge');
  const challengeAction = actionMatch[1];
  const challengeValue = challengeMatch[1];

