  res = http.get(challengeLoc.startsWith('http') ? challengeLoc : `${BASE}${challengeLoc}`, params());
  check(res, { 'challenge follow 200': (r) => r.status === 200 });
  let grantId = null;
  {
    const j = safeJson(res);
    if (j) {
      if (j.csrf) csrf = j.csrf;
