  let cartId = null;
  let etag = getHeader(res, 'ETag');
  {
    const j = safeJson(res);
    if (j) {
      if (j.csrf) csrf = j.csrf;
      if (j.id) cartId = j.id;
    }
  }
  if (!cartId) fail('no cart id');

  // ---- Reservation ----
  res = http.post(
    `${BASE}/v2/reservations`,
    JSON.stringify({ cart_id: cartId }),
    params({ headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf } })
  );
  check(res, { 'reservation 202': (r) => r.status === 202 });
  let statusUrl = null;
