  // ---- Order (one committed order per journey) ----
  const idemKey = `idem-${cartId}-${vu}-${__ITER}`;
  const orderHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
