                    self._abs(loc),
                    name="GET login redirect",
                    catch_response=True,
                    allow_redirects=False,
                ) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"redirect status {r2.status_code}")
                        return False
                    try:
                        body = r2.json()
                    except Exception:
                        r2.failure("redirect not json")
                        return False
                    if "csrf" not in body:
                        r2.failure("no csrf in redirect body")
                        return False
                    self.csrf = body["csrf"]
                return True
            elif r.status_code == 200:
                try:
                    body = r.json()
                except Exception:
                    r.failure("login not json")
                    return False
                if "csrf" not in body:
                    r.failure("no csrf in login body")
