            if "csrf" in body:
                self.csrf = body["csrf"]
            if not status_url:
                r.failure("no status_url")
                return None

        reservation_id = None
        for attempt in range(5):
            time.sleep(0.06)
            with self.client.get(
                self._abs(status_url),
                name="GET reservation status",
                catch_response=True,
                allow_redirects=False,
            ) as rs:
                if rs.status_code != 200:
                    rs.failure(f"status poll {rs.status_code}")
                    return None
                try:
                    sbody = rs.json()
                except Exception:
                    rs.failure("status not json")
                    return None
                status = sbody.get("status")
                if status == "ready":
                    reservation_id = sbody.get("reservation_id")
                    if not reservation_id:
                        rs.failure("ready without reservation_id")
                        return None
                    return reservation_id
                if status in ("pending",):
                    continue
                if status in ("failed",):
                    rs.failure("reservation failed")
                    return None
                rs.failure(f"unknown status {status}")
                return None
        return None

    def _order(self, cart, reservation_id):
        payload = {"cart_id": cart["id"]}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf or "",
            "Idempotency-Key": cart["id"],
        }
        if cart.get("etag"):
            headers["If-Match"] = cart["etag"]
        with self.client.post(
            "/v2/orders",
            json=payload,
            name="POST /v2/orders",
            catch_response=True,
            allow_redirects=False,
            headers=headers,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id=cart["id"]):
                    return self._order(cart, reservation_id)
                r.failure("order 401 unrecovered")
                return False
            if r.status_code != 201:
                r.failure(f"order status {r.status_code}")
                return False
            try:
                body = r.json()
            except Exception:
                r.failure("order not json")
                return False
            if body.get("accepted") is not True:
                r.failure("order not accepted")
                return False
            if "csrf" in body:
                self.csrf = body["csrf"]
            return True

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        if not self._login():
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        grant = self._get_challenge_grant()
        if not grant:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        picked = self._pick_product()
        if not picked:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        product_id, variant_id = picked

        cart = self._create_cart(product_id, variant_id, grant)
        if not cart:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        if not self._patch_quantity(cart):
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        reservation_id = self._reserve(cart)
        if not reservation_id:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        self._order(cart, reservation_id)

        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = None

    def tick(self):
        if self.start_time is None:
            self.start_time = time.time()
        elapsed = time.time() - self.start_time
        # 2 users, 2 iterations each; stop after enough time
        if elapsed > 120:
            return None
        return (2, 2)
