import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv("BASE_URL") != null
            ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

    // accounts.json rows (same records as the JMX CSVs)
    private static final List<Map<String, Object>> ACCOUNTS = List.of(
            Map.of("username", "bench-1", "password", "bench", "quantity", 2, "delay", 0),
            Map.of("username", "bench-2", "password", "bench", "quantity", 3, "delay", 500)
    );

    private static final AtomicInteger SEED = new AtomicInteger(0);

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>");

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableFollowRedirect()
            .disableCaching()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    // ---- helpers -------------------------------------------------------

    private static String extractCsrf(String body) {
        if (body == null) return null;
        Matcher m = CSRF_INPUT.matcher(body);
        return m.find() ? m.group(1) : null;
    }

    private static String jsonString(String body, String field) {
        if (body == null) return null;
        Matcher m = Pattern.compile("\"" + Pattern.quote(field) + "\"\\s*:\\s*\"([^\"]*)\"").matcher(body);
        return m.find() ? m.group(1) : null;
    }

    private static boolean jsonBool(String body, String field) {
        if (body == null) return false;
        Matcher m = Pattern.compile("\"" + Pattern.quote(field) + "\"\\s*:\\s*(true|false)").matcher(body);
        return m.find() && "true".equals(m.group(1));
    }

    // ---- feeder --------------------------------------------------------

    private static Iterator<Map<String, Object>> accountFeeder() {
        List<Map<String, Object>> rows = new ArrayList<>();
        for (Map<String, Object> a : ACCOUNTS) {
            Map<String, Object> row = new LinkedHashMap<>(a);
            row.put("seed", SEED.incrementAndGet());
            rows.add(row);
        }
        return rows.iterator();
    }

    // ---- scenario ------------------------------------------------------

    private static final ScenarioBuilder SCENARIO = scenario("ModelSimulation")
            .feed(accountFeeder())
            .exec(session -> session.set("csrf", "").set("cart", "").set("etag", "").set("grant", ""))

            // fresh login per journey
            .exec(http("GET /v2/login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(bodyString().transform(ModelSimulation::extractCsrf)
                            .notNull().saveAs("formCsrf")))

            .exec(http("POST /v2/login")
                    .post("/v2/login")
                    .body(StringBody(session ->
                            "{\"username\":\"" + session.getString("username")
                                    + "\",\"password\":\"" + session.getString("password")
                                    + "\",\"csrf\":\"" + session.getString("formCsrf") + "\"}"))
                    .check(status().in(200, 302))
                    .check(bodyString().transform(ModelSimulation::extractCsrf)
                            .optional().saveAs("loginCsrf")))

            .exec(session -> {
                String c = session.getString("loginCsrf");
                if (c == null || c.isEmpty()) c = session.getString("formCsrf");
                return session.set("csrf", c);
            })

            // catalog
            .exec(http("GET /v2/catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(bodyString().transform(ModelSimulation::extractCsrf)
                            .optional().saveAs("catCsrf"))
                    .check(bodyString().transform(b -> {
                        if (b == null) return null;
                        Matcher m = Pattern.compile(
                                "\"id\"\\s*:\\s*\"([^\"]+)\"[^\\[\\]]*\"variants\"\\s*:\\s*\\[\\s*\\{[^}]*\"id\"\\s*:\\s*\"([^\"]+)\"[^}]*\"in_stock\"\\s*:\\s*true")
                                .matcher(b);
                        return m.find() ? m.group(1) + "|" + m.group(2) : null;
                    }).notNull().saveAs("productVariant")))

            .exec(session -> {
                String c = session.getString("catCsrf");
                if (c != null && !c.isEmpty()) session = session.set("csrf", c);
                String pv = session.getString("productVariant");
                String[] parts = pv.split("\\|", 2);
                return session.set("product", parts[0]).set("variant", parts[1]);
            })

            // challenge -> grant
            .exec(http("GET /v2/challenge-form")
                    .get("/v2/challenge-form")
                    .check(status().is(200))
                    .check(bodyString().transform(b -> {
                        if (b == null) return null;
                        Matcher m = Pattern.compile("/v2/challenges/([^\"'\\s]+)").matcher(b);
                        return m.find() ? m.group(1) : null;
                    }).notNull().saveAs("challengeId"))
                    .check(bodyString().transform(ModelSimulation::extractCsrf)
                            .optional().saveAs("chCsrf")))

            .exec(session -> {
                String c = session.getString("chCsrf");
                if (c != null && !c.isEmpty()) session = session.set("csrf", c);
                return session;
            })

            .exec(http("POST /v2/challenges/{id}")
                    .post("/v2/challenges/#{challengeId}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"challenge\":\"#{challengeId}\"}"))
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("chLocation")))

            .exec(http("GET challenge Location")
                    .get(session -> {
                        String loc = session.getString("chLocation");
                        return loc != null ? loc : "/v2/challenge-form";
                    })
                    .check(status().is(200))
                    .check(bodyString().transform(ModelSimulation::extractCsrf)
                            .optional().saveAs("grantCsrf"))
                    .check(bodyString().transform(b -> jsonString(b, "grant_id"))
                            .notNull().saveAs("grant")))

            .exec(session -> {
                String c = session.getString("grantCsrf");
                if (c != null && !c.isEmpty()) session = session.set("csrf", c);
                return session;
            })

            // create cart
            .exec(http("POST /v2/carts")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody(session ->
                            "{\"product_id\":\"" + session.getString("product")
                                    + "\",\"variant_id\":\"" + session.getString("variant")
                                    + "\",\"grant_id\":\"" + session.getString("grant") + "\"}"))
                    .check(status().is(201))
                    .check(header("ETag").notNull().saveAs("etag"))
                    .check(bodyString().transform(b -> jsonString(b, "id"))
                            .notNull().saveAs("cart"))
                    .check(bodyString().transform(ModelSimulation::extractCsrf)
                            .optional().saveAs("cartCsrf")))

            .exec(session -> {
                String c = session.getString("cartCsrf");
                if (c != null && !c.isEmpty()) session = session.set("csrf", c);
                return session;
            })

            // set quantity (numeric, preserved)
            .exec(http("PATCH /v2/carts/{id}")
                    .patch("/v2/carts/#{cart}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("If-Match", "#{etag}")
                    .body(StringBody(session ->
                            "{\"quantity\":" + session.getInt("quantity") + "}"))
                    .check(status().in(200, 204))
                    .check(header("ETag").optional().saveAs("etag2"))
                    .check(bodyString().transform(ModelSimulation::extractCsrf)
                            .optional().saveAs("patchCsrf")))

            .exec(session -> {
                String e = session.getString("etag2");
                if (e != null && !e.isEmpty()) session = session.set("etag", e);
                String c = session.getString("patchCsrf");
                if (c != null && !c.isEmpty()) session = session.set("csrf", c);
                return session;
            })

            // reservation
            .exec(http("POST /v2/reservations")
                    .post("/v2/reservations")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
                    .check(status().is(202))
                    .check(bodyString().transform(b -> jsonString(b, "status_url"))
                            .notNull().saveAs("statusUrl"))
                    .check(bodyString().transform(ModelSimulation::extractCsrf)
                            .optional().saveAs("resCsrf")))

            .exec(session -> {
                String c = session.getString("resCsrf");
                if (c != null && !c.isEmpty()) session = session.set("csrf", c);
                return session;
            })

            // poll reservation (>=50ms apart, <=5 times)
            .asLongAs(session -> session.getString("reservationId") == null
                    && session.getInt("pollCount") < 5).on(
                    pause(Duration.ofMillis(60))
                            .exec(session -> session.set("pollCount", session.getInt("pollCount") + 1))
                            .exec(http("GET reservation status")
                                    .get("#{statusUrl}")
                                    .check(status().is(200))
                                    .check(bodyString().transform(b -> jsonString(b, "status"))
                                            .optional().saveAs("resStatus"))
                                    .check(bodyString().transform(b -> jsonString(b, "reservation_id"))
                                            .optional().saveAs("reservationId")))
            )

            .exec(session -> {
                String st = session.getString("resStatus");
                if (!"ready".equals(st)) {
                    return session.markAsFailed();
                }
                return session;
            })

            // order
            .exec(http("POST /v2/orders")
                    .post("/v2/orders")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("If-Match", "#{etag}")
                    .header("Idempotency-Key", "#{cart}")
                    .body(StringBody(session ->
                            "{\"cart_id\":\"" + session.getString("cart")
                                    + "\",\"reservation_id\":\"" + session.getString("reservationId") + "\"}"))
                    .check(status().is(201))
                    .check(bodyString().transform(b -> jsonBool(b, "accepted"))
                            .is(true))
                    .check(bodyString().transform(b -> jsonString(b, "id"))
                            .notNull().saveAs("orderId")));

    {
        setUp(
                SCENARIO.injectClosed(
                        constantConcurrentUsers(2).during(Duration.ofSeconds(1))
                ).protocols(HTTP)
        ).maxDuration(Duration.ofSeconds(120));
    }
}
