                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
        ).exec(session -> {
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginRedirect", loc);
            }
            return session.remove("loginRedirect");
        }).doIf(session -> session.contains("loginRedirect")).then(
                exec(
                        http("GET login redirect")
                                .get("#{loginRedirect}")
                                .check(status().is(200))
                                .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                )
        ).exec(session -> {
            String csrf = session.getString("csrf");
            if (csrf == null) {
                csrf = session.getString("formCsrf");
            }
            return session.set("csrf", csrf);
        });
    }

    private static ChainBuilder catalog() {
        return exec(
                http("GET /v2/catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id").find().saveAs("product"))
                        .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").find().saveAs("variant"))
        );
    }

    private static ChainBuilder createCart() {
        return exec(
                http("POST /v2/carts")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\"}"))
                        .check(status().is(201))
                        .check(jsonPath("$.id").saveAs("cart"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
                        .check(header("ETag").optional().saveAs("etag"))
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null) {
                return session.set("csrf", c);
            }
            return session;
        });
    }

    private static ChainBuilder checkout() {
        return exec(
