import os
import re
import time
import uuid

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _extract_csrf_from_form(html):
    if not html:
        return None
    # find input tags with name=csrf and capture value
    for m in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r"""name\s*=\s*["']csrf["']""", tag, re.IGNORECASE):
            vm = re.search(r"""value\s*=\s*["']([^"']*)["']""", tag, re.IGNORECASE)
            if vm:
                return vm.group(1)
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.0, 0.0)

    def on_start(self):
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.username = None
        self.iterations_done = 0
        self.max_iterations = 2

    # ---------- helpers ----------
    def _headers(self, extra=None):
        h = {"Content-Type": "application/json"}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if extra:
            h.update(extra)
        return h

    def _handle_expiry(self, resp, retry_fn):
        """If 401 expired/session, attempt renew+recover then retry once."""
        if resp.status_code != 401:
            return False
        try:
            body = resp.json()
        except Exception:
            return False
        err = body.get("error")
        if err == "denied":
            return False
        if err not in ("expired", "session"):
            return False
        # renew
        r = self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._headers(),
            catch_response=True,
            name="POST /v2/session/renew",
        )
        if r.status_code == 200:
            try:
                j = r.json()
                if j.get("csrf"):
                    self.csrf = j["csrf"]
            except Exception:
                pass
            r.success()
        else:
            r.failure(f"renew failed {r.status_code}")
        # recover cart if exists
        if self.cart_id:
            rr = self.client.post(
                f"/v2/carts/{self.cart_id}/recover",
                json={},
                headers=self._headers(),
                catch_response=True,
                name="POST /v2/carts/{id}/recover",
            )
            if rr.status_code in (200, 201, 204):
                rr.success()
            else:
                rr.failure(f"recover failed {rr.status_code}")
        # retry once
        retry_fn()
        return True

    # ---------- journey steps ----------
    def do_login(self):
        # GET login form
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="GET /v2/login-form",
        ) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return False
            csrf = _extract_csrf_from_form(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return False
            self.csrf = csrf
            r.success()

        # choose account
        if not self.username:
            self.username = "bench"

        # POST login
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": self.csrf},
            headers=self._headers(),
            catch_response=True,
            name="POST /v2/login",
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                r.success()
                # follow exactly once
                with self.client.get(
                    loc,
                    catch_response=True,
                    name="GET login redirect",
                    allow_redirects=False,
                ) as r2:
                    if r2.status_code not in (200, 204):
                        r2.failure(f"redirect status {r2.status_code}")
                        return False
                    try:
                        j = r2.json()
                        if j.get("csrf"):
                            self.csrf = j["csrf"]
                    except Exception:
                        pass
                    r2.success()
                return True
            elif r.status_code == 200:
                try:
                    j = r.json()
                except Exception:
                    r.failure("login non-json")
                    return False
                if j.get("csrf"):
                    self.csrf = j["csrf"]
                r.success()
                return True
            else:
                r.failure(f"login status {r.status_code}")
                return False

    def do_catalog(self):
        with self.client.get(
            "/v2/catalog",
            headers=self._headers(),
            catch_response=True,
            name="GET /v2/catalog",
        ) as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return None
            try:
                j = r.json()
            except Exception:
                r.failure("catalog non-json")
                return None
            products = (j.get("data") or {}).get("products") or []
            for p in products:
                variants = p.get("variants") or []
                for v in variants:
                    if v.get("in_stock"):
                        r.success()
                        return (p.get("id"), v.get("id"))
            r.failure("no in-stock product")
            return None

    def do_challenge(self):
        with self.client.get(
            "/v2/challenge-form",
            headers=self._headers(),
            catch_response=True,
            name="GET /v2/challenge-form",
        ) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return False
            html = r.text or ""
            action_m = re.search(r"""action\s*=\s*["']([^"']+)["']""", html, re.IGNORECASE)
            chal_m = re.search(
                r"""<input\b[^>]*name\s*=\s*["']challenge["'][^>]*>""", html, re.IGNORECASE
            )
            challenge_val = None
            if chal_m:
                vm = re.search(r"""value\s*=\s*["']([^"']*)["']""", chal_m.group(0), re.IGNORECASE)
                if vm:
                    challenge_val = vm.group(1)
            if not action_m or not challenge_val:
                r.failure("challenge form missing action/challenge")
                return False
            action = action_m.group(1)
            r.success()

        with self.client.post(
            action,
            json={"challenge": challenge_val},
            headers=self._headers(),
            catch_response=True,
            name="POST /v2/challenges/{id}",
            allow_redirects=False,
        ) as r:
            if r.status_code != 302:
                r.failure(f"challenge post status {r.status_code}")
                return False
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge 302 no Location")
                return False
            r.success()

        with self.client.get(
            loc,
            headers=self._headers(),
            catch_response=True,
            name="GET challenge Location",
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure(f"challenge location status {r.status_code}")
                return False
            try:
                j = r.json()
            except Exception:
                r.failure("challenge location non-json")
                return False
            if j.get("csrf"):
                self.csrf = j["csrf"]
            if j.get("grant_id"):
                self.grant_id = j["grant_id"]
                r.success()
                return True
            r.failure("no grant_id")
            return False

    def do_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
            self.grant_id = None  # pass once
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=self._headers(),
            catch_response=True,
            name="POST /v2/carts",
        ) as r:
            if r.status_code != 201:
                r.failure(f"cart status {r.status_code}")
                return False
            try:
                j = r.json()
            except Exception:
                r.failure("cart non-json")
                return False
            cid = j.get("id")
            if not cid:
                r.failure("cart no id")
                return False
            self.cart_id = cid
            if j.get("csrf"):
                self.csrf = j["csrf"]
            et = r.headers.get("ETag")
            if et:
                self.etag = et
            r.success()
            return True

    def do_patch_quantity(self, qty=2):
        if not self.cart_id:
            return False
        # read cart for etag
        with self.client.get(
            f"/v2/carts/{self.cart_id}",
            headers=self._headers(),
            catch_response=True,
            name="GET /v2/carts/{id}",
        ) as r:
            if r.status_code != 200:
                r.failure(f"cart get status {r.status_code}")
                return False
            et = r.headers.get("ETag")
            if et:
                self.etag = et
            r.success()

        def _patch():
            extra = {}
            if self.etag:
                extra["If-Match"] = self.etag
            with self.client.patch(
                f"/v2/carts/{self.cart_id}",
                json={"quantity": qty},
                headers=self._headers(extra),
                catch_response=True,
                name="PATCH /v2/carts/{id}",
            ) as r:
                if r.status_code == 412:
                    # re-read and retry once
                    with self.client.get(
                        f"/v2/carts/{self.cart_id}",
                        headers=self._headers(),
                        catch_response=True,
                        name="GET /v2/carts/{id} (412 reread)",
                    ) as rr:
                        if rr.status_code == 200:
                            et2 = rr.headers.get("ETag")
                            if et2:
                                self.etag = et2
                            rr.success()
                        else:
                            rr.failure(f"reread status {rr.status_code}")
                    extra2 = {}
                    if self.etag:
                        extra2["If-Match"] = self.etag
                    with self.client.patch(
                        f"/v2/carts/{self.cart_id}",
                        json={"quantity": qty},
                        headers=self._headers(extra2),
                        catch_response=True,
                        name="PATCH /v2/carts/{id} (retry)",
                    ) as r2:
                        if r2.status_code in (200, 204):
                            et3 = r2.headers.get("ETag")
                            if et3:
                                self.etag = et3
                            r2.success()
                            return True
                        r2.failure(f"patch retry status {r2.status_code}")
                        return False
                elif r.status_code in (200, 204):
                    et3 = r.headers.get("ETag")
                    if et3:
                        self.etag = et3
                    r.success()
                    return True
                else:
                    r.failure(f"patch status {r.status_code}")
                    return False

        return _patch()

    def do_reservation(self):
        if not self.cart_id:
            return None
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers=self._headers(),
            catch_response=True,
            name="POST /v2/reservations",
        ) as r:
            if r.status_code != 202:
                r.failure(f"reservation status {r.status_code}")
                return None
            try:
                j = r.json()
            except Exception:
                r.failure("reservation non-json")
                return None
            if j.get("csrf"):
                self.csrf = j["csrf"]
            status_url = j.get("status_url")
            if not status_url:
                r.failure("no status_url")
                return None
            r.success()

        reservation_id = None
        for attempt in range(5):
            time.sleep(0.06)
            with self.client.get(
                status_url,
                headers=self._headers(),
                catch_response=True,
                name="GET reservation status",
            ) as r:
                if r.status_code != 200:
                    r.failure(f"status poll {r.status_code}")
                    return None
                try:
                    j = r.json()
                except Exception:
                    r.failure("status non-json")
                    return None
                st = j.get("status")
                if st == "ready":
                    reservation_id = j.get("reservation_id")
                    r.success()
                    break
                elif st in ("pending",):
                    r.success()
                    continue
                else:
                    r.failure(f"reservation status {st}")
                    return None
        return reservation_id

    def do_order(self):
        if not self.cart_id:
            return False
        idem = f"idem-{self.cart_id}-{uuid.uuid4().hex[:8]}"
        payload = {"cart_id": self.cart_id}
        extra = {"Idempotency-Key": idem}
        if self.etag:
            extra["If-Match"] = self.etag

        def _post():
            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=self._headers(extra),
                catch_response=True,
                name="POST /v2/orders",
            ) as r:
                if r.status_code == 201:
                    try:
                        j = r.json()
                    except Exception:
                        r.failure("order non-json")
                        return False
                    if j.get("accepted") is True:
                        if j.get("csrf"):
                            self.csrf = j["csrf"]
                        r.success()
                        return True
                    r.failure("order accepted false")
                    return False
                elif r.status_code == 200:
                    try:
                        j = r.json()
                    except Exception:
                        r.failure("order 200 non-json")
                        return False
                    if j.get("accepted") is True:
                        if j.get("csrf"):
                            self.csrf = j["csrf"]
                        r.success()
                        return True
                    r.failure("order 200 accepted false")
                    return False
                else:
                    r.failure(f"order status {r.status_code}")
                    return False

        return _post()

    # ---------- main task ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        # fresh login each journey
        self.cart_id = None
        self.etag = None
        self.grant_id = None

        if not self.do_login():
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        prod = self.do_catalog()
        if not prod:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        product_id, variant_id = prod

        # challenge to get grant
        self.do_challenge()

        if not self.do_cart(product_id, variant_id):
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        self.do_patch_quantity(2)

        reservation_id = self.do_reservation()
        if reservation_id:
            # attach reservation to order payload via cart? protocol says reservation_id optional
            pass

        self.do_order()

        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class ShopShape(LoadTestShape):
    """
    Source JMX: 4 threads, 38s duration, ConstantThroughputTimer 121.2/min (~2.02/s).
    Execution contract: users=2, iterations=2, rate=2, max_vus=4, flow mode.
    Phased targets 5/15/5 over three 10s plateaus; warmup 5s; drain <=5s.
    We honor the contract: 2 users, each doing 2 iterations, paced at ~2/s aggregate.
    """

    def tick(self):
        run_time = self.get_run_time()
        # total budget: warmup 5 + 30 scored + drain 5 = 40s
        if run_time >= 40:
            return None
        # 2 users throughout; pacing handled by wait_time=0 and iteration cap
        return (2, 2)
