import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL =
            System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableFollowRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .shareConnections();

    // ---- helpers ---------------------------------------------------------

    private static String userFor(int threadNum) {
        return "bench-" + threadNum;
    }

    // ---- scenario --------------------------------------------------------

    private static final ScenarioBuilder JOURNEY = scenario("ModelSimulation")
            .exec(session -> session.set("username", userFor(session.userId() + 1)))
            .exec(session -> session
                    .set("csrf", "MISSING")
                    .set("cart", "MISSING")
                    .set("etag", "MISSING")
                    .set("grant", "MISSING")
                    .set("product", "MISSING")
                    .set("variant", "MISSING")
                    .set("quantity", 2)
                    .set("hasCart", false)
                    .set("pending", true)
                    .set("ready", false))

            // 1. login form
            .exec(http("GET /v2/login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(regex("<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>")
                            .saveAs("form")))

            // 2. login
            .exec(http("POST /v2/login")
                    .post("/v2/login")
                    .body(StringBody(session ->
                            "{\"username\":\"" + session.getString("username")
                                    + "\",\"password\":\"bench\",\"csrf\":\""
                                    + session.getString("form") + "\"}"))
                    .check(status().in(200, 302))
                    .check(regex("\"csrf\"\\s*:").optional().saveAs("csrfPresent"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
                    .check(header("Location").optional().saveAs("location"))
                    .check(regex("(?im)^Location:").optional().saveAs("redirect")))
            .exec(session -> {
                String csrfNew = session.getString("csrfNew");
                if (csrfNew != null && !csrfNew.isEmpty()) {
                    return session.set("csrf", csrfNew);
                }
                return session;
            })

            // 3. follow login redirect once if present
            .doIf(session -> session.getString("redirect") != null)
            .then(
                    exec(http("GET login redirect")
                            .get(session -> session.getString("location"))
                            .check(status().is(200))
                            .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
                            .check(jsonPath("$.grant_id").optional().saveAs("grantNew")))
                            .exec(session -> {
                                String c = session.getString("csrfNew");
                                String g = session.getString("grantNew");
                                Session s = session;
                                if (c != null && !c.isEmpty()) s = s.set("csrf", c);
                                if (g != null && !g.isEmpty()) s = s.set("grant", g);
                                return s;
                            })
            )

            // 4. catalog
            .exec(http("GET /v2/catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id")
                            .find().saveAs("product"))
                    .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                            .find().saveAs("variant")))

            // 5. create cart
            .exec(http("POST /v2/carts")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody(session ->
                            "{\"product_id\":\"" + session.getString("product")
                                    + "\",\"variant_id\":\"" + session.getString("variant")
                                    + "\",\"grant_id\":\"" + session.getString("grant") + "\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.id").saveAs("cart"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
                    .check(header("ETag").optional().saveAs("etagNew")))
            .exec(session -> {
                Session s = session.set("hasCart", true);
                String c = session.getString("csrfNew");
                String e = session.getString("etagNew");
                if (c != null && !c.isEmpty()) s = s.set("csrf", c);
                if (e != null && !e.isEmpty()) s = s.set("etag", e);
                return s;
            })

            // 6. place order
            .exec(http("POST /v2/orders")
                    .post("/v2/orders")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .header("Idempotency-Key", session -> session.getString("cart"))
                    .header("If-Match", session -> session.getString("etag"))
                    .body(StringBody(session ->
                            "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.accepted").is("true"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrfNew")))
            .exec(session -> {
                String c = session.getString("csrfNew");
                if (c != null && !c.isEmpty()) return session.set("csrf", c);
                return session;
            });

    {
        setUp(
                JOURNEY.injectClosed(
                        constantConcurrentUsers(2).during(Duration.ofSeconds(1))
                ).protocols(HTTP)
        ).assertions(
                global().failedRequests().count().is(0L)
        );
    }
}
