import http from 'k6/http';
import { check, group, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { randomIntBetween } from 'https://jslib.k6.io/k6-utils/1.4.0/index.js';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// ---- Custom metrics (transaction-level tagging) ----
const journeySuccess = new Rate('journey_success');
const journeyBusinessFailure = new Rate('journey_business_failure');
const orderCommitted = new Counter('orders_committed');
const cartCreated = new Counter('carts_created');
const duplicateCart = new Counter('duplicate_carts');
const businessFailureRate = new Rate('business_failure');
const unexpectedFailure = new Counter('unexpected_failures');
const businessResponses = new Counter('business_responses');
const loginDuration = new Trend('login_duration', true);
const checkoutDuration = new Trend('checkout_duration', true);

// ---- Execution contract ----
export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    // Safety: threshold scope/denominator exactly match contract.
    // business_failure numerator = unexpected failures (excl. expected expiry/scheduled429),
    // denominator = all business responses (incl. expected expiry).
    business_failure: ['rate<0.01'],
    journey_success: ['rate>0.99'],
    journey_business_failure: ['rate<0.01'],
    http_req_failed: ['rate<0.01'],
    checks: ['rate>0.99'],
  },
  // k6 handleSummary disabled per protocol.
  summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(90)', 'p(95)'],
};

// ---- Fixture variants (two count equally) ----
const PROFILES = [
  {},
  { html_layout: 1, reverse_catalog: true },
];

// ---- Negative-control overrides ----
const NEGATIVE_CONTROLS = [
  { decline_orders: true },
];

function pickProfile(vu, iter) {
  // Alternate profiles across iterations so both variants count equally.
  return PROFILES[(vu + iter) % PROFILES.length];
}

function pickNegativeControl(vu, iter) {
  // Apply negative control on the second iteration of each VU (deterministic).
  if (iter === 1) return NEGATIVE_CONTROLS[0];
  return null;
}

// ---- Per-VU cookie jar (preserve per-user cookies) ----
function makeJar() {
  return http.cookieJar();
}

// ---- Helpers ----
function parseCsrfFromForm(html) {
  // Mixed with decoys/attribute variants; match input[name=csrf] with value.
  const re = /<input\b(?=[^>]*\bname\s*=\s*["']csrf["'])(?=[^>]*\bvalue\s*=\s*["']([^"']+)["'])[^>]*>/i;
  const m = re.exec(html || '');
  return m ? m[1] : null;
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function isExpired(res) {
  try {
    const b = res.json();
    return b && b.error === 'expired';
  } catch (e) {
    return false;
  }
}

function isSessionRevoked(res) {
  try {
    const b = res.json();
    return b && b.error === 'session';
  } catch (e) {
    return false;
  }
}

function isDenied(res) {
  try {
    const b = res.json();
    return b && b.error === 'denied';
  } catch (e) {
    return false;
  }
}

function isScheduled429(res) {
  return res.status === 429;
}

function isUnexpected(res) {
  // 500 is unexpected; 401 denied is not expiry -> fail its assertion (counted unexpected).
  if (res.status >= 500) return true;
  if (res.status === 401 && isDenied(res)) return true;
  return false;
}

function recordBusiness(res) {
  businessResponses.add(1);
  if (isUnexpected(res)) {
    unexpectedFailure.add(1);
    businessFailureRate.add(1);
  } else {
    businessFailureRate.add(0);
  }
}

function sleepRetryAfter(res) {
  const ra = getHeader(res, 'Retry-After');
  const secs = ra ? parseFloat(ra) : 1;
  sleep(Math.max(0.05, isNaN(secs) ? 1 : secs));
}

// ---- Session state per VU ----
function newSession() {
  return {
    csrf: null,
    user: null,
    cartId: null,
    etag: null,
    grantId: null,
    idempotencyKey: null,
    hasCart: false,
  };
}

// ---- Login flow ----
function doLogin(jar, username) {
  const t0 = Date.now();
  const formRes = http.get(`${BASE}/v2/login-form`, { jar, redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const formCsrf = parseCsrfFromForm(formRes.body);
  check(formCsrf, { 'login-form csrf extracted': (v) => !!v });

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    { jar, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );

  let csrf = null;
  let user = null;
  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loc, { 'login 302 has Location': (v) => !!v });
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar, redirects: 0 });
      check(followRes, { 'login follow 200': (r) => r.status === 200 });
      try {
        const b = followRes.json();
        csrf = b.csrf;
        user = b.user;
      } catch (e) { /* ignore */ }
    }
  } else {
    check(loginRes, { 'login 200': (r) => r.status === 200 });
    try {
      const b = loginRes.json();
      csrf = b.csrf;
      user = b.user;
    } catch (e) { /* ignore */ }
  }
  check(csrf, { 'login csrf present': (v) => !!v });
  loginDuration.add(Date.now() - t0);
  return { csrf, user };
}

// ---- Renew / recover ----
function renewSession(jar, sess) {
  const res = http.post(
    `${BASE}/v2/session/renew`,
    JSON.stringify({}),
    { jar, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf || '' } }
  );
  if (res.status === 200) {
    try {
      const b = res.json();
      if (b.csrf) sess.csrf = b.csrf;
    } catch (e) { /* ignore */ }
    return true;
  }
  return false;
}

function recoverCart(jar, sess) {
  if (!sess.cartId) return true;
  const res = http.post(
    `${BASE}/v2/carts/${sess.cartId}/recover`,
    JSON.stringify({}),
    { jar, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf || '' } }
  );
  if (res.status === 200) {
    try {
      const b = res.json();
      if (b.csrf) sess.csrf = b.csrf;
    } catch (e) { /* ignore */ }
    return true;
  }
  return false;
}

// Wraps an authenticated non-GET call with bounded recovery (once per operation).
function authedCall(jar, sess, method, path, body, extraHeaders) {
  const headers = Object.assign(
    { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf || '' },
    extraHeaders || {}
  );
  let res = http.request(method, `${BASE}${path}`, body ? JSON.stringify(body) : null, {
    jar, redirects: 0, headers,
  });

  if (res.status === 401) {
    if (isExpired(res)) {
      // Renew, recover cart, retry once.
      const renewed = renewSession(jar, sess);
      if (renewed) recoverCart(jar, sess);
      headers['X-CSRF-Token'] = sess.csrf || '';
      res = http.request(method, `${BASE}${path}`, body ? JSON.stringify(body) : null, {
        jar, redirects: 0, headers,
      });
    } else if (isSessionRevoked(res)) {
      // Renew may fail; get fresh form/login, recover cart, retry once.
      const fresh = doLogin(jar, sess.user || 'bench');
      if (fresh.csrf) sess.csrf = fresh.csrf;
      recoverCart(jar, sess);
      headers['X-CSRF-Token'] = sess.csrf || '';
      res = http.request(method, `${BASE}${path}`, body ? JSON.stringify(body) : null, {
        jar, redirects: 0, headers,
      });
    } else if (isDenied(res)) {
      // Not expiry: fail its assertion (do not retry).
      check(res, { 'denied is not expiry': () => false });
    }
  }
  return res;
}

// ---- Catalog ----
function fetchCatalog(jar, sess, profile) {
  // Traverse at most 3 pages via /v2/catalog/page.
  const products = [];
  let next = null;
  let pages = 0;
  const first = http.get(`${BASE}/v2/catalog`, { jar, redirects: 0 });
  check(first, { 'catalog 200': (r) => r.status === 200 });
  try {
    const b = first.json();
    if (b && b.data && Array.isArray(b.data.products)) {
      for (const p of b.data.products) products.push(p);
    }
    next = b && b.next;
  } catch (e) { /* ignore */ }

  while (next && pages < 3) {
    pages++;
    const url = next.startsWith('http') ? next : `${BASE}${next}`;
    const r = http.get(url, { jar, redirects: 0 });
    check(r, { 'catalog page 200': (x) => x.status === 200 });
    try {
      const b = r.json();
      if (b && b.data && Array.isArray(b.data.products)) {
        for (const p of b.data.products) products.push(p);
      }
      next = b && b.next;
    } catch (e) { next = null; }
  }

  // Pick an in-stock variant.
  let chosen = null;
  const list = profile && profile.reverse_catalog ? products.slice().reverse() : products;
  for (const p of list) {
    if (!p || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (v && v.in_stock) {
        chosen = { product_id: p.id, variant_id: v.id };
        break;
      }
    }
    if (chosen) break;
  }
  return chosen;
}

// ---- Challenge flow ----
function solveChallenge(jar, sess) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { jar, redirects: 0 });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const body = formRes.body || '';
  const actionMatch = /<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i.exec(body);
  const challengeMatch = /<input\b(?=[^>]*\bname\s*=\s*["']challenge["'])(?=[^>]*\bvalue\s*=\s*["']([^"']+)["'])[^>]*>/i.exec(body);
  const action = actionMatch ? actionMatch[1] : null;
  const challenge = challengeMatch ? challengeMatch[1] : null;
  check(action, { 'challenge action present': (v) => !!v });
  check(challenge, { 'challenge value present': (v) => !!v });
  if (!action || !challenge) return null;

  const postRes = http.post(
    action.startsWith('http') ? action : `${BASE}${action}`,
    JSON.stringify({ challenge }),
    { jar, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf || '' } }
  );
  check(postRes, { 'challenge post 302': (r) => r.status === 302 });
  const loc = getHeader(postRes, 'Location');
  if (!loc) return null;
  const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar, redirects: 0 });
  check(followRes, { 'challenge follow 200': (r) => r.status === 200 });
  try {
    const b = followRes.json();
    if (b.csrf) sess.csrf = b.csrf;
    return b.grant_id || null;
  } catch (e) {
    return null;
  }
}

// ---- Cart ----
function createCart(jar, sess, product, grantId) {
  const body = { product_id: product.product_id, variant_id: product.variant_id };
  if (grantId) body.grant_id = grantId;
  const res = authedCall(jar, sess, 'POST', '/v2/carts', body);
  check(res, { 'cart create 201': (r) => r.status === 201 });
  if (res.status === 201) {
    cartCreated.add(1);
    try {
      const b = res.json();
      if (b.csrf) sess.csrf = b.csrf;
      sess.cartId = b.id;
      sess.hasCart = true;
      sess.idempotencyKey = `idem-${b.id}-${Date.now()}`;
    } catch (e) { /* ignore */ }
    const etag = getHeader(res, 'ETag');
    if (etag) sess.etag = etag;
    return true;
  }
  return false;
}

function patchCartQuantity(jar, sess, qty) {
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf || '' };
  if (sess.etag) headers['If-Match'] = sess.etag;
  let res = http.patch(`${BASE}/v2/carts/${sess.cartId}`, JSON.stringify({ quantity: qty }), {
    jar, redirects: 0, headers,
  });
  if (res.status === 412) {
    // Re-read and retry same payload once.
    const re = http.get(`${BASE}/v2/carts/${sess.cartId}`, { jar, redirects: 0 });
    const etag = getHeader(re, 'ETag');
    if (etag) sess.etag = etag;
    headers['If-Match'] = sess.etag || '';
    res = http.patch(`${BASE}/v2/carts/${sess.cartId}`, JSON.stringify({ quantity: qty }), {
      jar, redirects: 0, headers,
    });
  }
  check(res, { 'cart patch 200': (r) => r.status === 200 });
  const etag = getHeader(res, 'ETag');
  if (etag) sess.etag = etag;
  try {
    const b = res.json();
    if (b && b.csrf) sess.csrf = b.csrf;
  } catch (e) { /* ignore */ }
  return res.status === 200;
}

// ---- Reservation ----
function reserveCart(jar, sess) {
  const res = authedCall(jar, sess, 'POST', '/v2/reservations', { cart_id: sess.cartId });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  if (res.status !== 202) return null;
  let statusUrl = null;
  try {
    const b = res.json();
    if (b.csrf) sess.csrf = b.csrf;
    statusUrl = b.status_url;
  } catch (e) { /* ignore */ }
  if (!statusUrl) return null;

  // Poll at least 50ms apart, at most 5 times.
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const poll = http.get(statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`, {
      jar, redirects: 0,
    });
    check(poll, { 'reservation poll 200': (r) => r.status === 200 });
    try {
      const b = poll.json();
      if (b.csrf) sess.csrf = b.csrf;
      if (b.status === 'ready' && b.reservation_id) return b.reservation_id;
      if (b.status === 'failed') return null;
    } catch (e) { /* ignore */ }
  }
  return null;
}

// ---- Order ----
function placeOrder(jar, sess, reservationId, negativeControl) {
  const t0 = Date.now();
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': sess.csrf || '',
    'Idempotency-Key': sess.idempotencyKey || `idem-${sess.cartId}`,
  };
  if (sess.etag) headers['If-Match'] = sess.etag;
  const body = { cart_id: sess.cartId };
  if (reservationId) body.reservation_id = reservationId;

  let res = http.post(`${BASE}/v2/orders`, JSON.stringify(body), { jar, redirects: 0, headers });

  // Bounded recovery: only on expiry/session, never restart checkout.
  if (res.status === 401 && (isExpired(res) || isSessionRevoked(res))) {
    if (isExpired(res)) {
      renewSession(jar, sess);
    } else {
      const fresh = doLogin(jar, sess.user || 'bench');
      if (fresh.csrf) sess.csrf = fresh.csrf;
    }
    recoverCart(jar, sess);
    headers['X-CSRF-Token'] = sess.csrf || '';
    res = http.post(`${BASE}/v2/orders`, JSON.stringify(body), { jar, redirects: 0, headers });
  }

  checkoutDuration.add(Date.now() - t0);
  recordBusiness(res);

  let accepted = false;
  let businessFailure = false;
  try {
    const b = res.json();
    if (b && b.csrf) sess.csrf = b.csrf;
    if (res.status === 201 && b && b.accepted === true) accepted = true;
    if (res.status === 200 && b && b.accepted === false) businessFailure = true;
  } catch (e) { /* ignore */ }

  if (negativeControl && negativeControl.decline_orders) {
    // Negative control: order must NOT be accepted.
    check(res, { 'negative control: order declined': () => !accepted });
    if (accepted) {
      // Negative control failed the intended check.
      journeySuccess.add(0);
      return { accepted: false, businessFailure: true, negativeControlFailed: true };
    }
    journeyBusinessFailure.add(1);
    return { accepted: false, businessFailure: true, negativeControlFailed: false };
  }

  check(res, { 'order accepted': () => accepted });
  if (accepted) {
    orderCommitted.add(1);
    journeySuccess.add(1);
    journeyBusinessFailure.add(0);
  } else if (businessFailure) {
    journeySuccess.add(0);
    journeyBusinessFailure.add(1);
  } else {
    journeySuccess.add(0);
    journeyBusinessFailure.add(0);
  }
  return { accepted, businessFailure, negativeControlFailed: false };
}

// ---- Work / browse (business responses for custom rate) ----
function doWork(jar, sess) {
  let attempts = 0;
  while (attempts < 4) {
    const res = http.post(`${BASE}/v2/work`, JSON.stringify({}), {
      jar, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf || '' },
    });
    recordBusiness(res);
    if (isScheduled429(res)) {
      sleepRetryAfter(res);
      attempts++;
      continue;
    }
    check(res, { 'work 200 ok': (r) => r.status === 200 });
    return res;
  }
  return null;
}

// ---- Journey ----
export default function () {
  const vu = __VU;
  const iter = __ITER;
  const profile = pickProfile(vu, iter);
  const negativeControl = pickNegativeControl(vu, iter);

  const jar = makeJar();
  const sess = newSession();
  const username = `bench-${((vu - 1) % 16) + 1}`;

  group('journey', () => {
    // Fresh login/cart every journey.
    const login = doLogin(jar, username);
    sess.csrf = login.csrf;
    sess.user = login.user || username;
    check(sess.csrf, { 'session csrf': (v) => !!v });

    // Catalog.
    const product = fetchCatalog(jar, sess, profile);
    check(product, { 'in-stock product found': (v) => !!v });
    if (!product) {
      journeySuccess.add(0);
      return;
    }

    // Challenge -> grant.
    const grantId = solveChallenge(jar, sess);
    sess.grantId = grantId;

    // Create cart (grant passed once).
    const created = createCart(jar, sess, product, grantId);
    if (!created) {
      journeySuccess.add(0);
      return;
    }

    // Patch quantity.
    patchCartQuantity(jar, sess, 2);

    // Reservation.
    const reservationId = reserveCart(jar, sess);
    check(reservationId, { 'reservation ready': (v) => !!v });
    if (!reservationId) {
      // pending/failed must never reach checkout.
      journeySuccess.add(0);
      return;
    }

    // Order.
    placeOrder(jar, sess, reservationId, negativeControl);

    // Business work (contributes to business_failure denominator).
    doWork(jar, sess);
  });
}
