import os
import re
import time
import uuid

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


BASE_URL = os.environ["BASE_URL"]
PASSWORD = "bench"
MAX_ITERATIONS = 2


def _csrf_from_form(html):
    if not html:
        return None
    for m in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r"""\bname\s*=\s*["']csrf["']""", tag, re.IGNORECASE):
            vm = re.search(r"""\bvalue\s*=\s*["']([^"']*)["']""", tag, re.IGNORECASE)
            if vm:
                return vm.group(1)
    return None


def _pick_product(catalog):
    data = catalog.get("data") or {}
    for prod in data.get("products") or []:
        for var in prod.get("variants") or []:
            if var.get("in_stock"):
                return prod.get("id"), var.get("id")
    return None, None


class ShopUser(HttpUser):
    host = BASE_URL
    abstract = False

    def on_start(self):
        self.iterations_done = 0
        self.username = "bench-%d" % (self.environment.runner.user_count and 0 or 0)
        # assign stable per-user account
        self.username = "bench-%d" % ((id(self) % 16) + 1)

    # ---- helpers ----
    def _login(self):
        with self.client.get("/v2/login-form", name="GET /v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return None
            csrf = _csrf_from_form(r.text)
            if not csrf:
                r.failure("login-form missing csrf")
                return None
            r.success()
        with self.client.post("/v2/login",
                              json={"username": self.username, "password": PASSWORD, "csrf": csrf},
                              name="POST /v2/login", catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("login 302 without Location")
                    return None
                r.success()
                with self.client.get(loc, name="GET /v2/login redirect",
                                     catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code != 200:
                        r2.failure("login redirect status %s" % r2.status_code)
                        return None
                    try:
                        body = r2.json()
                    except Exception:
                        r2.failure("login redirect not json")
                        return None
                    if "csrf" not in body:
                        r2.failure("login redirect missing csrf")
                        return None
                    r2.success()
                    return body["csrf"]
            if r.status_code != 200:
                r.failure("login status %s" % r.status_code)
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("login not json")
                return None
            if "csrf" not in body:
                r.failure("login missing csrf")
                return None
            r.success()
            return body["csrf"]

    def _get_catalog(self):
        with self.client.get("/v2/catalog", name="GET /v2/catalog",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("catalog status %s" % r.status_code)
                return None, None
            try:
                body = r.json()
            except Exception:
                r.failure("catalog not json")
                return None, None
            pid, vid = _pick_product(body)
            if not pid or not vid:
                r.failure("catalog no in-stock product")
                return None, None
            r.success()
            return pid, vid

    def _challenge(self, csrf):
        with self.client.get("/v2/challenge-form", name="GET /v2/challenge-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge-form status %s" % r.status_code)
                return None, csrf
            action = None
            for m in re.finditer(r"<form\b[^>]*>", r.text or "", re.IGNORECASE):
                am = re.search(r"""\baction\s*=\s*["']([^"']+)["']""", m.group(0), re.IGNORECASE)
                if am and "/v2/challenges/" in am.group(1):
                    action = am.group(1)
                    break
            if not action:
                r.failure("challenge-form missing action")
                return None, csrf
            r.success()
        with self.client.post(action, json={"challenge": "x"},
                              name="POST /v2/challenges/{id}", catch_response=True,
                              headers={"X-CSRF-Token": csrf}, allow_redirects=False) as r:
            if r.status_code != 302:
                r.failure("challenge status %s" % r.status_code)
                return None, csrf
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge 302 without Location")
                return None, csrf
            r.success()
        with self.client.get(loc, name="GET /v2/challenges redirect",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge redirect status %s" % r.status_code)
                return None, csrf
            try:
                body = r.json()
            except Exception:
                r.failure("challenge redirect not json")
                return None, csrf
            if "grant_id" not in body:
                r.failure("challenge redirect missing grant_id")
                return None, csrf
            r.success()
            return body["grant_id"], body.get("csrf", csrf)

    def _create_cart(self, csrf, pid, vid, grant):
        payload = {"product_id": pid, "variant_id": vid}
        if grant:
            payload["grant_id"] = grant
        with self.client.post("/v2/carts", json=payload, name="POST /v2/carts",
                              catch_response=True, headers={"X-CSRF-Token": csrf},
                              allow_redirects=False) as r:
            if r.status_code != 201:
                r.failure("cart status %s" % r.status_code)
                return None, None, csrf
            try:
                body = r.json()
            except Exception:
                r.failure("cart not json")
                return None, None, csrf
            if "id" not in body:
                r.failure("cart missing id")
                return None, None, csrf
            r.success()
            return body["id"], r.headers.get("ETag"), body.get("csrf", csrf)

    def _patch_quantity(self, csrf, cart_id, etag):
        payload = {"quantity": 2}
        headers = {"X-CSRF-Token": csrf, "If-Match": etag or ""}
        with self.client.patch("/v2/carts/%s" % cart_id, json=payload,
                               name="PATCH /v2/carts/{id}", catch_response=True,
                               headers=headers, allow_redirects=False) as r:
            if r.status_code == 412:
                r.success()
                with self.client.get("/v2/carts/%s" % cart_id,
                                     name="GET /v2/carts/{id}", catch_response=True,
                                     allow_redirects=False) as r2:
                    if r2.status_code != 200:
                        r2.failure("cart re-read status %s" % r2.status_code)
                        return None, csrf
                    new_etag = r2.headers.get("ETag")
                    r2.success()
                headers2 = {"X-CSRF-Token": csrf, "If-Match": new_etag or ""}
                with self.client.patch("/v2/carts/%s" % cart_id, json=payload,
                                       name="PATCH /v2/carts/{id} retry",
                                       catch_response=True, headers=headers2,
                                       allow_redirects=False) as r3:
                    if r3.status_code not in (200, 204):
                        r3.failure("cart patch retry status %s" % r3.status_code)
                        return None, csrf
                    r3.success()
                    return r3.headers.get("ETag", new_etag), csrf
            if r.status_code not in (200, 204):
                r.failure("cart patch status %s" % r.status_code)
                return None, csrf
            r.success()
            return r.headers.get("ETag", etag), csrf

    def _reserve(self, csrf, cart_id):
        with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                              name="POST /v2/reservations", catch_response=True,
                              headers={"X-CSRF-Token": csrf}, allow_redirects=False) as r:
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None, csrf
            try:
                body = r.json()
            except Exception:
                r.failure("reservation not json")
                return None, csrf
            status_url = body.get("status_url")
            csrf = body.get("csrf", csrf)
            if not status_url:
                r.failure("reservation missing status_url")
                return None, csrf
            r.success()
        reservation_id = None
        for i in range(5):
            time.sleep(0.05)
            with self.client.get(status_url, name="GET /v2/reservations status",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure("reservation status poll %s" % r.status_code)
                    return None, csrf
                try:
                    body = r.json()
                except Exception:
                    r.failure("reservation poll not json")
                    return None, csrf
                st = body.get("status")
                if st == "ready":
                    reservation_id = body.get("reservation_id")
                    if not reservation_id:
                        r.failure("reservation ready without id")
                        return None, csrf
                    r.success()
                    return reservation_id, csrf
                if st in ("pending",):
                    r.success()
                    continue
                if st in ("failed",):
                    r.failure("reservation failed")
                    return None, csrf
                r.failure("reservation unknown status %s" % st)
                return None, csrf
        return None, csrf

    def _order(self, csrf, cart_id, etag, reservation_id):
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = {"X-CSRF-Token": csrf, "Idempotency-Key": cart_id}
        if etag:
            headers["If-Match"] = etag
        with self.client.post("/v2/orders", json=payload, name="POST /v2/orders",
                              catch_response=True, headers=headers,
                              allow_redirects=False) as r:
            if r.status_code == 200:
                try:
                    body = r.json()
                except Exception:
                    r.failure("order not json")
                    return False, csrf
                if body.get("accepted") is False:
                    r.failure("order business failure accepted=false")
                    return False, csrf
                r.failure("order 200 without accepted=true")
                return False, csrf
            if r.status_code != 201:
                r.failure("order status %s" % r.status_code)
                return False, csrf
            try:
                body = r.json()
            except Exception:
                r.failure("order not json")
                return False, csrf
            if body.get("accepted") is not True:
                r.failure("order missing accepted=true")
                return False, csrf
            if "id" not in body:
                r.failure("order missing id")
                return False, csrf
            r.success()
            return True, body.get("csrf", csrf)

    # ---- journey ----
    @task
    def journey(self):
        if self.iterations_done >= MAX_ITERATIONS:
            raise StopUser()
        self.iterations_done += 1

        csrf = self._login()
        if not csrf:
            return
        pid, vid = self._get_catalog()
        if not pid:
            return
        grant, csrf = self._challenge(csrf)
        if not grant:
            return
        cart_id, etag, csrf = self._create_cart(csrf, pid, vid, grant)
        if not cart_id:
            return
        etag, csrf = self._patch_quantity(csrf, cart_id, etag)
        if etag is None:
            return
        reservation_id, csrf = self._reserve(csrf, cart_id)
        if not reservation_id:
            return
        ok, csrf = self._order(csrf, cart_id, etag, reservation_id)
        if not ok:
            return


class ShopShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 1:
            return (2, 2)
        return None
