import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableFollowRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    // ---- helpers ----

    private static String userFor(int vu) {
        return "bench-" + vu;
    }

    // ---- chains ----

    private static ChainBuilder loginForm() {
        return exec(
                http("GET /v2/login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(regex("<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>")
                                .saveAs("formCsrf"))
        );
    }

    private static ChainBuilder login() {
        return exec(session -> {
                    String user = userFor(session.userId() + 1);
                    return session.set("username", user);
                })
                .exec(
                        http("POST /v2/login")
                                .post("/v2/login")
                                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{formCsrf}\"}"))
                                .check(status().in(200, 302))
                                .check(header("Location").optional().saveAs("loginLocation"))
                                .check(bodyString().optional().saveAs("loginBody"))
                )
                .exec(session -> {
                    String loc = session.getString("loginLocation");
                    if (loc != null && !loc.isEmpty()) {
                        return session.set("loginRedirect", true);
                    }
                    return session.set("loginRedirect", false);
                })
                .doIf(session -> Boolean.TRUE.equals(session.get("loginRedirect"))).then(
                        exec(
                                http("GET login redirect")
                                        .get("#{loginLocation}")
                                        .check(status().is(200))
                                        .check(jsonPath("$.csrf").saveAs("csrf"))
                                        .check(jsonPath("$.grant_id").optional().saveAs("grant"))
                        )
                )
                .doIf(session -> !Boolean.TRUE.equals(session.get("loginRedirect"))).then(
                        exec(session -> {
                            String body = session.getString("loginBody");
                            String csrf = null;
                            if (body != null) {
                                int i = body.indexOf("\"csrf\"");
                                if (i >= 0) {
                                    int c = body.indexOf(':', i);
                                    int q1 = body.indexOf('"', c + 1);
                                    int q2 = body.indexOf('"', q1 + 1);
                                    if (q1 >= 0 && q2 > q1) {
                                        csrf = body.substring(q1 + 1, q2);
                                    }
                                }
                            }
                            return session.set("csrf", csrf);
                        })
                )
                .exec(session -> {
                    if (session.getString("csrf") == null) {
                        throw new IllegalStateException("login did not yield csrf");
                    }
                    return session;
                });
    }

    private static ChainBuilder catalog() {
        return exec(
                http("GET /v2/catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[*]").findAll().optional().saveAs("products"))
                        .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id").find().saveAs("product"))
                        .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").find().saveAs("variant"))
        );
    }

    private static ChainBuilder createCart() {
        return exec(
                http("POST /v2/carts")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\",\"grant_id\":\"#{grant}\"}"))
                        .check(status().is(201))
                        .check(jsonPath("$.id").saveAs("cart"))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                        .check(header("ETag").optional().saveAs("etag"))
        ).exec(session -> {
            String nc = session.getString("newCsrf");
            if (nc != null) {
                return session.set("csrf", nc);
            }
            return session;
        });
    }

    private static ChainBuilder placeOrder() {
        return exec(
                http("POST /v2/orders")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("Idempotency-Key", "#{cart}")
                        .header("If-Match", "#{etag}")
                        .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
                        .check(status().is(201))
                        .check(jsonPath("$.accepted").is("true"))
                        .check(jsonPath("$.id").saveAs("orderId"))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
        ).exec(session -> {
            String nc = session.getString("newCsrf");
            if (nc != null) {
                return session.set("csrf", nc);
            }
            return session;
        });
    }

    // ---- recovery (bounded, single retry) ----

    private static ChainBuilder renewSession() {
        return exec(
                http("POST /v2/session/renew")
                        .post("/v2/session/renew")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().in(200, 401))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
        ).exec(session -> {
            String nc = session.getString("newCsrf");
            if (nc != null) {
                return session.set("csrf", nc);
            }
            return session;
        });
    }

    private static ChainBuilder recoverCart() {
        return exec(
                http("POST /v2/carts/{id}/recover")
                        .post("/v2/carts/#{cart}/recover")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().in(200, 401))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
        ).exec(session -> {
            String nc = session.getString("newCsrf");
            if (nc != null) {
                return session.set("csrf", nc);
            }
            return session;
        });
    }

    // ---- scenario ----

    private static final ScenarioBuilder scn = scenario("ModelSimulation")
            .exec(session -> session
                    .set("csrf", "")
                    .set("cart", "")
                    .set("etag", "")
                    .set("grant", "")
                    .set("product", "")
                    .set("variant", ""))
            .exec(loginForm())
            .exec(login())
            .exec(catalog())
            .exec(createCart())
            .exec(placeOrder());

    {
        setUp(
                scn.injectOpen(
                        rampUsers(2).during(Duration.ofSeconds(1))
                ).protocols(httpProtocol)
        ).maxDuration(Duration.ofSeconds(120));
    }
}
