import os
import re
import time
import uuid

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

CSRF_INPUT_RE = re.compile(
    r"""<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>""",
    re.IGNORECASE,
)


def _extract_csrf_from_form(text):
    m = CSRF_INPUT_RE.search(text or "")
    return m.group(1) if m else None


class ShopUser(HttpUser):
    host = BASE_URL
    abstract = False

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._iterations_done = 0
        self._max_iterations = 2
        self._username = None

    def on_start(self):
        # Assign a stable bench account per virtual user.
        idx = (self.environment.runner.user_count if self.environment.runner else 1)
        # Use a per-instance counter derived from id to spread across bench-1..16
        try:
            n = (id(self) % 16) + 1
        except Exception:
            n = 1
        self._username = "bench-%d" % n

    # ---------- helpers ----------

    def _get_login_form(self):
        with self.client.get(
            "/v2/login-form",
            name="GET /v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure("login-form status %s" % resp.status_code)
                return None
            token = _extract_csrf_from_form(resp.text)
            if not token:
                resp.failure("login-form missing csrf")
                return None
            resp.success()
            return token

    def _login(self, form_csrf):
        payload = {
            "username": self._username,
            "password": "bench",
            "csrf": form_csrf,
        }
        with self.client.post(
            "/v2/login",
            json=payload,
            name="POST /v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code not in (200, 302):
                resp.failure("login status %s" % resp.status_code)
                return None, None
            location = resp.headers.get("Location")
            body = {}
            try:
                body = resp.json() if resp.text else {}
            except Exception:
                body = {}
            csrf = body.get("csrf") if isinstance(body, dict) else None
            if resp.status_code == 302 and location:
                resp.success()
                return csrf, location
            if not csrf:
                resp.failure("login missing csrf")
                return None, None
            resp.success()
            return csrf, None

    def _follow_location(self, location, csrf):
        with self.client.get(
            location,
            name="GET login redirect",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure("redirect status %s" % resp.status_code)
                return csrf, None
            try:
                body = resp.json()
            except Exception:
                resp.failure("redirect not json")
                return csrf, None
            new_csrf = body.get("csrf") or csrf
            grant = body.get("grant_id")
            resp.success()
            return new_csrf, grant

    def _get_catalog(self, csrf):
        headers = {"X-CSRF-Token": csrf} if csrf else {}
        with self.client.get(
            "/v2/catalog",
            name="GET /v2/catalog",
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure("catalog status %s" % resp.status_code)
                return None, None, csrf
            try:
                body = resp.json()
            except Exception:
                resp.failure("catalog not json")
                return None, None, csrf
            new_csrf = body.get("csrf") or csrf
            products = (body.get("data") or {}).get("products") or []
            for p in products:
                variants = p.get("variants") or []
                for v in variants:
                    if v.get("in_stock"):
                        resp.success()
                        return p.get("id"), v.get("id"), new_csrf
            resp.failure("no in-stock product")
            return None, None, new_csrf

    def _create_cart(self, csrf, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        headers = {"X-CSRF-Token": csrf} if csrf else {}
        with self.client.post(
            "/v2/carts",
            json=payload,
            name="POST /v2/carts",
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 201:
                resp.failure("cart status %s" % resp.status_code)
                return None, None, csrf
            try:
                body = resp.json()
            except Exception:
                resp.failure("cart not json")
                return None, None, csrf
            cart_id = body.get("id")
            new_csrf = body.get("csrf") or csrf
            if not cart_id:
                resp.failure("cart missing id")
                return None, None, new_csrf
            resp.success()
            return cart_id, resp.headers.get("ETag"), new_csrf

    def _renew_session(self, csrf):
        headers = {"X-CSRF-Token": csrf} if csrf else {}
        with self.client.post(
            "/v2/session/renew",
            json={},
            name="POST /v2/session/renew",
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure("renew status %s" % resp.status_code)
                return None
            try:
                body = resp.json()
            except Exception:
                resp.failure("renew not json")
                return None
            new_csrf = body.get("csrf") or csrf
            resp.success()
            return new_csrf

    def _recover_cart(self, csrf, cart_id):
        headers = {"X-CSRF-Token": csrf} if csrf else {}
        with self.client.post(
            "/v2/carts/%s/recover" % cart_id,
            json={},
            name="POST /v2/carts/[id]/recover",
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code not in (200, 204):
                resp.failure("recover status %s" % resp.status_code)
                return csrf
            try:
                body = resp.json() if resp.text else {}
            except Exception:
                body = {}
            new_csrf = (body.get("csrf") if isinstance(body, dict) else None) or csrf
            resp.success()
            return new_csrf

    def _place_order(self, csrf, cart_id, etag, idem_key):
        headers = {"X-CSRF-Token": csrf} if csrf else {}
        headers["Idempotency-Key"] = idem_key
        if etag:
            headers["If-Match"] = etag
        with self.client.post(
            "/v2/orders",
            json={"cart_id": cart_id},
            name="POST /v2/orders",
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                try:
                    body = resp.json()
                except Exception:
                    body = {}
                err = body.get("error") if isinstance(body, dict) else None
                if err in ("expired", "session"):
                    resp.success()
                    return "expired", csrf
                resp.failure("order 401 %s" % err)
                return "fail", csrf
            if resp.status_code != 201:
                resp.failure("order status %s" % resp.status_code)
                return "fail", csrf
            try:
                body = resp.json()
            except Exception:
                resp.failure("order not json")
                return "fail", csrf
            if not body.get("accepted"):
                resp.failure("order not accepted")
                return "fail", csrf
            new_csrf = body.get("csrf") or csrf
            resp.success()
            return "ok", new_csrf

    # ---------- journey ----------

    @task
    def journey(self):
        if self._iterations_done >= self._max_iterations:
            raise StopUser()

        # Fresh login/cart each journey.
        form_csrf = self._get_login_form()
        if not form_csrf:
            self._iterations_done += 1
            if self._iterations_done >= self._max_iterations:
                raise StopUser()
            return

        csrf, location = self._login(form_csrf)
        grant_id = None
        if location:
            csrf, grant_id = self._follow_location(location, csrf)
        if not csrf:
            self._iterations_done += 1
            if self._iterations_done >= self._max_iterations:
                raise StopUser()
            return

        product_id, variant_id, csrf = self._get_catalog(csrf)
        if not product_id or not variant_id:
            self._iterations_done += 1
            if self._iterations_done >= self._max_iterations:
                raise StopUser()
            return

        cart_id, etag, csrf = self._create_cart(csrf, product_id, variant_id, grant_id)
        if not cart_id:
            self._iterations_done += 1
            if self._iterations_done >= self._max_iterations:
                raise StopUser()
            return

        idem_key = "idem-%s" % uuid.uuid4().hex

        # Attempt order; on expiry, renew + recover + retry once.
        status, csrf = self._place_order(csrf, cart_id, etag, idem_key)
        if status == "expired":
            new_csrf = self._renew_session(csrf)
            if new_csrf:
                csrf = new_csrf
            csrf = self._recover_cart(csrf, cart_id)
            status, csrf = self._place_order(csrf, cart_id, etag, idem_key)

        self._iterations_done += 1
        if self._iterations_done >= self._max_iterations:
            raise StopUser()


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._start = None
        self._done = False

    def tick(self):
        if self._done:
            return None
        if self._start is None:
            self._start = time.time()
        # 2 users, 2 iterations each; stop once users have finished.
        runner = self.runner
        if runner is not None:
            try:
                total = runner.stats.total
                if total.num_requests > 0 and runner.user_count == 0:
                    self._done = True
                    return None
            except Exception:
                pass
        return (2, 2)
