// Use ramping-arrival-rate to hit phased targets. Pre-allocate enough VUs for 15/s peak.
export const options = {
  scenarios: {
    work: {
      executor: 'ramping-arrival-rate',
      startRate: 5,
      timeUnit: '1s',
      preAllocatedVUs: 16,
      maxVUs: 32,
      stages: [
        {target: 5, duration: '5s'},   // warmup
        {target: 5, duration: '10s'},  // plateau 1
        {target: 15, duration: '10s'}, // plateau 2
        {target: 5, duration: '10s'},  // plateau 3
        {target: 0, duration: '5s'}    // drain
      ],
      gracefulStop: '5s'
    }
  },
  thresholds: {
    checks: ['rate>=0.99'],
    business_failure: ['rate<0.01']
  },
  noCookiesReset: true
};

let csrf = '', cart = '', grant = '';
const base = __ENV.BASE_URL || 'http://127.0.0.1:8000';

function body(r) { try { return r.json(); } catch (_) { return {}; } }

function raw(path, method='GET', data=null, extra={}) {
  const r = http.request(method, base + path, data===null ? null : JSON.stringify(data), {
    headers: Object.assign({'Content-Type':'application/json','X-CSRF-Token':csrf}, extra),
    redirects: 0, timeout: '3s'
  });
