import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "name\\s*=\\s*[\"']csrf[\"'][^>]*value\\s*=\\s*[\"']([^\"']+)[\"']|value\\s*=\\s*[\"']([^\"']+)[\"'][^>]*name\\s*=\\s*[\"']csrf[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_INPUT = Pattern.compile(
            "name\\s*=\\s*[\"']challenge[\"'][^>]*value\\s*=\\s*[\"']([^\"']+)[\"']|value\\s*=\\s*[\"']([^\"']+)[\"'][^>]*name\\s*=\\s*[\"']challenge[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern ACTION_ATTR = Pattern.compile(
            "action\\s*=\\s*[\"']([^\"']+)[\"']", Pattern.CASE_INSENSITIVE);

    private static String pick(Matcher m) {
        if (m.find()) {
            return m.group(1) != null ? m.group(1) : m.group(2);
        }
        return null;
    }

    private static String extractCsrf(String body) {
        if (body == null) return null;
        return pick(CSRF_INPUT.matcher(body));
    }

    private static String extractChallenge(String body) {
        if (body == null) return null;
        return pick(CHALLENGE_INPUT.matcher(body));
    }

    private static String extractAction(String body) {
        if (body == null) return null;
        Matcher m = ACTION_ATTR.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String jsonStr(String body, String key) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String jsonNum(String body, String key) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(-?\\d+)");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static boolean jsonBool(String body, String key) {
        if (body == null) return false;
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(true|false)");
        Matcher m = p.matcher(body);
        if (m.find()) return "true".equals(m.group(1));
        return false;
    }

    private static String firstProductId(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"products\"\\s*:\\s*\\[\\s*\\{[^}]*?\"id\"\\s*:\\s*\"?([A-Za-z0-9_\\-]+)\"?");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String firstVariantId(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"variants\"\\s*:\\s*\\[\\s*\\{[^}]*?\"id\"\\s*:\\s*\"?([A-Za-z0-9_\\-]+)\"?");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String firstInStockVariant(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"variants\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher m = p.matcher(body);
        if (!m.find()) return null;
        String variants = m.group(1);
        Pattern v = Pattern.compile("\\{[^{}]*\"id\"\\s*:\\s*\"?([A-Za-z0-9_\\-]+)\"?[^{}]*\"in_stock\"\\s*:\\s*(true|false)[^{}]*\\}");
        Matcher vm = v.matcher(variants);
        while (vm.find()) {
            if ("true".equals(vm.group(2))) return vm.group(1);
        }
        return null;
    }

    private static String nextLink(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"next\"\\s*:\\s*\"([^\"]+)\"");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String etagOf(String header) {
        return header;
    }

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-model-sim");

    private static final String[] USERS = new String[]{
            "bench-1", "bench-2", "bench-3", "bench-4", "bench-5", "bench-6", "bench-7", "bench-8",
            "bench-9", "bench-10", "bench-11", "bench-12", "bench-13", "bench-14", "bench-15", "bench-16"
    };

    private static String userFor(int i) {
        return USERS[i % USERS.length];
    }

    private static ChainBuilder loginFlow(String user) {
        return exec(
                http("login-form")
                        .get("/v2/login-form")
                        .check(status().lt(400))
                        .check(bodyString().saveAs("loginFormBody"))
        ).exec(session -> {
            String csrf = extractCsrf(session.getString("loginFormBody"));
            return session.set("csrf", csrf == null ? "" : csrf);
        }).exec(
                http("login")
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String csrf = session.getString("csrf");
                            return "{\"username\":\"" + user + "\",\"password\":\"bench\",\"csrf\":\"" + csrf + "\"}";
                        }))
                        .check(status().in(200, 201, 302))
                        .check(bodyString().saveAs("loginBody"))
                        .check(header("Location").optional().saveAs("loginLocation"))
        ).exec(session -> {
            String body = session.getString("loginBody");
            String csrf = jsonStr(body, "csrf");
            if (csrf == null) csrf = session.getString("csrf");
            return session.set("csrf", csrf == null ? "" : csrf);
        }).exec(session -> {
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginRedirect", loc);
            }
            return session;
        }).doIf(session -> session.getString("loginRedirect") != null).then(
                exec(
                        http("login-redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().lt(400))
                                .check(bodyString().saveAs("loginRedirectBody"))
                ).exec(session -> {
                    String body = session.getString("loginRedirectBody");
                    String csrf = jsonStr(body, "csrf");
                    if (csrf != null) return session.set("csrf", csrf);
                    return session;
                })
        );
    }

    private static ChainBuilder catalogFlow() {
        return exec(
                http("catalog")
                        .get("/v2/catalog")
                        .check(status().lt(400))
                        .check(bodyString().saveAs("catalogBody"))
        ).exec(session -> {
            String body = session.getString("catalogBody");
            String pid = firstProductId(body);
            String vid = firstInStockVariant(body);
            if (vid == null) vid = firstVariantId(body);
            return session.set("productId", pid == null ? "" : pid)
                    .set("variantId", vid == null ? "" : vid);
        });
    }

    private static ChainBuilder challengeFlow() {
        return exec(
                http("challenge-form")
                        .get("/v2/challenge-form")
                        .check(status().lt(400))
                        .check(bodyString().saveAs("challengeFormBody"))
        ).exec(session -> {
            String body = session.getString("challengeFormBody");
            String action = extractAction(body);
            String challenge = extractChallenge(body);
            return session.set("challengeAction", action == null ? "" : action)
                    .set("challengeValue", challenge == null ? "" : challenge);
        }).exec(
                http("challenge-submit")
                        .post(session -> session.getString("challengeAction"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> "{\"challenge\":\"" + session.getString("challengeValue") + "\"}"))
                        .check(status().in(200, 201, 302))
                        .check(header("Location").optional().saveAs("challengeLocation"))
        ).exec(session -> {
            String loc = session.getString("challengeLocation");
            return session.set("challengeRedirect", loc == null ? "" : loc);
        }).doIf(session -> !session.getString("challengeRedirect").isEmpty()).then(
                exec(
                        http("challenge-claim")
                                .get(session -> session.getString("challengeRedirect"))
                                .check(status().lt(400))
                                .check(bodyString().saveAs("challengeClaimBody"))
                ).exec(session -> {
                    String body = session.getString("challengeClaimBody");
                    String grant = jsonStr(body, "grant_id");
                    String csrf = jsonStr(body, "csrf");
                    Session s = session.set("grantId", grant == null ? "" : grant);
                    if (csrf != null) s = s.set("csrf", csrf);
                    return s;
                })
        );
    }

    private static ChainBuilder cartFlow() {
        return exec(
                http("cart-create")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> {
                            String pid = session.getString("productId");
                            String vid = session.getString("variantId");
                            String grant = session.getString("grantId");
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"product_id\":\"").append(pid).append("\",\"variant_id\":\"").append(vid).append("\"");
                            if (grant != null && !grant.isEmpty()) {
                                sb.append(",\"grant_id\":\"").append(grant).append("\"");
                            }
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().in(200, 201))
                        .check(bodyString().saveAs("cartBody"))
                        .check(header("ETag").optional().saveAs("cartEtag"))
        ).exec(session -> {
            String body = session.getString("cartBody");
            String id = jsonStr(body, "id");
            String csrf = jsonStr(body, "csrf");
            Session s = session.set("cartId", id == null ? "" : id);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        });
    }

    private static ChainBuilder cartPatchFlow() {
        return exec(
                http("cart-get")
                        .get(session -> "/v2/carts/" + session.getString("cartId"))
                        .check(status().lt(400))
                        .check(header("ETag").optional().saveAs("cartEtag"))
        ).exec(
                http("cart-patch")
                        .patch(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> {
                            String e = session.getString("cartEtag");
                            return e == null ? "*" : e;
                        })
                        .body(StringBody("{\"quantity\":1}"))
                        .check(status().in(200, 204, 412))
        ).doIf(session -> {
            Integer st = session.getInt("cartPatchStatus");
            return st != null && st == 412;
        }).then(
                exec(
                        http("cart-get-retry")
                                .get(session -> "/v2/carts/" + session.getString("cartId"))
                                .check(status().lt(400))
                                .check(header("ETag").optional().saveAs("cartEtag"))
                ).exec(
                        http("cart-patch-retry")
                                .patch(session -> "/v2/carts/" + session.getString("cartId"))
                                .header("X-CSRF-Token", session -> session.getString("csrf"))
                                .header("If-Match", session -> {
                                    String e = session.getString("cartEtag");
                                    return e == null ? "*" : e;
                                })
                                .body(StringBody("{\"quantity\":1}"))
                                .check(status().in(200, 204))
                )
        );
    }

    private static ChainBuilder reservationFlow() {
        return exec(
                http("reservation-create")
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                        .check(status().in(200, 201, 202))
                        .check(bodyString().saveAs("reservationBody"))
        ).exec(session -> {
            String body = session.getString("reservationBody");
            String statusUrl = jsonStr(body, "status_url");
            String csrf = jsonStr(body, "csrf");
            Session s = session.set("statusUrl", statusUrl == null ? "" : statusUrl);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        }).asLongAs(session -> {
            Integer polls = session.getInt("pollCount");
            return polls == null || polls < 5;
        }).on(
                pause(Duration.ofMillis(60)).exec(
                        http("reservation-poll")
                                .get(session -> session.getString("statusUrl"))
                                .check(status().lt(400))
                                .check(bodyString().saveAs("pollBody"))
                ).exec(session -> {
                    String body = session.getString("pollBody");
                    String status = jsonStr(body, "status");
                    String rid = jsonStr(body, "reservation_id");
                    Integer polls = session.getInt("pollCount");
                    int p = polls == null ? 1 : polls + 1;
                    Session s = session.set("pollCount", p);
                    if ("ready".equals(status) && rid != null) {
                        s = s.set("reservationId", rid).set("reservationReady", true);
                    }
                    return s;
                })
        );
    }

    private static ChainBuilder orderFlow() {
        return exec(
                http("order-create")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                        .header("If-Match", session -> {
                            String e = session.getString("cartEtag");
                            return e == null ? "*" : e;
                        })
                        .body(StringBody(session -> {
                            String rid = session.getString("reservationId");
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"cart_id\":\"").append(session.getString("cartId")).append("\"");
                            if (rid != null && !rid.isEmpty()) {
                                sb.append(",\"reservation_id\":\"").append(rid).append("\"");
                            }
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().in(200, 201))
                        .check(bodyString().saveAs("orderBody"))
        ).exec(session -> {
            String body = session.getString("orderBody");
            boolean accepted = jsonBool(body, "accepted");
            String csrf = jsonStr(body, "csrf");
            Session s = session.set("orderAccepted", accepted);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        });
    }

    private static ChainBuilder workFlow() {
        return asLongAs(session -> {
            Integer retries = session.getInt("workRetries");
            return retries == null || retries < 4;
        }).on(
                exec(
                        http("work")
                                .post("/v2/work")
                                .header("X-CSRF-Token", session -> session.getString("csrf"))
                                .body(StringBody("{}"))
                                .check(status().in(200, 429))
                                .check(bodyString().saveAs("workBody"))
                                .check(header("Retry-After").optional().saveAs("retryAfter"))
                ).exec(session -> {
                    Integer retries = session.getInt("workRetries");
                    int r = retries == null ? 0 : retries;
                    return session.set("workRetries", r + 1);
                }).doIf(session -> {
                    Integer retries = session.getInt("workRetries");
                    return retries != null && retries < 4;
                }).then(
                        pause(Duration.ofMillis(1000))
                )
        );
    }

    private static ChainBuilder journey(int idx) {
        String user = userFor(idx);
        return exec(session -> session.set("user", user))
                .exec(loginFlow(user))
                .exec(catalogFlow())
                .exec(challengeFlow())
                .exec(cartFlow())
                .exec(cartPatchFlow())
                .exec(reservationFlow())
                .exec(orderFlow())
                .exec(workFlow());
    }

    private static final ScenarioBuilder SCENARIO = scenario("ModelSimulation")
            .exec(session -> session.set("csrf", ""))
            .exec(journey(0))
            .exec(journey(1));

    {
        setUp(
                SCENARIO.injectOpen(
                        atOnceUsers(2)
                )
        ).protocols(HTTP)
                .maxDuration(Duration.ofSeconds(60));
    }
}
