```javascript
import http from 'k6/http';
import { check } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workStarts = new Counter('work_starts');
const workOk = new Counter('work_ok');
const workUnexpected = new Counter('work_unexpected');
const workScheduled = new Counter('work_scheduled');
const workExpiry = new Counter('work_expiry');
const businessResponses = new Counter('business_responses');
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 8,
      maxVUs: 32,
      exec: 'workFlow',
    },
  },
  thresholds: {
    'business_failure': ['rate<0.01'],
  },
  discardResponseBodies: false,
};

function parseCsrf(html) {
  if (!html) return null;
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  // fallback: value before name
  const re2 = /<input\b[^>]*\bvalue\s*=\s*["']([^"']*)["'][^>]*\bname\s*=\s*["']?csrf["']?/gi;
  while ((m = re2.exec(html)) !== null) {
    return m[1];
  }
  return null;
}

function getCookie(jar, name) {
  const cookies = jar.cookiesForURL(BASE);
  const v = cookies[name];
  if (!v) return null;
  return Array.isArray(v) ? v[0] : v;
}

function login(jar) {
  const formRes = http.get(`${BASE}/v2/login-form`, { jar, redirects: 0 });
  if (formRes.status !== 200) return null;
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: 'bench-1', password: 'bench', csrf }),
    { jar, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar, redirects: 0 });
      if (follow.status >= 400) return null;
    }
  } else if (loginRes.status >= 400) {
    return null;
  }
  let body = null;
  try { body = loginRes.json(); } catch (e) { body = null; }
  const token = (body && body.csrf) || csrf;
  return { csrf: token };
}

function renew(jar, csrf) {
  const r = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  if (r.status >= 400) return null;
  let body = null;
  try { body = r.json(); } catch (e) { body = null; }
  return { csrf: (body && body.csrf) || csrf };
}

function doWork(jar, csrf) {
  let token = csrf;
  let attempts = 0;
  let scheduledRetries = 0;
  while (attempts < 6) {
    attempts++;
    const res = http.post(`${BASE}/v2/work`, JSON.stringify({}), {
      jar,
      redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
      tags: { op: 'work' },
    });
    businessResponses.add(1);
    if (res.status === 429) {
      workScheduled.add(1);
      scheduledRetries++;
      if (scheduledRetries > 4) {
        workUnexpected.add(1);
        businessFailure.add(true);
        return { ok: false };
      }
      const ra = res.headers['Retry-After'] || res.headers['retry-after'];
      let wait = 1;
      if (ra) {
        const n = parseFloat(ra);
        if (!isNaN(n)) wait = n;
      }
      // sleep via busy wait not available; use http.batch trick? use sleep
      // k6 sleep
      // eslint-disable-next-line no-undef
      // import sleep
      sleepSec(wait);
      continue;
    }
    if (res.status === 401) {
      let err = null;
      try { err = res.json(); } catch (e) { err = null; }
      const code = err && err.error;
      if (code === 'expired') {
        workExpiry.add(1);
        const rn = renew(jar, token);
        if (!rn) {
          workUnexpected.add(1);
          businessFailure.add(true);
          return { ok: false };
        }
        token = rn.csrf;
        continue;
      }
      // session revoked or denied
      workUnexpected.add(1);
      businessFailure.add(true);
      return { ok: false };
    }
    if (res.status >= 400) {
      workUnexpected.add(1);
      businessFailure.add(true);
      return { ok: false };
    }
    // success
    let body = null;
    try { body = res.json(); } catch (e) { body = null; }
    if (body && body.csrf) token = body.csrf;
    if (body && body.ok === true) {
      workOk.add(1);
      businessFailure.add(false);
      return { ok: true, csrf: token };
    }
    workUnexpected.add(1);
    businessFailure.add(true);
    return { ok: false };
  }
  workUnexpected.add(1);
  businessFailure.add(true);
  return { ok: false };
}

// minimal sleep helper using Date busy loop is bad; use k6 sleep
import { sleep } from 'k6';
function sleepSec(s) { sleep(s); }

export function workFlow() {
  const jar = http.cookieJar();
  const auth = login(jar);
  if (!auth) {
    businessFailure.add(true);
    return;
  }
  workStarts.add(1);
  doWork(jar, auth.csrf);
}

export default function () {
  workFlow();
}
