import os
import re
import time
import uuid
import random
from urllib.parse import urljoin

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
PASSWORD = "bench"


def _abs(path):
    return urljoin(BASE_URL, path)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf = None
        self.username = None
        self.iterations_done = 0
        self.max_iterations = 2

    # ---------- helpers ----------
    def _extract_csrf(self, text):
        # input[name=csrf] mixed with decoys/attribute variants
        m = re.search(
            r'<input[^>]*name\s*=\s*["\']?csrf["\']?[^>]*value\s*=\s*["\']([^"\']+)["\']',
            text,
            re.IGNORECASE,
        )
        if not m:
            m = re.search(
                r'<input[^>]*value\s*=\s*["\']([^"\']+)["\'][^>]*name\s*=\s*["\']?csrf["\']?',
                text,
                re.IGNORECASE,
            )
        return m.group(1) if m else None

    def _login(self):
        self.username = "bench-%d" % random.randint(1, 16)
        with self.client.get(
            "/v2/login-form", name="GET /v2/login-form", catch_response=True
        ) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = self._extract_csrf(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return False
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": PASSWORD, "csrf": csrf},
            name="POST /v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(
                    loc, name="GET login redirect", catch_response=True
                ) as r2:
                    if r2.status_code >= 400:
                        r2.failure("redirect status %s" % r2.status_code)
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        data = {}
                    self.csrf = data.get("csrf") or self.csrf
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    data = {}
                self.csrf = data.get("csrf") or self.csrf
            else:
                r.failure("login status %s" % r.status_code)
                return False
        if not self.csrf:
            return False
        return True

    def _renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            name="POST /v2/session/renew",
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    data = {}
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            return False

    def _work(self):
        headers = {"X-CSRF-Token": self.csrf or ""}
        attempts = 0
        while attempts < 5:
            attempts += 1
            with self.client.post(
                "/v2/work",
                json={},
                headers=headers,
                name="POST /v2/work",
                catch_response=True,
            ) as r:
                if r.status_code == 200:
                    try:
                        data = r.json()
                    except Exception:
                        r.failure("work non-json")
                        return False
                    if data.get("ok") is True:
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        return True
                    r.failure("work ok!=true")
                    return False
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    r.success()
                    time.sleep(max(0.05, delay))
                    continue
                if r.status_code == 401:
                    try:
                        err = r.json().get("error")
                    except Exception:
                        err = None
                    if err == "expired":
                        r.success()
                        if self._renew():
                            headers = {"X-CSRF-Token": self.csrf or ""}
                            continue
                        return False
                    if err == "session":
                        r.success()
                        if self._login():
                            headers = {"X-CSRF-Token": self.csrf or ""}
                            continue
                        return False
                    r.failure("401 denied")
                    return False
                if r.status_code >= 500:
                    r.failure("work status %s" % r.status_code)
                    return False
                r.failure("work status %s" % r.status_code)
                return False
        return False

    # ---------- task ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        if not self._login():
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        ok = self._work()
        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class PhasedShape(LoadTestShape):
    # Phased targets 5/15/5 over three 10s plateaus, warmup 5s, drain <=5s.
    # Total: warmup 5s + 30s scored + drain 5s = 40s
    def tick(self):
        t = self.get_run_time()
        if t < 5:
            return (2, 2)
        if t < 15:
            return (5, 5)
        if t < 25:
            return (15, 15)
        if t < 35:
            return (5, 5)
        if t < 40:
            return (1, 1)
        return None
