import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "name=[\"']csrf[\"'][^>]*value=[\"']([^\"']+)[\"']|value=[\"']([^\"']+)[\"'][^>]*name=[\"']csrf[\"']");
    private static final Pattern CHALLENGE_INPUT = Pattern.compile(
            "name=[\"']challenge[\"'][^>]*value=[\"']([^\"']+)[\"']|value=[\"']([^\"']+)[\"'][^>]*name=[\"']challenge[\"']");
    private static final Pattern CHALLENGE_ACTION = Pattern.compile("action=[\"']([^\"']*?/v2/challenges/[^\"']+)[\"']");

    private static String firstGroup(Matcher m) {
        if (m.find()) {
            return m.group(1) != null ? m.group(1) : m.group(2);
        }
        return null;
    }

    private static String extractCsrf(String body) {
        if (body == null) return null;
        return firstGroup(CSRF_INPUT.matcher(body));
    }

    private static String extractChallenge(String body) {
        if (body == null) return null;
        return firstGroup(CHALLENGE_INPUT.matcher(body));
    }

    private static String extractChallengeAction(String body) {
        if (body == null) return null;
        Matcher m = CHALLENGE_ACTION.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String jsonField(String body, String field) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(field) + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String jsonRawField(String body, String field) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(field) + "\"\\s*:\\s*([^,}\\]]+)");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1).trim();
        return null;
    }

    private static boolean jsonBool(String body, String field) {
        String raw = jsonRawField(body, field);
        return raw != null && raw.equals("true");
    }

    private static String pickAccount() {
        int n = ThreadLocalRandom.current().nextInt(16) + 1;
        return "bench-" + n;
    }

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableCaching()
            .disableFollowRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json");

    // ---------- Chains ----------

    private static ChainBuilder login() {
        return exec(session -> session.set("username", pickAccount()))
                .exec(http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginFormBody")))
                .exec(session -> {
                    String csrf = extractCsrf(session.getString("loginFormBody"));
                    return session.set("csrf", csrf);
                })
                .exec(http("login")
                        .post("/v2/login")
                        .body(StringBody(session ->
                                "{\"username\":\"" + session.getString("username") +
                                        "\",\"password\":\"bench\",\"csrf\":\"" + session.getString("csrf") + "\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginBody")))
                .exec(session -> {
                    String loc = session.getString("loginLocation");
                    if (loc != null && !loc.isEmpty()) {
                        return session.set("loginRedirect", loc);
                    }
                    return session;
                })
                .doIf(session -> session.getString("loginRedirect") != null).then(
                        exec(http("login-redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("loginBody2")))
                                .exec(session -> {
                                    String csrf = jsonField(session.getString("loginBody2"), "csrf");
                                    if (csrf == null) csrf = extractCsrf(session.getString("loginBody2"));
                                    return session.set("csrf", csrf);
                                })
                )
                .doIf(session -> session.getString("loginRedirect") == null).then(
                        exec(session -> {
                            String csrf = jsonField(session.getString("loginBody"), "csrf");
                            if (csrf == null) csrf = extractCsrf(session.getString("loginBody"));
                            return session.set("csrf", csrf);
                        })
                );
    }

    private static ChainBuilder renew() {
        return exec(http("renew")
                .post("/v2/session/renew")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody("{}"))
                .check(status().in(200, 401))
                .check(bodyString().optional().saveAs("renewBody")))
                .exec(session -> {
                    String csrf = jsonField(session.getString("renewBody"), "csrf");
                    if (csrf != null) return session.set("csrf", csrf);
                    return session;
                });
    }

    private static ChainBuilder recoverCart() {
        return doIf(session -> session.getString("cartId") != null).then(
                exec(http("cart-recover")
                        .post(session -> "/v2/carts/" + session.getString("cartId") + "/recover")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 401, 404))
                        .check(bodyString().optional().saveAs("recoverBody")))
                        .exec(session -> {
                            String csrf = jsonField(session.getString("recoverBody"), "csrf");
                            if (csrf != null) return session.set("csrf", csrf);
                            return session;
