                        .body(StringBody(session ->
                                "{\"challenge\":\"" + session.getString("challengeValue") + "\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("challengeLocation"))
                        .check(bodyString().optional().saveAs("challengeBody")))
                .exec(session -> {
                    String loc = session.getString("challengeLocation");
                    if (loc != null && !loc.isEmpty()) return session.set("challengeRedirect", loc);
                    return session;
                })
                .doIf(session -> session.getString("challengeRedirect") != null).then(
                        exec(http("challenge-redirect")
                                .get(session -> session.getString("challengeRedirect"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("challengeResultBody")))
                                .exec(session -> {
                                    String body = session.getString("challengeResultBody");
                                    String grant = jsonField(body, "grant_id");
                                    String csrf = jsonField(body, "csrf");
                                    Session s = session.set("grantId", grant);
                                    if (csrf != null) s = s.set("csrf", csrf);
                                    return s;
                                })
                )
                .doIf(session -> session.getString("challengeRedirect") == null).then(
                        exec(session -> {
                            String body = session.getString("challengeBody");
                            String grant = jsonField(body, "grant_id");
                            String csrf = jsonField(body, "csrf");
                            Session s = session.set("grantId", grant);
