```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workStarts = new Counter('work_starts');
const workOk = new Counter('work_ok');
const workUnexpected = new Counter('work_unexpected');
const workScheduled = new Counter('work_scheduled');
const workDropped = new Counter('work_dropped');
const workLatency = new Trend('work_latency');
const bizFailRate = new Rate('business_failure');

const USERS = ['bench-1', 'bench-2', 'bench-3', 'bench-4', 'bench-5', 'bench-6', 'bench-7', 'bench-8',
  'bench-9', 'bench-10', 'bench-11', 'bench-12', 'bench-13', 'bench-14', 'bench-15', 'bench-16', 'bench'];

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 8,
      maxVUs: 32,
      exec: 'workFlow',
    },
  },
  thresholds: {
    'work_ok': ['count>0'],
  },
  discardResponseBodies: false,
};

function jarFor(user) {
  return http.cookieJar();
}

function parseCsrfFromForm(body) {
  // find input[name=csrf] value, tolerate attribute variants
  const re = /<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = body.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function login(user) {
  const jar = http.cookieJar();
  const formRes = http.get(`${BASE}/v2/login-form`, { jar, tags: { name: 'login-form' } });
  if (formRes.status !== 200) return null;
  const csrf = parseCsrfFromForm(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({ username: user, password: 'bench', csrf }), {
    jar,
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });
  let body = loginRes.body;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const r2 = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar, tags: { name: 'login-redirect' } });
      body = r2.body;
    }
  }
  let token = null;
  try {
    const j = JSON.parse(body);
    token = j.csrf;
  } catch (e) {
    token = parseCsrfFromForm(body || '');
  }
  return token;
}

function renew(jar, csrf) {
  const r = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'renew' },
  });
  let newCsrf = csrf;
  try {
    const j = JSON.parse(r.body);
    if (j.csrf) newCsrf = j.csrf;
  } catch (e) {}
  return { status: r.status, csrf: newCsrf, body: r.body };
}

function doWork(jar, csrf) {
  let token = csrf;
  let attempts = 0;
  let scheduledRetries = 0;
  while (attempts < 2) {
    attempts++;
    const res = http.post(`${BASE}/v2/work`, JSON.stringify({}), {
      jar,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
      tags: { name: 'work' },
    });
    workLatency.add(res.timings.duration);
    if (res.status === 401) {
      let err = null;
      try { err = JSON.parse(res.body).error; } catch (e) {}
      if (err === 'expired') {
        const rn = renew(jar, token);
        token = rn.csrf;
        continue;
      }
      if (err === 'denied') {
        bizFailRate.add(true);
        return { ok: false, status: res.status };
      }
      // session revoked -> re-login
      return { ok: false, status: res.status, relogin: true };
    }
    if (res.status === 429) {
      workScheduled.add(1);
      const ra = parseInt(res.headers['Retry-After'] || '1', 10);
      if (scheduledRetries < 4) {
        scheduledRetries++;
        sleep(Math.max(ra, 1));
        continue;
      }
      workDropped.add(1);
      return { ok: false, status: 429 };
    }
    if (res.status >= 500) {
      workUnexpected.add(1);
      bizFailRate.add(true);
      return { ok: false, status: res.status };
    }
    if (res.status >= 400) {
      bizFailRate.add(true);
      return { ok: false, status: res.status };
    }
    let ok = false;
    try { ok = JSON.parse(res.body).ok === true; } catch (e) {}
    if (ok) {
      workOk.add(1);
      bizFailRate.add(false);
      return { ok: true, status: res.status, csrf: token };
    }
    bizFailRate.add(true);
    return { ok: false, status: res.status };
  }
  workDropped.add(1);
  return { ok: false, status: 0 };
}

export function workFlow() {
  const user = USERS[(__VU - 1) % USERS.length];
  const jar = http.cookieJar();
  let csrf = login(user);
  if (!csrf) {
    workDropped.add(1);
    return;
  }
  workStarts.add(1);
  const r = doWork(jar, csrf);
  if (r.relogin) {
    const c2 = login(user);
    if (c2) doWork(jar, c2);
  }
  check(r, { 'work ok': (v) => v.ok === true });
}

export default function () {
  workFlow();
}
