import os
import re
import time
import uuid
import random
from urllib.parse import urljoin

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
PASSWORD = "bench"
USERS = ["bench-1", "bench-2", "bench-3", "bench-4", "bench-5", "bench-6",
         "bench-7", "bench-8", "bench-9", "bench-10", "bench-11", "bench-12",
         "bench-13", "bench-14", "bench-15", "bench-16", "bench"]

CSRF_INPUT_RE = re.compile(
    r'<input[^>]*name=["\']csrf["\'][^>]*>', re.IGNORECASE)
VALUE_RE = re.compile(r'value=["\']([^"\']*)["\']', re.IGNORECASE)
ACTION_RE = re.compile(r'action=["\']([^"\']*)["\']', re.IGNORECASE)
CHALLENGE_INPUT_RE = re.compile(
    r'<input[^>]*name=["\']challenge["\'][^>]*>', re.IGNORECASE)


def extract_csrf(html):
    m = CSRF_INPUT_RE.search(html or "")
    if not m:
        return None
    v = VALUE_RE.search(m.group(0))
    return v.group(1) if v else None


def extract_challenge(html):
    m = CHALLENGE_INPUT_RE.search(html or "")
    if not m:
        return None
    v = VALUE_RE.search(m.group(0))
    return v.group(1) if v else None


def extract_action(html):
    m = ACTION_RE.search(html or "")
    return m.group(1) if m else None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def on_start(self):
        self.username = random.choice(USERS)
        self.csrf = None
        self.session_ok = False
        self.iterations_done = 0
        self.max_iterations = 2
        self._login()

    # ---------- auth ----------
    def _login(self):
        with self.client.get("/v2/login-form", name="GET /v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return
            csrf = extract_csrf(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return
        payload = {"username": self.username, "password": PASSWORD, "csrf": csrf}
        with self.client.post("/v2/login", json=payload, name="POST /v2/login",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return
                with self.client.get(loc, name="GET login redirect",
                                     catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure("redirect status %s" % r2.status_code)
                        return
                    body = r2.json() if r2.text else {}
                    self.csrf = body.get("csrf") or csrf
                    self.session_ok = True
            elif r.status_code == 200:
                body = r.json() if r.text else {}
                self.csrf = body.get("csrf") or csrf
                self.session_ok = True
            else:
                r.failure("login status %s" % r.status_code)

    def _renew(self):
        with self.client.post("/v2/session/renew", json={},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              name="POST /v2/session/renew",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 200:
                body = r.json() if r.text else {}
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return True
            return False

    def _fresh_login(self):
        self.session_ok = False
        self._login()
        return self.session_ok

    def _auth_headers(self, extra=None):
        h = {"X-CSRF-Token": self.csrf or ""}
        if extra:
            h.update(extra)
        return h

    # ---------- catalog ----------
    def _get_catalog(self):
        with self.client.get("/v2/catalog", name="GET /v2/catalog",
                             catch_response=True) as r:
            if r.status_code != 200:
                r.failure("catalog status %s" % r.status_code)
                return None
            try:
                return r.json()
            except Exception:
                r.failure("catalog not json")
                return None

    def _pick_product(self, catalog):
        try:
            products = catalog["data"]["products"]
        except Exception:
            return None
        for p in products:
            for v in p.get("variants", []):
                if v.get("in_stock"):
                    return p["id"], v["id"]
        return None

    # ---------- cart ----------
    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload,
                              headers=self._auth_headers(),
                              name="POST /v2/carts",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                body = {}
                try:
                    body = r.json()
                except Exception:
                    pass
                if body.get("error") == "expired":
                    r.success()
                    if self._renew():
                        return self._create_cart(product_id, variant_id, grant_id)
                    if self._fresh_login():
                        return self._create_cart(product_id, variant_id, grant_id)
                    return None
                r.failure("401 %s" % body.get("error"))
                return None
            if r.status_code != 201:
                r.failure("cart status %s" % r.status_code)
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("cart not json")
                return None
            if body.get("csrf"):
                self.csrf = body["csrf"]
            return body.get("id"), r.headers.get("ETag")

    def _patch_cart(self, cart_id, etag, quantity):
        headers = self._auth_headers({"If-Match": etag or ""})
        with self.client.patch("/v2/carts/%s" % cart_id,
                               json={"quantity": quantity},
                               headers=headers,
                               name="PATCH /v2/carts/{id}",
                               catch_response=True, allow_redirects=False) as r:
            if r.status_code == 412:
                r.success()
                with self.client.get("/v2/carts/%s" % cart_id,
                                     name="GET /v2/carts/{id}",
                                     catch_response=True) as r2:
                    if r2.status_code != 200:
                        r2.failure("re-read status %s" % r2.status_code)
                        return None
                    new_etag = r2.headers.get("ETag")
                with self.client.patch("/v2/carts/%s" % cart_id,
                                       json={"quantity": quantity},
                                       headers=self._auth_headers({"If-Match": new_etag or ""}),
                                       name="PATCH /v2/carts/{id}",
                                       catch_response=True, allow_redirects=False) as r3:
                    if r3.status_code >= 400:
                        r3.failure("patch retry status %s" % r3.status_code)
                        return None
                    return r3.headers.get("ETag") or new_etag
            if r.status_code == 401:
                body = {}
                try:
                    body = r.json()
                except Exception:
                    pass
                if body.get("error") == "expired":
                    r.success()
                    if self._renew():
                        return self._patch_cart(cart_id, etag, quantity)
                    if self._fresh_login():
                        return self._patch_cart(cart_id, etag, quantity)
                    return None
                r.failure("401 %s" % body.get("error"))
                return None
            if r.status_code >= 400:
                r.failure("patch status %s" % r.status_code)
                return None
            return r.headers.get("ETag") or etag

    # ---------- challenge ----------
    def _do_challenge(self):
        with self.client.get("/v2/challenge-form", name="GET /v2/challenge-form",
                             catch_response=True) as r:
            if r.status_code != 200:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            action = extract_action(r.text)
            challenge = extract_challenge(r.text)
            if not action or not challenge:
                r.failure("challenge form missing fields")
                return None
        with self.client.post(action, json={"challenge": challenge},
                              headers=self._auth_headers(),
                              name="POST /v2/challenges/{id}",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code != 302:
                r.failure("challenge status %s" % r.status_code)
                return None
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge no Location")
                return None
        with self.client.get(loc, name="GET challenge redirect",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge redirect status %s" % r.status_code)
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("challenge redirect not json")
                return None
            if body.get("csrf"):
                self.csrf = body["csrf"]
            return body.get("grant_id")

    # ---------- reservation ----------
    def _reserve(self, cart_id):
        with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                              headers=self._auth_headers(),
                              name="POST /v2/reservations",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("reservation not json")
                return None
            if body.get("csrf"):
                self.csrf = body["csrf"]
            status_url = body.get("status_url")
        if not status_url:
            return None
        for _ in range(5):
            time.sleep(0.06)
            with self.client.get(status_url, name="GET reservation status",
                                 catch_response=True) as r:
                if r.status_code != 200:
                    r.failure("status poll %s" % r.status_code)
                    return None
                try:
                    body = r.json()
                except Exception:
                    r.failure("status not json")
                    return None
                st = body.get("status")
                if st == "ready":
                    return body.get("reservation_id")
                if st in ("pending",):
                    continue
                return None
        return None

    # ---------- order ----------
    def _order(self, cart_id, reservation_id, etag):
        idem = str(uuid.uuid4())
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = self._auth_headers({"Idempotency-Key": idem})
        if etag:
            headers["If-Match"] = etag
        with self.client.post("/v2/orders", json=payload, headers=headers,
                              name="POST /v2/orders",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                body = {}
                try:
                    body = r.json()
                except Exception:
                    pass
                if body.get("error") == "expired":
                    r.success()
                    if self._renew():
                        return self._order(cart_id, reservation_id, etag)
                    if self._fresh_login():
                        return self._order(cart_id, reservation_id, etag)
                    return False
                r.failure("401 %s" % body.get("error"))
                return False
            if r.status_code != 201:
                r.failure("order status %s" % r.status_code)
                return False
            try:
                body = r.json()
            except Exception:
                r.failure("order not json")
                return False
            if body.get("accepted") is not True:
                r.failure("order not accepted")
                return False
            if body.get("csrf"):
                self.csrf = body["csrf"]
            return True

    # ---------- work ----------
    def _do_work(self):
        retries = 0
        while retries <= 4:
            with self.client.post("/v2/work", json={},
                                  headers=self._auth_headers(),
                                  name="POST /v2/work",
                                  catch_response=True, allow_redirects=False) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    r.success()
                    time.sleep(delay)
                    retries += 1
                    continue
                if r.status_code == 401:
                    body = {}
                    try:
                        body = r.json()
                    except Exception:
                        pass
                    if body.get("error") == "expired":
                        r.success()
                        if self._renew():
                            retries += 1
                            continue
                        if self._fresh_login():
                            retries += 1
                            continue
                        return False
                    r.failure("401 %s" % body.get("error"))
                    return False
                if r.status_code >= 500:
                    r.failure("work status %s" % r.status_code)
                    return False
                if r.status_code >= 400:
                    r.failure("work status %s" % r.status_code)
                    return False
                try:
                    body = r.json()
                except Exception:
                    r.failure("work not json")
                    return False
                if body.get("ok") is not True:
                    r.failure("work not ok")
                    return False
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return True
        return False

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self.session_ok:
            if not self._fresh_login():
                raise StopUser()

        catalog = self._get_catalog()
        if not catalog:
            return
        pick = self._pick_product(catalog)
        if not pick:
            return
        product_id, variant_id = pick

        grant_id = self._do_challenge()

        cart = self._create_cart(product_id, variant_id, grant_id)
        if not cart:
            return
        cart_id, etag = cart

        etag = self._patch_cart(cart_id, etag, random.randint(1, 5))
        if etag is None:
            return

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            return

        if not self._order(cart_id, reservation_id, etag):
            return

        self._do_work()


class PhasedShape(LoadTestShape):
    # 5s warmup, then 3x10s plateaus at 5/15/5, then drain
    def tick(self):
        t = self.get_run_time()
        if t < 5:
            return (2, 2)
        if t < 15:
            return (5, 5)
        if t < 25:
            return (15, 15)
        if t < 35:
            return (5, 5)
        if t < 40:
            return (0, 0)
        return None
