import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.atomic.AtomicInteger;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    static final int TARGET_RATE = 10;
    static final int USERS = 2;
    static final int ITERATIONS = 2;

    static final AtomicInteger workStarts = new AtomicInteger();

    HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    // ---- helpers ----
    static String csrfFrom(String body) {
        // extract csrf from JSON {"csrf":"..."} or form input
        if (body == null) return null;
        int i = body.indexOf("\"csrf\"");
        if (i >= 0) {
            int c = body.indexOf(':', i);
            int q1 = body.indexOf('"', c + 1);
            int q2 = body.indexOf('"', q1 + 1);
            if (q1 >= 0 && q2 > q1) return body.substring(q1 + 1, q2);
        }
        int n = body.indexOf("name=\"csrf\"");
        if (n >= 0) {
            int v = body.indexOf("value=\"", n);
            if (v >= 0) {
                int s = v + 7;
                int e = body.indexOf('"', s);
                if (e > s) return body.substring(s, e);
            }
        }
        return null;
    }

    static String extractJsonString(String body, String key) {
        if (body == null) return null;
        int i = body.indexOf("\"" + key + "\"");
        if (i < 0) return null;
        int c = body.indexOf(':', i);
        int q1 = body.indexOf('"', c + 1);
        int q2 = body.indexOf('"', q1 + 1);
        if (q1 >= 0 && q2 > q1) return body.substring(q1 + 1, q2);
        return null;
    }

    static String extractFirstProductId(String body) {
        if (body == null) return null;
        int p = body.indexOf("\"products\"");
        if (p < 0) return null;
        int id = body.indexOf("\"id\"", p);
        if (id < 0) return null;
        int c = body.indexOf(':', id);
        int q1 = body.indexOf('"', c + 1);
        int q2 = body.indexOf('"', q1 + 1);
        if (q1 >= 0 && q2 > q1) return body.substring(q1 + 1, q2);
        return null;
    }

    static String extractFirstVariantId(String body) {
        if (body == null) return null;
        int v = body.indexOf("\"variants\"");
        if (v < 0) return null;
        int id = body.indexOf("\"id\"", v);
        if (id < 0) return null;
        int c = body.indexOf(':', id);
        int q1 = body.indexOf('"', c + 1);
        int q2 = body.indexOf('"', q1 + 1);
        if (q1 >= 0 && q2 > q1) return body.substring(q1 + 1, q2);
        return null;
    }

    // ---- scenario ----
    ScenarioBuilder scn = scenario("ModelSimulation")
            .exec(session -> session.set("user", "bench-" + (1 + ThreadLocalRandom.current().nextInt(16))))
            .exec(session -> session.set("password", "bench"))
            .exec(session -> session.set("cartId", (String) null))
            .exec(session -> session.set("csrf", (String) null))
            .exec(session -> session.set("productId", (String) null))
            .exec(session -> session.set("variantId", (String) null))
            .exec(session -> session.set("grantId", (String) null))
            .exec(session -> session.set("reservationId", (String) null))
            .exec(session -> session.set("idemKey", UUID.randomUUID().toString()))

            // 1. login form
            .exec(http("login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(bodyString().saveAs("loginFormBody")))
            .exec(session -> {
                String csrf = csrfFrom(session.getString("loginFormBody"));
                return session.set("csrf", csrf);
            })

            // 2. login
            .exec(http("login")
                    .post("/v2/login")
                    .body(StringBody(session -> {
                        String u = session.getString("user");
                        String p = session.getString("password");
                        String c = session.getString("csrf");
                        return "{\"username\":\"" + u + "\",\"password\":\"" + p + "\",\"csrf\":\"" + c + "\"}";
                    }))
                    .check(status().in(200, 302))
                    .check(bodyString().saveAs("loginBody")))
            .exec(session -> {
                String csrf = csrfFrom(session.getString("loginBody"));
                if (csrf != null) return session.set("csrf", csrf);
                return session;
            })

            // 3. catalog
            .exec(http("catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(bodyString().saveAs("catalogBody")))
            .exec(session -> {
                String pid = extractFirstProductId(session.getString("catalogBody"));
                String vid = extractFirstVariantId(session.getString("catalogBody"));
                return session.set("productId", pid).set("variantId", vid);
            })

            // 4. create cart
            .exec(http("create-cart")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody(session -> {
                        String pid = session.getString("productId");
                        String vid = session.getString("variantId");
                        String gid = session.getString("grantId");
                        StringBuilder sb = new StringBuilder("{");
                        sb.append("\"product_id\":\"").append(pid).append("\",");
                        sb.append("\"variant_id\":\"").append(vid).append("\"");
                        if (gid != null) sb.append(",\"grant_id\":\"").append(gid).append("\"");
                        sb.append("}");
                        return sb.toString();
                    }))
                    .check(status().is(201))
                    .check(bodyString().saveAs("cartBody")))
            .exec(session -> {
                String body = session.getString("cartBody");
                String id = extractJsonString(body, "id");
                String csrf = extractJsonString(body, "csrf");
                Session s = session.set("cartId", id);
                if (csrf != null) s = s.set("csrf", csrf);
                return s;
            })

            // 5. work operation (the pool operation)
            .exec(session -> {
                workStarts.incrementAndGet();
                return session;
            })
            .exec(http("work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody("{}"))
                    .check(status().in(200, 429))
                    .check(bodyString().saveAs("workBody")))

            .exec(session -> session);

    {
        setUp(
                scn.injectOpen(
                        rampUsersPerSec(0).to(TARGET_RATE).during(Duration.ofSeconds(5)),
                        constantUsersPerSec(TARGET_RATE).during(Duration.ofSeconds(30))
                )
        ).protocols(httpProtocol)
                .maxDuration(Duration.ofSeconds(45));
    }
}
