import http from 'k6/http';
import { check } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workStarts = new Counter('work_starts');
const workOk = new Counter('work_ok');
const workUnexpected = new Counter('work_unexpected');
const workScheduled = new Counter('work_scheduled');
const businessResponses = new Counter('business_responses');
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 10,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 32,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    business_failure: ['rate<0.01'],
  },
  discardResponseBodies: false,
};

function parseCsrf(html) {
  if (!html) return null;
  const re = /<input[^>]*name=["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const v = /value=["']([^"']*)["']/i.exec(tag);
    if (v) return v[1];
  }
  return null;
}

function parseChallenge(html) {
  if (!html) return null;
  const action = /<form[^>]*action=["']([^"']+)["']/i.exec(html);
  const input = /<input[^>]*name=["']?challenge["']?[^>]*>/i.exec(html);
  let val = null;
  if (input) {
    const v = /value=["']([^"']*)["']/i.exec(input[0]);
    if (v) val = v[1];
  }
  return { action: action ? action[1] : null, value: val };
}

function jarFor(user) {
  return http.cookieJar();
}

function login(user) {
  const jar = jarFor(user);
  const formRes = http.get(`${BASE}/v2/login-form`, { jar, redirects: 0 });
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { jar, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar, redirects: 0 });
  }
  let body = null;
  try { body = JSON.parse(loginRes.body); } catch (e) {}
  const token = body && body.csrf ? body.csrf : csrf;
  return { jar, csrf: token, user };
}

function renew(session) {
  const res = http.post(
    `${BASE}/v2/session/renew`,
    '{}',
    { jar: session.jar, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf } }
  );
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) {}
  if (body && body.csrf) session.csrf = body.csrf;
  return res.status < 400;
}

function doWork(session) {
  let attempts = 0;
  let scheduledRetries = 0;
  while (attempts < 2) {
    attempts++;
    const res = http.post(
      `${BASE}/v2/work`,
      '{}',
      {
        jar: session.jar,
        redirects: 0,
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf },
        tags: { name: 'work' },
      }
    );
    businessResponses.add(1);
    if (res.status === 429) {
      workScheduled.add(1);
      if (scheduledRetries < 4) {
        scheduledRetries++;
        const ra = parseFloat(res.headers['Retry-After'] || '1');
        const wait = isNaN(ra) ? 1 : ra;
        // sleep via busy wait not allowed; use k6 sleep
        // eslint-disable-next-line no-undef
        try { require('k6').sleep(wait); } catch (e) {}
        continue;
      }
      businessFailure.add(false);
      return;
    }
    if (res.status === 401) {
      let body = null;
      try { body = JSON.parse(res.body); } catch (e) {}
      const err = body && body.error;
      if (err === 'expired') {
        businessFailure.add(false);
        if (renew(session)) continue;
        return;
      }
      if (err === 'session') {
        businessFailure.add(false);
        const fresh = login(session.user);
        if (fresh) { session.jar = fresh.jar; session.csrf = fresh.csrf; continue; }
        return;
      }
      // denied or other
      businessFailure.add(true);
      workUnexpected.add(1);
      return;
    }
    if (res.status >= 500) {
      businessFailure.add(true);
      workUnexpected.add(1);
      return;
    }
    if (res.status >= 400) {
      businessFailure.add(true);
      workUnexpected.add(1);
      return;
    }
    let body = null;
    try { body = JSON.parse(res.body); } catch (e) {}
    if (body && body.ok === true) {
      workOk.add(1);
      businessFailure.add(false);
      return;
    }
    businessFailure.add(true);
    workUnexpected.add(1);
    return;
  }
}

export default function () {
  const user = `bench-${((__VU - 1) % 16) + 1}`;
  const session = login(user);
  if (!session) return;
  workStarts.add(1);
  doWork(session);
}
