def _extract_csrf_from_form(html):
    if not html:
        return None
    # input[name=csrf] with mixed attribute variants
    m = re.search(r'<input[^>]*name\s*=\s*["\']?csrf["\']?[^>]*>', html, re.IGNORECASE)
    if not m:
        return None
    tag = m.group(0)
    v = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
    if v:
        return v.group(1)
    return None


def _extract_challenge_action(html):
    if not html:
        return None
    m = re.search(r'<form[^>]*action\s*=\s*["\']([^"\']+)["\']', html, re.IGNORECASE)
    if m:
        return m.group(1)
    return None


def _extract_challenge_value(html):
    if not html:
        return None
    m = re.search(r'<input[^>]*name\s*=\s*["\']?challenge["\']?[^>]*>', html, re.IGNORECASE)
    if not m:
        return None
    tag = m.group(0)
    v = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
    if v:
        return v.group(1)
    return None


