        payload = {"username": self.username, "password": PASSWORD, "csrf": csrf}
        with self.client.post("/v2/login", json=payload, catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure(f"login redirect status {r2.status_code}")
                        return False
                    try:
                        body = r2.json()
                    except Exception:
                        r2.failure("login redirect not json")
                        return False
                    self.csrf = body.get("csrf")
                    if not self.csrf:
