    # ---------- catalog ----------
    def _get_catalog(self):
        with self.client.get("/v2/catalog", catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure(f"catalog status {r.status_code}")
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("catalog not json")
                return None
            return body

    def _pick_product(self, catalog):
        try:
            products = catalog["data"]["products"]
        except Exception:
            return None
        for p in products:
            for v in p.get("variants", []):
                if v.get("in_stock"):
                    return p["id"], v["id"]
        return None

    # ---------- cart ----------
    def _create_cart(self, product_id, variant_id, grant_id=None):
        headers = {"X-CSRF-Token": self.csrf}
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                return ("401", r)
            if r.status_code >= 400:
                r.failure(f"cart create status {r.status_code}")
                return (None, None)
            try:
                body = r.json()
            except Exception:
                r.failure("cart create not json")
                return (None, None)
            new_csrf = body.get("csrf")
            if new_csrf:
                self.csrf = new_csrf
            return (body.get("id"), r.headers.get("ETag"))

    def _patch_cart(self, cart_id, etag, quantity):
        headers = {"X-CSRF-Token": self.csrf, "If-Match": etag or ""}
        payload = {"quantity": quantity}
        with self.client.patch(f"/v2/carts/{cart_id}", json=payload, headers=headers,
                               catch_response=True, allow_redirects=False) as r:
            if r.status_code == 412:
                # re-read and retry once
                with self.client.get(f"/v2/carts/{cart_id}", catch_response=True,
                                     allow_redirects=False) as rg:
                    if rg.status_code >= 400:
                        rg.failure(f"cart re-read status {rg.status_code}")
                        return False
                    new_etag = rg.headers.get("ETag")
                headers2 = {"X-CSRF-Token": self.csrf, "If-Match": new_etag or ""}
                with self.client.patch(f"/v2/carts/{cart_id}", json=payload, headers=headers2,
                                       catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure(f"cart patch retry status {r2.status_code}")
                        return False
                    try:
                        b = r2.json()
                        if b.get("csrf"):
                            self.csrf = b["csrf"]
                    except Exception:
                        pass
                    return True
            if r.status_code == 401:
                return "401"
            if r.status_code >= 400:
                r.failure(f"cart patch status {r.status_code}")
                return False
            try:
                b = r.json()
                if b.get("csrf"):
                    self.csrf = b["csrf"]
