    # ---------- challenge ----------
    def _do_challenge(self):
        with self.client.get("/v2/challenge-form", catch_response=True,
                             allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure(f"challenge-form status {r.status_code}")
                return None
            action = _extract_challenge_action(r.text)
            value = _extract_challenge_value(r.text)
            if not action or not value:
                r.failure("challenge form missing action/value")
                return None
        headers = {"X-CSRF-Token": self.csrf}
        with self.client.post(action, json={"challenge": value}, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge 302 no Location")
                    return None
                with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code >= 400:
