                    except Exception:
                        delay = 1.0
                    self._work_retry_after = time.time() + delay
                    r.success()
                    if attempts > 4:
                        return False
                    time.sleep(delay)
                    continue
                if r.status_code == 401:
                    r.success()
                    return "401"
                if r.status_code >= 500:
                    r.failure(f"work status {r.status_code}")
                    return False
                if r.status_code >= 400:
                    r.failure(f"work status {r.status_code}")
                    return False
                try:
                    body = r.json()
