        return False

    # ---------- journey ----------
    def _run_journey(self):
        if not self._ensure_session():
            return
        catalog = self._get_catalog()
        if not catalog:
            return
        pick = self._pick_product(catalog)
        if not pick:
            return
        product_id, variant_id = pick

        grant_id = None
        # occasionally do challenge to get grant
        if random.random() < 0.3:
            grant_id = self._do_challenge()

        cart_id, etag = self._create_cart(product_id, variant_id, grant_id)
        if cart_id == "401":
            if not self._renew():
                self.session_ready = False
                return
            cart_id, etag = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            return

        qty = random.randint(1, 5)
        pr = self._patch_cart(cart_id, etag, qty)
        if pr == "401":
            if not self._renew():
                self.session_ready = False
                return
            # recover cart
            with self.client.post(f"/v2/carts/{cart_id}/recover", json={},
                                  headers={"X-CSRF-Token": self.csrf},
                                  catch_response=True, allow_redirects=False) as rr:
                if rr.status_code >= 400:
                    rr.failure(f"recover status {rr.status_code}")
                    return
            pr = self._patch_cart(cart_id, etag, qty)
        if pr is not True:
            return

        reservation_id = self._reserve(cart_id)
        if reservation_id == "401":
            if not self._renew():
                self.session_ready = False
                return
            reservation_id = self._reserve(cart_id)
        if not reservation_id:
            return

        idem = str(uuid.uuid4())
        ok = self._order(cart_id, reservation_id, idem, etag)
        if ok == "401":
            if not self._renew():
                self.session_ready = False
                return
            ok = self._order(cart_id, reservation_id, idem, etag)
        if ok is not True:
            return

        # work operation
        w = self._do_work()
        if w == "401":
            if not self._renew():
                self.session_ready = False
                return
            self._do_work()

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self._run_journey()
        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


