    // Extract csrf from login form HTML: input[name=csrf] value=...
    // Use regex check to capture value.
    static final String CSRF_REGEX = "name=\"?csrf\"?[^>]*value=\"?([^\"\\s>]+)\"?";

    // ---- login chain ----
    ChainBuilder login = exec(
        http("GET /v2/login-form")
            .get("/v2/login-form")
            .check(status().lt(400))
            .check(regex(CSRF_REGEX).saveAs("csrf"))
    ).exec(session -> {
        String u = randUser();
        return session.set("username", u).set("password", "bench");
    }).exec(
        http("POST /v2/login")
            .post("/v2/login")
            .body(StringBody("{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{csrf}\"}"))
            .check(status().in(200, 201, 302))
            .check(header("Location").optional().saveAs("loginLoc"))
            .check(bodyString().optional().saveAs("loginBody"))
    ).exec(session -> {
        String loc = session.getString("loginLoc");
        if (loc != null && !loc.isEmpty()) {
            return session.set("loginRedirect", loc);
        }
        return session;
    }).doIf(session -> session.getString("loginRedirect") != null).then(
        exec(
            http("GET login redirect")
                .get("#{loginRedirect}")
                .check(status().lt(400))
                .check(bodyString().optional().saveAs("loginBody2"))
        )
    ).exec(session -> {
        // capture csrf from body if present
        String body = session.getString("loginBody");
        if (body == null) body = session.getString("loginBody2");
        String csrf = session.getString("csrf");
        if (body != null) {
            java.util.regex.Matcher m = java.util.regex.Pattern
                .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
            if (m.find()) csrf = m.group(1);
        }
        return session.set("csrf", csrf);
    });

    // ---- work operation ----
    ChainBuilder work = exec(
        http("POST /v2/work")
            .post("/v2/work")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().in(200, 429))
            .check(header("Retry-After").optional().saveAs("retryAfter"))
            .check(bodyString().optional().saveAs("workBody"))
    ).exec(session -> {
        Integer st = session.getInt("status");
        // status not directly available; use response status via check
        return session;
    });

    // We need to handle 429 retry with Retry-After. Use a loop via asLongAs.
    ChainBuilder workWithRetry = asLongAs(session -> {
        Integer attempts = session.getInt("workAttempts");
        if (attempts == null) attempts = 0;
        return attempts < 4;
    }).on(
        exec(session -> session.set("workAttempts",
            (session.getInt("workAttempts") == null ? 0 : session.getInt("workAttempts")) + 1))
        .exec(
            http("POST /v2/work")
                .post("/v2/work")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().saveAs("workStatus"))
                .check(header("Retry-After").optional().saveAs("retryAfter"))
                .check(bodyString().optional().saveAs("workBody"))
        )
        .exec(session -> {
            Integer st = session.getInt("workStatus");
            if (st != null && st == 429) {
                String ra = session.getString("retryAfter");
                long ms = 1000L;
                try { if (ra != null) ms = (long)(Double.parseDouble(ra) * 1000); } catch (Exception e) {}
                try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                return session;
            }
            // success or unexpected: stop loop
            return session.set("workAttempts", 99);
        })
    );

    // ---- scenario ----
    ScenarioBuilder scn = scenario("ModelSimulation")
        .exec(login)
        .exec(workWithRetry);

    // Phased injection: 5/s for 10s, 15/s for 10s, 5/s for 10s
    setUp(
        scn.injectOpen(
            constantUsersPerSec(5).during(Duration.ofSeconds(10)),
            constantUsersPerSec(15).during(Duration.ofSeconds(10)),
            constantUsersPerSec(5).during(Duration.ofSeconds(10))
        )
    ).protocols(httpProtocol)
     .maxDuration(Duration.ofSeconds(60));
}
