```javascript
import http from 'k6/http';
import { check } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import encoding from 'k6/encoding';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// ---- metrics ----
const workStarts = new Counter('work_starts');
const workOk = new Counter('work_ok');
const workErr = new Counter('work_err');
const workDropped = new Counter('work_dropped');
const work429 = new Counter('work_429');
const work500 = new Counter('work_500');
const bizFail = new Rate('business_failure');
const phaseRate = new Trend('phase_rate');

export const options = {
  scenarios: {
    phased: {
      executor: 'ramping-arrival-rate',
      startRate: 5,
      timeUnit: '1s',
      preAllocatedVUs: 32,
      maxVUs: 32,
      stages: [
        { target: 5, duration: '10s' },
        { target: 15, duration: '10s' },
        { target: 5, duration: '10s' },
      ],
      gracefulStop: '5s',
    },
  },
  thresholds: {
    'business_failure': ['rate<0.01'],
    'work_dropped': ['count<1'],
  },
  discardResponseBodies: false,
};

// ---- per-VU state ----
let state = null;

function parseCsrf(html) {
  // find input[name=csrf] value, tolerate attribute variants
  const re = /<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = html.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function parseChallengeForm(html) {
  const actionM = html.match(/action\s*=\s*["']([^"']*\/v2\/challenges\/[^"']*)["']/i);
  const valM = html.match(/name\s*=\s*["']?challenge["']?[^>]*value\s*=\s*["']([^"']*)["']/i) ||
               html.match(/value\s*=\s*["']([^"']*)["'][^>]*name\s*=\s*["']?challenge["']?/i);
  return { action: actionM ? actionM[1] : null, value: valM ? valM[1] : null };
}

function jar() {
  return http.cookieJar();
}

function get(path, params) {
  return http.get(BASE + path, Object.assign({ redirects: 0 }, params || {}));
}

function post(path, body, params) {
  return http.post(BASE + path, body, Object.assign({ redirects: 0 }, params || {}));
}

function patch(path, body, params) {
  return http.patch(BASE + path, body, Object.assign({ redirects: 0 }, params || {}));
}

function login(user) {
  const form = get('/v2/login-form');
  if (form.status !== 200) return null;
  const csrf = parseCsrf(form.body);
  if (!csrf) return null;
  const res = post('/v2/login', JSON.stringify({ username: user, password: 'bench', csrf }), {
    headers: { 'Content-Type': 'application/json' },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (res.status === 302) {
    const loc = res.headers['Location'];
    if (loc) {
      const follow = get(loc.replace(BASE, ''));
      try { body = follow.json(); } catch (e) { body = null; }
    }
  }
  if (!body || !body.csrf) return null;
  return { csrf: body.csrf, user: body.user };
}

function renew(s) {
  const res = post('/v2/session/renew', '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': s.csrf },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.csrf) s.csrf = body.csrf;
  return res.status < 400;
}

function recoverCart(s, cartId) {
  if (!cartId) return;
  post('/v2/carts/' + cartId + '/recover', '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': s.csrf },
  });
}

function authed(method, path, body, s, extraHeaders) {
  const headers = Object.assign({
    'Content-Type': 'application/json',
    'X-CSRF-Token': s.csrf,
  }, extraHeaders || {});
  let res;
  if (method === 'GET') res = get(path, { headers });
  else if (method === 'POST') res = post(path, body, { headers });
  else if (method === 'PATCH') res = patch(path, body, { headers });
  return res;
}

function handle401(res, s, cartId, retryFn) {
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  const err = body && body.error;
  if (err === 'expired') {
    if (renew(s)) {
      recoverCart(s, cartId);
      return retryFn();
    }
    return null;
  }
  if (err === 'session') {
    // revoked: fresh login
    const fresh = login(s.user);
    if (fresh) {
      s.csrf = fresh.csrf;
      recoverCart(s, cartId);
      return retryFn();
    }
    return null;
  }
  // denied or other: fail
  return null;
}

function pickProduct() {
  const res = get('/v2/catalog');
  if (res.status !== 200) return null;
  let body = null;
  try { body = res.json(); } catch (e) { return null; }
  const products = body && body.data && body.data.products;
  if (!products || !products.length) return null;
  for (const p of products) {
    if (p.variants) {
      for (const v of p.variants) {
        if (v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
  }
  return null;
}

function doChallenge(s) {
  const form = get('/v2/challenge-form', { headers: { 'X-CSRF-Token': s.csrf } });
  if (form.status !== 200) return null;
  const { action, value } = parseChallengeForm(form.body);
  if (!action || !value) return null;
  const res = post(action.replace(BASE, ''), JSON.stringify({ challenge: value }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': s.csrf },
  });
  if (res.status === 302) {
    const loc = res.headers['Location'];
    if (loc) {
      const follow = get(loc.replace(BASE, ''), { headers: { 'X-CSRF-Token': s.csrf } });
      let body = null;
      try { body = follow.json(); } catch (e) { body = null; }
      if (body && body.csrf) s.csrf = body.csrf;
      if (body && body.grant_id) return body.grant_id;
    }
  }
  return null;
}

function createCart(s, product, variant, grantId) {
  const payload = { product_id: product, variant_id: variant };
  if (grantId) payload.grant_id = grantId;
  let res = authed('POST', '/v2/carts', JSON.stringify(payload), s);
  if (res.status === 401) {
    res = handle401(res, s, null, () => authed('POST', '/v2/carts', JSON.stringify(payload), s));
    if (!res) return null;
  }
  if (res.status !== 201) return null;
  let body = null;
  try { body = res.json(); } catch (e) { return null; }
  if (body && body.csrf) s.csrf = body.csrf;
  return { id: body.id, etag: res.headers['Etag'] || res.headers['ETag'] };
}

function setQuantity(s, cartId, qty) {
  let res = authed('GET', '/v2/carts/' + cartId, null, s);
  if (res.status === 401) {
    res = handle401(res, s, cartId, () => authed('GET', '/v2/carts/' + cartId, null, s));
    if (!res) return false;
  }
  if (res.status !== 200) return false;
  let etag = res.headers['Etag'] || res.headers['ETag'];
  const doPatch = () => authed('PATCH', '/v2/carts/' + cartId, JSON.stringify({ quantity: qty }), s, { 'If-Match': etag });
  let pr = doPatch();
  if (pr.status === 412) {
    const re = authed('GET', '/v2/carts/' + cartId, null, s);
    if (re.status === 200) {
      etag = re.headers['Etag'] || re.headers['ETag'];
      pr = doPatch();
    }
  }
  if (pr.status === 401) {
    pr = handle401(pr, s, cartId, doPatch);
    if (!pr) return false;
  }
  return pr.status < 400;
}

function reserve(s, cartId) {
  let res = authed('POST', '/v2/reservations', JSON.stringify({ cart_id: cartId }), s);
  if (res.status === 401) {
    res = handle401(res, s, cartId, () => authed('POST', '/v2/reservations', JSON.stringify({ cart_id: cartId }), s));
    if (!res) return null;
  }
  if (res.status !== 202) return null;
  let body = null;
  try { body = res.json(); } catch (e) { return null; }
  if (body && body.csrf) s.csrf = body.csrf;
  const statusUrl = body && body.status_url;
  if (!statusUrl) return null;
  for (let i = 0; i < 5; i++) {
    if (i > 0) { /* sleep handled by k6 sleep */ }
    const poll = get(statusUrl.replace(BASE, ''), { headers: { 'X-CSRF-Token': s.csrf } });
    let pb = null;
    try { pb = poll.json(); } catch (e) { pb = null; }
    if (pb && pb.csrf) s.csrf = pb.csrf;
    if (pb && pb.status === 'ready' && pb.reservation_id) return pb.reservation_id;
    if (pb && (pb.status === 'failed')) return null;
    // pending: wait >=50ms
    if (i < 4) {
      const start = Date.now();
      while (Date.now() - start < 60) { /* busy wait small */ }
    }
  }
  return null;
}

function checkout(s, cartId, reservationId) {
  const idem = 'idem-' + cartId + '-' + Math.random().toString(36).slice(2);
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const doPost = () => authed('POST', '/v2/orders', JSON.stringify(payload), s, { 'Idempotency-Key': idem });
  let res = doPost();
  if (res.status === 401) {
    res = handle401(res, s, cartId, doPost);
    if (!res) return false;
  }
  if (res.status !== 201) return false;
  let body = null;
  try { body = res.json(); } catch (e) { return false; }
  if (body && body.csrf) s.csrf = body.csrf;
  return body && body.accepted === true;
}

function doWork(s) {
  const start = Date.now();
  let res = authed('POST', '/v2/work', '{}', s);
  if (res.status === 401) {
    res = handle401(res, s, null, () => authed('POST', '/v2/work', '{}', s));
    if (!res) { workDropped.add(1); return; }
  }
  if (res.status === 429) {
    work429.add(1);
    const ra = parseInt(res.headers['Retry-After'] || '1', 10);
    const wait = (isNaN(ra) ? 1 : ra) * 1000;
    const t0 = Date.now();
    while (Date.now() - t0 < wait) { /* wait */ }
    // retry up to 4
    for (let i = 0; i < 4; i++) {
      res = authed('POST', '/v2/work', '{}', s);
      if (res.status === 429) {
        work429.add(1);
        const ra2 = parseInt(res.headers['Retry-After'] || '1', 10);
        const w2 = (isNaN(ra2) ? 1 : ra2) * 1000;
        const t1 = Date.now();
        while (Date.now() - t1 < w2) { /* wait */ }
        continue;
      }
      break;
    }
  }
  if (res.status >= 400 && res.status !== 429) {
    workErr.add(1);
    if (res.status === 500) work500.add(1);
    bizFail.add(true);
    return;
  }
  if (res.status === 429) {
    workDropped.add(1);
    return;
  }
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.ok === true) {
    workOk.add(1);
    workStarts.add(1);
    bizFail.add(false);
  } else {
    workErr.add(1);
    bizFail.add(true);
  }
}

export default function () {
  if (!state) {
    const user = 'bench-' + (1 + (__VU % 16));
    const s = login(user);
    if (!s) { workDropped.add(1); return; }
    state = s;
  }
  const s = state;

  // Journey: fresh login/cart per iteration
  const fresh = login(s.user);
  if (!fresh) { workDropped.add(1); return; }
  s.csrf = fresh.csrf;

  const prod = pickProduct();
  if (!prod) { workDropped.add(1); return; }

  let grantId = null;
  // attempt challenge (optional path)
  grantId = doChallenge(s);

  const cart = createCart(s, prod.product_id, prod.variant_id, grantId);
  if (!cart) { workDropped.add(1); return; }

  if (!setQuantity(s, cart.id, 1)) { workDropped.add(1); return; }

  const reservationId = reserve(s, cart.id);
  if (!reservationId) { workDropped.add(1); return; }

  if (!checkout(s, cart.id, reservationId)) { workDropped.add(1); return; }

  // The pool operation
  doWork(s);
}
