import os
import re
import time
import json
import random
from urllib.parse import urljoin

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser, RescheduleTaskImmediately


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
PASSWORD = "bench"
USERS = [f"bench-{i}" for i in range(1, 17)] + ["bench"]


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL + "/", url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = random.choice(USERS)
        self.csrf = None
        self.session_ready = False
        self.iterations_done = 0
        self.max_iterations = 2

    # ---------- helpers ----------
    def _extract_csrf_from_form(self, text):
        # input[name=csrf] with mixed attribute variants / decoys
        patterns = [
            r'<input[^>]*name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']',
            r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']',
        ]
        for p in patterns:
            m = re.search(p, text, re.IGNORECASE)
            if m:
                return m.group(1)
        return None

    def _extract_challenge(self, text):
        action = None
        token = None
        m = re.search(r'<form[^>]*action=["\']([^"\']+)["\']', text, re.IGNORECASE)
        if m:
            action = m.group(1)
        m = re.search(
            r'<input[^>]*name=["\']challenge["\'][^>]*value=["\']([^"\']*)["\']',
            text, re.IGNORECASE)
        if m:
            token = m.group(1)
        return action, token

    def _login(self):
        with self.client.get("/v2/login-form", catch_response=True,
                             allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure(f"login-form {r.status_code}")
                return False
            csrf = self._extract_csrf_from_form(r.text or "")
            if not csrf:
                r.failure("no csrf in login form")
                return False
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": PASSWORD, "csrf": csrf},
            catch_response=True, allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(_abs(loc), catch_response=True,
                                     allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure(f"login redirect {r2.status_code}")
                        return False
                    try:
                        body = r2.json()
                    except Exception:
                        r2.failure("login redirect not json")
                        return False
                    self.csrf = body.get("csrf")
            elif r.status_code < 400:
                try:
                    body = r.json()
                except Exception:
                    r.failure("login not json")
                    return False
                self.csrf = body.get("csrf")
            else:
                r.failure(f"login {r.status_code}")
                return False
        if not self.csrf:
            return False
        self.session_ready = True
        return True

    def _renew(self):
        if not self.csrf:
            return False
        with self.client.post(
            "/v2/session/renew", json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True, allow_redirects=False,
        ) as r:
            if r.status_code >= 400:
                r.failure(f"renew {r.status_code}")
                return False
            try:
                body = r.json()
            except Exception:
                r.failure("renew not json")
                return False
            if body.get("csrf"):
                self.csrf = body["csrf"]
        return True

    def _recover_cart(self, cart_id):
        if not cart_id:
            return
        with self.client.post(
            f"/v2/carts/{cart_id}/recover", json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True, allow_redirects=False,
        ) as r:
            if r.status_code >= 400:
                r.failure(f"recover {r.status_code}")
            else:
                try:
                    body = r.json()
                    if body.get("csrf"):
                        self.csrf = body["csrf"]
                except Exception:
                    pass

    def _handle_401(self, r, cart_id=None):
        try:
            body = r.json()
        except Exception:
            return False
        err = body.get("error")
        if err == "expired":
            if self._renew():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        if err == "session":
            self.session_ready = False
            if self._login():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        return False

    def _get_catalog_product(self):
        with self.client.get("/v2/catalog", catch_response=True,
                             allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure(f"catalog {r.status_code}")
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("catalog not json")
                return None
        products = (body.get("data") or {}).get("products") or []
        for p in products:
            for v in p.get("variants") or []:
                if v.get("in_stock"):
                    return p["id"], v["id"]
        # fallback: traverse pages
        next_url = body.get("next")
        pages = 0
        while next_url and pages < 3:
            pages += 1
            with self.client.get(_abs(next_url), catch_response=True,
                                 allow_redirects=False) as r:
                if r.status_code >= 400:
                    r.failure(f"catalog page {r.status_code}")
                    return None
                try:
                    body = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    return None
            for p in body.get("products") or []:
                for v in p.get("variants") or []:
                    if v.get("in_stock"):
                        return p["id"], v["id"]
            next_url = body.get("next")
        return None

    def _maybe_challenge(self):
        # Try to obtain a grant_id via challenge flow (optional)
        with self.client.get("/v2/challenge-form", catch_response=True,
                             allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure(f"challenge-form {r.status_code}")
                return None
            action, token = self._extract_challenge(r.text or "")
            if not action or token is None:
                return None
        with self.client.post(
            _abs(action), json={"challenge": token},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True, allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge 302 no Location")
                    return None
                with self.client.get(_abs(loc), catch_response=True,
                                     allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure(f"challenge loc {r2.status_code}")
                        return None
                    try:
                        body = r2.json()
                    except Exception:
                        r2.failure("challenge loc not json")
                        return None
                    if body.get("csrf"):
                        self.csrf = body["csrf"]
                    return body.get("grant_id")
            elif r.status_code < 400:
                try:
                    body = r.json()
                except Exception:
                    r.failure("challenge not json")
                    return None
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return body.get("grant_id")
            else:
                r.failure(f"challenge {r.status_code}")
                return None

    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post(
            "/v2/carts", json=payload,
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True, allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    return self._create_cart(product_id, variant_id, grant_id)
                r.failure("cart 401 unrecoverable")
                return None
            if r.status_code >= 400:
                r.failure(f"cart {r.status_code}")
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("cart not json")
                return None
            if body.get("csrf"):
                self.csrf = body["csrf"]
            return body.get("id")

    def _patch_cart(self, cart_id, quantity):
        # read etag
        with self.client.get(f"/v2/carts/{cart_id}", catch_response=True,
                             allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    return self._patch_cart(cart_id, quantity)
                r.failure("cart get 401")
                return False
            if r.status_code >= 400:
                r.failure(f"cart get {r.status_code}")
                return False
            etag = r.headers.get("ETag")
        payload = {"quantity": quantity}
        headers = {"X-CSRF-Token": self.csrf}
        if etag:
            headers["If-Match"] = etag
        with self.client.patch(
            f"/v2/carts/{cart_id}", json=payload, headers=headers,
            catch_response=True, allow_redirects=False,
        ) as r:
            if r.status_code == 412:
                # re-read and retry once
                with self.client.get(f"/v2/carts/{cart_id}", catch_response=True,
                                     allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure(f"cart reget {r2.status_code}")
                        return False
                    etag2 = r2.headers.get("ETag")
                headers2 = {"X-CSRF-Token": self.csrf}
                if etag2:
                    headers2["If-Match"] = etag2
                with self.client.patch(
                    f"/v2/carts/{cart_id}", json=payload, headers=headers2,
                    catch_response=True, allow_redirects=False,
                ) as r3:
                    if r3.status_code >= 400:
                        r3.failure(f"cart patch retry {r3.status_code}")
                        return False
                    try:
                        body = r3.json()
                        if body.get("csrf"):
                            self.csrf = body["csrf"]
                    except Exception:
                        pass
                    return True
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    return self._patch_cart(cart_id, quantity)
                r.failure("cart patch 401")
                return False
            if r.status_code >= 400:
                r.failure(f"cart patch {r.status_code}")
                return False
            try:
                body = r.json()
                if body.get("csrf"):
                    self.csrf = body["csrf"]
            except Exception:
                pass
            return True

    def _reserve(self, cart_id):
        with self.client.post(
            "/v2/reservations", json={"cart_id": cart_id},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True, allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    return self._reserve(cart_id)
                r.failure("reservation 401")
                return None
            if r.status_code >= 400:
                r.failure(f"reservation {r.status_code}")
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("reservation not json")
                return None
            if body.get("csrf"):
                self.csrf = body["csrf"]
            status_url = body.get("status_url")
        if not status_url:
            return None
        for _ in range(5):
            time.sleep(0.06)
            with self.client.get(_abs(status_url), catch_response=True,
                                 allow_redirects=False) as r:
                if r.status_code >= 400:
                    r.failure(f"res status {r.status_code}")
                    return None
                try:
                    body = r.json()
                except Exception:
                    r.failure("res status not json")
                    return None
            st = body.get("status")
            if st == "ready":
                return body.get("reservation_id")
            if st in ("pending",):
                continue
            return None
        return None

    def _order(self, cart_id, reservation_id):
        headers = {"X-CSRF-Token": self.csrf,
                   "Idempotency-Key": f"cart-{cart_id}-{self.username}"}
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        with self.client.post(
            "/v2/orders", json=payload, headers=headers,
            catch_response=True, allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    return self._order(cart_id, reservation_id)
                r.failure("order 401")
                return False
            if r.status_code >= 400:
                r.failure(f"order {r.status_code}")
                return False
            try:
                body = r.json()
            except Exception:
                r.failure("order not json")
                return False
            if body.get("csrf"):
                self.csrf = body["csrf"]
            if body.get("accepted") is True:
                return True
            r.failure("order not accepted")
            return False

    def _work(self):
        # POST /v2/work is the operation. Handle scheduled 429 with Retry-After.
        attempts = 0
        while attempts <= 4:
            attempts += 1
            with self.client.post(
                "/v2/work", json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True, allow_redirects=False,
            ) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    r.success()
                    if attempts > 4:
                        return
                    time.sleep(max(delay, 0.05))
                    continue
                if r.status_code == 401:
                    if self._handle_401(r):
                        continue
                    r.failure("work 401")
                    return
                if r.status_code >= 400:
                    r.failure(f"work {r.status_code}")
                    return
                try:
                    body = r.json()
                except Exception:
                    r.failure("work not json")
                    return
                if body.get("ok") is True:
                    r.success()
                    return
                r.failure("work not ok")
                return

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self.session_ready:
            if not self._login():
                raise StopUser()

        # fresh cart per journey
        prod = self._get_catalog_product()
        if not prod:
            return
        product_id, variant_id = prod

        grant_id = None
        try:
            grant_id = self._maybe_challenge()
        except Exception:
            grant_id = None

        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            return

        if not self._patch_cart(cart_id, random.randint(1, 5)):
            return

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            return

        if not self._order(cart_id, reservation_id):
            return

        # the actual pool operation
        self._work()


class ShopUserA(ShopUser):
    weight = 1


class ShopUserB(ShopUser):
    weight = 1


class PhasedShape(LoadTestShape):
    # 5 -> 15 -> 5 starts/s over three 10s plateaus, plus warmup/drain.
    # We approximate "starts/s" via user count; each user does ~1 journey per
    # few seconds. Use a modest user count scaled to target.
    def tick(self):
        run_time = self.get_run_time()
        # warmup 5s, then 3x10s plateaus, then drain 5s
        if run_time < 5:
            return (2, 2)
        if run_time < 15:
            return (5, 2)
        if run_time < 25:
            return (15, 2)
        if run_time < 35:
            return (5, 2)
        if run_time < 40:
            return (1, 2)
        return None
