import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import encoding from 'k6/encoding';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workOk = new Counter('work_ok');
const work429 = new Counter('work_429');
const workErr = new Counter('work_err');
const workRaw = new Counter('work_raw');
const workRate = new Rate('work_rate');
const workLatency = new Trend('work_latency');

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '60s',
      gracefulStop: '5s',
    },
  },
  thresholds: {
    work_rate: ['rate>0.9'],
  },
  discardResponseBodies: false,
  noConnectionReuse: false,
};

const USERS = ['bench-1', 'bench-2'];
const PASSWORD = 'bench';

function jar() {
  return http.cookieJar();
}

function parseCsrf(html) {
  if (!html) return null;
  const re = /<input[^>]*name=["']?csrf["']?[^>]*value=["']([^"']+)["']/i;
  let m = html.match(re);
  if (m) return m[1];
  const re2 = /<input[^>]*value=["']([^"']+)["'][^>]*name=["']?csrf["']?/i;
  m = html.match(re2);
  if (m) return m[1];
  return null;
}

function parseChallenge(html) {
  if (!html) return null;
  const actionM = html.match(/<form[^>]*action=["']([^"']+)["']/i);
  const inputM = html.match(/<input[^>]*name=["']?challenge["']?[^>]*value=["']([^"']*)["']/i) ||
                 html.match(/<input[^>]*value=["']([^"']*)["'][^>]*name=["']?challenge["']?/i);
  if (!actionM) return null;
  return { action: actionM[1], value: inputM ? inputM[1] : '' };
}

function login(user, cj) {
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: cj, redirects: 0 });
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(`${BASE}/v2/login`,
    JSON.stringify({ username: user, password: PASSWORD, csrf }),
    { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json' } });
  let body = null;
  try { body = JSON.parse(loginRes.body); } catch (e) {}
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const r2 = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: cj, redirects: 0 });
      try { body = JSON.parse(r2.body); } catch (e) {}
    }
  }
  if (!body || !body.csrf) return null;
  return { csrf: body.csrf, user: body.user };
}

function renew(cj, csrf) {
  const r = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}),
    { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf } });
  if (r.status >= 400) return null;
  let b = null;
  try { b = JSON.parse(r.body); } catch (e) {}
  return b && b.csrf ? b.csrf : csrf;
}

function getCatalog(cj) {
  const r = http.get(`${BASE}/v2/catalog`, { jar: cj, redirects: 0 });
  if (r.status !== 200) return null;
  try {
    const b = JSON.parse(r.body);
    const products = b.data && b.data.products;
    if (!products || !products.length) return null;
    for (const p of products) {
      if (p.variants) {
        for (const v of p.variants) {
          if (v.in_stock) return { product_id: p.id, variant_id: v.id };
        }
      }
    }
  } catch (e) {}
  return null;
}

function solveChallenge(cj, csrf) {
  const r = http.get(`${BASE}/v2/challenge-form`, { jar: cj, redirects: 0 });
  if (r.status !== 200) return null;
  const ch = parseChallenge(r.body);
  if (!ch) return null;
  const action = ch.action.startsWith('http') ? ch.action : `${BASE}${ch.action}`;
  const post = http.post(action, JSON.stringify({ challenge: ch.value }),
    { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf } });
  let loc = post.headers['Location'];
  if (post.status === 302 && loc) {
    const g = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: cj, redirects: 0 });
    try {
      const b = JSON.parse(g.body);
      if (b.grant_id) return { grant_id: b.grant_id, csrf: b.csrf || csrf };
    } catch (e) {}
  }
  return null;
}

function createCart(cj, csrf, item, grantId) {
  const payload = { product_id: item.product_id, variant_id: item.variant_id };
  if (grantId) payload.grant_id = grantId;
  const r = http.post(`${BASE}/v2/carts`, JSON.stringify(payload),
    { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf } });
  if (r.status === 401) {
    let b = null; try { b = JSON.parse(r.body); } catch (e) {}
    if (b && b.error === 'expired') {
      const nc = renew(cj, csrf);
      if (nc) {
        const r2 = http.post(`${BASE}/v2/carts`, JSON.stringify(payload),
          { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': nc } });
        if (r2.status === 201) {
          let b2 = null; try { b2 = JSON.parse(r2.body); } catch (e) {}
          if (b2 && b2.id) return { id: b2.id, csrf: b2.csrf || nc, etag: r2.headers['Etag'] };
        }
      }
    }
    return null;
  }
  if (r.status !== 201) return null;
  let b = null; try { b = JSON.parse(r.body); } catch (e) {}
  if (!b || !b.id) return null;
  return { id: b.id, csrf: b.csrf || csrf, etag: r.headers['Etag'] };
}

function patchCart(cj, csrf, cartId, etag, qty) {
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
  if (etag) headers['If-Match'] = etag;
  const r = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: qty }),
    { jar: cj, redirects: 0, headers });
  if (r.status === 412) {
    const g = http.get(`${BASE}/v2/carts/${cartId}`, { jar: cj, redirects: 0 });
    const ne = g.headers['Etag'];
    const h2 = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
    if (ne) h2['If-Match'] = ne;
    const r2 = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: qty }),
      { jar: cj, redirects: 0, headers: h2 });
    return { ok: r2.status < 400, csrf, etag: r2.headers['Etag'] || ne };
  }
  return { ok: r.status < 400, csrf, etag: r.headers['Etag'] || etag };
}

function reserve(cj, csrf, cartId) {
  const r = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }),
    { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf } });
  if (r.status !== 202) return null;
  let b = null; try { b = JSON.parse(r.body); } catch (e) {}
  if (!b || !b.status_url) return null;
  const su = b.status_url.startsWith('http') ? b.status_url : `${BASE}${b.status_url}`;
  let curCsrf = b.csrf || csrf;
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const s = http.get(su, { jar: cj, redirects: 0 });
    if (s.status !== 200) continue;
    let sb = null; try { sb = JSON.parse(s.body); } catch (e) {}
    if (!sb) continue;
    if (sb.csrf) curCsrf = sb.csrf;
    if (sb.status === 'ready' && sb.reservation_id) return { reservation_id: sb.reservation_id, csrf: curCsrf };
    if (sb.status === 'failed') return null;
  }
  return null;
}

function checkout(cj, csrf, cartId, reservationId, idemKey) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'Idempotency-Key': idemKey };
  const r = http.post(`${BASE}/v2/orders`, JSON.stringify(payload),
    { jar: cj, redirects: 0, headers });
  if (r.status === 401) {
    let b = null; try { b = JSON.parse(r.body); } catch (e) {}
    if (b && b.error === 'expired') {
      const nc = renew(cj, csrf);
      if (nc) {
        const h2 = { 'Content-Type': 'application/json', 'X-CSRF-Token': nc, 'Idempotency-Key': idemKey };
        const r2 = http.post(`${BASE}/v2/orders`, JSON.stringify(payload),
          { jar: cj, redirects: 0, headers: h2 });
        return r2.status === 201;
      }
    }
    return false;
  }
  if (r.status !== 201) return false;
  let b = null; try { b = JSON.parse(r.body); } catch (e) {}
  return !!(b && b.accepted === true);
}

function doWork(cj, csrf) {
  let curCsrf = csrf;
  let retries = 0;
  while (retries <= 4) {
    workRaw.add(1);
    const t0 = Date.now();
    const r = http.post(`${BASE}/v2/work`, JSON.stringify({}),
      { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': curCsrf } });
    const dt = Date.now() - t0;
    if (r.status === 200) {
      let b = null; try { b = JSON.parse(r.body); } catch (e) {}
      if (b && b.ok === true) {
        workOk.add(1);
        workRate.add(true);
        workLatency.add(dt);
        return true;
      }
      workErr.add(1);
      workRate.add(false);
      return false;
    }
    if (r.status === 429) {
      work429.add(1);
      const ra = parseInt(r.headers['Retry-After'] || '1', 10);
      sleep(Math.max(1, isNaN(ra) ? 1 : ra));
      retries++;
      continue;
    }
    if (r.status === 401) {
      let b = null; try { b = JSON.parse(r.body); } catch (e) {}
      if (b && b.error === 'expired') {
        const nc = renew(cj, curCsrf);
        if (nc) { curCsrf = nc; retries++; continue; }
      }
    }
    workErr.add(1);
    workRate.add(false);
    return false;
  }
  workRate.add(false);
  return false;
}

export default function () {
  const vu = __VU;
  const user = USERS[(vu - 1) % USERS.length];
  const cj = jar();

  const sess = login(user, cj);
  if (!sess) { sleep(0.5); return; }
  let csrf = sess.csrf;

  const item = getCatalog(cj);
  if (!item) { sleep(0.5); return; }

  let grantId = null;
  const ch = solveChallenge(cj, csrf);
  if (ch) { grantId = ch.grant_id; csrf = ch.csrf; }

  const cart = createCart(cj, csrf, item, grantId);
  if (!cart) { sleep(0.5); return; }
  csrf = cart.csrf;

  const pr = patchCart(cj, csrf, cart.id, cart.etag, 1);
  if (!pr.ok) { sleep(0.5); return; }
  csrf = pr.csrf;

  const res = reserve(cj, csrf, cart.id);
  if (!res) { sleep(0.5); return; }
  csrf = res.csrf;

  const idemKey = `idem-${cart.id}-${Date.now()}`;
  const ok = checkout(cj, csrf, cart.id, res.reservation_id, idemKey);
  if (!ok) { sleep(0.5); return; }

  doWork(cj, csrf);
  sleep(0.05);
}
