from locust import HttpUser, task, between, events
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
PASSWORD = "bench"
USERS = ["bench-1", "bench-2", "bench-3", "bench-4", "bench-5", "bench-6",
         "bench-7", "bench-8", "bench-9", "bench-10", "bench-11", "bench-12",
         "bench-13", "bench-14", "bench-15", "bench-16", "bench"]

CSRF_INPUT_RE = re.compile(
    r"""<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>""", re.IGNORECASE)
VALUE_RE = re.compile(r"""value\s*=\s*["']([^"']*)["']""", re.IGNORECASE)
ACTION_RE = re.compile(r"""action\s*=\s*["']([^"']*)["']""", re.IGNORECASE)
CHALLENGE_INPUT_RE = re.compile(
    r"""<input[^>]*name\s*=\s*["']?challenge["']?[^>]*>""", re.IGNORECASE)


def _extract_csrf(html):
    m = CSRF_INPUT_RE.search(html or "")
    if not m:
        return None
    v = VALUE_RE.search(m.group(0))
    return v.group(1) if v else None


def _extract_challenge(html):
    m = CHALLENGE_INPUT_RE.search(html or "")
    if not m:
        return None
    v = VALUE_RE.search(m.group(0))
    return v.group(1) if v else None


def _extract_action(html):
    m = ACTION_RE.search(html or "")
    return m.group(1) if m else None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = random.choice(USERS)
        self.csrf = None
        self.session_ready = False
        self.iterations_done = 0
        self.max_iterations = 2
        self.work_retry_after = 0.0

    # ---------- low level helpers ----------
    def _req(self, method, path, name=None, **kwargs):
        kwargs.setdefault("allow_redirects", False)
        return self.client.request(method, path, name=name or path, **kwargs)

    def _auth_headers(self, extra=None):
        h = {"X-CSRF-Token": self.csrf or ""}
        if extra:
            h.update(extra)
        return h

    def _login(self):
        r = self._req("GET", "/v2/login-form", name="GET /v2/login-form")
        if r.status_code >= 400:
            return False
        csrf = _extract_csrf(r.text)
        if not csrf:
            return False
        r = self._req(
            "POST", "/v2/login", name="POST /v2/login",
            json={"username": self.username, "password": PASSWORD, "csrf": csrf},
        )
        if r.status_code == 302:
            loc = r.headers.get("Location")
            if loc:
                r2 = self._req("GET", loc, name="GET login redirect")
                if r2.status_code < 400:
                    try:
                        data = r2.json()
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                    except Exception:
                        pass
        if r.status_code >= 400:
            return False
        try:
            data = r.json()
        except Exception:
            data = {}
        if data.get("csrf"):
            self.csrf = data["csrf"]
        if not self.csrf:
            return False
        self.session_ready = True
        return True

    def _renew(self):
        r = self._req(
            "POST", "/v2/session/renew", name="POST /v2/session/renew",
            json={}, headers=self._auth_headers(),
        )
        if r.status_code >= 400:
            return False
        try:
            data = r.json()
        except Exception:
            data = {}
        if data.get("csrf"):
            self.csrf = data["csrf"]
        return True

    def _recover_cart(self, cart_id):
        if not cart_id:
            return
        r = self._req(
            "POST", f"/v2/carts/{cart_id}/recover",
            name="POST /v2/carts/{id}/recover",
            json={}, headers=self._auth_headers(),
        )
        if r.status_code < 400:
            try:
                data = r.json()
                if data.get("csrf"):
                    self.csrf = data["csrf"]
            except Exception:
                pass

    def _handle_401(self, r, cart_id=None):
        try:
            data = r.json()
        except Exception:
            data = {}
        err = data.get("error")
        if err == "expired":
            if self._renew():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        if err == "session":
            self.session_ready = False
            if self._login():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        return False

    # ---------- catalog ----------
    def _get_catalog(self):
        r = self._req("GET", "/v2/catalog", name="GET /v2/catalog")
        if r.status_code >= 400:
            return None
        try:
            data = r.json()
        except Exception:
            return None
        products = (data.get("data") or {}).get("products") or []
        for p in products:
            for v in p.get("variants") or []:
                if v.get("in_stock"):
                    return (p.get("id"), v.get("id"))
        return None

    def _get_catalog_page(self):
        r = self._req("GET", "/v2/catalog/page", name="GET /v2/catalog/page")
        if r.status_code >= 400:
            return None
        try:
            data = r.json()
        except Exception:
            return None
        pages = 0
        cur = data
        while cur and pages < 3:
            prod = cur.get("product") or cur.get("data")
            if isinstance(prod, dict):
                for v in prod.get("variants") or []:
                    if v.get("in_stock"):
                        return (prod.get("id"), v.get("id"))
            nxt = cur.get("next")
            if not nxt:
                break
            url = urljoin("/v2/catalog/page", nxt) if not nxt.startswith("http") else nxt
            r = self._req("GET", url, name="GET /v2/catalog/page")
            if r.status_code >= 400:
                break
            try:
                cur = r.json()
            except Exception:
                break
            pages += 1
        return None

    # ---------- challenge ----------
    def _solve_challenge(self):
        r = self._req("GET", "/v2/challenge-form", name="GET /v2/challenge-form")
        if r.status_code >= 400:
            return None
        action = _extract_action(r.text)
        challenge = _extract_challenge(r.text)
        if not action or not challenge:
            return None
        r = self._req(
            "POST", action, name="POST /v2/challenges/{id}",
            json={"challenge": challenge}, headers=self._auth_headers(),
        )
        if r.status_code == 302:
            loc = r.headers.get("Location")
            if loc:
                r2 = self._req("GET", loc, name="GET challenge redirect")
                if r2.status_code < 400:
                    try:
                        data = r2.json()
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        return data.get("grant_id")
                    except Exception:
                        return None
        return None

    # ---------- cart ----------
    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        r = self._req(
            "POST", "/v2/carts", name="POST /v2/carts",
            json=payload, headers=self._auth_headers(),
        )
        if r.status_code == 401:
            if self._handle_401(r):
                r = self._req(
                    "POST", "/v2/carts", name="POST /v2/carts",
                    json=payload, headers=self._auth_headers(),
                )
        if r.status_code >= 400:
            return None
        try:
            data = r.json()
        except Exception:
            return None
        if data.get("csrf"):
            self.csrf = data["csrf"]
        return data.get("id")

    def _patch_cart(self, cart_id, quantity):
        r = self._req("GET", f"/v2/carts/{cart_id}", name="GET /v2/carts/{id}")
        if r.status_code == 401:
            if self._handle_401(r, cart_id):
                r = self._req("GET", f"/v2/carts/{cart_id}", name="GET /v2/carts/{id}")
        if r.status_code >= 400:
            return False
        etag = r.headers.get("ETag")
        headers = self._auth_headers()
        if etag:
            headers["If-Match"] = etag
        payload = {"quantity": quantity}
        r = self._req(
            "PATCH", f"/v2/carts/{cart_id}", name="PATCH /v2/carts/{id}",
            json=payload, headers=headers,
        )
        if r.status_code == 412:
            r2 = self._req("GET", f"/v2/carts/{cart_id}", name="GET /v2/carts/{id}")
            if r2.status_code < 400:
                etag2 = r2.headers.get("ETag")
                headers = self._auth_headers()
                if etag2:
                    headers["If-Match"] = etag2
                r = self._req(
                    "PATCH", f"/v2/carts/{cart_id}", name="PATCH /v2/carts/{id}",
                    json=payload, headers=headers,
                )
        if r.status_code == 401:
            if self._handle_401(r, cart_id):
                return self._patch_cart(cart_id, quantity)
        if r.status_code >= 400:
            return False
        try:
            data = r.json()
            if data.get("csrf"):
                self.csrf = data["csrf"]
        except Exception:
            pass
        return True

    # ---------- reservation ----------
    def _reserve(self, cart_id):
        r = self._req(
            "POST", "/v2/reservations", name="POST /v2/reservations",
            json={"cart_id": cart_id}, headers=self._auth_headers(),
        )
        if r.status_code == 401:
            if self._handle_401(r, cart_id):
                r = self._req(
                    "POST", "/v2/reservations", name="POST /v2/reservations",
                    json={"cart_id": cart_id}, headers=self._auth_headers(),
                )
        if r.status_code >= 400:
            return None
        try:
            data = r.json()
        except Exception:
            return None
        if data.get("csrf"):
            self.csrf = data["csrf"]
        status_url = data.get("status_url")
        if not status_url:
            return None
        for _ in range(5):
            time.sleep(0.06)
            r = self._req("GET", status_url, name="GET reservation status")
            if r.status_code >= 400:
                return None
            try:
                sdata = r.json()
            except Exception:
                return None
            st = sdata.get("status")
            if st == "ready":
                return sdata.get("reservation_id")
            if st in ("pending",):
                continue
            return None
        return None

    # ---------- order ----------
    def _order(self, cart_id, reservation_id):
        idem = str(uuid.uuid4())
        headers = self._auth_headers({"Idempotency-Key": idem})
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        r = self._req(
            "POST", "/v2/orders", name="POST /v2/orders",
            json=payload, headers=headers,
        )
        if r.status_code == 401:
            if self._handle_401(r, cart_id):
                r = self._req(
                    "POST", "/v2/orders", name="POST /v2/orders",
                    json=payload, headers=headers,
                )
        if r.status_code >= 400:
            return False
        try:
            data = r.json()
        except Exception:
            return False
        if data.get("csrf"):
            self.csrf = data["csrf"]
        if data.get("accepted") is True:
            return True
        return False

    # ---------- work ----------
    def _do_work(self):
        retries = 0
        while retries <= 4:
            with self.client.post(
                "/v2/work", json={}, headers=self._auth_headers(),
                name="POST /v2/work", catch_response=True,
                allow_redirects=False,
            ) as resp:
                if resp.status_code == 429:
                    ra = resp.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    resp.success()
                    time.sleep(max(delay, 0.05))
                    retries += 1
                    continue
                if resp.status_code == 401:
                    if self._handle_401(resp):
                        resp.success()
                        retries += 1
                        continue
                    resp.failure("401 unauthorized on work")
                    return False
                if resp.status_code >= 500:
                    resp.failure(f"unexpected {resp.status_code}")
                    return False
                if resp.status_code >= 400:
                    resp.failure(f"unexpected {resp.status_code}")
                    return False
                try:
                    data = resp.json()
                except Exception:
                    resp.failure("bad json")
                    return False
                if data.get("ok") is True:
                    resp.success()
                    return True
                resp.failure("ok not true")
                return False
        return False

    # ---------- journey ----------
    def _journey(self):
        if not self.session_ready:
            if not self._login():
                return
        pick = self._get_catalog()
        if not pick:
            pick = self._get_catalog_page()
        if not pick:
            return
        product_id, variant_id = pick
        grant_id = self._solve_challenge()
        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            return
        if not self._patch_cart(cart_id, random.randint(1, 5)):
            return
        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            return
        self._order(cart_id, reservation_id)

    @task
    def run(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        try:
            self._journey()
            self._do_work()
        except StopUser:
            raise
        except Exception:
            pass
        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


