class PhasedShape(LoadTestShape):
    """Phased targets 5/15/5 over three 10s plateaus, warmup 5s, drain 5s."""

    def __init__(self):
        super().__init__()
        self.start = None

    def tick(self):
        if self.start is None:
            self.start = time.time()
        elapsed = time.time() - self.start
        # warmup 5s
        if elapsed < 5:
            return (2, 2)
        # plateau 1: 5 users for 10s
        if elapsed < 15:
            return (5, 5)
        # plateau 2: 15 users for 10s
        if elapsed < 25:
            return (15, 15)
        # plateau 3: 5 users for 10s
        if elapsed < 35:
            return (5, 5)
        # drain 5s
        if elapsed < 40:
            return (1, 1)
        return None
