import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");
    private static final String PASSWORD = "bench";

    private static final Pattern CSRF_INPUT = Pattern.compile("name=\"csrf\"[^>]*value=\"([^\"]+)\"");
    private static final Pattern CSRF_INPUT_ALT = Pattern.compile("value=\"([^\"]+)\"[^>]*name=\"csrf\"");
    private static final Pattern CHALLENGE_INPUT = Pattern.compile("name=\"challenge\"[^>]*value=\"([^\"]*)\"");
    private static final Pattern CHALLENGE_ACTION = Pattern.compile("action=\"(/v2/challenges/[^\"]+)\"");

    private static String extractCsrf(String body) {
        if (body == null) return null;
        Matcher m = CSRF_INPUT.matcher(body);
        if (m.find()) return m.group(1);
        m = CSRF_INPUT_ALT.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractChallenge(String body) {
        if (body == null) return null;
        Matcher m = CHALLENGE_INPUT.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractChallengeAction(String body) {
        if (body == null) return null;
        Matcher m = CHALLENGE_ACTION.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String jsonField(String body, String field) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(field) + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String jsonRawField(String body, String field) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(field) + "\"\\s*:\\s*([^,}\\]]+)");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1).trim();
        return null;
    }

    private static String firstProductId(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"products\"\\s*:\\s*\\[\\s*\\{[^}]*?\"id\"\\s*:\\s*\"?([^,\"}]+)\"?");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String firstVariantId(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"variants\"\\s*:\\s*\\[\\s*\\{[^}]*?\"id\"\\s*:\\s*\"?([^,\"}]+)\"?");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String firstInStockVariant(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"variants\"\\s*:\\s*\\[\\s*\\{([^\\]]*?)\\]");
        Matcher m = p.matcher(body);
        if (m.find()) {
            String variants = m.group(1);
            Pattern vp = Pattern.compile("\\{[^}]*?\"id\"\\s*:\\s*\"?([^,\"}]+)\"?[^}]*?\"in_stock\"\\s*:\\s*(true|false)");
            Matcher vm = vp.matcher(variants);
            while (vm.find()) {
                if ("true".equals(vm.group(2))) return vm.group(1);
            }
            vm = vp.matcher(variants);
            if (vm.find()) return vm.group(1);
        }
        return null;
    }

    private static String nextPage(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"next\"\\s*:\\s*\"([^\"]+)\"");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String cartId(String body) {
        return jsonField(body, "id");
    }

    private static String etagFromHeader(String header) {
        return header;
    }

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-bench");

    private static final String[] USERS = new String[]{
            "bench-1", "bench-2", "bench-3", "bench-4", "bench-5", "bench-6", "bench-7", "bench-8",
            "bench-9", "bench-10", "bench-11", "bench-12", "bench-13", "bench-14", "bench-15", "bench-16"
    };

    private static String pickUser() {
        return USERS[ThreadLocalRandom.current().nextInt(USERS.length)];
    }

    private static ChainBuilder loginFlow() {
        return exec(session -> {
            String user = pickUser();
            return session.set("username", user).set("password", PASSWORD);
        })
        .exec(http("login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(bodyString().saveAs("loginFormBody")))
        .exec(session -> {
            String csrf = extractCsrf(session.getString("loginFormBody"));
            return session.set("csrf", csrf);
        })
        .exec(http("login")
                .post("/v2/login")
                .body(StringBody(session -> {
                    String u = session.getString("username");
                    String c = session.getString("csrf");
                    return "{\"username\":\"" + u + "\",\"password\":\"" + PASSWORD + "\",\"csrf\":\"" + c + "\"}";
                }))
                .check(status().in(200, 302))
                .check(header("Location").optional().saveAs("loginLocation"))
                .check(bodyString().optional().saveAs("loginBody")))
        .exec(session -> {
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginRedirect", loc);
            }
            return session;
        })
        .doIf(session -> session.getString("loginRedirect") != null).then(
                exec(http("login-redirect")
                        .get(session -> session.getString("loginRedirect"))
                        .check(status().is(200))
                        .check(bodyString().optional().saveAs("loginRedirectBody")))
        )
        .exec(session -> {
            String csrf = jsonField(session.getString("loginBody"), "csrf");
            if (csrf == null) csrf = jsonField(session.getString("loginRedirectBody"), "csrf");
            if (csrf == null) csrf = session.getString("csrf");
            return session.set("csrf", csrf);
        });
    }

    private static ChainBuilder challengeFlow() {
        return exec(http("challenge-form")
                .get("/v2/challenge-form")
                .check(status().is(200))
                .check(bodyString().saveAs("challengeFormBody")))
        .exec(session -> {
            String body = session.getString("challengeFormBody");
            String action = extractChallengeAction(body);
            String challenge = extractChallenge(body);
            return session.set("challengeAction", action).set("challengeValue", challenge);
        })
        .exec(http("challenge-submit")
                .post(session -> session.getString("challengeAction"))
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> "{\"challenge\":\"" + session.getString("challengeValue") + "\"}"))
                .check(status().in(200, 302))
                .check(header("Location").optional().saveAs("challengeLocation")))
        .doIf(session -> session.getString("challengeLocation") != null).then(
                exec(http("challenge-grant")
                        .get(session -> session.getString("challengeLocation"))
                        .check(status().is(200))
                        .check(bodyString().saveAs("grantBody")))
        )
        .exec(session -> {
            String grant = jsonField(session.getString("grantBody"), "grant_id");
            String csrf = jsonField(session.getString("grantBody"), "csrf");
            if (csrf != null) session = session.set("csrf", csrf);
            return session.set("grantId", grant);
        });
    }

    private static ChainBuilder catalogFlow() {
        return exec(http("catalog")
                .get("/v2/catalog")
                .check(status().is(200))
                .check(bodyString().saveAs("catalogBody")))
        .exec(session -> {
            String body = session.getString("catalogBody");
            String pid = firstProductId(body);
            String vid = firstInStockVariant(body);
            if (vid == null) vid = firstVariantId(body);
            return session.set("productId", pid).set("variantId", vid);
        });
    }

    private static ChainBuilder cartFlow() {
        return exec(http("cart-create")
                .post("/v2/carts")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> {
                    String pid = session.getString("productId");
                    String vid = session.getString("variantId");
                    String grant = session.getString("grantId");
                    StringBuilder sb = new StringBuilder("{");
                    sb.append("\"product_id\":\"").append(pid).append("\",");
                    sb.append("\"variant_id\":\"").append(vid).append("\"");
                    if (grant != null && !grant.isEmpty()) {
                        sb.append(",\"grant_id\":\"").append(grant).append("\"");
                    }
                    sb.append("}");
                    return sb.toString();
                }))
                .check(status().is(201))
                .check(header("ETag").optional().saveAs("cartEtag"))
                .check(bodyString().saveAs("cartBody")))
        .exec(session -> {
            String body = session.getString("cartBody");
            String cid = cartId(body);
            String csrf = jsonField(body, "csrf");
            if (csrf != null) session = session.set("csrf", csrf);
            return session.set("cartId", cid);
        });
    }

    private static ChainBuilder cartPatchFlow() {
        return exec(http("cart-get")
                .get(session -> "/v2/carts/" + session.getString("cartId"))
                .check(status().is(200))
                .check(header("ETag").optional().saveAs("cartEtag"))
                .check(bodyString().optional().saveAs("cartGetBody")))
        .exec(http("cart-patch")
                .patch(session -> "/v2/carts/" + session.getString("cartId"))
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("If-Match", session -> {
                    String e = session.getString("cartEtag");
                    return e == null ? "*" : e;
                })
                .body(StringBody("{\"quantity\":2}"))
                .check(status().in(200, 412))
                .check(bodyString().optional().saveAs("patchBody")))
        .exec(session -> {
            String csrf = jsonField(session.getString("patchBody"), "csrf");
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    private static ChainBuilder reservationFlow() {
        return exec(http("reservation-create")
                .post("/v2/reservations")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                .check(status().is(202))
                .check(bodyString().saveAs("reservationBody")))
        .exec(session -> {
            String body = session.getString("reservationBody");
            String statusUrl = jsonField(body, "status_url");
            String csrf = jsonField(body, "csrf");
            if (csrf != null) session = session.set("csrf", csrf);
            return session.set("statusUrl", statusUrl);
        })
        .asLongAs(session -> {
            String st = session.getString("reservationStatus");
            return st == null || "pending".equals(st);
        }, "poll").on(
                pause(Duration.ofMillis(60))
                .exec(http("reservation-status")
                        .get(session -> session.getString("statusUrl"))
                        .check(status().is(200))
                        .check(bodyString().saveAs("statusBody")))
                .exec(session -> {
                    String body = session.getString("statusBody");
                    String st = jsonField(body, "status");
                    String rid = jsonField(body, "reservation_id");
                    String csrf = jsonField(body, "csrf");
                    if (csrf != null) session = session.set("csrf", csrf);
                    return session.set("reservationStatus", st).set("reservationId", rid);
                })
        );
    }

    private static ChainBuilder orderFlow() {
        return exec(http("order-create")
                .post("/v2/orders")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                .body(StringBody(session -> {
                    String cid = session.getString("cartId");
                    String rid = session.getString("reservationId");
                    StringBuilder sb = new StringBuilder("{");
                    sb.append("\"cart_id\":\"").append(cid).append("\"");
                    if (rid != null && !rid.isEmpty()) {
                        sb.append(",\"reservation_id\":\"").append(rid).append("\"");
                    }
                    sb.append("}");
                    return sb.toString();
                }))
                .check(status().is(201))
                .check(bodyString().saveAs("orderBody")))
        .exec(session -> {
            String body = session.getString("orderBody");
            String accepted = jsonRawField(body, "accepted");
            String csrf = jsonField(body, "csrf");
            if (csrf != null) session = session.set("csrf", csrf);
            return session.set("orderAccepted", accepted);
        });
    }

    private static ChainBuilder workFlow() {
        return exec(http("work")
                .post("/v2/work")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody("{}"))
                .check(status().in(200, 429))
                .check(bodyString().optional().saveAs("workBody")))
        .exec(session -> {
            Integer status = session.getInt("workStatus");
            return session;
        });
    }

    private static ChainBuilder fullJourney() {
        return loginFlow()
                .exec(challengeFlow())
                .exec(catalogFlow())
                .exec(cartFlow())
                .exec(cartPatchFlow())
                .exec(reservationFlow())
                .exec(orderFlow())
                .exec(workFlow());
    }

    private static final ScenarioBuilder SCENARIO = scenario("ModelSimulation")
            .exec(fullJourney());

    {
        setUp(
                SCENARIO.injectOpen(
                        rampUsers(2).during(Duration.ofSeconds(1))
                )
        ).protocols(HTTP)
         .maxDuration(Duration.ofSeconds(60));
    }
}
