import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { SharedArray } from 'k6/data';
import exec from 'k6/execution';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workOk = new Counter('work_ok');
const workScheduled = new Counter('work_scheduled');
const workUnexpected = new Counter('work_unexpected');
const workBusiness = new Counter('work_business');
const workUnexpectedRate = new Rate('work_unexpected_rate');
const workLatency = new Trend('work_latency');

const USERS = ['bench-1', 'bench-2', 'bench-3', 'bench-4', 'bench-5', 'bench-6', 'bench-7', 'bench-8',
  'bench-9', 'bench-10', 'bench-11', 'bench-12', 'bench-13', 'bench-14', 'bench-15', 'bench-16'];

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      exec: 'workFlow',
      rate: 8,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 16,
      maxVUs: 32,
      startTime: '0s',
      gracefulStop: '5s',
    },
  },
  thresholds: {
    work_unexpected_rate: ['rate<0.01'],
  },
  discardResponseBodies: false,
  noConnectionReuse: false,
};

function parseCsrf(html) {
  if (!html) return null;
  const re = /<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseChallengeAction(html) {
  if (!html) return null;
  const re = /<form[^>]*action\s*=\s*["']([^"']*\/v2\/challenges\/[^"']*)["']/i;
  const m = html.match(re);
  return m ? m[1] : null;
}

function parseChallengeInput(html) {
  if (!html) return null;
  const re = /<input[^>]*name\s*=\s*["']?challenge["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function absUrl(u) {
  if (!u) return null;
  if (u.startsWith('http')) return u;
  if (u.startsWith('/')) return BASE + u;
  return BASE + '/' + u;
}

function login(jar) {
  const formRes = http.get(BASE + '/v2/login-form', { jar, redirects: 0 });
  if (formRes.status !== 200) return null;
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const user = USERS[Math.floor(Math.random() * USERS.length)];
  const loginRes = http.post(BASE + '/v2/login', JSON.stringify({
    username: user, password: 'bench', csrf,
  }), {
    jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json' },
  });
  let body = null;
  try { body = JSON.parse(loginRes.body); } catch (e) { body = null; }
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const followRes = http.get(absUrl(loc), { jar, redirects: 0 });
      try { body = JSON.parse(followRes.body); } catch (e) { body = null; }
    }
  }
  if (!body || !body.csrf) return null;
  return { csrf: body.csrf, user };
}

function renew(jar, csrf) {
  const r = http.post(BASE + '/v2/session/renew', JSON.stringify({}), {
    jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  let body = null;
  try { body = JSON.parse(r.body); } catch (e) { body = null; }
  if (body && body.csrf) return body.csrf;
  return null;
}

function doWork(jar, csrf) {
  let token = csrf;
  let attempts = 0;
  let retries429 = 0;
  while (attempts < 2) {
    attempts++;
    const res = http.post(BASE + '/v2/work', JSON.stringify({}), {
      jar,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
      redirects: 0,
      tags: { name: 'work' },
    });
    workBusiness.add(1);
    if (res.status === 429) {
      workScheduled.add(1);
      if (retries429 >= 4) {
        return { ok: false, reason: 'scheduled_exhausted' };
      }
      retries429++;
      const ra = res.headers['Retry-After'];
      let wait = 1;
      if (ra) {
        const n = parseFloat(ra);
        if (!isNaN(n)) wait = n;
      }
      sleep(wait);
      continue;
    }
    if (res.status === 401) {
      let errBody = null;
      try { errBody = JSON.parse(res.body); } catch (e) { errBody = null; }
      const err = errBody && errBody.error;
      if (err === 'expired') {
        const newCsrf = renew(jar, token);
        if (newCsrf) token = newCsrf;
        continue;
      }
      if (err === 'session') {
        const fresh = login(jar);
        if (fresh) { token = fresh.csrf; continue; }
        return { ok: false, reason: 'session_revoked' };
      }
      workUnexpected.add(1);
      workUnexpectedRate.add(1);
      return { ok: false, reason: 'denied' };
    }
    if (res.status >= 400) {
      workUnexpected.add(1);
      workUnexpectedRate.add(1);
      return { ok: false, reason: 'status_' + res.status };
    }
    let body = null;
    try { body = JSON.parse(res.body); } catch (e) { body = null; }
    if (body && body.ok === true) {
      workOk.add(1);
      workUnexpectedRate.add(0);
      workLatency.add(res.timings.duration);
      return { ok: true, csrf: token };
    }
    workUnexpected.add(1);
    workUnexpectedRate.add(1);
    return { ok: false, reason: 'bad_body' };
  }
  return { ok: false, reason: 'retry_exhausted' };
}

export function workFlow() {
  const jar = http.cookieJar();
  const auth = login(jar);
  if (!auth) {
    workUnexpectedRate.add(1);
    return;
  }
  const r = doWork(jar, auth.csrf);
  check(r, { 'work ok': (v) => v.ok === true });
}
