import os
import re
import time
import uuid
import random
from urllib.parse import urljoin

from locust import HttpUser, task, between, events
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL + "/", url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.0, 0.0)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.password = "bench"
        self.csrf = None
        self.session_ready = False
        self.cart_id = None
        self.cart_etag = None
        self.iterations_done = 0
        self.max_iterations = 2

    # ---------- low level helpers ----------
    def _get(self, path, name=None, allow_redirects=False, **kw):
        return self.client.get(path, name=name or path, allow_redirects=allow_redirects, **kw)

    def _post(self, path, name=None, allow_redirects=False, **kw):
        return self.client.post(path, name=name or path, allow_redirects=allow_redirects, **kw)

    def _headers_csrf(self, extra=None):
        h = {}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if extra:
            h.update(extra)
        return h

    def _extract_csrf_from_html(self, text):
        # input[name=csrf] mixed with decoys/attribute variants
        if not text:
            return None
        # try value before name and after
        patterns = [
            r'<input[^>]*name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']',
            r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']',
        ]
        for p in patterns:
            m = re.search(p, text, re.IGNORECASE)
            if m:
                return m.group(1)
        return None

    def _extract_challenge_action(self, text):
        if not text:
            return None
        m = re.search(r'<form[^>]*action=["\']([^"\']*?/v2/challenges/[^"\']+)["\']', text, re.IGNORECASE)
        if m:
            return m.group(1)
        m = re.search(r'action=["\']([^"\']*?/v2/challenges/[^"\']+)["\']', text, re.IGNORECASE)
        if m:
            return m.group(1)
        return None

    def _extract_challenge_input(self, text):
        if not text:
            return None
        patterns = [
            r'<input[^>]*name=["\']challenge["\'][^>]*value=["\']([^"\']*)["\']',
            r'<input[^>]*value=["\']([^"\']*)["\'][^>]*name=["\']challenge["\']',
        ]
        for p in patterns:
            m = re.search(p, text, re.IGNORECASE)
            if m:
                return m.group(1)
        return None

    # ---------- auth ----------
    def do_login(self):
        # fresh login each journey
        self.csrf = None
        self.session_ready = False
        self.cart_id = None
        self.cart_etag = None

        with self.client.get("/v2/login-form", name="GET /v2/login-form",
                             allow_redirects=False, catch_response=True) as r:
            if r.status_code >= 400:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = self._extract_csrf_from_html(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return False
            self.csrf = csrf

        payload = {"username": self.username, "password": self.password, "csrf": self.csrf}
        with self.client.post("/v2/login", json=payload, name="POST /v2/login",
                              allow_redirects=False, catch_response=True) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(_abs(loc), name="GET login redirect",
                                     allow_redirects=False, catch_response=True) as r2:
                    if r2.status_code >= 400:
                        r2.failure("login redirect status %s" % r2.status_code)
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        data = None
                    if isinstance(data, dict) and data.get("csrf"):
                        self.csrf = data["csrf"]
            elif r.status_code >= 400:
                r.failure("login status %s" % r.status_code)
                return False
            else:
                try:
                    data = r.json()
                except Exception:
                    data = None
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]

        if not self.csrf:
            return False
        self.session_ready = True
        return True

    def renew_session(self):
        if not self.csrf:
            return False
        with self.client.post("/v2/session/renew", json={}, name="POST /v2/session/renew",
                              headers=self._headers_csrf(), allow_redirects=False,
                              catch_response=True) as r:
            if r.status_code >= 400:
                r.failure("renew status %s" % r.status_code)
                return False
            try:
                data = r.json()
            except Exception:
                data = None
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]
            return True

    def recover_cart(self):
        if not self.cart_id:
            return True
        with self.client.post("/v2/carts/%s/recover" % self.cart_id, json={},
                              name="POST /v2/carts/{id}/recover",
                              headers=self._headers_csrf(), allow_redirects=False,
                              catch_response=True) as r:
            if r.status_code >= 400:
                r.failure("recover status %s" % r.status_code)
                return False
            try:
                data = r.json()
            except Exception:
                data = None
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]
            return True

    def handle_401(self, resp):
        """Return True if recovered (caller may retry once)."""
        try:
            data = resp.json()
        except Exception:
            data = {}
        err = (data or {}).get("error")
        if err == "expired":
            if self.renew_session():
                self.recover_cart()
                return True
            return False
        if err == "session":
            # revoked: fresh login
            if self.do_login():
                self.recover_cart()
                return True
            return False
        # denied or unknown -> not recoverable
        return False

    # ---------- catalog ----------
    def fetch_catalog(self):
        with self.client.get("/v2/catalog", name="GET /v2/catalog",
                             allow_redirects=False, catch_response=True) as r:
            if r.status_code == 401:
                if self.handle_401(r):
                    return self.fetch_catalog()
                r.failure("catalog 401 unrecoverable")
                return None
            if r.status_code >= 400:
                r.failure("catalog status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("catalog bad json")
                return None
        products = (((data or {}).get("data") or {}).get("products")) or []
        return products

    def fetch_catalog_page(self, url):
        with self.client.get(_abs(url), name="GET /v2/catalog/page",
                             allow_redirects=False, catch_response=True) as r:
            if r.status_code == 401:
                if self.handle_401(r):
                    return self.fetch_catalog_page(url)
                r.failure("catalog page 401 unrecoverable")
                return None
            if r.status_code >= 400:
                r.failure("catalog page status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("catalog page bad json")
                return None
        return data

    def pick_variant(self):
        products = self.fetch_catalog()
        if products:
            for p in products:
                for v in (p.get("variants") or []):
                    if v.get("in_stock"):
                        return p.get("id"), v.get("id")
        # fallback: traverse pages
        url = "/v2/catalog/page"
        for _ in range(3):
            data = self.fetch_catalog_page(url)
            if not data:
                break
            prod = data.get("product") or data.get("data")
            if isinstance(prod, dict):
                for v in (prod.get("variants") or []):
                    if v.get("in_stock"):
                        return prod.get("id"), v.get("id")
            nxt = data.get("next")
            if not nxt:
                break
            url = nxt
        return None, None

    # ---------- challenge ----------
    def solve_challenge(self):
        with self.client.get("/v2/challenge-form", name="GET /v2/challenge-form",
                             allow_redirects=False, catch_response=True) as r:
            if r.status_code >= 400:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            action = self._extract_challenge_action(r.text)
            chal = self._extract_challenge_input(r.text)
            if not action or chal is None:
                r.failure("challenge form parse failed")
                return None
        with self.client.post(_abs(action), json={"challenge": chal},
                              name="POST /v2/challenges/{id}",
                              headers=self._headers_csrf(), allow_redirects=False,
                              catch_response=True) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge 302 no Location")
                    return None
                with self.client.get(_abs(loc), name="GET challenge redirect",
                                     allow_redirects=False, catch_response=True) as r2:
                    if r2.status_code >= 400:
                        r2.failure("challenge redirect status %s" % r2.status_code)
                        return None
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("challenge redirect bad json")
                        return None
                    if isinstance(data, dict) and data.get("csrf"):
                        self.csrf = data["csrf"]
                    return (data or {}).get("grant_id")
            elif r.status_code >= 400:
                r.failure("challenge status %s" % r.status_code)
                return None
            else:
                try:
                    data = r.json()
                except Exception:
                    data = None
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                return (data or {}).get("grant_id") if isinstance(data, dict) else None

    # ---------- cart ----------
    def create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload, name="POST /v2/carts",
                              headers=self._headers_csrf(), allow_redirects=False,
                              catch_response=True) as r:
            if r.status_code == 401:
                if self.handle_401(r):
                    return self.create_cart(product_id, variant_id, grant_id)
                r.failure("cart 401 unrecoverable")
                return None
            if r.status_code >= 400:
                r.failure("cart status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("cart bad json")
                return None
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]
            self.cart_id = (data or {}).get("id")
            self.cart_etag = r.headers.get("ETag")
            return self.cart_id

    def get_cart(self):
        if not self.cart_id:
            return None
        with self.client.get("/v2/carts/%s" % self.cart_id, name="GET /v2/carts/{id}",
                             allow_redirects=False, catch_response=True) as r:
            if r.status_code == 401:
                if self.handle_401(r):
                    return self.get_cart()
                r.failure("get cart 401 unrecoverable")
                return None
            if r.status_code >= 400:
                r.failure("get cart status %s" % r.status_code)
                return None
            self.cart_etag = r.headers.get("ETag")
            return True

    def patch_cart(self, quantity):
        if not self.cart_id:
            return False
        payload = {"quantity": quantity}
        for attempt in range(2):
            headers = self._headers_csrf()
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            with self.client.patch("/v2/carts/%s" % self.cart_id, json=payload,
                                   name="PATCH /v2/carts/{id}",
                                   headers=headers, allow_redirects=False,
                                   catch_response=True) as r:
                if r.status_code == 401:
                    if self.handle_401(r):
                        continue
                    r.failure("patch 401 unrecoverable")
                    return False
                if r.status_code == 412:
                    # re-read and retry same payload once
                    if attempt == 0:
                        if self.get_cart():
                            continue
                    r.failure("patch 412 after retry")
                    return False
                if r.status_code >= 400:
                    r.failure("patch status %s" % r.status_code)
                    return False
                if r.headers.get("ETag"):
                    self.cart_etag = r.headers.get("ETag")
                try:
                    data = r.json()
                except Exception:
                    data = None
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
        return False

    # ---------- reservation ----------
    def reserve(self):
        if not self.cart_id:
            return None
        with self.client.post("/v2/reservations", json={"cart_id": self.cart_id},
                              name="POST /v2/reservations",
                              headers=self._headers_csrf(), allow_redirects=False,
                              catch_response=True) as r:
            if r.status_code == 401:
                if self.handle_401(r):
                    return self.reserve()
                r.failure("reservation 401 unrecoverable")
                return None
            if r.status_code >= 400:
                r.failure("reservation status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("reservation bad json")
                return None
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]
            status_url = (data or {}).get("status_url")
        if not status_url:
            return None
        for i in range(5):
            if i > 0:
                time.sleep(0.06)
            with self.client.get(_abs(status_url), name="GET reservation status",
                                 allow_redirects=False, catch_response=True) as r:
                if r.status_code == 401:
                    if self.handle_401(r):
                        continue
                    r.failure("res status 401 unrecoverable")
                    return None
                if r.status_code >= 400:
                    r.failure("res status %s" % r.status_code)
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("res status bad json")
                    return None
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                status = (data or {}).get("status")
                if status == "ready":
                    return (data or {}).get("reservation_id")
                if status in ("pending",):
                    continue
                if status in ("failed",):
                    return None
        return None

    # ---------- order ----------
    def place_order(self, reservation_id):
        if not self.cart_id:
            return False
        payload = {"cart_id": self.cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        idem = "idem-%s-%s" % (self.cart_id, uuid.uuid4().hex)
        for attempt in range(2):
            headers = self._headers_csrf({"Idempotency-Key": idem})
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            with self.client.post("/v2/orders", json=payload, name="POST /v2/orders",
                                  headers=headers, allow_redirects=False,
                                  catch_response=True) as r:
                if r.status_code == 401:
                    if self.handle_401(r):
                        continue
                    r.failure("order 401 unrecoverable")
                    return False
                if r.status_code >= 400:
                    r.failure("order status %s" % r.status_code)
                    return False
                try:
                    data = r.json()
                except Exception:
                    r.failure("order bad json")
                    return False
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                if r.status_code == 200 and isinstance(data, dict) and data.get("accepted") is False:
                    r.failure("order accepted:false")
                    return False
                if isinstance(data, dict) and data.get("accepted") is True:
                    return True
                r.failure("order unexpected body")
                return False
        return False

    # ---------- work ----------
    def do_work(self):
        """POST /v2/work with scheduled 429 handling. Returns True on success."""
        for attempt in range(5):
            with self.client.post("/v2/work", json={}, name="POST /v2/work",
                                  headers=self._headers_csrf(), allow_redirects=False,
                                  catch_response=True) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After")
                    try:
                        delay = float(ra) if ra is not None else 1.0
                    except Exception:
                        delay = 1.0
                    if delay < 0:
                        delay = 1.0
                    # scheduled 429 is expected, not a failure
                    if attempt < 4:
                        time.sleep(delay)
                        continue
                    r.failure("work 429 exhausted retries")
                    return False
                if r.status_code == 401:
                    if self.handle_401(r):
                        continue
                    r.failure("work 401 unrecoverable")
                    return False
                if r.status_code >= 500:
                    r.failure("work status %s" % r.status_code)
                    return False
                if r.status_code >= 400:
                    r.failure("work status %s" % r.status_code)
                    return False
                try:
                    data = r.json()
                except Exception:
                    r.failure("work bad json")
                    return False
                if isinstance(data, dict) and data.get("ok") is True:
                    return True
                r.failure("work not ok")
                return False
        return False

    # ---------- journey ----------
    def run_journey(self):
        if not self.do_login():
            return False
        product_id, variant_id = self.pick_variant()
        if not product_id or not variant_id:
            return False
        grant_id = self.solve_challenge()
        if not self.create_cart(product_id, variant_id, grant_id):
            return False
        if not self.patch_cart(random.randint(1, 3)):
            return False
        reservation_id = self.reserve()
        if not reservation_id:
            return False
        if not self.place_order(reservation_id):
            return False
        return True

    @task
    def main_task(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        # assign username deterministically per user
        if self.username is None:
            idx = (id(self) % 16) + 1
            self.username = "bench-%d" % idx
        ok = self.run_journey()
        if ok:
            self.do_work()
        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


