class LoadTestShape:
    """Phased shape: warmup 5s, three 10s plateaus at 5/15/5, drain <=5s."""

    def __init__(self):
        self.start = None

    def tick(self):
        now = time.time()
        if self.start is None:
            self.start = now
        t = now - self.start
        # warmup 5s
        if t < 5:
            return (2, 2)
        # plateau 1: 5 users for 10s
        if t < 15:
            return (5, 5)
        # plateau 2: 15 users for 10s
        if t < 25:
            return (15, 15)
        # plateau 3: 5 users for 10s
        if t < 35:
            return (5, 5)
        # drain
        if t < 40:
            return (1, 1)
        return None
