import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.atomic.AtomicInteger;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .shareConnections();

    // ---- CSRF / session helpers ----
    private static final String CSRF = "#{csrf}";

    private static ChainBuilder login() {
        return exec(
                http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(regex("name=\"csrf\"[^>]*value=\"([^\"]+)\"").saveAs("csrf"))
        ).exec(
                http("login")
                        .post("/v2/login")
                        .body(StringBody("{\"username\":\"#{user}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLoc"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
        ).exec(session -> {
            String loc = session.getString("loginLoc");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginLoc", loc);
            }
            return session;
        }).doIf(session -> session.getString("loginLoc") != null).then(
                http("login-redirect")
                        .get("#{loginLoc}")
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
        ).exec(session -> {
            String c = session.getString("csrf2");
            if (c != null && !c.isEmpty()) {
                return session.set("csrf", c);
            }
            return session;
        });
    }

    private static ChainBuilder renew() {
        return exec(
                http("renew")
                        .post("/v2/session/renew")
                        .header("X-CSRF-Token", CSRF)
                        .body(StringBody("{}"))
                        .check(status().in(200, 401))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
        ).exec(session -> {
            String c = session.getString("csrf2");
            if (c != null && !c.isEmpty()) {
                return session.set("csrf", c);
            }
            return session;
        });
    }

    // ---- Work operation (the pool) ----
    private static ChainBuilder workOnce() {
        return exec(
                http("work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", CSRF)
                        .body(StringBody("{}"))
                        .check(status().in(200, 401, 429, 500))
                        .check(jsonPath("$.ok").optional().saveAs("ok"))
                        .check(jsonPath("$.error").optional().saveAs("err"))
                        .check(header("Retry-After").optional().saveAs("retryAfter"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
        ).exec(session -> {
            String c = session.getString("csrf2");
            if (c != null && !c.isEmpty()) {
                return session.set("csrf", c);
            }
            return session;
        });
    }

    private static ChainBuilder workWithRecovery() {
        return exec(workOnce())
                .doIf(session -> {
                    Integer s = session.getInt("status");
                    return s != null && s == 401;
                }).then(
                        exec(session -> {
                            String err = session.getString("err");
                            if ("denied".equals(err)) {
                                return session.markAsFailed();
                            }
                            return session;
                        })
                        .exec(renew())
                        .exec(workOnce())
                )
                .doIf(session -> {
                    Integer s = session.getInt("status");
                    return s != null && s == 429;
                }).then(
                        pause(Duration.ofSeconds(1))
                        .exec(workOnce())
                );
    }

    // ---- Journey (checkout) ----
    private static ChainBuilder journey() {
        return exec(login())
                .exec(
                        http("catalog")
                                .get("/v2/catalog")
                                .check(status().is(200))
                                .check(jsonPath("$.data.products[0].id").saveAs("pid"))
                                .check(jsonPath("$.data.products[0].variants[0].id").saveAs("vid"))
                )
                .exec(
                        http("cart-create")
                                .post("/v2/carts")
                                .header("X-CSRF-Token", CSRF)
                                .body(StringBody("{\"product_id\":\"#{pid}\",\"variant_id\":\"#{vid}\"}"))
                                .check(status().is(201))
                                .check(jsonPath("$.id").saveAs("cartId"))
                                .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
                                .check(header("ETag").optional().saveAs("etag"))
                )
                .exec(session -> {
                    String c = session.getString("csrf2");
                    if (c != null && !c.isEmpty()) {
                        return session.set("csrf", c);
                    }
                    return session;
                })
                .exec(
                        http("cart-get")
                                .get("/v2/carts/#{cartId}")
                                .check(status().is(200))
                                .check(header("ETag").optional().saveAs("etag"))
                )
                .exec(
                        http("cart-patch")
                                .patch("/v2/carts/#{cartId}")
                                .header("X-CSRF-Token", CSRF)
                                .header("If-Match", "#{etag}")
                                .body(StringBody("{\"quantity\":1}"))
                                .check(status().in(200, 412))
                                .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
                )
                .exec(session -> {
                    String c = session.getString("csrf2");
                    if (c != null && !c.isEmpty()) {
                        return session.set("csrf", c);
                    }
                    return session;
                })
                .exec(
                        http("order")
                                .post("/v2/orders")
                                .header("X-CSRF-Token", CSRF)
                                .header("Idempotency-Key", "#{cartId}-order")
                                .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                                .check(status().is(201))
                                .check(jsonPath("$.accepted").is("true"))
                                .check(jsonPath("$.id").saveAs("orderId"))
                                .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
                )
                .exec(session -> {
                    String c = session.getString("csrf2");
                    if (c != null && !c.isEmpty()) {
                        return session.set("csrf", c);
                    }
                    return session;
                });
    }

    // ---- Rate control: 10 starts/s, phased 5/15/5 over three 10s plateaus ----
    // We use a shared atomic counter to gate work starts per second.
    private static final AtomicInteger workStartsThisSecond = new AtomicInteger(0);
    private static volatile long currentSecond = -1;

    private static boolean tryAcquireWork() {
        long now = System.currentTimeMillis() / 1000;
        if (now != currentSecond) {
            synchronized (ModelSimulation.class) {
                if (now != currentSecond) {
                    currentSecond = now;
                    workStartsThisSecond.set(0);
                }
            }
        }
        return workStartsThisSecond.incrementAndGet() <= 10;
    }

    private static ChainBuilder pacedWork() {
        return exec(session -> {
            // spin-wait until we can acquire a slot in this second
            long deadline = System.currentTimeMillis() + 2000;
            while (System.currentTimeMillis() < deadline) {
                if (tryAcquireWork()) {
                    return session;
                }
                try {
                    Thread.sleep(5);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return session.markAsFailed();
                }
            }
            return session.markAsFailed();
        }).exec(workWithRecovery());
    }

    private static final AtomicInteger userCounter = new AtomicInteger(0);

    private ScenarioBuilder scenario() {
        return scenario("Model")
                .exec(session -> {
                    int idx = userCounter.incrementAndGet();
                    String user = "bench-" + ((idx % 16) + 1);
                    return session.set("user", user);
                })
                .exec(login())
                .during(Duration.ofSeconds(40)).on(
                        exec(pacedWork())
                );
    }

    {
        setUp(
                scenario().injectOpen(
                        rampUsers(2).during(Duration.ofSeconds(1))
                )
        ).protocols(HTTP)
                .maxDuration(Duration.ofSeconds(60));
    }
}
