import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { randomIntBetween } from 'https://jslib.k6.io/k6-utils/1.2.0/index.js';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workOk = new Counter('work_ok');
const workScheduled = new Counter('work_scheduled');
const workUnexpected = new Counter('work_unexpected');
const workDropped = new Counter('work_dropped');
const workLatency = new Trend('work_latency');
const businessFailure = new Rate('business_failure');

const TARGET_RATE = 10;
const WARMUP = 5;
const SCORE_START = 5;
const SCORE_END = 35;
const DRAIN = 5;
const TOTAL = SCORE_END + DRAIN; // 40s

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE,
      timeUnit: '1s',
      duration: `${TOTAL}s`,
      preAllocatedVUs: 8,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    work_unexpected: ['count<10'],
    business_failure: ['rate<0.01'],
  },
  discardResponseBodies: false,
  noConnectionReuse: false,
};

function parseCsrf(html) {
  if (!html) return null;
  // input[name=csrf] with attribute variants
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = html.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function parseLoginNonce(res) {
  // cookie login_nonce
  const cookies = res.cookies || {};
  if (cookies['login_nonce'] && cookies['login_nonce'].length) {
    return cookies['login_nonce'][0].value;
  }
  return null;
}

function getCookie(jar, name) {
  const cookies = jar.cookiesForURL(BASE);
  if (cookies[name] && cookies[name].length) return cookies[name][0];
  return null;
}

function login() {
  const jar = http.cookieJar();
  jar.clear(BASE);
