import http from 'k6/http';
import { sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workOk = new Counter('work_ok');
const workScheduled = new Counter('work_scheduled');
const workUnexpected = new Counter('work_unexpected');
const workDropped = new Counter('work_dropped');
const workLatency = new Trend('work_latency');
const businessFailure = new Rate('business_failure');

const TARGET_RATE = 10;
const TOTAL = 40;

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE,
      timeUnit: '1s',
      duration: `${TOTAL}s`,
      preAllocatedVUs: 24,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
};

function parseCsrf(html) {
  if (!html) return null;
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = html.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function login() {
  const jar = http.cookieJar();
  jar.clear(BASE);
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0, tags: { name: 'login-form' } });
  if (formRes.status !== 200) return null;
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({ username: 'bench-1', password: 'bench', csrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });
  let body = null;
  try { body = loginRes.json(); } catch (e) { body = null; }
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0, tags: { name: 'login-follow' } });
      try { body = follow.json(); } catch (e) { body = null; }
    }
  }
  if (!body || !body.csrf) return null;
  return { csrf: body.csrf, user: body.user };
}

function renew(csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'renew' },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (res.status === 200 && body && body.csrf) return body.csrf;
  return null;
}

function doWork(csrf) {
  return http.post(`${BASE}/v2/work`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'work' },
  });
}

function handleWork(res, csrf, setCsrf, depth) {
  if (depth > 4) {
    workUnexpected.add(1);
    businessFailure.add(true);
    return;
  }
  const status = res.status;
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }

  if (status === 429) {
    workScheduled.add(1);
    businessFailure.add(false);
    const ra = res.headers['Retry-After'];
    const wait = ra ? parseFloat(ra) : 1;
    sleep(Math.min(wait, 1));
    const retry = doWork(csrf);
    handleWork(retry, csrf, setCsrf, depth + 1);
    return;
  }
  if (status === 401) {
    if (body && body.error === 'expired') {
      businessFailure.add(false);
      const newCsrf = renew(csrf);
      if (newCsrf) {
        setCsrf(newCsrf);
        const retry = doWork(newCsrf);
        handleWork(retry, newCsrf, setCsrf, depth + 1);
        return;
      }
    }
    if (body && (body.error === 'expired' || body.error === 'session')) {
      const auth = login();
      if (auth) {
        setCsrf(auth.csrf);
        const retry = doWork(auth.csrf);
        handleWork(retry, auth.csrf, setCsrf, depth + 1);
        return;
      }
    }
    workUnexpected.add(1);
    businessFailure.add(true);
    return;
  }
  if (status >= 400) {
    workUnexpected.add(1);
    businessFailure.add(true);
    return;
  }
  if (status === 200 && body && body.ok === true) {
    workOk.add(1);
    businessFailure.add(false);
    workLatency.add(res.timings.duration);
    return;
  }
  workUnexpected.add(1);
  businessFailure.add(true);
}

export default function () {
  const auth = login();
  if (!auth) {
    workDropped.add(1);
    return;
  }
  let csrf = auth.csrf;
  const res = doWork(csrf);
  handleWork(res, csrf, (c) => { csrf = c; }, 0);
}
