import os
import re
import time
import uuid
import random
from urllib.parse import urljoin

from locust import HttpUser, task, between, events
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL + "/", url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.password = "bench"
        self.csrf = None
        self.session_ready = False
        self.iterations_done = 0
        self.max_iterations = 2

    # ---------- helpers ----------
    def _pick_account(self):
        if self.username is None:
            self.username = "bench-%d" % random.randint(1, 16)

    def _extract_csrf_from_form(self, text):
        # input[name=csrf] with mixed attribute variants
        m = re.search(
            r'<input[^>]*name\s*=\s*["\']?csrf["\']?[^>]*>',
            text,
            re.IGNORECASE,
        )
        if not m:
            return None
        tag = m.group(0)
        vm = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
        if vm:
            return vm.group(1)
        return None

    def _extract_challenge_form(self, text):
        action = None
        am = re.search(
            r'<form[^>]*action\s*=\s*["\']([^"\']+)["\']',
            text,
            re.IGNORECASE,
        )
        if am:
            action = am.group(1)
        cm = re.search(
            r'<input[^>]*name\s*=\s*["\']?challenge["\']?[^>]*>',
            text,
            re.IGNORECASE,
        )
        challenge = None
        if cm:
            tag = cm.group(0)
            vm = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
            if vm:
                challenge = vm.group(1)
        return action, challenge

    def _login(self):
        self._pick_account()
        with self.client.get(
            "/v2/login-form",
            name="GET /v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code >= 400:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = self._extract_csrf_from_form(r.text or "")
            if not csrf:
                r.failure("no csrf in login form")
                return False
            r.success()

        payload = {
            "username": self.username,
            "password": self.password,
            "csrf": csrf,
        }
        with self.client.post(
            "/v2/login",
            json=payload,
            name="POST /v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(
                    _abs(loc),
                    name="GET login redirect",
                    catch_response=True,
                    allow_redirects=False,
                ) as r2:
                    if r2.status_code >= 400:
                        r2.failure("redirect status %s" % r2.status_code)
                        return False
                    r2.success()
                r.success()
            elif r.status_code >= 400:
                r.failure("login status %s" % r.status_code)
                return False
            else:
                try:
                    data = r.json()
                except Exception:
                    r.failure("login not json")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                r.success()

        if not self.csrf:
            # try to fetch a fresh csrf via login-form again
            with self.client.get(
                "/v2/login-form",
                name="GET /v2/login-form",
                catch_response=True,
                allow_redirects=False,
            ) as r:
                if r.status_code < 400:
                    c = self._extract_csrf_from_form(r.text or "")
                    if c:
                        self.csrf = c
                    r.success()
                else:
                    r.failure("login-form status %s" % r.status_code)
                    return False

        self.session_ready = True
        return True

    def _headers(self, extra=None):
        h = {}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if extra:
            h.update(extra)
        return h

    def _renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._headers(),
            name="POST /v2/session/renew",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code >= 400:
                r.failure("renew status %s" % r.status_code)
                return False
            try:
                data = r.json()
            except Exception:
                data = {}
            if data.get("csrf"):
                self.csrf = data["csrf"]
            r.success()
            return True

    def _recover_cart(self, cart_id):
        with self.client.post(
            "/v2/carts/%s/recover" % cart_id,
            json={},
            headers=self._headers(),
            name="POST /v2/carts/{id}/recover",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code >= 400:
                r.failure("recover status %s" % r.status_code)
