            if d.get("csrf"):
                self.csrf = d["csrf"]
            r.success()
            return True

    def _reserve(self, cart_id):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": cart_id},
            headers=self._headers(),
            name="POST /v2/reservations",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    r.success()
                    return None
                r.failure("reservation 401 unrecoverable")
                return None
            if r.status_code >= 400:
                r.failure("reservation status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("reservation not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            status_url = data.get("status_url")
            r.success()

        if not status_url:
            return None
        status_url = _abs(status_url)
        for _ in range(5):
            time.sleep(0.06)
            with self.client.get(
                status_url,
                name="GET reservation status",
                catch_response=True,
                allow_redirects=False,
            ) as r:
                if r.status_code >= 400:
                    r.failure("res status %s" % r.status_code)
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("res status not json")
                    return None
                r.success()
            status = data.get("status")
            if status == "ready":
                return data.get("reservation_id")
            if status in ("pending",):
                continue
            return None
        return None

    def _checkout(self, cart_id, reservation_id, idem_key):
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = self._headers({"Idempotency-Key": idem_key})
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            name="POST /v2/orders",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    r.success()
                    return False
                r.failure("order 401 unrecoverable")
                return False
            if r.status_code >= 400:
                r.failure("order status %s" % r.status_code)
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("order not json")
                return False
            if data.get("csrf"):
                self.csrf = data["csrf"]
            if data.get("accepted") is True:
                r.success()
                return True
            r.failure("order not accepted")
            return False

    def _do_work(self):
        # POST /v2/work with scheduled 429 handling
        retries = 0
        while retries <= 4:
            with self.client.post(
                "/v2/work",
                json={},
                headers=self._headers(),
                name="POST /v2/work",
                catch_response=True,
                allow_redirects=False,
            ) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        wait = float(ra)
                    except Exception:
                        wait = 1.0
                    r.success()
                    time.sleep(max(0.05, wait))
                    retries += 1
                    continue
                if r.status_code == 401:
                    if self._handle_401(r):
                        r.success()
                        return True
                    r.failure("work 401 unrecoverable")
                    return False
                if r.status_code >= 500:
                    r.failure("work status %s" % r.status_code)
                    return False
                if r.status_code >= 400:
                    r.failure("work status %s" % r.status_code)
                    return False
                try:
                    data = r.json()
                except Exception:
                    r.failure("work not json")
                    return False
                if data.get("ok") is True:
                    r.success()
                    return True
                r.failure("work not ok")
                return False
        return False

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        if not self.session_ready:
            if not self._login():
                self.iterations_done += 1
                if self.iterations_done >= self.max_iterations:
                    raise StopUser()
                return

        # fresh cart per journey
        prod = self._get_catalog_product()
        if not prod:
            prod = self._get_catalog_page_product()
        if not prod:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        product_id, variant_id = prod

        grant_id = None
        cart = self._create_cart(product_id, variant_id, grant_id)
        if cart is None:
            # maybe challenge required
            grant_id = self._solve_challenge()
            if grant_id:
                cart = self._create_cart(product_id, variant_id, grant_id)
        if cart is None or not cart.get("id"):
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        cart_id = cart["id"]
        etag = cart.get("etag")

        if not self._patch_cart(cart_id, etag, random.randint(1, 5)):
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        reservation_id = self._reserve(cart_id)
        if reservation_id is None:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        idem_key = str(uuid.uuid4())
        self._checkout(cart_id, reservation_id, idem_key)

        # the pool operation
        self._do_work()

        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


