import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.atomic.AtomicInteger;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableCaching()
            .disableFollowRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    // ---- shared helpers ----

    private static final AtomicInteger IDEMP = new AtomicInteger(0);

    private static String idemKey() {
        return "idem-" + System.nanoTime() + "-" + IDEMP.incrementAndGet();
    }

    private static final String CSRF = "csrf";
    private static final String CART_ID = "cartId";
    private static final String ETAG = "etag";
    private static final String PRODUCT_ID = "productId";
    private static final String VARIANT_ID = "variantId";
    private static final String GRANT_ID = "grantId";
    private static final String RESERVATION_ID = "reservationId";
    private static final String ORDER_ID = "orderId";
    private static final String IDEM = "idemKey";

    // ---- login / session ----

    private static ChainBuilder login() {
        return exec(
                http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(regex("name=\"csrf\"[^>]*value=\"([^\"]+)\"").saveAs(CSRF))
        ).exec(
                http("login")
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String csrf = session.getString(CSRF);
                            String user = session.getString("username");
                            return "{\"username\":\"" + user + "\",\"password\":\"bench\",\"csrf\":\"" + csrf + "\"}";
                        }))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginBody"))
        ).exec(session -> {
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginRedirect", loc);
            }
            return session;
        }).doIf(session -> session.contains("loginRedirect")).then(
                exec(
                        http("login-redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().is(200))
                                .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").saveAs(CSRF))
                )
        ).exec(session -> {
            if (!session.contains("loginRedirect")) {
                String body = session.getString("loginBody");
                if (body != null) {
                    java.util.regex.Matcher m = java.util.regex.Pattern
                            .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                    if (m.find()) {
                        return session.set(CSRF, m.group(1));
                    }
                }
            }
            return session;
        });
    }

    private static ChainBuilder renew() {
        return exec(
                http("renew")
                        .post("/v2/session/renew")
                        .header("X-CSRF-Token", session -> session.getString(CSRF))
                        .body(StringBody("{}"))
                        .check(status().in(200, 401))
                        .check(bodyString().optional().saveAs("renewBody"))
        ).exec(session -> {
            String body = session.getString("renewBody");
            if (body != null) {
                java.util.regex.Matcher m = java.util.regex.Pattern
                        .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                if (m.find()) {
                    return session.set(CSRF, m.group(1));
                }
            }
            return session;
        });
    }

    // ---- catalog ----

    private static ChainBuilder pickProduct() {
        return exec(
                http("catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[0].id").saveAs(PRODUCT_ID))
                        .check(jsonPath("$.data.products[0].variants[?(@.in_stock==true)][0].id").saveAs(VARIANT_ID))
        );
    }

    // ---- cart ----

    private static ChainBuilder createCart() {
        return exec(
                http("cart-create")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString(CSRF))
                        .body(StringBody(session -> {
                            String pid = session.getString(PRODUCT_ID);
                            String vid = session.getString(VARIANT_ID);
                            String grant = session.getString(GRANT_ID);
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"product_id\":\"").append(pid)
                              .append("\",\"variant_id\":\"").append(vid).append("\"");
                            if (grant != null && !grant.isEmpty()) {
                                sb.append(",\"grant_id\":\"").append(grant).append("\"");
                            }
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().is(201))
                        .check(jsonPath("$.id").saveAs(CART_ID))
                        .check(jsonPath("$.csrf").optional().saveAs("cartCsrf"))
                        .check(header("ETag").optional().saveAs(ETAG))
        ).exec(session -> {
            String c = session.getString("cartCsrf");
            if (c != null && !c.isEmpty()) {
                return session.set(CSRF, c);
            }
            return session;
        });
    }

    private static ChainBuilder patchCart() {
        return exec(
                http("cart-patch")
                        .patch(session -> "/v2/carts/" + session.getString(CART_ID))
                        .header("X-CSRF-Token", session -> session.getString(CSRF))
                        .header("If-Match", session -> session.getString(ETAG))
                        .body(StringBody("{\"quantity\":1}"))
                        .check(status().in(200, 412))
                        .check(header("ETag").optional().saveAs(ETAG))
        ).doIf(session -> session.getInt("cartPatchStatus") == 412).then(
                exec(
                        http("cart-reread")
                                .get(session -> "/v2/carts/" + session.getString(CART_ID))
                                .check(status().is(200))
                                .check(header("ETag").saveAs(ETAG))
                ).exec(
                        http("cart-patch-retry")
                                .patch(session -> "/v2/carts/" + session.getString(CART_ID))
                                .header("X-CSRF-Token", session -> session.getString(CSRF))
                                .header("If-Match", session -> session.getString(ETAG))
                                .body(StringBody("{\"quantity\":1}"))
                                .check(status().is(200))
                                .check(header("ETag").optional().saveAs(ETAG))
                )
        );
    }

    // ---- checkout ----

    private static ChainBuilder checkout() {
        return exec(session -> session.set(IDEM, idemKey()))
                .exec(
                        http("order-create")
                                .post("/v2/orders")
                                .header("X-CSRF-Token", session -> session.getString(CSRF))
                                .header("Idempotency-Key", session -> session.getString(IDEM))
                                .header("If-Match", session -> session.getString(ETAG))
                                .body(StringBody(session -> {
                                    String cart = session.getString(CART_ID);
                                    String res = session.getString(RESERVATION_ID);
                                    StringBuilder sb = new StringBuilder();
                                    sb.append("{\"cart_id\":\"").append(cart).append("\"");
                                    if (res != null && !res.isEmpty()) {
                                        sb.append(",\"reservation_id\":\"").append(res).append("\"");
                                    }
                                    sb.append("}");
                                    return sb.toString();
                                }))
                                .check(status().in(201, 200))
                                .check(bodyString().saveAs("orderBody"))
                ).exec(session -> {
                    String body = session.getString("orderBody");
                    boolean accepted = body != null && body.contains("\"accepted\":true");
                    if (accepted) {
                        java.util.regex.Matcher m = java.util.regex.Pattern
                                .compile("\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (m.find()) {
                            session = session.set(ORDER_ID, m.group(1));
                        }
                        java.util.regex.Matcher c = java.util.regex.Pattern
                                .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (c.find()) {
                            session = session.set(CSRF, c.group(1));
                        }
                        return session.set("orderCommitted", true);
                    }
                    return session.set("orderCommitted", false);
                });
    }

    // ---- browse work ----

    private static ChainBuilder browseWork() {
        return exec(
                http("browse-work")
                        .post("/v2/browse")
                        .header("X-CSRF-Token", session -> session.getString(CSRF))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429))
                        .check(bodyString().optional().saveAs("browseBody"))
        ).exec(session -> {
            int status = session.getInt("browseStatus");
            if (status == 429) {
                return session.set("browseRetry", true);
            }
            return session.set("browseRetry", false);
        });
    }

    // ---- scenarios ----

    private static final ScenarioBuilder BROWSE = scenario("browse")
            .exec(session -> session.set("username", "bench-" + (1 + ThreadLocalRandom.current().nextInt(16))))
            .exec(login())
            .exec(pickProduct())
            .exec(createCart())
            .exec(patchCart())
            .during(Duration.ofSeconds(40)).on(
                    exec(browseWork())
            );

    private static final ScenarioBuilder CHECKOUT = scenario("checkout")
            .exec(session -> session.set("username", "bench-" + (1 + ThreadLocalRandom.current().nextInt(16))))
            .exec(login())
            .exec(pickProduct())
            .exec(createCart())
            .exec(patchCart())
            .during(Duration.ofSeconds(40)).on(
                    exec(checkout())
            );

    {
        setUp(
                BROWSE.injectOpen(
                        constantUsersPerSec(8).during(Duration.ofSeconds(40))
                ).protocols(HTTP),
                CHECKOUT.injectOpen(
                        constantUsersPerSec(2).during(Duration.ofSeconds(40))
                ).protocols(HTTP)
        ).maxDuration(Duration.ofSeconds(60));
    }
}
