import http from 'k6/http';
import { sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import encoding from 'k6/encoding';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// ---- metrics ----
const browseStarts = new Counter('browse_starts');
const checkoutStarts = new Counter('checkout_starts');
const browseErrors = new Counter('browse_errors');
const checkoutErrors = new Counter('checkout_errors');
const unexpected = new Counter('unexpected_failures');
const businessResponses = new Counter('business_responses');
const businessFailureRate = new Rate('business_failure');
const cartCorrect = new Counter('cart_correct');
const cartIncorrect = new Counter('cart_incorrect');
const checkoutLatency = new Trend('checkout_latency');

export const options = {
  scenarios: {
    browse: {
      executor: 'constant-arrival-rate',
      exec: 'browseFlow',
      rate: 8,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 8,
      maxVUs: 32,
      startTime: '0s',
    },
    checkout: {
      executor: 'constant-arrival-rate',
      exec: 'checkoutFlow',
      rate: 2,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 4,
      maxVUs: 32,
      startTime: '0s',
    },
  },
  discardResponseBodies: false,
  noConnectionReuse: false,
  thresholds: {
    business_failure: ['rate<0.01'],
  },
};

// ---- helpers ----
function jar() {
  return http.cookieJar();
}

function parseCsrfFromForm(html) {
  // find input[name=csrf] value, tolerate attribute variants
  const re = /<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = html.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function parseChallengeForm(html) {
  const actionM = html.match(/action\s*=\s*["']([^"']*\/v2\/challenges\/[^"']*)["']/i);
  const inputM = html.match(/<input[^>]*name\s*=\s*["']?challenge["']?[^>]*>/i);
  let value = null;
  if (inputM) {
    const vm = inputM[0].match(/value\s*=\s*["']([^"']*)["']/i);
    if (vm) value = vm[1];
  }
  return { action: actionM ? actionM[1] : null, value };
}

function login(user) {
  const j = jar();
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: j, redirects: 0 });
  if (formRes.status >= 400) return null;
  const csrf = parseCsrfFromForm(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { jar: j, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const r = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: j, redirects: 0 });
      if (r.status >= 400) return null;
    }
  } else if (loginRes.status >= 400) {
    return null;
  }
  let body = {};
  try { body = JSON.parse(loginRes.body); } catch (e) {}
  const token = body.csrf || csrf;
  return { jar: j, csrf: token, user: body.user || user };
}

function renew(sess) {
  const r = http.post(`${BASE}/v2/session/renew`, '{}', {
    jar: sess.jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf },
    redirects: 0,
  });
  if (r.status >= 400) return false;
  try {
    const b = JSON.parse(r.body);
    if (b.csrf) sess.csrf = b.csrf;
  } catch (e) {}
  return true;
}

function recoverCart(sess, cartId) {
  const r = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    jar: sess.jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf },
    redirects: 0,
  });
  if (r.status >= 400) return false;
  try {
    const b = JSON.parse(r.body);
    if (b.csrf) sess.csrf = b.csrf;
  } catch (e) {}
  return true;
}

function authed(sess, method, path, body, extraHeaders) {
  const headers = Object.assign(
    { 'X-CSRF-Token': sess.csrf },
    body ? { 'Content-Type': 'application/json' } : {},
    extraHeaders || {}
  );
  const params = { jar: sess.jar, headers, redirects: 0 };
  let res;
  if (method === 'GET') res = http.get(`${BASE}${path}`, params);
  else if (method === 'POST') res = http.post(`${BASE}${path}`, body || '{}', params);
  else if (method === 'PATCH') res = http.patch(`${BASE}${path}`, body || '{}', params);
  else res = http.request(method, `${BASE}${path}`, body, params);
  return res;
}

function handle401(sess, res, cartId) {
  if (res.status !== 401) return false;
  let err = null;
  try { err = JSON.parse(res.body).error; } catch (e) {}
  if (err === 'expired') {
    if (!renew(sess)) return false;
    if (cartId) recoverCart(sess, cartId);
    return true;
  }
  if (err === 'session') {
    // revoked: renew may fail; caller should re-login
    return 'relogin';
  }
  return false;
}

function pickProduct(sess) {
  const r = authed(sess, 'GET', '/v2/catalog');
  if (r.status >= 400) return null;
  let b;
  try { b = JSON.parse(r.body); } catch (e) { return null; }
  const products = (b.data && b.data.products) || [];
  for (const p of products) {
    for (const v of (p.variants || [])) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  // fallback: paginate
  let next = b.next;
  let pages = 0;
  while (next && pages < 3) {
    pages++;
    const url = next.startsWith('http') ? next : `${BASE}${next}`;
    const pr = http.get(url, { jar: sess.jar, redirects: 0 });
    if (pr.status >= 400) break;
    let pb;
    try { pb = JSON.parse(pr.body); } catch (e) { break; }
    const list = (pb.data && pb.data.products) || (pb.product ? [pb.product] : []);
    for (const p of list) {
      for (const v of (p.variants || [])) {
        if (v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
    next = pb.next;
  }
  return null;
}

function maybeChallenge(sess) {
  const r = authed(sess, 'GET', '/v2/challenge-form');
  if (r.status >= 400) return null;
  const { action, value } = parseChallengeForm(r.body);
  if (!action || !value) return null;
  const post = authed(sess, 'POST', action.replace(BASE, ''), JSON.stringify({ challenge: value }));
  if (post.status === 302) {
    const loc = post.headers['Location'];
    if (loc) {
      const g = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: sess.jar, redirects: 0 });
      if (g.status < 400) {
        try {
          const b = JSON.parse(g.body);
          if (b.csrf) sess.csrf = b.csrf;
          return b.grant_id || null;
        } catch (e) {}
      }
    }
  }
  return null;
}

function createCart(sess, product, grantId) {
  const payload = { product_id: product.product_id, variant_id: product.variant_id };
  if (grantId) payload.grant_id = grantId;
  let r = authed(sess, 'POST', '/v2/carts', JSON.stringify(payload));
  if (r.status === 401) {
    const h = handle401(sess, r, null);
    if (h === 'relogin') return null;
    if (h) r = authed(sess, 'POST', '/v2/carts', JSON.stringify(payload));
  }
  if (r.status !== 201) return null;
  let b;
  try { b = JSON.parse(r.body); } catch (e) { return null; }
  if (b.csrf) sess.csrf = b.csrf;
  return { id: b.id, etag: r.headers['Etag'] || r.headers['ETag'] };
}

function patchQuantity(sess, cartId, etag, qty) {
  const payload = JSON.stringify({ quantity: qty });
  const headers = { 'If-Match': etag || '*' };
  let r = authed(sess, 'PATCH', `/v2/carts/${cartId}`, payload, headers);
  if (r.status === 412) {
    const g = authed(sess, 'GET', `/v2/carts/${cartId}`);
    if (g.status < 400) {
      const newEtag = g.headers['Etag'] || g.headers['ETag'];
      r = authed(sess, 'PATCH', `/v2/carts/${cartId}`, payload, { 'If-Match': newEtag || '*' });
    }
  }
  if (r.status === 401) {
    const h = handle401(sess, r, cartId);
    if (h === 'relogin') return false;
    if (h) {
      r = authed(sess, 'PATCH', `/v2/carts/${cartId}`, payload, headers);
    }
  }
  if (r.status >= 400) return false;
  try {
    const b = JSON.parse(r.body);
    if (b.csrf) sess.csrf = b.csrf;
  } catch (e) {}
  return true;
}

function reserve(sess, cartId) {
  let r = authed(sess, 'POST', '/v2/reservations', JSON.stringify({ cart_id: cartId }));
  if (r.status === 401) {
    const h = handle401(sess, r, cartId);
    if (h === 'relogin') return null;
    if (h) r = authed(sess, 'POST', '/v2/reservations', JSON.stringify({ cart_id: cartId }));
  }
  if (r.status !== 202) return null;
  let b;
  try { b = JSON.parse(r.body); } catch (e) { return null; }
  if (b.csrf) sess.csrf = b.csrf;
  const statusUrl = b.status_url;
  if (!statusUrl) return null;
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
    const pr = http.get(url, { jar: sess.jar, redirects: 0 });
    if (pr.status >= 400) return null;
    let pb;
    try { pb = JSON.parse(pr.body); } catch (e) { return null; }
    if (pb.csrf) sess.csrf = pb.csrf;
    if (pb.status === 'ready') return pb.reservation_id || null;
    if (pb.status === 'failed') return null;
  }
  return null;
}

function placeOrder(sess, cartId, reservationId, idemKey) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = { 'Idempotency-Key': idemKey };
  let r = authed(sess, 'POST', '/v2/orders', JSON.stringify(payload), headers);
  if (r.status === 401) {
    const h = handle401(sess, r, cartId);
    if (h === 'relogin') return { ok: false, relogin: true };
    if (h) r = authed(sess, 'POST', '/v2/orders', JSON.stringify(payload), headers);
  }
  if (r.status === 201) {
    let b;
    try { b = JSON.parse(r.body); } catch (e) { return { ok: false }; }
    if (b.csrf) sess.csrf = b.csrf;
    if (b.accepted === true) return { ok: true, id: b.id };
    return { ok: false };
  }
  if (r.status === 200) {
    // accepted:false business failure
    return { ok: false };
  }
  return { ok: false };
}

function doWork(sess, path) {
  let attempts = 0;
  while (attempts < 5) {
    attempts++;
    const r = authed(sess, 'POST', path, '{}');
    if (r.status === 429) {
      const ra = r.headers['Retry-After'];
      const wait = ra ? parseFloat(ra) : 1;
      sleep(Math.min(wait, 1));
      continue;
    }
    if (r.status === 401) {
      const h = handle401(sess, r, null);
      if (h === 'relogin') return { ok: false, relogin: true };
      if (h) continue;
      return { ok: false };
    }
    if (r.status >= 500) {
      unexpected.add(1);
      businessResponses.add(1);
      businessFailureRate.add(1);
      return { ok: false };
    }
    if (r.status >= 400) {
      businessResponses.add(1);
      businessFailureRate.add(1);
      return { ok: false };
    }
    businessResponses.add(1);
    businessFailureRate.add(0);
    return { ok: true };
  }
  return { ok: false };
}

function pickUser() {
  const n = 1 + Math.floor(Math.random() * 16);
  return `bench-${n}`;
}

// ---- scenarios ----
export function browseFlow() {
  let sess = login(pickUser());
  if (!sess) { browseErrors.add(1); return; }
  const res = doWork(sess, '/v2/browse');
  if (res.relogin) {
    sess = login(pickUser());
    if (!sess) { browseErrors.add(1); return; }
    const r2 = doWork(sess, '/v2/browse');
    if (r2.ok) browseStarts.add(1); else browseErrors.add(1);
  } else if (res.ok) {
    browseStarts.add(1);
  } else {
    browseErrors.add(1);
  }
}

export function checkoutFlow() {
  const t0 = Date.now();
  let sess = login(pickUser());
  if (!sess) { checkoutErrors.add(1); return; }

  const product = pickProduct(sess);
  if (!product) { checkoutErrors.add(1); return; }

  const grantId = maybeChallenge(sess);
  const cart = createCart(sess, product, grantId);
  if (!cart) { checkoutErrors.add(1); return; }

  if (!patchQuantity(sess, cart.id, cart.etag, 1)) {
    cartIncorrect.add(1);
    checkoutErrors.add(1);
    return;
  }

  const reservationId = reserve(sess, cart.id);
  if (!reservationId) { checkoutErrors.add(1); return; }

  const idemKey = `idem-${cart.id}-${Date.now()}`;
  const order = placeOrder(sess, cart.id, reservationId, idemKey);
  if (order.relogin) {
    sess = login(pickUser());
    if (!sess) { checkoutErrors.add(1); return; }
    const order2 = placeOrder(sess, cart.id, reservationId, idemKey);
    if (order2.ok) {
      checkoutStarts.add(1);
      cartCorrect.add(1);
      checkoutLatency.add(Date.now() - t0);
    } else {
      checkoutErrors.add(1);
      cartIncorrect.add(1);
    }
  } else if (order.ok) {
    checkoutStarts.add(1);
    cartCorrect.add(1);
    checkoutLatency.add(Date.now() - t0);
  } else {
    checkoutErrors.add(1);
    cartIncorrect.add(1);
  }
}
