def _csrf_from_html(text):
    # find input[name=csrf] value, tolerate attribute variants
    m = re.search(r'<input[^>]*name=["\']?csrf["\']?[^>]*>', text, re.I)
    if not m:
        return None
    tag = m.group(0)
    v = re.search(r'value=["\']([^"\']*)["\']', tag, re.I)
    if v:
        return v.group(1)
    return None


def _nonce_from_html(text):
    m = re.search(r'<input[^>]*name=["\']?login_nonce["\']?[^>]*>', text, re.I)
    if not m:
        return None
    tag = m.group(0)
    v = re.search(r'value=["\']([^"\']*)["\']', tag, re.I)
    return v.group(1) if v else None


def _challenge_from_html(text):
    m = re.search(r'<form[^>]*action=["\']([^"\']*challenges[^"\']*)["\']', text, re.I)
    action = m.group(1) if m else None
    cm = re.search(r'<input[^>]*name=["\']?challenge["\']?[^>]*>', text, re.I)
    cval = None
    if cm:
        v = re.search(r'value=["\']([^"\']*)["\']', cm.group(0), re.I)
        cval = v.group(1) if v else None
    return action, cval


class ShopBase(HttpUser):
