        products = (data.get("data") or {}).get("products") or []
        candidates = []
        for p in products:
            for v in p.get("variants") or []:
                if v.get("in_stock"):
                    candidates.append((p.get("id"), v.get("id")))
        if candidates:
            return random.choice(candidates)
        # fallback: paginate
        next_url = data.get("next")
        pages = 0
        while next_url and pages < 3:
            pages += 1
            with self.client.get(next_url, catch_response=True, allow_redirects=False) as r:
                if r.status_code >= 400:
                    r.failure("catalog page status %s" % r.status_code)
                    return None
                try:
                    pd = r.json()
                except Exception:
                    r.failure("catalog page bad json")
