            if r.status_code >= 400:
                r.failure("browse status %s" % r.status_code)
                return False
            try:
                d = r.json()
            except Exception:
                r.failure("browse bad json")
                return False
            if not d.get("ok"):
                r.failure("browse not ok")
                return False
        return True

    def _do_checkout_journey(self):
        pick = self._pick_product()
        if not pick:
            return False
        pid, vid = pick
        if not self._create_cart(pid, vid):
            return False
        if not self._patch_quantity(random.randint(1, 5)):
            return False
        return self._checkout()


