class PhasedShape(LoadTestShape):
    # 3 plateaus of 10s: 5, 15, 5 users; warmup 5s; drain 5s
    def tick(self):
        t = _now()
        t0 = _T0["t"]
        if t0 is None:
            return (2, 2)
        elapsed = t - t0
        if elapsed < 5:
            return (2, 2)
        if elapsed < 15:
            return (5, 2)
        if elapsed < 25:
            return (15, 2)
        if elapsed < 35:
            return (5, 2)
        if elapsed < 40:
            return (2, 2)
